('usr-learner-01', 'learner@lerngdomnaeng.com', 'សុខ ជា (Learner)', 'learner', 'junior', 'senior', 'Information Technology', 'SME Company', 1200),
('usr-instructor-01', 'instructor@lerngdomnaeng.com', 'លោកគ្រូ សុជាតិ វណ្ណារ៉ា (Instructor)', 'instructor', 'director', 'executive', 'Corporate Training', 'Standard Enterprise', 3500);
INSERT INTO `courses` (`id`, `title_kh`, `title_en`, `description_kh`, `description_en`, `target_level`, `category`, `instructor_name`, `total_lessons`, `estimated_minutes`) VALUES ('course-intern-comm', 'ទំនាក់ទំនង និងសីលធម៌ការងារប្រកបដោយវិជ្ជាជីវៈ', 'Workplace Communication & Professional Ethics for Interns', 'កសាងមូលដ្ឋានគ្រឹះរឹងមាំ៖ ការឆ្លើយតបអ៊ីមែលផ្លូវការ របៀបសួរសំណួរដើម្បីភាពច្បាស់លាស់ និងការទទួល Feedback ប្រកបដោយភាពចាស់ទុំ។', 'Master professional workplace communication, active listening, asking clarifying questions, and handling feedback constructively.', 'intern', 'Workplace Fundamentals', 'លោកគ្រូ សុជាតិ វណ្ណារ៉ា', 10, 110);
INSERT INTO `courses` (`id`, `title_kh`, `title_en`, `description_kh`, `description_en`, `target_level`, `category`, `instructor_name`, `total_lessons`, `estimated_minutes`) VALUES ('course-eq-critical', 'EQ និងការត្រិះរិះពិចារណាដោះស្រាយបញ្ហាការងារ', 'Workplace EQ & Critical Problem Solving', 'គ្រប់គ្រងសម្ពាធអារម្មណ៍ យល់ចិត្តអ្នកដទៃ (Empathy) និងវិភាគរកឫសគល់នៃបញ្ហានៅកន្លែងធ្វើការតាមបែបតក្កវិជ្ជា។', 'Develop emotional intelligence, empathy, and root-cause problem solving under pressure.', 'junior', 'EQ & Problem Solving', 'អ្នកគ្រូ ចាន់ថុល សុរិយា', 10, 115);
INSERT INTO `courses` (`id`, `title_kh`, `title_en`, `description_kh`, `description_en`, `target_level`, `category`, `instructor_name`, `total_lessons`, `estimated_minutes`) VALUES ('course-leader-delegation', 'សិល្បៈនៃការចាត់ចែងការងារ និងការផ្ដល់ Feedback ប្រកបដោយការស្ថាបនា', 'Task Delegation & Constructive Feedback for Team Leaders', 'របៀបប្រគល់ភារកិច្ចឱ្យចំមនុស្ស និងចំជំនាញ ការរៀបចំការប្រជុំ 1-on-1 និងការដោះស្រាយបុគ្គលិកដែលមិនស្តាប់បង្គាប់។', 'Master delegation frameworks, 1-on-1 coaching sessions, and handling team resistance fairly.', 'teamLeader', 'Management & Leadership', 'លោកគ្រូ រតនា គីមសាន', 10, 125);
INSERT INTO `courses` (`id`, `title_kh`, `title_en`, `description_kh`, `description_en`, `target_level`, `category`, `instructor_name`, `total_lessons`, `estimated_minutes`) VALUES ('course-manager-conflict', 'ការដោះស្រាយជម្លោះ និងការសន្ទនាស្មុគស្មាញក្នុងស្ថាប័ន', 'Conflict Resolution & Difficult Conversations for Managers', 'បច្ចេកទេសសម្រុះសម្រួលការខ្វែងគំនិតរវាងបុគ្គលិក ការការពារវប្បធម៌ Toxic និងការចរចាផលប្រយោជន៍ស្ថាប័នដោយយុត្តិធម៌។', 'Navigate workplace politics, mediate team conflicts, and protect ethical team culture.', 'manager', 'Conflict & Negotiation', 'អ្នកគ្រូ លីដា វណ្ណនី', 10, 120);
INSERT INTO `courses` (`id`, `title_kh`, `title_en`, `description_kh`, `description_en`, `target_level`, `category`, `instructor_name`, `total_lessons`, `estimated_minutes`) VALUES ('course-founder-sme', 'ភាពជាអ្នកដឹកនាំយុទ្ធសាស្ត្រ និងការកសាងក្រុមការងារ SME', 'Strategic Leadership & SME Team Building for Founders', 'យុទ្ធសាស្ត្រជ្រើសរើសមនុស្សត្រូវនឹងវប្បធម៌ ការគ្រប់គ្រងលំហូរសាច់ប្រាក់បឋម និងការដឹកនាំអាជីវកម្មឱ្យមានចីរភាព។', 'Hiring strategy, cash flow literacy, delegation culture, and scaling small teams sustainably.', 'founder', 'Strategy & SME Leadership', 'លោកឧកញ៉ា សុផាត ប៊ុនណារិទ្ធ', 10, 135);
INSERT INTO `courses` (`id`, `title_kh`, `title_en`, `description_kh`, `description_en`, `target_level`, `category`, `instructor_name`, `total_lessons`, `estimated_minutes`) VALUES ('course-senior-mentorship', 'ជំនាញបច្ចេកទេសកម្រិតខ្ពស់ និងការធ្វើជាទីប្រឹក្សាការងារ (Mentorship)', 'Technical Mastery & Mentorship for Senior Specialists', 'ក្លាយជាអ្នកជំនាញឯកទេស (SME) ដោះស្រាយបញ្ហាស្មុគស្មាញដោយម្ចាស់ការ និងបង្វឹកសមាជិកជំនាន់ក្រោយប្រកបដោយប្រសិទ្ធភាព។', 'Subject matter expertise, autonomous problem solving, and coaching junior talent effectively.', 'senior', 'Specialist & Mentorship', 'លោក ស៊ុន វិទូ', 10, 130);
INSERT INTO `courses` (`id`, `title_kh`, `title_en`, `description_kh`, `description_en`, `target_level`, `category`, `instructor_name`, `total_lessons`, `estimated_minutes`) VALUES ('course-supervisor-ops', 'ការត្រួតពិនិត្យប្រតិបត្តិការ និងការគ្រប់គ្រងគុណភាព (QA/QC & Supervision)', 'Operations Supervision & Quality Control for Supervisors', 'ភ្ជាប់យុទ្ធសាស្ត្រថ្នាក់លើទៅការអនុវត្តជាក់ស្តែង ត្រួតពិនិត្យស្តង់ដារ QA/QC និងគ្រប់គ្រងទិន្នផលប្រចាំថ្ងៃ។', 'Translate high-level strategy into daily execution, ensure QA/QC standards, and optimize workflow.', 'supervisor', 'Operations & Quality', 'អ្នកស្រី កែវ មុនីនាថ', 10, 125);
INSERT INTO `courses` (`id`, `title_kh`, `title_en`, `description_kh`, `description_en`, `target_level`, `category`, `instructor_name`, `total_lessons`, `estimated_minutes`) VALUES ('course-hod-strategy', 'យុទ្ធសាស្ត្រដឹកនាំនាយកដ្ឋាន និងការគ្រប់គ្រង P&L (Departmental Leadership)', 'Departmental Strategy & Financial Leadership for Heads of Department', 'គ្រប់គ្រងថវិកាប្រចាំឆ្នាំ ដឹកនាំកិច្ចសហការអន្តរនាយកដ្ឋាន (Cross-functional) និងជំរុញចំណូលស្ថាប័ន។', 'P&L management, cross-department alignment, strategic annual budgeting, and business scaling.', 'headOfDepartment', 'Department Strategy', 'លោក គង់ សម្បត្តិ', 10, 130);
INSERT INTO `courses` (`id`, `title_kh`, `title_en`, `description_kh`, `description_en`, `target_level`, `category`, `instructor_name`, `total_lessons`, `estimated_minutes`) VALUES ('course-director-governance', 'អភិបាលកិច្ចស្ថាប័ន និងការពង្រីកអាជីវកម្មជាយុទ្ធសាស្ត្រ (Corporate Governance)', 'Corporate Governance & Strategic Expansion for Directors', 'គ្រប់គ្រងហានិភ័យស្ថាប័ន ពង្រីកទីផ្សារ និងសាខាធុរកិច្ច និងកសាងប្រព័ន្ធអភិបាលកិច្ចរឹងមាំយូរអង្វែង។', 'Enterprise risk management, market expansion, board alignment, and long-term governance.', 'director', 'Governance & Expansion', 'លោកជំទាវ ជា សុភាព', 10, 135);
INSERT INTO `courses` (`id`, `title_kh`, `title_en`, `description_kh`, `description_en`, `target_level`, `category`, `instructor_name`, `total_lessons`, `estimated_minutes`) VALUES ('course-executive-csuite', 'ភាពជាអ្នកដឹកនាំកំពូល C-Suite និងការបង្កើតតម្លៃទីផ្សារ (C-Suite Leadership)', 'C-Suite Executive Leadership & Company Valuation', 'រាយការណ៍ជូនក្រុមប្រឹក្សាភិបាល (Board of Directors) យុទ្ធសាស្ត្របែងចែកទុន (Capital Allocation) និងបង្កើនតម្លៃក្រុមហ៊ុន។', 'Executive leadership, capital allocation, investor relations, and maximizing company valuation.', 'executive', 'Executive Leadership', 'ឯកឧត្តមបណ្ឌិត ហេង វណ្ណា', 10, 140);
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-comm-1', 'course-intern-comm', 'mod-1', 1, '១. របៀបសួរបញ្ជាក់ការងារកុំឱ្យខុសទិសដៅ (Asking for Clarity Without Fear)', 'Asking Clarifying Questions Effectively', 'text', '• យល់ដឹងពីមូលហេតុដែលការសួរបញ្ជាក់បង្ហាញពីទំនួលខុសត្រូវវិជ្ជាជីវៈ មិនមែនជាភាពអសមត្ថភាព។\n• ចេះប្រើប្រាស់រូបមន្ត 4W1H ដើម្បីបញ្ជាក់ទម្រង់ (Format) ម៉ោងកំណត់ (Deadline) និងការរំពឹងទុករបស់ប្រធាន។\n• កាត់បន្ថយការខកចិត្ត និងពេលវេលាដែលត្រូវកែកិច្ចការឡើងវិញ។', 'កំហុសធំបំផុតរបស់បុគ្គលិកថ្មីគឺ ការស្ងៀមស្ងាត់ហើយធ្វើតាមការស្មាន។ ការសួរនាំដើម្បីភាពច្បាស់លាស់ជួយសន្សំពេលវេលាក្រុមហ៊ុន និងកសាងទំនុកចិត្តថាអ្នកជាមនុស្សម៉ត់ចត់។', '«សុភា ជាបុគ្គលិកថ្មីនៅក្រុមហ៊ុនភ្នាក់ងារផ្សព្វផ្សាយ (Digital Agency) មួយនៅភ្នំពេញ។ ថ្ងៃមួយ ប្រធានប្រាប់នាងយ៉ាងប្រញាប់មុនពេលចេញទៅជួបអតិថិជន៖ "ជួយធ្វើរបាយការណ៍លក់សប្តាហ៍មុនឱ្យខ្ញុំបន្ទាន់!"។ សុភាមិនហ៊ានសួរថា តើចង់បានជា Excel ឬ Slide ហើយ Deadline ម៉ោងប៉ុន្មានទេ។ នាងចំណាយពេលពេញមួយថ្ងៃរចនា Slide យ៉ាងស្អាតរហូតដល់ម៉ោង ៥ ល្ងាច។ ប៉ុន្តែប្រធានត្រូវការត្រឹមតារាងលេខ Excel បន្ទាន់នៅម៉ោង ២ រសៀលដើម្បីប្រជុំផ្ទៃក្នុង។ លទ្ធផល៖ ប្រធានខកចិត្តយ៉ាងខ្លាំងដោយសារគ្មានទិន្នន័យប្រជុំ ហើយសុភាមានអារម្មណ៍បាក់ទឹកចិត្ត និងយំដោយសារគិតថាខ្លួនឯងខំអស់ពីសមត្ថភាពហើយនៅតែខុស។»', '✅ របៀបនិយាយត្រឹមត្រូវ និងវិជ្ជាជីវៈ៖\n«ជម្រាបសួរបង! ដើម្បីកុំឱ្យខុសទិសដៅ និងតម្រូវការជាក់ស្តែង តើបងចង់បានរបាយការណ៍ជាតារាងលេខ Excel សង្ខេប ឬជា Slide បទបង្ហាញ? ហើយតើបងត្រូវការប្រើប្រាស់នៅម៉ោងប៉ុន្មានដែរ ដើម្បីខ្ញុំរៀបចំជូនទាន់ពេលវេលា?»', 'អនុវត្តការសរសេរសារបញ្ជាក់ការងារសាកល្បងមួយផ្ញើទៅកាន់ប្រធាន នៅពេលអ្នកទទួលបានកិច្ចការដែលមិនទាន់ច្បាស់ពី Deadline ឬលទ្ធផលរំពឹងទុក។', 'តើកន្លងមកអ្នកធ្លាប់ជួបការយល់ច្រឡំដោយសារមិនបានសួរនាំបញ្ជាក់ការងារឱ្យច្បាស់ដែរឬទេ? តើការខកខាននោះបានបង្រៀនអ្វីខ្លះដល់អ្នក?', '🎯 សកម្មភាពថ្ងៃនេះ៖ មុននឹងចាប់ផ្តើមកិច្ចការបន្ទាប់ សូមផ្ញើសារ ឬសួរផ្ទាល់មាត់យ៉ាងហោច ១ ដង ដើម្បីបញ្ជាក់ទម្រង់ និងម៉ោងប្រគល់ឱ្យច្បាស់ ១០០%។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-comm-1', 'lesson-comm-1', 'ប្រសិនបើប្រធានរបស់អ្នកប្រគល់ការងារបន្ទាន់មួយដែលអ្នកមិនទាន់យល់ច្បាស់ពីទម្រង់ និង Deadline តើអ្នកគួរធ្វើបែបណា?', 'If your manager assigns an urgent task without clear format or deadline, what should you do?', '["A. ស្ងៀមស្ងាត់ហើយធ្វើតាមការស្មានក្រែងលោត្រូវ ដើម្បីកុំឱ្យប្រធានគិតថាយើងមិនចេះ។","B. សួរបញ្ជាក់ទម្រង់ (Format) និងម៉ោងកំណត់ (Deadline) ដោយគួរសម មុនពេលចាប់ផ្តើមធ្វើ។","C. ចាំដល់ម៉ោងប្រជុំទើបប្រាប់ប្រធានថាដោយសារមិនច្បាស់ទើបមិនទាន់បានធ្វើ។"]', '["A. Stay quiet and guess, hoping not to look incompetent.","B. Clarify format and deadline politely before starting.","C. Wait until the meeting to tell them you did not understand."]', 1, 'ការពន្យល់៖ ជម្រើស B បង្ហាញពីភាពចាស់ទុំ និងទំនួលខុសត្រូវខ្ពស់។ ការសួរបញ្ជាក់ចំណាយពេលតែ ២ នាទី ប៉ុន្តែការពារការខាតបង់ពេលវេលារាប់ម៉ោង និងកាត់បន្ថយការកែប្រែឡើងវិញ។', 'Explanation: Clarifying early shows professionalism and prevents hours of rework.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-comm-2', 'course-intern-comm', 'mod-1', 2, '២. វិជ្ជាជីវៈក្នុងការឆ្លើយតបអ៊ីមែល & Telegram ការងារ (Workplace Messaging Etiquette)', 'Professional Email & Messaging Etiquette', 'text', '• ចេះសរសេរ Subject Line ច្បាស់លាស់ និងរៀបចំកថាខណ្ឌងាយអានតាមទម្រង់ 4 ផ្នែក។\n• ស្គាល់ពីព្រំដែននៃការប្រើប្រាស់បណ្តាញទំនាក់ទំនងផ្ទាល់ខ្លួនសម្រាប់ការងារផ្លូវការ។\n• ជៀសវាងការផ្ញើសារមិនច្បាស់លាស់ដែលធ្វើឱ្យអ្នកដទៃរង់ចាំ។', 'សារការងារត្រូវតែខ្លី ចំគោលដៅ និងគោរពពេលវេលាអ្នកអាន។ កុំផ្ញើសារសួរត្រឹមតែ "បង?" រួចទុកឱ្យគេរង់ចាំដោយភាពស្រពេចស្រពិល។', '«វិចិត្រ តែងតែផ្ញើសារ Telegram ទៅកាន់ថ្នាក់លើថា "បង! ទំនេរទេ?" រួចស្ងាត់ឈឹងរង់ចាំប្រធានឆ្លើយតប។ ប្រធានរបស់គាត់កំពុងប្រជុំមានអារម្មណ៍ភ័យផង និងធុញទ្រាន់ផង ដោយមិនដឹងថាមានរឿងបន្ទាន់អ្វី។ ក្រោយមក គាត់បានរៀនប្តូរមកជា៖ "ជម្រាបសួរបង! ខ្ញុំត្រូវការហត្ថលេខាលើ PO លេខ 104 សម្រាប់ទិញសម្ភារការិយាល័យ។ ឯកសារបានដាក់លើតុបងរួចហើយ។ ពេលបងទំនេរ ខ្ញុំសុំជួប ២ នាទី"។ ប្រធានឆ្លើយតបយល់ព្រមភ្លាមៗក្នុងរយៈពេល ៣ នាទី។»', '✅ ក្បួនសរសេរសារការងារ ៤ ផ្នែក៖\n១. [ស្វាគមន៍គួរសម]៖ "ជម្រាបសួរបង..."\n២. [បញ្ហា/សំណើសង្ខេប]៖ "ខ្ញុំសូមគោរពស្នើសុំ..."\n៣. [ឯកសារភ្ជាប់/បរិបទ]៖ "មានឯកសារភ្ជាប់ក្នុងតំណរភ្ជាប់នេះ..."\n៤. [សំណូមពរសកម្មភាពបន្ទាប់]៖ "តើបងអាចពិនិត្យមុនម៉ោង ៤ រសៀលបានទេ?"', 'រៀបចំអ៊ីមែលសុំច្បាប់ឈប់សម្រាកព្យាបាលជំងឺ ឬស្នើសុំឯកសារការងារ ស្របតាមទម្រង់ ៤ ផ្នែកខាងលើ។', 'តើអ្នកមានអារម្មណ៍បែបណាពេលមានគេផ្ញើសារមិនច្បាស់លាស់មករំខានការងាររបស់អ្នក? តើអ្នកធ្លាប់ធ្វើបែបនេះទៅកាន់អ្នកដទៃដែរឬទេ?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ពិនិត្យសារការងាររបស់អ្នកឡើងវិញ មុននឹងចុច Send ដោយធានាថាមានព័ត៌មានគ្រប់គ្រាន់ក្នុងសារតែមួយ។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-comm-2', 'lesson-comm-2', 'នៅពេលត្រូវការជំនួយ ឬហត្ថលេខាពីប្រធានដែលកំពុងរវល់ តើការផ្ញើសារបែបណាដែលមានវិជ្ជាជីវៈបំផុត?', 'When you need help or signature from a busy manager, what is the most professional message?', '["A. ផ្ញើពាក្យ \\"បង?\\" រួចចាំមើលប្រធានឆ្លើយតបសិន ទើបសរសេររឿងរ៉ាវបន្ត។","B. ផ្ញើសារដែលមានទាំងការស្វាគមន៍ មូលហេតុសង្ខេប ឯកសារយោង និងសំណើសកម្មភាពក្នុងសារតែមួយ។","C. ខលទូរស័ព្ទទារហត្ថលេខាភ្លាមៗដោយមិនបាច់ផ្ញើសារមុន។"]', '["A. Send \\"Bong?\\" and wait for reply before telling details.","B. Send a single clear message with greeting, summary, reference, and requested action.","C. Call repeatedly without messaging first."]', 1, 'ការពន្យល់៖ ជម្រើស B គោរពពេលវេលាអ្នកទទួលខ្ពស់បំផុត។ អ្នកអានអាចយល់ពីភាពបន្ទាន់ និងសម្រេចចិត្តបានភ្លាមៗដោយមិនបាច់ចំណាយពេលសួរដេញដោលច្រើនដង។', 'Explanation: Option B respects the recipient time and gives all context at a glance.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-comm-3', 'course-intern-comm', 'mod-1', 3, '៣. របៀបទទួលយក Feedback ដោយមិនការពារខ្លួន (Receiving Feedback with Emotional Maturity)', 'Receiving Constructive Criticism with Emotional Maturity', 'text', '• បែងចែកដាច់រវាងការរិះគន់លើការងារ និងការវាយប្រហារលើតម្លៃផ្ទាល់ខ្លួន។\n• ចេះគ្រប់គ្រងអារម្មណ៍ការពារខ្លួន (Defensive mode) និងប្រើពាក្យអរគុណជាមុន។\n• សួរនាំដើម្បីទទួលបានដំណោះស្រាយកែលម្អជាក់ស្តែង។', 'Feedback គឺជាកាដូសម្រាប់ការរីកចម្រើន។ អ្នកដែលឡើងតំណែងលឿន គឺជាអ្នកដែលចេះស្រូបយកចំណុចខ្វះខាតយកមកកែប្រែដោយស្ងប់ចិត្ត មិនមែនជាអ្នកពូកែដោះសារនោះឡើយ។', '«នៅពេលប្រធានប្រាប់ថា របាយការណ៍របស់តារាមានចំណុចខុសច្រើន តារាមានអារម្មណ៍ខឹង មុខក្រហម និងព្យាយាមដោះសារថាដោយសារកុំព្យូទ័រយឺត និងទិន្នន័យមកពីផ្នែកផ្សេងមិនច្បាស់។ ប្រធានមានអារម្មណ៍ថា តារាពិបាកបង្រៀន។ ផ្ទុយទៅវិញ កល្យាណ ពេលជួបរឿងដូចគ្នា នាងបានដកដង្ហើមវែងៗ រួចនិយាយថា៖ "អរគុណបងដែលបានជួយកត់សម្គាល់! ខ្ញុំពិតជាខ្វះការប្រុងប្រយ័ត្នលើចំណុចនេះមែន។ តើបងគិតថាខ្ញុំគួរពិនិត្យលើទិន្នន័យចំណុចណាជាពិសេសដើម្បីកុំឱ្យខុសទៀត?"។ ប្រធានពេញចិត្តនឹងឥរិយាបថកល្យាណជាខ្លាំង ហើយបានផ្តល់ឱកាសឱ្យនាងកាន់គម្រោងធំៗជាបន្តបន្ទាប់។»', '✅ របៀបឆ្លើយតប ៣ ជំហាន៖\n១. ទទួលស្គាល់៖ "អរគុណបងចំពោះមតិកែលម្អនេះ។"\n២. បញ្ជាក់ការយល់ស្រប៖ "ខ្ញុំយល់ស្របថាការវិភាគទិន្នន័យចំណុចនេះមិនទាន់គ្រប់ជ្រុងជ្រោយទេ។"\n៣. សកម្មភាពកែតម្រូវ៖ "ខ្ញុំនឹងកែសម្រួលឡើងវិញ ហើយផ្ញើជូនបងនៅម៉ោង ៤ រសៀលនេះ"។', 'អនុវត្តការដកដង្ហើមវែងៗ ៥ វិនាទីមុនពេលឆ្លើយតប នៅពេលទទួលបានការរិះគន់លើកិច្ចការរបស់អ្នក។', 'តើប្រតិកម្មដំបូងរបស់អ្នកនៅពេលមានគេរិះគន់ការងាររបស់អ្នកគឺជាអ្វី? តើអ្នកមានទំនោរការពារខ្លួន ឬស្តាប់ដើម្បីកែលម្អ?', '🎯 សកម្មភាពថ្ងៃនេះ៖ នៅពេលទទួលបាន Feedback ថ្ងៃនេះ សូមនិយាយពាក្យ "អរគុណ" ជាមុនសិន មុននឹងពន្យល់ហេតុផលណាមួយ។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-comm-3', 'lesson-comm-3', 'នៅពេលប្រធាន ឬសហការីរិះគន់ថាកិច្ចការរបស់អ្នកមានកំហុសបច្ចេកទេសច្រើន តើប្រតិកម្មដំបូងដ៏ត្រឹមត្រូវបំផុតគឺជាអ្វី?', 'When a manager points out technical errors in your work, what is the best initial reaction?', '["A. លើកហេតុផលភ្លាមៗថាដោយសារកុំព្យូទ័រគាំង ឬសហការីផ្សេងមិនបានជួយ។","B. ស្ងប់អារម្មណ៍ ថ្លែងអំណរគុណចំពោះមតិកែលម្អ និងសួរបញ្ជាក់ចំណុចដែលត្រូវកែតម្រូវឱ្យបានច្បាស់។","C. ឈប់និយាយស្តីជាមួយអ្នករិះគន់ព្រោះគិតថាគេមិនចូលចិត្តយើង។"]', '["A. Defend yourself immediately blaming computer or teammates.","B. Stay calm, thank them for the feedback, and ask for specific improvement areas.","C. Stop talking to the reviewer feeling personally attacked."]', 1, 'ការពន្យល់៖ ជម្រើស B បង្ហាញពី EQ ខ្ពស់ និងវិជ្ជាជីវៈ។ ការទទួលយក Feedback ដោយបើកចំហជួយឱ្យអ្នករៀនសូត្របានលឿន និងកសាងទំនុកចិត្តជាមួយថ្នាក់លើ។', 'Explanation: High EQ professionals welcome feedback as a learning tool.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-comm-4', 'course-intern-comm', 'mod-1', 4, '៤. ការគ្រប់គ្រងពេលវេលា & ភាពគួរឱ្យទុកចិត្តក្នុងការងារ (Time Management & Professional Reliability)', 'Time Management & Reliability in Workplace', 'text', '• យល់ដឹងពីគោលការណ៍ Under-promise and Over-deliver ក្នុងការងារ។\n• ចេះប្រើប្រាស់ប្រព័ន្ធផ្តល់ដំណឹងជាមុន (Early Warning System) នៅពេលដឹងថាមិនអាចទាន់ Deadline។\n• កសាងកេរ្តិ៍ឈ្មោះជាបុគ្គលិកដែលអាចទុកចិត្តបាន (Reliable Professional)។', 'ភាពគួរឱ្យទុកចិត្ត (Reliability) គឺជាទ្រព្យសម្បត្តិធំបំផុតរបស់បុគ្គលិក។ ប្រសិនបើអ្នកដឹងថានឹងយឺត សូមប្រាប់ជាមុន កុំរង់ចាំដល់គេមកទារទើបដោះសារ។', '«សុផល ដឹងថាកិច្ចការរបស់គាត់មិនអាចរួចទាន់ម៉ោង ៥ ល្ងាចទេ ប៉ុន្តែគាត់ខ្លាចប្រធានស្តីបន្ទោស ក៏ស្ងៀមស្ងាត់រហូតដល់ម៉ោង ៥ ទើបប្រធានទូរស័ព្ទមកសួរ។ ពេលនោះប្រធានខឹងយ៉ាងខ្លាំងព្រោះគាត់ត្រូវយកឯកសារទៅប្រជុំជាមួយក្រុមប្រឹក្សាភិបាល។ ផ្ទុយទៅវិញ វិបុល កាលដែលដឹងថាកិច្ចការស្មុគស្មាញនៅម៉ោង ២ រសៀល គាត់បានទូរស័ព្ទទៅប្រាប់ប្រធានភ្លាមៗថា៖ "បង! ខ្ញុំជួបបញ្ហាបច្ចេកទេសលើទិន្នន័យគណនេយ្យ ខ្ញុំសុំពន្យារដល់ម៉ោង ១០ ព្រឹកស្អែក។ ប៉ុន្តែខ្ញុំបានផ្ញើទិន្នន័យបឋមជូនបងមើលសិន"។ ប្រធានអាចរៀបចំផែនការបម្រុងទាន់ពេលវេលា និងកោតសរសើរវិបុលថាជាមនុស្សមានទំនួលខុសត្រូវ។»', '✅ ក្បួន Early Warning៖\nរាយការណ៍ជាមុនយ៉ាងហោច ៣ ទៅ ៤ ម៉ោង មុនពេលដល់ Deadline ដោយបញ្ជាក់៖\n១. ស្ថានភាពបច្ចុប្បន្ន (បានប៉ុន្មានភាគរយ)\n២. ឧបសគ្គដែលកំពុងជួបប្រទះ\n៣. ដំណោះស្រាយ ឬម៉ោងថ្មីដែលសន្យាថានឹងរួចរាល់។', 'កត់ត្រាកាលវិភាគការងារថ្ងៃស្អែករបស់អ្នក ដោយបន្ថែម Buffer time ២០% លើកិច្ចការនីមួយៗដើម្បីការពារឧបទ្ទវហេតុចៃដន្យ។', 'តើកន្លងមកអ្នកធ្លាប់ធ្វើឱ្យបាត់បង់ទំនុកចិត្តដោយសារការយឺតយ៉ាវ Deadline ដែរឬទេ? តើអ្នកអាចកែលម្អប្រព័ន្ធគ្រប់គ្រងពេលវេលារបស់អ្នកយ៉ាងដូចម្តេច?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ពិនិត្យមើលកិច្ចការទាំងអស់ថ្ងៃនេះ ប្រសិនបើមានការងារណាមិនទាន់ សូមរាយការណ៍ជូនថ្នាក់លើឥឡូវនេះ។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-comm-4', 'lesson-comm-4', 'នៅពេលអ្នកដឹងច្បាស់ថាមិនអាចបញ្ចប់ការងារទាន់ Deadline ម៉ោង ៥ ល្ងាចបានទេ តើអ្នកគួរធ្វើដូចម្តេច?', 'When you realize at 2 PM that you cannot meet a 5 PM deadline, what should you do?', '["A. ស្ងាត់ស្ងៀមធ្វើរហូតដល់ផុតម៉ោង ៥ ហើយចាំដល់ថ្ងៃស្អែកទើបប្រាប់ថាធ្វើមិនទាន់។","B. រាយការណ៍ជាមុនភ្លាមៗនៅម៉ោង ២ រសៀល ដោយពន្យល់ឧបសគ្គ និងស្នើសុំម៉ោងកំណត់ថ្មីជាក់លាក់។","C. ប្រគល់ការងារមិនទាន់ចប់ទាំងប្រញាប់ប្រញាល់ដោយមិនខ្វល់ពីគុណភាព។"]', '["A. Stay quiet and wait for tomorrow to explain why you failed.","B. Give an early warning immediately at 2 PM, explain obstacles and propose a realistic new deadline.","C. Submit unfinished, poor quality work in a hurry."]', 1, 'ការពន្យល់៖ ជម្រើស B ផ្តល់ឱកាសឱ្យថ្នាក់លើរៀបចំផែនការបម្រុង (Contingency plan) និងរក្សាទំនុកចិត្តវិជ្ជាជីវៈ។', 'Explanation: Early communication allows contingency planning and protects trust.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-comm-5', 'course-intern-comm', 'mod-1', 5, '៥. ការគ្រប់គ្រងពេលវេលា និងការចាត់អាទិភាពតាម Eisenhower Matrix', 'Workplace Time Management & Eisenhower Matrix', 'text', '• បែងចែកដាច់ស្រឡះរវាងការងារ «បន្ទាន់ (Urgent)» និងការងារ «សំខាន់ (Important)»។\n• អនុវត្តក្បួនបំបាត់ការងារខ្ជះខ្ជាយពេលវេលា ដើម្បីសម្រេចលទ្ធផលស្នូលប្រចាំថ្ងៃ។\n• កសាងទម្លាប់រៀបចំ Top 3 Priorities មុនពេលចាប់ផ្តើមធ្វើការរាល់ព្រឹក។', 'ការរវល់ (Being Busy) មិនមានន័យថាមានទិន្នផល (Being Productive) នោះទេ។ បុគ្គលិកជោគជ័យផ្តោតថាមពលលើការងារសំខាន់ៗដែលបង្កើតតម្លៃខ្ពស់បំផុតដល់ស្ថាប័ន។', '«ចាន់ណា ជាបុគ្គលិកថ្មីដែលតែងតែរត់ឆ្លេឆ្លាពេញមួយថ្ងៃ៖ ឆ្លើយតប Telegram ភ្លាមៗ ជួយទិញកាហ្វេសហការី និងមើលអ៊ីមែលគ្រប់ ៥ នាទី។ នៅម៉ោង ៥ ល្ងាច នាងអស់កម្លាំងខ្លាំង ប៉ុន្តែរបាយការណ៍វិភាគទិន្នន័យដែលប្រធានប្រគល់ឱ្យបែរជាមិនទាន់បានចាប់ផ្តើមធ្វើសោះ។ ប្រធានផ្នែកបានហៅចាន់ណាមកណែនាំអំពីតារាង Eisenhower Matrix ដោយបង្រៀនឱ្យនាងបិទសំឡេង Notification ពេលកំពុងធ្វើកិច្ចការសំខាន់បំផុត។ ក្រោយពីអនុវត្តក្បួននេះ ចាន់ណាបញ្ចប់ការងារស្នូលបានមុនថ្ងៃត្រង់ជារៀងរាល់ថ្ងៃ។»', '✅ របៀបចាត់ចែងការងារ ៤ ប្រអប់៖\n១. បន្ទាន់ & សំខាន់៖ ធ្វើភ្លាមៗ (Do First - វិបត្តិ, Deadline ថ្ងៃនេះ)។\n២. មិនបន្ទាន់ តែសំខាន់៖ កំណត់ម៉ោងធ្វើច្បាស់លាស់ (Schedule - ផែនការយុទ្ធសាស្ត្រ, ការរៀនសូត្រ)។\n៣. បន្ទាន់ តែមិនសំខាន់៖ ផ្ទេរភារកិច្ចបើអាច (Delegate - ការឆ្លើយសារសួរព័ត៌មានទូទៅ)។\n៤. មិនបន្ទាន់ & មិនសំខាន់៖ លុបចោលទាំងស្រុង (Eliminate - ការអង្គុយអូសបណ្តាញសង្គមឥតប្រយោជន៍)។', 'សរសេរបញ្ជីការងារ ៥ មុខដែលអ្នកត្រូវធ្វើនៅថ្ងៃស្អែក ហើយចាត់ចូលក្នុងប្រអប់ទាំង ៤ នៃ Eisenhower Matrix។', 'តើអ្នកចំណាយពេលប៉ុន្មានម៉ោងក្នុងមួយថ្ងៃលើការងារដែលមិនបង្កើតផលពិតប្រាកដដល់គោលដៅរបស់អ្នក?', '🎯 សកម្មភាពថ្ងៃនេះ៖ កំណត់កិច្ចការ Top 1 នៃថ្ងៃនេះ ហើយចំណាយពេល ៦០ នាទីផ្តោតតែលើវាដោយមិនបើកបណ្តាញសង្គម។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-comm-5', 'lesson-comm-5', 'នៅម៉ោង ៩ ព្រឹក អ្នកត្រូវបញ្ចប់របាយការណ៍លក់ប្រចាំខែ (Deadline ម៉ោង ១១ ព្រឹក) ស្រាប់តែមានមិត្តរួមការងារម្នាក់មកសុំឱ្យអ្នកជួយរៀបចំតុប្រជុំ។ តើអ្នកគួរឆ្លើយតបបែបណា?', 'You have a critical report due at 11 AM. A colleague asks you to help arrange meeting chairs. How should you respond?', '["A. ឈប់ធ្វើរបាយការណ៍ ហើយទៅជួយរៀបចំតុរហូតដល់ម៉ោង ១១ ដើម្បីកុំឱ្យខូចចិត្តគេ។","B. ឆ្លើយតបដោយសុភាព៖ «ខ្ញុំកំពុងជាប់របាយការណ៍បន្ទាន់ Deadline ម៉ោង ១១។ ក្រោយម៉ោង ១១ ខ្ញុំនឹងអាចជួយបងបាន ឬបងអាចសួរទៅប្អូន X បានទេ?»","C. ស្រែកស្តីបន្ទោសឱ្យគាត់ថាគ្មានការយល់ចិត្ត។"]', '["A. Drop the report and help set up tables to please them.","B. Politely decline: \\"I have an urgent deadline at 11 AM. I can help after 11 or you can ask X.\\"","C. Yell at them for being inconsiderate."]', 1, 'ការពន្យល់៖ ជម្រើស B រក្សាអាទិភាពការងារស្នូលរបស់ខ្លួនផង និងឆ្លើយតបប្រកបដោយការគួរសមវិជ្ជាជីវៈផង។', 'Explanation: Politely protecting your core focus while offering alternatives shows mature professional boundaries.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-comm-6', 'course-intern-comm', 'mod-1', 6, '៦. ការរៀបចំរបាយការណ៍សង្ខេបប្រចាំថ្ងៃជូនប្រធាន (Daily Standup Reporting)', 'Writing High-Impact Daily Standup Reports', 'text', '• ចេះសរសេររបាយការណ៍សង្ខេបតាមរូបមន្ត 3P (Progress, Plans, Problems)។\n• បង្ហាញភាពជាម្ចាស់ការ និងតម្លាភាពក្នុងការងារជូនថ្នាក់ដឹកនាំ។\n• លើកឡើងពីឧបសគ្គការងារទាន់ពេល ដើម្បីទទួលបានការគាំទ្ររហ័ស។', 'ប្រធានផ្នែកមិនមានពេលអានរបាយការណ៍វែងអន្លាយនោះទេ។ របាយការណ៍សង្ខេបខ្លី ខ្លឹម និងចំចំណុចតាមទម្រង់ 3P គឺជាឧបករណ៍កសាងទំនុកចិត្តដ៏មានឥទ្ធិពលបំផុត។', '«ពិសិដ្ឋ ជាបុគ្គលិកហាត់ការផ្នែក IT Support។ រាល់ល្ងាចម៉ោង ៥:៣០ គាត់តែងតែផ្ញើសារសង្ខេប ៣ ចំណុចទៅកាន់ Telegram ក្រុម៖ អ្វីដែលបានធ្វើរួច (Progress), អ្វីដែលនឹងធ្វើស្អែក (Plans), និងបញ្ហាប្រឈមដែលត្រូវការជំនួយ (Problems)។ ប្រធានផ្នែកពេញចិត្តយ៉ាងខ្លាំងព្រោះមិនបាច់ចំណាយពេលតាមសួរដេញដោល ហើយដឹងច្បាស់ពីទិន្នផលការងាររបស់ពិសិដ្ឋ។ ត្រឹមតែ ៣ ខែ ពិសិដ្ឋត្រូវបានផ្តល់ការងារពេញសិទ្ធិមុនកាលកំណត់។»', '✅ គំរូរបាយការណ៍ 3P ស្តង់ដារវិជ្ជាជីវៈ៖\nជម្រាបសួរបង! របាយការណ៍ការងារថ្ងៃនេះរបស់ខ្ញុំ៖\n១. Progress (បានបញ្ចប់)៖ បានផ្ទៀងផ្ទាត់ទិន្នន័យអតិថិជន ៥០ នាក់ និងរៀបចំវិក្កយបត្ររួចរាល់។\n២. Plans (គម្រោងថ្ងៃស្អែក)៖ ទាក់ទងអតិថិជន ២០ នាក់បន្ទាប់ និងធ្វើបច្ចុប្បន្នភាពឯកសារប្រព័ន្ធ។\n៣. Problems (ឧបសគ្គ)៖ ប្រព័ន្ធអ៊ីនធឺណិតជាន់ទី ២ រអាក់រអួល បានរាយការណ៍ទៅ IT រួចរាល់។', 'អនុវត្តការសរសេររបាយការណ៍ 3P សម្រាប់កិច្ចការដែលអ្នកបានធ្វើនៅថ្ងៃនេះ។', 'តើប្រធានរបស់អ្នកដឹងច្បាស់ពីលទ្ធផលការងារប្រចាំថ្ងៃរបស់អ្នកកម្រិតណា? តើការផ្ញើសារ 3P អាចជួយកាត់បន្ថយការយល់ច្រឡំបានទេ?', '🎯 សកម្មភាពថ្ងៃនេះ៖ សាកល្បងរៀបចំរបាយការណ៍ 3P មួយច្បាប់ផ្ញើជូនប្រធានរបស់អ្នកនៅល្ងាចនេះ។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-comm-6', 'lesson-comm-6', 'តើគោលបំណងចម្បងនៃរបាយការណ៍សង្ខេបប្រចាំថ្ងៃ (Daily 3P Report) គឺជាអ្វី?', 'What is the primary purpose of a Daily 3P Report?', '["A. សរសេរអួតសរសើរខ្លួនឯងឱ្យប្រធានគិតថាខ្លួនរវល់ខ្លាំង។","B. បង្ហាញតម្លាភាពការងារ រក្សាការតម្រង់ទិសដៅជាមួយក្រុម និងលើកឡើងពីបញ្ហាដើម្បីដោះស្រាយទាន់ពេល។","C. ធ្វើគ្រាន់តែជាកិច្ចបំពេញកាតព្វកិច្ចដើម្បីកុំឱ្យត្រូវស្តីបន្ទោស។"]', '["A. Brag about how busy you are.","B. Provide work transparency, maintain alignment, and raise blockers early for resolution.","C. Pure compliance to avoid getting reprimanded."]', 1, 'ការពន្យល់៖ ជម្រើស B បង្ហាញពីគោលបំណងពិតប្រាកដនៃតម្លាភាពវិជ្ជាជីវៈ និងការសហការជាក្រុម។', 'Explanation: Daily reporting ensures transparent communication, alignment, and fast bottleneck removal.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-comm-7', 'course-intern-comm', 'mod-1', 7, '៧. ក្បួនគ្រប់គ្រងពេលវេលា «ការងារថ្ងៃនេះបញ្ចប់ថ្ងៃនេះ» (Haier OEC: Daily Clearing)', 'Haier OEC Model: Daily Clearing and Incremental Progress for Interns', 'text', '• យល់ដឹងពីទស្សនវិជ្ជាគ្រប់គ្រងបែបចិន Haier OEC (Overall, Every, Control & Clear) សម្រាប់ការងារប្រចាំថ្ងៃ។\n• បង្កើតទម្លាប់ «ការងារថ្ងៃនេះ ត្រូវបញ្ចប់ថ្ងៃនេះ និងល្អជាងម្សិលមិញ ១%» (日清日高)។\n• ចេះរៀបចំបញ្ជីកិច្ចការប្រចាំថ្ងៃ (Daily Checklist) ដើម្បីកុំឱ្យធ្លាក់ជំពាក់ការងារ ឬភ្លេចភ្លាំង។', 'ទស្សនវិជ្ជាគ្រប់គ្រងដ៏ល្បីល្បាញរបស់ក្រុមហ៊ុនយក្ស Haier (ដឹកនាំដោយ Zhang Ruimin) គឺ OEC (日事日毕，日清日高)៖ ការងារថ្ងៃនេះត្រូវតែបោសសម្អាតបញ្ចប់ឱ្យហើយក្នុងថ្ងៃនេះ ហើយរាល់ថ្ងៃត្រូវតែមានការរីកចម្រើនយ៉ាងហោចណាស់ ១%។ សម្រាប់បុគ្គលិកកម្មសិក្សាការងារ (Intern) និងបុគ្គលិកថ្មី ការមិនពន្យារពេល និងការធ្វើបញ្ជីត្រួតពិនិត្យការងារមុនចេញទៅផ្ទះ គឺជាគ្រឹះនៃភាពជឿជាក់ខ្ពស់បំផុត។', '«កញ្ញា មុនីនាថ ចូលធ្វើការជាបុគ្គលិកកម្មសិក្សាផ្នែករដ្ឋបាលនៅក្រុមហ៊ុននាំចូលទំនិញមួយនៅរាជធានីភ្នំពេញ។ ដំបូងឡើយ នាងតែងតែគិតថាការងារដែលធ្វើមិនទាន់ចាំទុកធ្វើស្អែក ព្រោះនាងជាត្រឹម Intern។ ជាលទ្ធផល ឯកសារទូទាត់វិក្កយបត្រថ្លៃដឹកជញ្ជូនត្រូវកកស្ទះ ធ្វើឱ្យឡានកុងតឺន័រមិនអាចបើកចេញពីកំពង់ផែបានទាន់ពេល។ ក្រោយពីទទួលការណែនាំពីអ្នកគ្រប់គ្រង នាងបានអនុវត្តក្បួន OEC ដោយឆ្លៀតពេល ១៥ នាទីមុនម៉ោង ៥ ល្ងាច ធ្វើបញ្ជីបោសសម្អាតការងារ (Daily Clear): ពិនិត្យថាគ្រប់អ៊ីមែល និងឯកសាររដ្ឋបាលក្នុងថ្ងៃនេះត្រូវបានផ្ញើ ឬបញ្ជូនបន្តរួចរាល់ ១០០%។ ត្រឹមតែ ៣ ខែ នាងត្រូវបានក្រុមហ៊ុនទទួលស្គាល់ថាជាបុគ្គលិកថ្មីដែលមានរបៀបរៀបរយបំផុត និងត្រូវបានតម្លើងជាបុគ្គលិកពេញសិទ្ធិមុនកាលកំណត់។»', '✅ គំរូបញ្ជីបោសសម្អាតការងារប្រចាំថ្ងៃ (OEC 15-Minute Daily Clear Checklist)៖\n១. [Inbox Zero]៖ ពិនិត្យអ៊ីមែល និងសារ Telegram ទាំងអស់ថាតើមានសារណាដែលយើងជំពាក់ការឆ្លើយតបដែរឬទេ?\n២. [Pending Tasks]៖ ការងារណាដែលមិនទាន់រួច ត្រូវផ្ញើសារប្រាប់ប្រធានក្រុមជាមុនអំពីស្ថានភាព (Status update) មុនម៉ោងចេញទៅផ្ទះ។\n៣. [Tomorrow Plan]៖ កត់ត្រាកិច្ចការអាទិភាពធំៗ ៣ យ៉ាងសម្រាប់ថ្ងៃស្អែក លើសៀវភៅកំណត់ហេតុ។', 'នៅម៉ោង ៤:៤៥ នាទីល្ងាចថ្ងៃនេះ ចំណាយពេល ១៥ នាទីបិទកិច្ចការដែលនៅសេសសល់ និងសរសេរកិច្ចការអាទិភាពចំនួន ៣ សម្រាប់ព្រឹកថ្ងៃស្អែក។', 'តើអ្នកធ្លាប់មានទម្លាប់ទុកការងារដែលពិបាកទៅធ្វើថ្ងៃស្អែករហូតដល់កកស្ទះដែរឬទេ? តើអ្នកអាចផ្លាស់ប្តូរទម្លាប់នេះដោយរបៀបណា?', '🎯 សកម្មភាពថ្ងៃនេះ៖ អនុវត្តការបោសសម្អាតការងារ ១៥ នាទីមុនចេញទៅផ្ទះ ធានាថាគ្មានសារការងារដែលមិនទាន់បានឆ្លើយតប។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-comm-7', 'lesson-comm-7', 'តាមទស្សនវិជ្ជា Haier OEC តើអ្វីជាអត្ថន័យស្នូលនៃពាក្យថា «日清日高» (Daily Clearing, Daily Rising)?', 'According to Haier OEC philosophy, what is the core meaning of Daily Clearing and Daily Rising?', '["A. ការងារដែលពិបាកត្រូវរុញឱ្យអ្នកដទៃធ្វើ ហើយការងារស្រួលទុកធ្វើថ្ងៃស្អែក។","B. ការងារថ្ងៃនេះត្រូវតែបញ្ចប់ឱ្យដាច់ស្រេចក្នុងថ្ងៃនេះ ហើយរាល់ថ្ងៃត្រូវកែលម្អឱ្យប្រសើរជាងម្សិលមិញ។","C. ធ្វើការងារតែពេលណាដែលប្រធានមកឈរមើលពីក្រោយខ្នង។"]', '["A. Push difficult tasks to others and leave easy tasks for tomorrow.","B. Complete today tasks today without backlog, improving incrementally every day.","C. Work only when the manager is watching closely."]', 1, 'ការពន្យល់៖ ក្បួន Haier OEC បង្រៀនឱ្យយើងបោសសម្អាតកិច្ចការប្រចាំថ្ងៃ មិនទុកឱ្យកកស្ទះ និងអភិវឌ្ឍសមត្ថភាពខ្លួនឯងបន្តិចម្តងៗជារៀងរាល់ថ្ងៃ។', 'Explanation: Haier OEC emphasizes closing all daily open loops and driving 1% daily self-improvement.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-comm-8', 'course-intern-comm', 'mod-1', 8, '៨. ភាពជាម្ចាស់ការ និងការយល់ចិត្តក្រុម (Alibaba: Ownership & Empathy)', 'Workplace Ownership & Building Trust: The Alibaba Cultural Mindset', 'text', '• យល់ដឹងពីផ្នត់គំនិតភាពជាម្ចាស់ការ (Ownership Mindset) មិនមែនគ្រាន់តែជាអ្នកធ្វើការតាមបញ្ជា (Task Taker)។\n• រៀនសង្កេតបរិយាកាស និងតម្រូវការរបស់ក្រុមដោយមិនចាំបាច់រង់ចាំគេប្រាប់គ្រប់ជំហាន។\n• បង្កើតទំនុកចិត្តជាមួយរៀមច្បង និងថ្នាក់ដឹកនាំតាមរយៈការជួយជ្រោមជ្រែងកិច្ចការរួម។', 'នៅក្រុមហ៊ុន Alibaba ស្ថាបនិក Jack Ma តែងតែលើកឡើងថា៖ «កុំធ្វើជាមនុស្សដែលរង់ចាំតែបញ្ជា ត្រូវធ្វើជាមនុស្សដែលឃើញបញ្ហាហើយចូលរួមដោះស្រាយ»។ សម្រាប់បុគ្គលិកកម្មសិក្សា ភាពខុសគ្នារវាងអ្នកដែលទទួលបានការតម្លើងតំណែង និងអ្នកដែលត្រូវបានគេបំភ្លេច គឺ «ភាពជាម្ចាស់ការ» (Ownership) — ការគិតមួយជំហានមុនប្រធាន និងការយកចិត្តទុកដាក់លើជោគជ័យរបស់ក្រុមទាំងមូល។', '«ក្នុងអំឡុងពេលរៀបចំពិធីសម្ពោធផលិតផលថ្មីមួយរបស់ក្រុមហ៊ុនអចលនទ្រព្យ លោក ពិសិដ្ឋ ជាបុគ្គលិកកម្មសិក្សាផ្នែកទីផ្សារ។ ពេលភ្លៀងធ្លាក់ភ្លាមៗ ទឹកបានហូរចូលមាត់ទ្វារសាលប្រជុំ។ ខណៈដែលបុគ្គលិកមួយចំនួនឈរមើល និងរង់ចាំអ្នកអនាម័យមកជូត ពិសិដ្ឋបានរត់ទៅយកកន្សែង និងស្បែកជើងជូតមកទប់ទឹកភ្លាមៗ ដើម្បីកុំឱ្យភ្ញៀវកិត្តិយសរអិលដួល។ ទង្វើដ៏ម្ចាស់ការ និងមិនប្រកាន់ការងារនេះ ត្រូវបានអគ្គនាយកមើលឃើញផ្ទាល់ភ្នែក។ ក្រោយពិធីចប់ អគ្គនាយកបានកោតសរសើរពិសិដ្ឋនៅចំពោះមុខបុគ្គលិកទាំងអស់ ហើយបានផ្តល់កិច្ចសន្យាការងារពេញសិទ្ធិភ្លាមៗជាមួយនឹងប្រាក់ខែខ្ពស់ជាងស្តង់ដារ។»', '✅ របៀបបង្ហាញភាពជាម្ចាស់ការក្នុងការងារប្រចាំថ្ងៃ៖\n• ជំនួសឱ្យការនិយាយថា៖ «ការងារហ្នឹងមិនមែននៅក្នុង Job Description ខ្ញុំទេ!»\n• ត្រូវនិយាយថា៖ «ការងារនេះខ្ញុំមិនទាន់ធ្លាប់ធ្វើទេ ប៉ុន្តែខ្ញុំរីករាយនឹងរៀនសូត្រ និងជួយសម្រាលបន្ទុកក្រុម។ តើបងត្រូវការឱ្យខ្ញុំជួយត្រង់ណាខ្លះ?»', 'ស្វែងរកកិច្ចការតូចមួយក្នុងក្រុមរបស់អ្នកនៅថ្ងៃនេះ (ដូចជាការជួយរៀបចំឯកសារ ឬជួយបង្រួបបង្រួមទិន្នន័យ) ហើយចូលរួមជួយដោយស្ម័គ្រចិត្ត។', 'តើអ្នកធ្លាប់មានអារម្មណ៍ថា «មិនមែនការងារខ្ញុំ ខ្ញុំមិនខ្វល់» ដែរឬទេ? តើផ្នត់គំនិតនោះប៉ះពាល់ដល់ឱកាសរីកចម្រើនរបស់អ្នកយ៉ាងដូចម្តេច?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ជួយសម្រាលការងារសមាជិកម្នាក់ក្នុងក្រុមយ៉ាងហោច ១ កិច្ចការដោយមិនចាំបាច់រង់ចាំការស្នើសុំ។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-comm-8', 'lesson-comm-8', 'នៅពេលអ្នកឃើញកិច្ចការរួមរបស់ក្រុមកំពុងជួបការកកស្ទះ តើឥរិយាបថណាដែលបង្ហាញពីភាពជាម្ចាស់ការ (Ownership)?', 'When you notice team tasks getting bottlenecked, what behavior demonstrates true ownership?', '["A. អង្គុយស្ងៀមធ្វើតែការងារផ្ទាល់ខ្លួន ព្រោះខ្លាចហត់បន្ថែមដោយគ្មានប្រាក់បន្ថែម។","B. ចូលរួមសួរនាំ និងស្ម័គ្រចិត្តជួយសម្រាលបន្ទុកក្រុមតាមលទ្ធភាព ដើម្បីឱ្យកិច្ចការរួមសម្រេចបាន។","C. បន្ទោសសមាជិកក្រុមដែលធ្វើការយឺតយ៉ាវនៅលើបណ្តាញសង្គម។"]', '["A. Sit passively and do only personal tasks to avoid extra work.","B. Inquire actively and volunteer to help alleviate bottlenecks for the collective success.","C. Complain about slow teammates on social media."]', 1, 'ការពន្យល់៖ ភាពជាម្ចាស់ការ (Ownership) គឺជាការផ្តោតលើលទ្ធផលរួមរបស់ស្ថាប័ន មិនមែនគ្រាន់តែការពារព្រំដែនតូចចង្អៀតរបស់ខ្លួនឯងនោះទេ។', 'Explanation: Ownership means prioritizing the collective mission over rigid individual boundaries.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-comm-9', 'course-intern-comm', 'mod-1', 9, '៩. សិល្បៈនៃការកត់ត្រាកិច្ចប្រជុំ និងរៀបចំឯកសារការងារ (Meeting Minutes & Documentation)', 'Professional Meeting Minutes & Workplace Documentation Mastery', 'text', '• ចេះកត់ត្រាកិច្ចប្រជុំ (Meeting Minutes) តាមទម្រង់ Action-Item Matrix (អ្នកណា ធ្វើអ្វី ពេលណា)។\n• រៀនស្រង់ចំណុចគន្លឹះ និងសេចក្តីសម្រេចចិត្តដោយមិនកត់ត្រាតាមពាក្យសម្តីឥតប្រយោជន៍។\n• កសាងប្រព័ន្ធរក្សាទុកឯកសារឌីជីថល (Google Drive/OneDrive) ដែលមានរបៀបរៀបរយ និងងាយស្រួលស្វែងរក។', 'នៅក្រុមហ៊ុនបច្ចេកវិទ្យាយក្សដូចជា Huawei ការកត់ត្រាកិច្ចប្រជុំមិនមែនជាការសរសេរតាមគ្រប់ពាក្យសម្តីនោះទេ ប៉ុន្តែជាការកត់ត្រា «សេចក្តីសម្រេចចិត្ត និងកិច្ចសន្យាសកម្មភាព» (Decisions & Action Items)។ បុគ្គលិកដែលចេះកត់ត្រាកិច្ចប្រជុំបានច្បាស់លាស់ គឺជាមនុស្សដែលគ្រប់គ្រងដំណើរការការងារ និងជាមនុស្សដំបូងគេដែលថ្នាក់ដឹកនាំស្វែងរកនៅពេលត្រូវការទិន្នន័យសំខាន់។', '«ក្នុងកិច្ចប្រជុំប្រចាំខែរបស់ក្រុមហ៊ុនចែកចាយគ្រឿងសំណង់មួយ លោក តារា ជា Intern ត្រូវបានចាត់តាំងឱ្យកត់ត្រាកិច្ចប្រជុំ។ ជំនួសឱ្យការសរសេររៀបរាប់វែងអន្លាយ ៤ ទំព័រដែលគ្មានអ្នកណាអាន តារាបានប្រើទម្រង់តារាង ៣ ជួរខ្លី៖ ១. បញ្ហាដែលបានសម្រេច ២. សកម្មភាពបន្ទាប់ (Action Items) ៣. អ្នកទទួលខុសត្រូវ និងថ្ងៃកំណត់ (PIC & Deadline)។ ក្រោយប្រជុំចប់ត្រឹមតែ ៣០ នាទី គាត់បានផ្ញើសារសង្ខេបនេះចូលក្នុង Group Telegram និងអ៊ីមែល។ ប្រធាននាយកដ្ឋានមានការស្ងើចសរសើរយ៉ាងខ្លាំង ព្រោះសមាជិកទាំងអស់ដឹងច្បាស់ពីអ្វីដែលត្រូវធ្វើដោយមិនបាច់សួរដដែលៗ។»', '✅ ទម្រង់កត់ត្រាកិច្ចប្រជុំកម្រិតស្តង់ដារ (Action-Oriented MoM Template)៖\n• [កាលបរិច្ឆេទ & គោលបំណង]៖ កិច្ចប្រជុំរៀបចំយុទ្ធនាការ Water Festival (ថ្ងៃទី 15/10)\n• [សេចក្តីសម្រេចសំខាន់]៖ យល់ព្រមជ្រើសរើស Agency A សម្រាប់ផលិតវីដេអូផ្សព្វផ្សាយ\n• [តារាងសកម្មភាព Action Matrix]៖\n  - ភារកិច្ច៖ ចុះកិច្ចសន្យាជាមួយ Agency | អ្នកទទួលខុសត្រូវ៖ បង វីរៈ | Deadline: ថ្ងៃសុក្រ ម៉ោង 3 រសៀល\n  - ភារកិច្ច៖ រៀបចំប្លង់ថត | អ្នកទទួលខុសត្រូវ៖ កញ្ញា លីដា | Deadline: ថ្ងៃចន្ទ ម៉ោង 10 ព្រឹក', 'អនុវត្តការសរសេរបញ្ជីសង្ខេប Action Items ពីកិច្ចប្រជុំ ឬការពិភាក្សាការងារបន្ទាប់របស់អ្នក រួចផ្ញើជូនប្រធានក្រុមពិនិត្យ។', 'តើអ្នកធ្លាប់ជួបកិច្ចប្រជុំដែលជជែកគ្នាច្រើនម៉ោង ប៉ុន្តែចប់ទៅគ្មានអ្នកណាដឹងថាត្រូវធ្វើអ្វីបន្តដែរឬទេ? តើអ្នកអាចជួយកែប្រែស្ថានភាពនោះយ៉ាងដូចម្តេច?', '🎯 សកម្មភាពថ្ងៃនេះ៖ កត់ត្រាកិច្ចប្រជុំបន្ទាប់របស់អ្នកតាមទម្រង់ Action Items Matrix ហើយចែករំលែកដល់ក្រុមក្នុងរយៈពេល ១ ម៉ោងក្រោយប្រជុំចប់។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-comm-9', 'lesson-comm-9', 'តើធាតុផ្សំដែលសំខាន់បំផុតនៅក្នុងកំណត់ហេតុកិច្ចប្រជុំ (Meeting Minutes) ប្រកបដោយវិជ្ជាជីវៈគឺជាអ្វី?', 'What is the most critical component of professional action-oriented meeting minutes?', '["A. ការកត់ត្រារាល់ពាក្យកំប្លែង និងការជជែកគ្នាលេងក្នុងកិច្ចប្រជុំឱ្យបានវែងបំផុត។","B. តារាងសកម្មភាពច្បាស់លាស់ (Action Items) ដែលបញ្ជាក់ពី អ្នកទទួលខុសត្រូវ និងកាលបរិច្ឆេទបញ្ចប់ (Who, What, When)។","C. ទុកកំណត់ហេតុចោលលើតុដោយមិនចាំបាច់ផ្ញើជូនអ្នកចូលរួមប្រជុំ។"]', '["A. Transcribing every joke and casual chat as verbatim as possible.","B. Clear action matrix specifying the task, person-in-charge (PIC), and hard deadline.","C. Leaving notes in a notebook without distributing to attendees."]', 1, 'ការពន្យល់៖ កំណត់ហេតុប្រជុំដែលមានប្រសិទ្ធភាពត្រូវផ្តោតលើលទ្ធផលសកម្មភាព៖ អ្នកណាត្រូវធ្វើអ្វី និងត្រូវបញ្ចប់ត្រឹមថ្ងៃណា (Who, What, When)។', 'Explanation: Action-oriented meeting minutes must specify accountability and delivery dates.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-comm-10', 'course-intern-comm', 'mod-1', 10, '១០. សុវត្ថិភាពទិន្នន័យ និងក្រមសីលធម៌ឌីជីថល (Workplace Data Privacy & Security)', 'Workplace Cybersecurity, Confidentiality & Digital Ethics for Beginners', 'text', '• យល់ដឹងពីសារៈសំខាន់នៃកិច្ចសន្យារក្សាការសម្ងាត់ (NDA) និងការការពារទិន្នន័យអតិថិជន។\n• ជៀសវាងការបង្ហោះរូបភាពឯកសារការងារ ឬអេក្រង់កុំព្យូទ័រលើបណ្តាញសង្គមផ្ទាល់ខ្លួន (Facebook, TikTok)។\n• អនុវត្តទម្លាប់ចាក់សោអេក្រង់ (Win+L / Cmd+Ctrl+Q) និងការប្រើប្រាស់ពាក្យសម្ងាត់រឹងមាំ (2FA)។', 'នៅក្នុងយុគសម័យឌីជីថល ទិន្នន័យគឺជាទ្រព្យសម្បត្តិដ៏មានតម្លៃបំផុតរបស់ក្រុមហ៊ុន។ កំហុសឆ្គងបន្តិចបន្តួចដូចជាការថតរូបតុធ្វើការបង្ហោះ Stories លើ Instagram ដោយជាប់ឯកសារបញ្ជីឈ្មោះអតិថិជន ឬលេខទូរស័ព្ទ អាចបណ្តាលឱ្យក្រុមហ៊ុនរងបណ្តឹងផ្លូវច្បាប់ និងធ្វើឱ្យអ្នកត្រូវបណ្តេញចេញភ្លាមៗ។ វិជ្ជាជីវៈចាប់ផ្តើមពីការការពារការសម្ងាត់របស់ស្ថាប័ន។', '«កញ្ញា សុជាតា ជាបុគ្គលិកកម្មសិក្សាផ្នែកធនធានមនុស្ស (HR Intern) នៅក្រុមហ៊ុនបច្ចេកវិទ្យាមួយ។ ដោយក្តីរំភើបដែលបានចូលធ្វើការនៅការិយាល័យស្អាត នាងបានថតរូប Selfie នៅតុធ្វើការរួចបង្ហោះលើ Story ហ្វេសប៊ុក។ ប៉ុន្តែនៅពីក្រោយខ្នងនាង អេក្រង់កុំព្យូទ័រកំពុងបើកបង្ហាញតារាងប្រាក់ខែរបស់បុគ្គលិកទាំងអស់ក្នុងក្រុមហ៊ុន។ មិត្តភក្តិម្នាក់បានថតអេក្រង់នោះទុក ហើយចែករំលែកបន្ត។ ត្រឹមតែមួយយប់ រឿងរ៉ាវបានបែកធ្លាយពេញក្រុមហ៊ុន បង្កជាជម្លោះផ្ទៃក្នុងធ្ងន់ធ្ងររវាងបុគ្គលិកចាស់ និងថ្មី។ ក្រុមហ៊ុនត្រូវបង្ខំចិត្តបញ្ចប់កិច្ចសន្យាការងាររបស់សុជាតាភ្លាមៗដោយសារការបំពានក្រមសីលធម៌សម្ងាត់ធ្ងន់ធ្ងរ។»', '✅ ច្បាប់ដែក ៣ យ៉ាងសម្រាប់សុវត្ថិភាពទិន្នន័យការងារ៖\n១. [Screen Lock]៖ ក្រោកពីតុធ្វើការកាលណា ត្រូវចុចចាក់សោអេក្រង់កុំព្យូទ័រជានិច្ច (Windows: ចុច Win + L | Mac: ចុច Cmd + Ctrl + Q)។\n២. [No Social Media Leak]៖ ដាច់ខាតមិនត្រូវថតរូបជាប់ឯកសារ ប្លង់គម្រោង ឬតួលេខហិរញ្ញវត្ថុបង្ហោះលើបណ្តាញសង្គមឡើយ។\n៣. [Phishing Awareness]៖ មិនត្រូវចុច Link ចម្លែកៗក្នុងអ៊ីមែល ឬទាញយក File គួរឱ្យសង្ស័យចូលក្នុងកុំព្យូទ័រក្រុមហ៊ុនជាដាច់ខាត។', 'ពិនិត្យកុំព្យូទ័រការងាររបស់អ្នកថ្ងៃនេះ៖ បើកដំណើរការ Two-Factor Authentication (2FA) លើគណនីអ៊ីមែលការងារ និងសាកល្បងអនុវត្តទម្លាប់ Lock Screen រាល់ពេលក្រោកពីតុ។', 'តើអ្នកធ្លាប់ធ្វេសប្រហែសក្នុងការចាក់សោអេក្រង់កុំព្យូទ័រ ឬទុកឯកសារសំខាន់ចោលលើតុដែរឬទេ? តើអ្នកនឹងកែប្រែទម្លាប់នេះដោយរបៀបណា?', '🎯 សកម្មភាពថ្ងៃនេះ៖ កំណត់ Hotkey លើកុំព្យូទ័ររបស់អ្នកសម្រាប់ Lock Screen និងអនុវត្តវាឱ្យក្លាយជាទម្លាប់ស្វ័យប្រវត្តិចាប់ពីថ្ងៃនេះតទៅ។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-comm-10', 'lesson-comm-10', 'តើទង្វើមួយណាដែលចាត់ទុកថាជាការបំពានក្រមសីលធម៌រក្សាការសម្ងាត់របស់ស្ថាប័ន (Confidentiality Breach)?', 'Which action is considered a serious breach of organizational confidentiality?', '["A. ចាក់សោអេក្រង់កុំព្យូទ័ររាល់ពេលដើរចេញទៅញ៉ាំកាហ្វេ។","B. ថតរូបឯកសារផ្ទៃក្នុង ឬតារាងព័ត៌មានអតិថិជនបង្ហោះលើបណ្តាញសង្គមផ្ទាល់ខ្លួន។","C. ប្តូរពាក្យសម្ងាត់គណនីការងាររៀងរាល់ ៣ ខែម្តង។"]', '["A. Locking your screen every time you step away for coffee.","B. Taking photos of internal documents or client lists and posting to personal social media.","C. Changing your workplace password every 3 months."]', 1, 'ការពន្យល់៖ ការបង្ហោះទិន្នន័យផ្ទៃក្នុងរបស់ក្រុមហ៊ុន ឬព័ត៌មានអតិថិជនលើបណ្តាញសង្គម គឺជាការបំពានច្បាប់រក្សាការសម្ងាត់យ៉ាងធ្ងន់ធ្ងរ (NDA Violation)។', 'Explanation: Exposing confidential company documents or client data on social media is a severe NDA breach.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-eq-1', 'course-eq-critical', 'mod-1', 1, '១. ការគ្រប់គ្រងអារម្មណ៍ និងសម្ពាធក្រោមភាពតានតឹង (Emotional Regulation & Grace Under Pressure)', 'Emotional Regulation & Composure Under Stress', 'text', '• យល់ដឹងពីបាតុភូត Amygdala Hijack នៅកន្លែងធ្វើការ (ការផ្ទុះកំហឹងភ្លាមៗដោយគ្មានការគិត)។\n• អនុវត្តរូបមន្ត STOP (Stop, Take a breath, Observe, Proceed) ពេលជួបសម្ពាធខ្លាំង។\n• បង្កើនភាពស្ងប់ស្ងាត់ដើម្បីធ្វើការសម្រេចចិត្តប្រកបដោយតក្កវិជ្ជា។', 'ភាពឆ្លាតវៃខាងផ្លូវចិត្ត (EQ) មិនមែនជាការសង្កត់អារម្មណ៍មិនឱ្យកើតមាននោះទេ ប៉ុន្តែជាសមត្ថភាពដឹងពីអារម្មណ៍ខ្លួនឯង ហើយជ្រើសរើសការឆ្លើយតបដែលឆ្លាតវៃជំនួសឱ្យប្រតិកម្មតបត។', '«រតនៈ ជាអ្នកសម្របសម្រួលគម្រោង (Project Coordinator) នៃក្រុមហ៊ុនដឹកជញ្ជូន។ ថ្ងៃមួយ ប្រព័ន្ធបច្ចេកវិទ្យាធ្លាក់ចុះ អតិថិជន VIP ម្នាក់បានទូរស័ព្ទមកស្រែកគំហក និងប្រើពាក្យប្រមាថយ៉ាងខ្លាំង។ រតនៈមានអារម្មណ៍ថាបេះដូងលោតញាប់ និងចង់ស្រែកតបតវិញភ្លាមៗ។ ប៉ុន្តែគាត់បានដកដង្ហើមវែងៗ ផ្អាក ៣ វិនាទី រួចឆ្លើយតបដោយសំឡេងស្ងប់ស្ងាត់៖ "ខ្ញុំយល់ច្បាស់ពីការខកចិត្តរបស់បង។ ឥឡូវនេះ ខ្ញុំកំពុងតាមដានកញ្ចប់ទំនិញរបស់បងដោយផ្ទាល់ជាមួយប្រធានឃ្លាំង ហើយខ្ញុំនឹងផ្ញើតេឡេក្រាមបញ្ជាក់ជូនបងក្នុងរយៈពេល ១០ នាទី"។ អតិថិជនបានបន្ទន់សំឡេងភ្លាមៗ ហើយក្រោយមកថែមទាំងបានផ្ញើសារសុំទោសរតនៈវិញផងដែរ។»', '✅ យុទ្ធសាស្ត្រ ៤ ជំហានពេលជួបសម្ពាធ៖\n១. STOP៖ ផ្អាកការវាយអត្ថបទ ឬការនិយាយភ្លាមៗ។\n២. BREATHE៖ ដកដង្ហើមចូលតាមច្រមុះ ៤ វិនាទី និងដកចេញយឺតៗ ៦ វិនាទី។\n៣. OBSERVE៖ សង្កេតមើល៖ "តើខ្ញុំកំពុងខឹង ឬភ័យខ្លាច? តើគោលដៅពិតប្រាកដរបស់ខ្ញុំគឺអ្វី?"\n៤. PROCEED៖ ឆ្លើយតបដោយផ្អែកលើដំណោះស្រាយ មិនមែនលើអារម្មណ៍។', 'អនុវត្តបច្ចេកទេសប្រអប់ដង្ហើម (Box Breathing 4-4-4) រយៈពេល ២ នាទី នៅពេលអ្នកមានអារម្មណ៍តានតឹងជាមួយការងារ។', 'តើកត្តាជំរុញ (Trigger) អារម្មណ៍ខឹងរបស់អ្នកនៅកន្លែងធ្វើការគឺជាអ្វី? តើអ្នកអាចដឹងខ្លួនមុនពេលអារម្មណ៍នោះផ្ទុះឡើងដោយរបៀបណា?', '🎯 សកម្មភាពថ្ងៃនេះ៖ នៅពេលមានសារ ឬអ៊ីមែលដែលធ្វើឱ្យអ្នកខឹង សូមផ្អាកយ៉ាងហោច ៥ នាទីសិនមុននឹងសរសេរតបត។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-eq-1', 'lesson-eq-1', 'នៅពេលអតិថិជន ឬសហការីកំពុងស្រែកបន្ទោសអ្នកដោយកំហឹង តើការឆ្លើយតបបែបណាដែលបង្ហាញពី EQ ខ្ពស់បំផុត?', 'When a client or colleague is yelling at you angrily, what response reflects the highest EQ?', '["A. ស្រែកតបតវិញដើម្បីការពារកិត្តិយសខ្លួនឯងកុំឱ្យគេមើលងាយ។","B. ស្ងាត់ស្ងៀម ដកដង្ហើមវែងៗ ទទួលស្គាល់អារម្មណ៍ខកចិត្តរបស់គេ រួចបង្វែរការសន្ទនាទៅរកដំណោះស្រាយជាក់ស្តែង។","C. បិទទូរស័ព្ទ ឬដើរចេញភ្លាមៗដោយមិននិយាយអ្វីទាំងអស់។"]', '["A. Shout back to defend your pride.","B. Stay composed, acknowledge their frustration, and steer conversation toward concrete solutions.","C. Hang up or walk away abruptly without a word."]', 1, 'ការពន្យល់៖ ជម្រើស B បំបែករលកកំហឹងដោយការយល់ចិត្ត (De-escalation) និងរក្សាភាពជាអ្នកវិជ្ជាជីវៈខ្ពស់។', 'Explanation: De-escalating with empathy deactivates anger and keeps problem-solving intact.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-eq-2', 'course-eq-critical', 'mod-1', 2, '២. វិធីសាស្ត្រវិភាគរកឫសគល់នៃបញ្ហា 5 Whys (Root Cause Problem Solving in SME Context)', 'Root Cause Problem Solving with 5 Whys', 'text', '• បែងចែកដាច់រវាង "រោគសញ្ញាខាងក្រៅ (Symptom)" និង "ឫសគល់ពិតប្រាកដ (Root Cause)" នៃបញ្ហា។\n• អនុវត្តឧបករណ៍ 5 Whys លើបញ្ហាការងារជាក់ស្តែងក្នុងបរិបទអាជីវកម្មកម្ពុជា។\n• កសាងដំណោះស្រាយជាប្រព័ន្ធការពារកុំឱ្យបញ្ហាកើតឡើងដដែលៗ។', 'ការដោះស្រាយតែរោគសញ្ញាប្រៀបដូចជាការលេបថ្នាំបំបាត់ការឈឺក្បាលពេលមានជំងឺគ្រុនក្តៅ។ អ្នកដឹកនាំល្អតែងតែជីកកកាយរកឫសគល់ពិតប្រាកដ ដើម្បីដោះស្រាយម្តងចប់ជាស្ថាពរ។', '«ហាងលក់សម្ភារសំណង់មួយតែងតែដឹកជញ្ជូនទំនិញខុសឱ្យអតិថិជនរៀងរាល់សប្តាហ៍។ ពីមុន ម្ចាស់ហាងតែងតែស្តីបន្ទោស និងកាត់ប្រាក់ខែអ្នកបើកបរ (ដោះស្រាយរោគសញ្ញា)។ ក្រោយមក អ្នកគ្រប់គ្រងថ្មីបានអនុវត្ត 5 Whys៖\n• ហេតុអ្វីដឹកខុស? ដោយសារលើកទំនិញខុសកូដពីឃ្លាំង។\n• ហេតុអ្វីលើកខុសកូដ? ដោយសារក្រដាសកត់ត្រាការកម្ម៉ង់សរសេរដោយដៃអានមិនច្បាស់។\n• ហេតុអ្វីសរសេរដៃ? ដោយសារកុំព្យូទ័រនៅតុលក់គាំងមិនដំណើរការ។\n• ហេតុអ្វីកុំព្យូទ័រគាំងយូរហើយមិនជួសជុល? ដោយសារគ្មានអ្នកណាទទួលខុសត្រូវថែទាំ IT។\nឫសគល់ពិតប្រាកដមិនមែនអ្នកបើកបរខ្ជិលទេ ប៉ុន្តែដោយសារខ្វះការថែទាំប្រព័ន្ធ IT! ក្រោយពីជួសជុលកុំព្យូទ័រ និងបោះពុម្ពវិក្កយបត្រមាន Barcode កំហុសដឹកជញ្ជូនធ្លាក់ចុះដល់សូន្យ។»', '✅ របៀបប្រើ 5 Whys៖\nចោទសួរ "ហេតុអ្វី?" ជាបន្តបន្ទាប់យ៉ាងតិច ៥ ដង រហូតដល់ជួបនឹង "ចន្លោះប្រហោងនៃប្រព័ន្ធ (System Failure)" ឬ "កង្វះដំណើរការស្តង់ដារ (Lack of SOP)"។', 'ជ្រើសរើសបញ្ហាការងារមួយដែលធ្លាប់កើតឡើងក្នុងក្រុមរបស់អ្នក ហើយសរសេរ 5 Whys ស្វែងរកឫសគល់ពិតប្រាកដ។', 'តើមានបញ្ហាអ្វីខ្លះក្នុងស្ថាប័នរបស់អ្នកដែលកំពុងកើតឡើងដដែលៗរៀងរាល់ខែ? តើឫសគល់ពិតប្រាកដអាចមកពីកង្វះប្រព័ន្ធ ឬដំណើរការមិនច្បាស់លាស់ដែរឬទេ?', '🎯 សកម្មភាពថ្ងៃនេះ៖ គូសផែនទី 5 Whys លើបញ្ហាមួយដែលកំពុងរំខានអ្នកក្នុងសប្តាហ៍នេះ រួចរៀបចំដំណោះស្រាយប្រព័ន្ធ ១ យ៉ាង។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-eq-2', 'lesson-eq-2', 'របាយការណ៍លក់ប្រចាំខែតែងតែខុសទិន្នន័យជាប្រចាំ។ តើការអនុវត្តបែបណាដែលជាការដោះស្រាយបែបឫសគល់ (Root Cause)?', 'Monthly sales reports have recurring errors. What is a true root-cause solution?', '["A. ដាក់ទណ្ឌកម្ម និងកាត់ប្រាក់លើកទឹកចិត្តបុគ្គលិកដែលធ្វើខុស។","B. ស្វែងរកមូលហេតុប្រព័ន្ធ បង្កើតទម្រង់ Excel Template ដែលមានរូបមន្តស្វ័យប្រវត្ត និងរៀបចំការបណ្តុះបណ្តាលខ្លី។","C. ឱ្យបុគ្គលិកម្នាក់ទៀតជួយអង្គុយផ្ទៀងផ្ទាត់រាល់ល្ងាចដោយមិនកែប្រែប្រព័ន្ធ។"]', '["A. Penalize and deduct bonuses of the reporting staff.","B. Diagnose system flaws, automate template formulas, and provide short training.","C. Assign another person to manually audit every night without fixing templates."]', 1, 'ការពន្យល់៖ ជម្រើស B ដោះស្រាយឫសគល់តាមរយៈការកែលម្អប្រព័ន្ធ (Systemic fix) និងការអភិវឌ្ឍជំនាញ ដែលជួយការពារកំហុសជាអចិន្ត្រៃយ៍។', 'Explanation: Fixing templates and workflows prevents the recurring root cause permanently.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-eq-3', 'course-eq-critical', 'mod-1', 3, '៣. ការស្តាប់ដោយការយល់ចិត្ត និងការបញ្ចេញទស្សនៈប្រកបដោយតក្កវិជ្ជា (Active Listening & Empathy in Workplace)', 'Active Listening & Empathic Communication', 'text', '• អនុវត្តបច្ចេកទេស Paraphrasing (ឆ្លុះបញ្ចាំងអ្វីដែលគេនិយាយ) ដើម្បីបង្កើតការទុកចិត្ត។\n• បែងចែករវាងការស្តាប់ដើម្បីឆ្លើយតប (Listen to reply) និងការស្តាប់ដើម្បីយល់ចិត្ត (Listen to understand)។\n• បញ្ចេញមតិខ្វែងគំនិតដោយមិនធ្វើឱ្យប៉ះពាល់ដល់អារម្មណ៍អ្នកដទៃ។', 'មនុស្សភាគច្រើនមិនស្តាប់ដើម្បីយល់នោះទេ គឺស្តាប់ដើម្បីរង់ចាំដល់វេនខ្លួនឯងតបតវិញប៉ុណ្ណោះ។ អ្នកដែលចេះស្តាប់ដោយការយល់ចិត្ត តែងតែទទួលបានការគោរព និងអាចបញ្ចុះបញ្ចូលអ្នកដទៃបានយ៉ាងងាយស្រួល។', '«នៅក្នុងកិច្ចប្រជុំយុទ្ធសាស្ត្រលក់ ផ្នែកលក់ និងផ្នែកទីផ្សារប្រកែកគ្នាយ៉ាងខ្លាំង។ ផ្នែកលក់បន្ទោសថាទិន្នន័យអតិថិជន (Leads) មិនមានគុណភាព ខណៈដែលផ្នែកទីផ្សារបន្ទោសថាផ្នែកលក់ខ្ជិលទាក់ទង។ សុវណ្ណ បានធ្វើអន្តរាគមន៍ដោយប្រើការស្តាប់យល់ចិត្ត៖ "បងសំណាងមកពីផ្នែកលក់ បារម្ភថាកូនចៅបងចំណាយពេលច្រើនលើលេខដែលទាក់ទងមិនចូល មែនទេ? ចំណែកបងស្រីមុំមកពីផ្នែកទីផ្សារ បារម្ភថាយុទ្ធនាការផ្សព្វផ្សាយចំណាយលុយច្រើន តែគ្មានការតាមដានទាន់ពេល មែនទេ?"។ ភាគីទាំងពីរស្តាប់ហើយមានអារម្មណ៍ថាមានគេយល់ចិត្ត ក៏ឈប់ប្រកែក ហើយចាប់ផ្តើមកំណត់លក្ខណៈសម្បត្តិ Lead រួមគ្នា។»', '✅ គំរូឃ្លា Paraphrasing ដ៏មានឥទ្ធិពល៖\n• "ប្រសិនបើខ្ញុំយល់ត្រឹមត្រូវ អ្វីដែលបងកំពុងបារម្ភធំបំផុតគឺ... មែនទេ?"\n• "បងចង់មានន័យថា ប្រសិនបើយើងបន្ថែមបុគ្គលិកផ្នែកនេះ នោះការងារនឹងលឿនជាងមុន មែនទេ?"', 'នៅក្នុងកិច្ចសន្ទនាបន្ទាប់ សូមធ្វើការសង្ខេបអ្វីដែលដៃគូសន្ទនានិយាយ មុននឹងចាប់ផ្តើមបញ្ចេញមតិផ្ទាល់ខ្លួនរបស់អ្នក។', 'តើអ្នកជាមនុស្សចូលចិត្តស្តាប់ដើម្បីឆ្លើយតប ឬស្តាប់ដើម្បីយល់ចិត្តអ្នកដទៃ? តើការកែប្រែទម្លាប់នេះអាចជួយទំនាក់ទំនងការងាររបស់អ្នកយ៉ាងដូចម្តេច?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ស្តាប់សហការីម្នាក់និយាយឱ្យចប់ដោយមិនកាត់សម្តីសូម្បីតែម្តង រួចសង្ខេបចំណុចសំខាន់របស់គាត់ឡើងវិញ។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-eq-3', 'lesson-eq-3', 'សហការីម្នាក់មកត្អូញត្អែរជាមួយអ្នកថាគាត់ហត់នឿយ និងមានសម្ពាធការងារច្រើនពេក។ តើការឆ្លើយតបបែបណាដែលបង្ហាញពី Active Listening & Empathy?', 'A teammate vents to you that they are overwhelmed with work. What response reflects active listening?', '["A. និយាយកាត់ភ្លាមថា \\"ប៉ុណ្ណឹងមិនទាន់ហត់ទេ ខ្ញុំធ្វើការច្រើនជាងអ្នកឯងទ្វេដងផង!\\"","B. ស្តាប់ដោយយកចិត្តទុកដាក់ ឆ្លុះបញ្ចាំងអារម្មណ៍របស់គាត់ (\\"ខ្ញុំឃើញប្អូនខំប្រឹងខ្លាំងណាស់សប្តាហ៍នេះ\\") និងសួរថាតើអាចជួយសម្រាលចំណុចណាខ្លះ។","C. ប្រាប់គាត់ឱ្យលាលែងពីការងារភ្លាមទៅបើពិបាកពេក។"]', '["A. Interrupt saying \\"That is nothing, I work twice as hard as you!\\"","B. Listen attentively, validate their feeling, and ask how you can help lighten the load.","C. Tell them to quit immediately if it is too hard."]', 1, 'ការពន្យល់៖ ជម្រើស B ផ្តល់សុវត្ថិភាពផ្លូវចិត្ត (Psychological safety) និងកសាងចំណងសាមគ្គីភាពក្នុងក្រុមការងារ។', 'Explanation: Validating their feelings builds psychological safety and team trust.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-eq-4', 'course-eq-critical', 'mod-1', 4, '៤. ការយកឈ្នះលើ Imposter Syndrome និងការកសាង Growth Mindset', 'Overcoming Imposter Syndrome & Cultivating Growth Mindset', 'text', '• កំណត់សម្គាល់អារម្មណ៍គិតថាខ្លួនឯងមិនសក្តិសម (Imposter Syndrome)។\n• ប្តូរភាសាផ្ទៃក្នុងពី Fixed Mindset ទៅជា Growth Mindset ដោយប្រើពាក្យ "មិនទាន់ (Not Yet)"។\n• កសាងទំនុកចិត្តលើខ្លួនឯងតាមរយៈទិន្នន័យសមិទ្ធផលជាក់ស្តែង (Brag Sheet)។', 'បុគ្គលិកដែលមានសមត្ថភាពខ្ពស់ភាគច្រើនតែងតែមានអារម្មណ៍ថាខ្លួនឯងមិនពូកែគ្រប់គ្រាន់ ហើយខ្លាចគេចាប់បានថាមិនចេះ។ ការយល់ដឹងថាការមិនចេះគឺជាចំណុចចាប់ផ្តើមនៃការរៀនសូត្រ គឺជាគន្លឹះឆ្ពោះទៅកាន់ភាពជោគជ័យ។', '«ចរិយា ទទួលបានការតែងតាំងជា Senior Data Analyst ក្នុងវ័យ ២៥ ឆ្នាំ។ នាងតែងតែភ័យខ្លាចរាល់ពេលចូលរួមប្រជុំជាមួយនាយកប្រតិបត្តិ ដោយគិតថានាងឡើងតំណែងនេះដោយសារសំណាងល្អប៉ុណ្ណោះ។ នាងលែងហ៊ានបញ្ចេញមតិព្រោះខ្លាចនិយាយខុស។ ប្រធានរបស់នាងបានកត់សម្គាល់ឃើញ ហើយបានឱ្យនាងធ្វើលំហាត់មួយ៖ កត់ត្រាគម្រោងជោគជ័យទាំង ៥ ដែលនាងបានដឹកនាំក្នុងរយៈពេល ១ ឆ្នាំកន្លងមក ព្រមទាំងតួលេខចំណេញដែលក្រុមហ៊ុនទទួលបាន។ នៅពេលមើលឃើញទិន្នន័យជាក់ស្តែង ចរិយាដឹងខ្លួនថាសមត្ថភាពរបស់នាងពិតជាសក្តិសម ហើយនាងបានយកឈ្នះការភ័យខ្លាចនោះបានទាំងស្រុង។»', '✅ របៀបប្តូរផ្នត់គំនិត (Mindset Shifts)៖\n• Fixed Mindset៖ "ខ្ញុំមិនពូកែរឿងលេខនេះទេ ខ្ញុំធ្វើមិនកើតឡើយ។"\n• Growth Mindset៖ "ខ្ញុំមិនទាន់ស្ទាត់ជំនាញលើរឿងលេខនេះនៅឡើយទេ ប៉ុន្តែខ្ញុំអាចរៀន និងអនុវត្តបន្ថែមបាន។"', 'បង្កើតឯកសារ "Brag Sheet" សង្ខេបមួយ ដោយកត់ត្រាសមិទ្ធផលការងារ ៣ យ៉ាងដែលអ្នកមានមោទនភាពបំផុតក្នុងអាជីពរបស់អ្នក។', 'តើអ្នកធ្លាប់មានអារម្មណ៍ថាខ្លួនឯងមិនសក្តិសមនឹងតំណែង ឬការងារបច្ចុប្បន្នដែរឬទេ? តើសមិទ្ធផលពិតប្រាកដអ្វីខ្លះដែលអ្នកធ្លាប់សម្រេចបាន?', '🎯 សកម្មភាពថ្ងៃនេះ៖ កត់ត្រាសមិទ្ធផលជោគជ័យមួយរបស់អ្នកក្នុងសប្តាហ៍នេះចូលក្នុង Private Notes។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-eq-4', 'lesson-eq-4', 'នៅពេលត្រូវបានប្រគល់គម្រោងបច្ចេកវិទ្យាថ្មីដែលអ្នកមិនធ្លាប់ធ្វើពីមុនមក តើផ្នត់គំនិត Growth Mindset បែបណាដែលគួរប្រកាន់យក?', 'When assigned a brand-new project you have never done, what is the Growth Mindset perspective?', '["A. បដិសេធភ្លាមៗព្រោះខ្លាចធ្វើខុសហើយប៉ះពាល់ដល់កេរ្តិ៍ឈ្មោះខ្លួនឯង។","B. ទទួលយកដោយភាពស្មោះត្រង់ថាខ្លួនមិនទាន់ចេះគ្រប់ជ្រុងជ្រោយ ប៉ុន្តែត្រៀមខ្លួនស្រាវជ្រាវ និងសួរនាំអ្នកជំនាញដើម្បីរៀនសូត្រ។","C. ធ្វើពុតជាចេះគ្រប់យ៉ាង ហើយលួចធ្វើស្ងាត់ៗដោយមិនហ៊ានសួរអ្នកណា។"]', '["A. Reject immediately fearing failure and reputation damage.","B. Accept honestly acknowledging you do not know yet, but commit to researching and learning proactively.","C. Pretend you know everything and work secretly without asking anyone."]', 1, 'ការពន្យល់៖ ជម្រើស B បង្ហាញពីភាពក្លាហានក្នុងការរៀនសូត្រ (Vulnerability & Growth) ដែលជាចរិតលក្ខណៈស្នូលនៃបុគ្គលិកឆ្នើម។', 'Explanation: Embracing the learning curve with proactive honesty is the core of Growth Mindset.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-eq-5', 'course-eq-critical', 'mod-1', 5, '៥. ការវិភាគរកឫសគល់នៃបញ្ហាតាមវិធី 5 Whys & Fishbone Diagram', 'Root Cause Problem Solving with 5 Whys & Fishbone', 'text', '• ចេះស្វែងរកឫសគល់ពិតប្រាកដនៃបញ្ហា ដោយមិនដោះស្រាយត្រឹមតែរោគសញ្ញាខាងក្រៅ។\n• អនុវត្តក្បួនសួរដេញដោល «ហេតុអ្វី?» ៥ ដង (5 Whys Technique) លើឧបសគ្គការងារជាក់ស្តែង។\n• បង្កើតដំណោះស្រាយប្រកបដោយចីរភាព ដើម្បីកុំឱ្យបញ្ហាចាស់កើតឡើងដដែលៗ។', 'នៅពេលជួបបញ្ហា មនុស្សទូទៅតែងតែស្តីបន្ទោសមនុស្ស ឬប្រញាប់បិទបាំងរោគសញ្ញា។ អ្នកជំនាញពិតប្រាកដប្រើបច្ចេកទេស 5 Whys ដើម្បីស្វែងរកកំហុសក្នុងប្រព័ន្ធ ឬដំណើរការការងារ។', '«អតិថិជន VIP ម្នាក់បានខឹងសម្បាយ៉ាងខ្លាំងព្រោះការបញ្ជាទិញទំនិញយឺត ៣ ថ្ងៃ។ ប្រធានដំបូងចង់ស្តីបន្ទោសអ្នកបើកបរឡានដឹក។ ប៉ុន្តែរតនា (Senior Specialist) បានស្នើឱ្យប្រើវិធី 5 Whys៖\n១. ហេតុអ្វីទំនិញយឺត? ព្រោះឡានចេញយឺត។\n២. ហេតុអ្វីឡានចេញយឺត? ព្រោះបុគ្គលិកឃ្លាំងរៀបចំឥវ៉ាន់មិនទាន់។\n៣. ហេតុអ្វីរៀបចំមិនទាន់? ព្រោះវិក្កយបត្របញ្ជាទិញចេញយឺត។\n៤. ហេតុអ្វីចេញយឺត? ព្រោះកុំព្យូទ័រគណនេយ្យគាំងពេលចេញវិក្កយបត្រ។\n៥. ហេតុអ្វីកុំព្យូទ័រគាំង? ព្រោះមិនដែលបានធ្វើបច្ចុប្បន្នភាពប្រព័ន្ធសុវត្ថិភាពទាល់តែសោះ។\nលទ្ធផល៖ ឫសគល់បញ្ហាគឺប្រព័ន្ធ IT មិនមែនអ្នកបើកបរឡាននោះទេ។ ក្រុមហ៊ុនបានដោះស្រាយចំបញ្ហា និងចំណេញពេលវេលាយ៉ាងច្រើន។»', '✅ របៀបប្រើប្រាស់ 5 Whys ក្នុងកិច្ចប្រជុំ៖\n«មុនពេលយើងស្តីបន្ទោសបុគ្គលណាម្នាក់ តើយើងអាចសួរ "ហេតុអ្វី?" ជាមួយគ្នាដើម្បីរកមើលថាតើប្រព័ន្ធ ឬដំណើរការ (Process) ណាដែលត្រូវការការកែសម្រួល?»', 'ជ្រើសរើសកំហុសការងារមួយដែលទើបតែកើតឡើងក្នុងក្រុមរបស់អ្នក ហើយសាកល្បងសរសេរ 5 Whys ដើម្បីរកឫសគល់។', 'តើអ្នកធ្លាប់ដោះស្រាយបញ្ហាការងារមួយដដែលៗដោយសារមិនបានដោះស្រាយចំឫសគល់ដែរឬទេ?', '🎯 សកម្មភាពថ្ងៃនេះ៖ អនុវត្តការសួរ 5 Whys លើបញ្ហាកកស្ទះមួយក្នុងការងាររបស់អ្នកថ្ងៃនេះ។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-eq-5', 'lesson-eq-5', 'នៅពេលមានកំហុសឆ្គងកើតឡើងក្នុងគម្រោង តើអ្នកដែលមានជំនាញ Critical Thinking ខ្ពស់គួរធ្វើបែបណា?', 'When an error occurs in a project, what should someone with high Critical Thinking do?', '["A. ស្វែងរកមនុស្សដែលធ្វើខុស ហើយស្តីបន្ទោសជាសាធារណៈ។","B. ផ្តោតលើការវិភាគដំណើរការការងារ (Process) តាមរយៈវិធី 5 Whys ដើម្បីកែប្រែប្រព័ន្ធកុំឱ្យកើតឡើងម្តងទៀត។","C. លាក់បាំងកំហុសនោះដើម្បីកុំឱ្យថ្នាក់លើដឹង។"]', '["A. Find who made the mistake and publicly blame them.","B. Analyze the work process using 5 Whys to fix the root cause and prevent recurrence.","C. Conceal the mistake to protect team reputation."]', 1, 'ការពន្យល់៖ ជម្រើស B ផ្តោតលើការកែលម្អប្រព័ន្ធ (Systemic improvement) មិនមែនលើការវាយប្រហារបុគ្គលឡើយ។', 'Explanation: Focusing on process and root cause creates systemic solutions and psychological safety.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-eq-6', 'course-eq-critical', 'mod-1', 6, '៦. ការកសាងភាពធន់នឹងសម្ពាធការងារ និងការទប់ស្កាត់ការឆេះដួងចិត្ត (Emotional Resilience & Burnout)', 'Workplace Emotional Resilience & Burnout Prevention', 'text', '• យល់ដឹងពីសញ្ញាដំបូងនៃការឆេះដួងចិត្ត (Burnout Signs) និងសម្ពាធអារម្មណ៍អវិជ្ជមាន។\n• អនុវត្តបច្ចេកទេសបញ្ឈប់អារម្មណ៍តានតឹងភ្លាមៗ (Emotional Pause & Box Breathing)។\n• កសាងព្រំដែនសុខភាពរវាងការងារ និងជីវិតផ្ទាល់ខ្លួន (Work-Life Boundaries)។', 'ភាពជោគជ័យយូរអង្វែងក្នុងអាជីពមិនអាស្រ័យតែលើការរត់ប្រណាំងយ៉ាងលឿននោះទេ ប៉ុន្តែអាស្រ័យលើសមត្ថភាពរត់ម៉ារ៉ាតុងដោយមិនអស់កម្លាំង ឬបាក់ទឹកចិត្ត (Emotional Resilience)។', '«វណ្ណា ជាបុគ្គលិកគណនេយ្យជាន់ខ្ពស់។ ក្នុងរដូវកាលបិទបញ្ជីចុងឆ្នាំ គាត់ធ្វើការ ១៤ ម៉ោងក្នុងមួយថ្ងៃ គេងមិនលក់ ហើយចាប់ផ្តើមឆេវឆាវដាក់មិត្តរួមការងារ និងគ្រួសារ។ គាត់គិតចង់លាលែងពីការងារភ្លាមៗ។ ប្រធានផ្នែកបានសង្កេតឃើញ ហើយបានតម្រូវឱ្យវណ្ណាឈប់សម្រាក ២ ថ្ងៃ និងណែនាំបច្ចេកទេសរៀបចំបែងចែកកាលវិភាគសម្រាកខួរក្បាល (Strategic Recovery)។ វណ្ណាបានរៀនពីរបៀបផ្ទេរការងារខ្លះ និងបង្កើតកាលវិភាគសម្រាកច្បាស់លាស់ ដែលជួយឱ្យគាត់ធ្វើការបានយូរអង្វែង និងមានថាមពលពេញលេញ។»', '✅ របៀបឆ្លើយតបនៅពេលមានអារម្មណ៍ធុញថប់ខ្លាំង៖\n«ខ្ញុំទទួលស្គាល់ថាខ្ញុំកំពុងមានអារម្មណ៍តានតឹង។ ខ្ញុំនឹងដកដង្ហើមវែងៗ ៥ នាទី ឬដើរចេញក្រៅមួយភ្លែតសិន មុនពេលធ្វើការសម្រេចចិត្ត ឬឆ្លើយតបសារនេះ។»', 'អនុវត្តការដកដង្ហើមតាមបែប Box Breathing (ដកចូល ៤ វិនាទី, ទប់ ៤ វិនាទី, ដកចេញ ៤ វិនាទី, ទប់ ៤ វិនាទី) រយៈពេល ៣ នាទី។', 'តើអ្នកមានវិធីសាស្ត្រអ្វីខ្លះដើម្បីបញ្ចូលថាមពលឡើងវិញ បន្ទាប់ពីឆ្លងកាត់សប្តាហ៍ការងារដ៏តានតឹង?', '🎯 សកម្មភាពថ្ងៃនេះ៖ កំណត់ម៉ោងបិទកុំព្យូទ័រការងារនៅល្ងាចនេះ ហើយចំណាយពេលយ៉ាងហោចណាស់ ៣០ នាទីហាត់ប្រាណ ឬដើរកម្សាន្ត។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-eq-6', 'lesson-eq-6', 'នៅពេលអ្នកចាប់ផ្តើមមានអារម្មណ៍អស់កម្លាំងខ្លាំង គេងមិនលក់ និងឆាប់ខឹងខុសធម្មតាចំពោះការងារ តើជាសញ្ញានៃអ្វី?', 'When you feel chronically exhausted, sleepless, and unusually irritable at work, what is this a sign of?', '["A. ភាពខ្ជិលច្រអូស និងខ្វះការប្តេជ្ញាចិត្ត។","B. សញ្ញាដំបូងនៃការឆេះដួងចិត្ត (Burnout) ដែលត្រូវការការកែសម្រួលកាលវិភាគ និងការសម្រាកស្តារថាមពល។","C. ត្រូវបង្ខំខ្លួនឯងធ្វើការឱ្យកាន់តែច្រើនម៉ោងថែមទៀត។"]', '["A. Pure laziness and lack of discipline.","B. Early signs of Burnout requiring schedule adjustments and recovery.","C. Forcing yourself to work even longer hours."]', 1, 'ការពន្យល់៖ ជម្រើស B ទទួលស្គាល់ស្ថានភាពសុខភាពផ្លូវចិត្ត និងជួយការពារការដួលរលំនៃសមត្ថភាពការងារយូរអង្វែង។', 'Explanation: Recognizing burnout early and taking strategic recovery protects long-term career sustainability.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-eq-7', 'course-eq-critical', 'mod-1', 7, '៧. ការវិភាគឫសគល់បញ្ហា «ក្បួនសួរហេតុផល ៥ ដង» (Toyota 5 Whys Root-Cause)', 'Toyota 5 Whys Root Cause Analysis for Junior Professionals', 'text', '• យល់ដឹងពីក្បួនវិភាគបញ្ហា 5 Whys របស់ក្រុមហ៊ុនរថយន្តតូយ៉ូតា (Toyota Production System)។\n• ចេះញែកឱ្យដាច់រវាង «រោគសញ្ញាខាងក្រៅ» (Symptom) និង «ឫសគល់ពិតប្រាកដ» (Root Cause) នៃបញ្ហាការងារ។\n• ស្នើដំណោះស្រាយដែលការពារកុំឱ្យបញ្ហាកើតឡើងដដែលៗជំនួសឱ្យការបិទបាំងជាបណ្តោះអាសន្ន។', 'នៅពេលការងារជួបបញ្ហា មនុស្សភាគច្រើនប្រញាប់ប្រញាល់ដោះស្រាយត្រឹមតែរោគសញ្ញាខាងក្រៅ (ដូចជាការលេបថ្នាំបំបាត់ការឈឺក្បាល ប៉ុន្តែមិនព្យាបាលដុំសាច់)។ វិធីសាស្ត្រ «5 Whys» បង្រៀនឱ្យយើងសួរសំណួរថា «ហេតុអ្វី?» ចំនួន ៥ ដងបន្តបន្ទាប់គ្នា ដើម្បីជ្រែកចូលទៅរកមូលហេតុដើមបំផុតក្នុងប្រព័ន្ធ ឬដំណើរការការងារ។', '«នៅក្រុមហ៊ុនពាណិជ្ជកម្មអេឡិចត្រូនិចមួយ ការដឹកជញ្ជូនទំនិញទៅអតិថិជនត្រូវយឺតយ៉ាវ ៣ ថ្ងៃជាប់គ្នា។ \nប្រធានក្រុមសួរ៖ ហេតុអ្វីបានជាដឹកយឺត? (Why 1) -> បុគ្គលិកឆ្លើយ៖ ព្រោះបុគ្គលិកវេចខ្ចប់ធ្វើមិនទាន់។\nសួរបន្ត៖ ហេតុអ្វីបានជាវេចខ្ចប់មិនទាន់? (Why 2) -> ព្រោះម៉ាស៊ីនព្រីនវិក្កយបត្រខូច។\nសួរបន្ត៖ ហេតុអ្វីបានជាម៉ាស៊ីនព្រីនខូច? (Why 3) -> ព្រោះប្រើទឹកថ្នាំក្លែងក្លាយមានតម្លៃថោក។\nសួរបន្ត៖ ហេតុអ្វីបានជាទិញទឹកថ្នាំក្លែងក្លាយ? (Why 4) -> ព្រោះផ្នែកលទ្ធកម្ម (Procurement) ត្រូវកាត់បន្ថយថ្លៃដើម។\nសួរបន្ត៖ ហេតុអ្វីបានជាផ្នែកលទ្ធកម្មផ្តោតតែលើតម្លៃថោក? (Why 5 - ឫសគល់) -> ព្រោះក្រុមហ៊ុនគ្មានគោលការណ៍ស្តង់ដារគុណភាពអប្បបរមាសម្រាប់សម្ភារការិយាល័យ! \nនៅពេលបង្កើតគោលការណ៍ស្តង់ដារគុណភាព បញ្ហាដឹកជញ្ជូនយឺតយ៉ាវត្រូវបានដោះស្រាយជាស្ថាពរ។»', '✅ របៀបរៀបចំរបាយការណ៍ដោះស្រាយបញ្ហាតាម 5 Whys៖\n១. [បញ្ហាដែលបានសង្កេតឃើញ]៖ កម្មវិធីទូរស័ព្ទ App Crash នៅម៉ោង ៨ យប់\n២. [ដំណើរការសួរ 5 Whys]៖ ហេតុអ្វី Server គាំង? -> ហេតុអ្វីទិន្នន័យកើនឡើងភ្លាមៗ? -> ហេតុអ្វីគ្មានប្រព័ន្ធ Auto-scale?...\n៣. [ដំណោះស្រាយជាប្រព័ន្ធ]៖ ដំឡើងប្រព័ន្ធ Cloud Auto-scaling ដើម្បីទប់ទល់នឹងកំណើនអ្នកប្រើប្រាស់ស្វ័យប្រវត្តិ។', 'ជ្រើសរើសបញ្ហាមួយដែលកើតឡើងជាញឹកញាប់ក្នុងការងាររបស់អ្នក ហើយអនុវត្តការសួរ «ហេតុអ្វី?» ៥ ដងដើម្បីស្វែងរកឫសគល់ពិតប្រាកដ។', 'តើកន្លងមកអ្នកធ្លាប់ដោះស្រាយបញ្ហាត្រឹមតែលើផ្ទៃក្រៅ រួចបញ្ហានោះនៅតែត្រឡប់មកវិញដដែលៗដែរឬទេ?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ពេលជួបបញ្ហាការងារ សូមកុំទាន់សន្និដ្ឋានភ្លាមៗ ចូរគូរដ្យាក្រាមសួរ «ហេតុអ្វី?» យ៉ាងហោច ៣ ទៅ ៥ ដងសិន។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-eq-7', 'lesson-eq-7', 'តើគោលបំណងចម្បងនៃវិធីសាស្ត្រ Toyota 5 Whys ក្នុងការដោះស្រាយបញ្ហាការងារគឺជាអ្វី?', 'What is the primary purpose of the Toyota 5 Whys methodology in problem solving?', '["A. រកឱ្យឃើញថាតើបុគ្គលិកណាជាអ្នកខុស ដើម្បីកាត់ប្រាក់ខែ និងស្តីបន្ទោស។","B. ស្វែងរកឫសគល់នៃបញ្ហានៅក្នុងប្រព័ន្ធការងារ ដើម្បីដាក់ចេញដំណោះស្រាយដែលការពារកុំឱ្យកើតឡើងម្តងទៀត។","C. សួរសំណួរដដែលៗដើម្បីធ្វើឱ្យសមាជិកក្រុមមានអារម្មណ៍ភ័យខ្លាច។"]', '["A. Find out who is at fault to cut salary and publicly blame them.","B. Uncover the fundamental root cause in the system to prevent recurrence permanently.","C. Repeatedly ask questions to intimidate junior staff."]', 1, 'ការពន្យល់៖ 5 Whys មិនមែនជាការស្វែងរកបុគ្គលខុសដើម្បីស្តីបន្ទោសឡើយ ប៉ុន្តែជាការកែលម្អប្រព័ន្ធការងារដើម្បីការពារកំហុសកុំឱ្យកើតមានឡើងដដែលៗ។', 'Explanation: The 5 Whys focuses on systemic flaws, not personal finger-pointing.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-eq-8', 'course-eq-critical', 'mod-1', 8, '៨. សិល្បៈនៃការគ្រប់គ្រងថ្នាក់លើ (Managing Up: Becoming Your Boss’s Right Hand)', 'Upward Management: Working Effectively with High-Pressure Managers', 'text', '• យល់ដឹងពីគោលគំនិត Managing Up (ការសម្រួលការងារ និងកសាងទំនុកចិត្តជាមួយថ្នាក់លើ)។\n• ចេះរាយការណ៍បញ្ហាអមជាមួយ «ជម្រើសដំណោះស្រាយ» យ៉ាងហោចណាស់ ២ ជម្រើស (Solution-Oriented Reporting)។\n• សម្របតាមស្ទីលទំនាក់ទំនងរបស់ប្រធាន (ចូលចិត្តមើលទិន្នន័យ ឬចូលចិត្តស្តាប់ការសង្ខេប)។', 'ការគ្រប់គ្រងថ្នាក់លើ (Managing Up) មិនមែនជាការបញ្ចើចបញ្ចើរ ឬការផ្គាប់ចិត្តដោយគ្មានវិជ្ជាជីវៈនោះទេ ប៉ុន្តែជាសមត្ថភាពក្នុងការយល់ដឹងពីសម្ពាធ គោលដៅ និងស្ទីលការងាររបស់ថ្នាក់លើ ដើម្បីធ្វើឱ្យកិច្ចការរួមសម្រេចបានលទ្ធផលខ្ពស់បំផុត។ ក្បួនមាស៖ «កុំយកបញ្ហាទទេរទៅឱ្យប្រធានដោះស្រាយ ចូរយកបញ្ហាអមដោយជម្រើសដំណោះស្រាយចំនួន ២ ឬ ៣ ជម្រើស»។', '«ប៊ុនណា ជា Junior Software Developer។ រាល់ពេល Code មានបញ្ហា គាត់តែងតែរត់ទៅបន្ទប់ប្រធានផ្នែក IT ហើយនិយាយថា៖ "បង! Database Error ហើយ ខ្ញុំមិនដឹងធ្វើម៉េចទេ!"។ ប្រធានរបស់គាត់ដែលកំពុងរវល់រៀបចំយុទ្ធសាស្ត្រប្រចាំឆ្នាំ មានអារម្មណ៍ហត់នឿយ និងធុញទ្រាន់យ៉ាងខ្លាំង។ ផ្ទុយទៅវិញ វណ្ណា ជា Developer ម្នាក់ទៀត នៅពេលជួបបញ្ហាដូចគ្នា គាត់បានស្រាវជ្រាវ និងរៀបចំសារ Telegram យ៉ាងច្បាស់៖ "ជម្រាបសួរបង! Database កំពុងជួបបញ្ហាស្លាក់ Query។ ខ្ញុំបានពិនិត្យឃើញជម្រើស ២៖ ជម្រើសទី ១ បង្កើត Index ថ្មីចំណាយពេល ១៥ នាទីមិនអស់ថវិកា ជម្រើសទី ២ បង្កើនទំហំ RAM Cloud ចំណាយ $20/ខែ។ ខ្ញុំសូមអនុសាសន៍ឱ្យជ្រើសរើសជម្រើសទី ១ សិន។ តើបងយល់ព្រមទេ?" ប្រធានឆ្លើយតបត្រឹមពាក្យ "យល់ព្រម!" ក្នុងរយៈពេល ៥ វិនាទី។ ក្រោយមក វណ្ណា ត្រូវបានតែងតាំងជា Lead Developer។»', '✅ រូបមន្តរាយការណ៍បញ្ហាអមដំណោះស្រាយ (The 1-2-3 Upward Framework)៖\n១. [ស្ថានភាពបច្ចុប្បន្ន]៖ "យើងកំពុងជួបបញ្ហា X..."\n២. [ជម្រើសដំណោះស្រាយដែលបានវិភាគ]៖ \n   - ជម្រើស A: គុណសម្បត្តិ... គុណវិបត្តិ...\n   - ជម្រើស B: គុណសម្បត្តិ... គុណវិបត្តិ...\n៣. [អនុសាសន៍របស់អ្នក]៖ "ខ្ញុំសូមស្នើឱ្យជ្រើសរើសជម្រើស A ព្រោះវាចំណេញពេលវេលាជាង។"', 'រៀបចំសារ ឬសេចក្តីព្រាងរាយការណ៍បញ្ហាមួយដែលអ្នកកំពុងជួប ដោយដាក់ជម្រើសដំណោះស្រាយចំនួន ២ មុននឹងជួបប្រធានរបស់អ្នក។', 'តើអ្នកធ្លាប់យកបញ្ហាទៅទម្លាក់លើតុប្រធានដោយមិនបានគិតរកដំណោះស្រាយជាមុនដែរឬទេ? តើអ្នកអាចផ្លាស់ប្តូរទម្លាប់នេះយ៉ាងដូចម្តេច?', '🎯 សកម្មភាពថ្ងៃនេះ៖ មុននឹងជួបប្រធានដើម្បីរាយការណ៍ឧបសគ្គណាមួយ ចូរចំណាយពេល ១០ នាទីសរសេរជម្រើសដោះស្រាយចំនួន ២ ជាមុនសិន។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-eq-8', 'lesson-eq-8', 'នៅពេលអ្នករាយការណ៍បញ្ហាស្មុគស្មាញមួយទៅកាន់ថ្នាក់លើ តើរបៀបណាដែលបង្ហាញពីភាពចាស់ទុំវិជ្ជាជីវៈ (Managing Up)?', 'When reporting a complex problem to your manager, which approach demonstrates professional maturity?', '["A. រាយការណ៍តែបញ្ហាហើយរង់ចាំប្រធានប្រាប់គ្រប់ជំហានថាត្រូវធ្វើយ៉ាងណា។","B. បង្ហាញបញ្ហាសង្ខេប អមដោយជម្រើសដំណោះស្រាយដែលបានគិតគូររួច (២-៣ ជម្រើស) និងអនុសាសន៍ជាក់លាក់។","C. លាក់បញ្ហានោះទុកកុំឱ្យប្រធានដឹង ដើម្បីកុំឱ្យប្រធានខឹង។"]', '["A. Report the raw problem and passively wait for instructions.","B. State the problem clearly alongside vetted solution options and a concrete recommendation.","C. Hide the problem from your manager to avoid anger."]', 1, 'ការពន្យល់៖ ថ្នាក់ដឹកនាំរវល់ខ្លាំងណាស់។ ការយកបញ្ហាអមដោយជម្រើសដំណោះស្រាយ (Solutions-oriented mindset) បង្ហាញពីសមត្ថភាពត្រិះរិះ និងជួយសម្រាលបន្ទុកថ្នាក់លើយ៉ាងច្រើន។', 'Explanation: Bringing pre-analyzed solutions with a clear recommendation saves executive time and proves strategic competence.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-eq-9', 'course-eq-critical', 'mod-1', 9, '៩. ការសម្របសម្រួលការងារអន្តរផ្នែក (Cross-Department Collaboration & Silo Busting)', 'Cross-Functional Collaboration: Overcoming Departmental Silos', 'text', '• យល់ដឹងពីគ្រោះថ្នាក់នៃផ្នត់គំនិតបែងចែកបន្ទាយ (Silo Mentality) រវាងផ្នែកលក់ ទីផ្សារ គណនេយ្យ និង IT។\n• ចេះកសាងទំនាក់ទំនងល្អជាមួយសហការីផ្នែកដទៃតាមរយៈការស្វែងយល់ពី KPI របស់ពួកគេ។\n• ដោះស្រាយភាពរអាក់រអួលនៃការងារដោយឈរលើគោលការណ៍ឈ្នះ-ឈ្នះ (Win-Win Alignment)។', 'នៅក្នុងក្រុមហ៊ុនជាច្រើន ឧបសគ្គធំបំផុតមិនមែនជាគូប្រជែងខាងក្រៅទេ ប៉ុន្តែជាជញ្ជាំងរវាងផ្នែក និងផ្នែក (Silos)៖ ផ្នែកលក់បន្ទោសផ្នែកទីផ្សារ ផ្នែកទីផ្សារបន្ទោសផ្នែកប្រតិបត្តិការ ហើយផ្នែកប្រតិបត្តិការបន្ទោសផ្នែកគណនេយ្យ។ បុគ្គលិកកម្រិត Junior ដែលចេះកសាងស្ពានមិត្តភាពអន្តរផ្នែក នឹងក្លាយជាកម្លាំងចលករដែលមិនអាចខ្វះបាននៅក្នុងស្ថាប័ន។', '«កញ្ញា លីនដា ជាបុគ្គលិកផ្នែកលក់ (Sales) តែងតែជួបការយឺតយ៉ាវក្នុងការចេញវិក្កយបត្រពីផ្នែកគណនេយ្យ ធ្វើឱ្យអតិថិជនរអ៊ូរទាំ។ ជំនួសឱ្យការឈ្លោះប្រកែក ឬប្តឹងទៅប្រធាន លីនដាបានទិញកាហ្វេមួយកែវទៅសុំជួបពិភាក្សាជាមួយកញ្ញា ចាន់ថន (បុគ្គលិកគណនេយ្យ) ដោយសួរថា៖ "បង ចាន់ថន តើឯកសារលក់របស់ខ្ញុំខ្វះខាតចំណុចណាខ្លះដែលធ្វើឱ្យបងពិបាកបញ្ចូលក្នុងប្រព័ន្ធ?" \nចាន់ថន បានពន្យល់ថា លីនដាតែងតែភ្លេចសរសេរបញ្ជាក់លេខ TIN អតិថិជន។ ពេលដឹងមូលហេតុ លីនដាបានកែប្រែទម្រង់ភ្លាមៗ។ ចាប់ពីពេលនោះមក វិក្កយបត្ររបស់លីនដាត្រូវបានគណនេយ្យចេញឱ្យយ៉ាងលឿនក្នុងរយៈពេលតែ ១០ នាទី ហើយការលក់របស់នាងកើនឡើង ២ ដង។»', '✅ របៀបសន្ទនាដើម្បីកសាងកិច្ចសហការអន្តរផ្នែក៖\n«ជម្រាបសួរបង! ខ្ញុំដឹងថាខាងផ្នែកបងកំពុងមមាញឹកខ្លាំង។ គោលដៅរបស់ខ្ញុំគឺចង់ជួយសម្រួលកិច្ចការនេះឱ្យកាន់តែរលូន។ តើខាងខ្ញុំអាចរៀបចំទិន្នន័យបែបណាដើម្បីឱ្យខាងបងងាយស្រួលបន្តការងារបំផុត?»', 'ស្វែងរកសហការីម្នាក់នៅផ្នែកដទៃដែលអ្នកឧស្សាហ៍ធ្វើការជាមួយ ហើយសួរនាំពីបញ្ហាប្រឈមរបស់ពួកគេក្នុងការទទួលការងារពីផ្នែករបស់អ្នក។', 'តើអ្នកធ្លាប់មានអារម្មណ៍អវិជ្ជមានជាមួយផ្នែកដទៃក្នុងក្រុមហ៊ុនដែរឬទេ? តើអ្នកបានព្យាយាមស្វែងយល់ពីសម្ពាធការងាររបស់ពួកគេហើយឬនៅ?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ផ្ញើសារអរគុណ ឬទិញភេសជ្ជៈជូនសហការីផ្នែកដទៃដែលបានជួយសម្រួលការងារអ្នកកាលពីសប្តាហ៍មុន។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-eq-9', 'lesson-eq-9', 'នៅពេលការងាររបស់អ្នកត្រូវកកស្ទះនៅផ្នែកដទៃ (ឧ. ផ្នែកគណនេយ្យ ឬ IT) តើវិធីសាស្ត្រណាដែលមានប្រសិទ្ធភាពយូរអង្វែងបំផុត?', 'When your work is blocked by another department, what approach is most effective long-term?', '["A. ស្រែកគំហក និងផ្ញើអ៊ីមែលបន្ទោសដោយ CC ប្រធានក្រុមហ៊ុនដើម្បីគាបសង្កត់។","B. ជួបពិភាក្សាដោយផ្ទាល់ដើម្បីយល់ពីបញ្ហាប្រឈមរបស់ពួកគេ និងកែសម្រួលដំណើរការការងារឱ្យត្រូវគ្នា (Win-Win)។","C. ឈប់ធ្វើការងារនោះចោល ហើយរង់ចាំរហូតដល់ប្រធានដេញដោល។"]', '["A. Yell and send aggressive escalations CCing top executives.","B. Meet directly with empathy to understand their constraints and align workflow mutually.","C. Stop working on the task completely."]', 1, 'ការពន្យល់៖ ការយល់ចិត្ត និងការសម្របសម្រួលដោយឈរលើគោលការណ៍ឈ្នះ-ឈ្នះ បង្កើតកិច្ចសហការយូរអង្វែង និងកម្ទេចជញ្ជាំងអន្តរផ្នែក (Silos)។', 'Explanation: Mutual empathy and collaborative alignment dismantle silos and generate sustainable momentum.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-eq-10', 'course-eq-critical', 'mod-1', 10, '១០. ការទទួលយក Feedback និងការហ្វឹកហាត់កែលម្អ (Sun Tzu: Knowing Thyself)', 'Radical Self-Awareness: Sun Tzu Wisdom on Continuous Self-Refinement', 'text', '• យល់ដឹងពីទស្សនវិជ្ជាស៊ុនអ៊ូ (Sun Tzu): «ស្គាល់គេ ស្គាល់ខ្លួនឯង ច្បាំងមួយរយដង មិនដែលចាញ់» (知己知彼 百战不殆)។\n• បំប្លែងពាក្យរិះគន់ (Constructive Criticism) ទៅជាផែនទីបង្ហាញផ្លូវនៃការអភិវឌ្ឍសមត្ថភាព។\n• អនុវត្តការហ្វឹកហាត់ដោយចេតនា (Deliberate Practice) ដើម្បីពង្រឹងចំណុចខ្សោយរបស់ខ្លួនជាប្រចាំ។', 'ទស្សនវិទូយុទ្ធសាស្ត្រ ស៊ុនអ៊ូ (Sun Tzu) បានបង្រៀនថា ជោគជ័យមិនមែនកើតចេញពីសំណាងនោះទេ ប៉ុន្តែកើតចេញពីការស្គាល់ខ្លួនឯងយ៉ាងច្បាស់លាស់ (知己)។ នៅកន្លែងធ្វើការ មនុស្សដែលរត់គេចពីពាក្យរិះគន់ នឹងនៅទ្រឹងមួយកន្លែងរាប់ឆ្នាំ។ ផ្ទុយទៅវិញ អ្នកដែលមាន EQ ខ្ពស់ តែងតែស្វែងរក Feedback ពីថ្នាក់លើ និងសហការី ដើម្បីកែលម្អចំណុចខ្វះខាត និងបង្វឹកខ្លួនឯងឱ្យក្លាយជាបុគ្គលិកឆ្នើម។', '«លោក សុវណ្ណ ជា Junior Graphic Designer។ រាល់ពេលប្រធានផ្នែកច្នៃប្រឌិត (Creative Director) កែការងាររបស់គាត់ សុវណ្ណតែងតែខឹង និងគិតក្នុងចិត្តថា "ប្រធាននេះមិនចេះសិល្បៈទេ!"។ អស់រយៈពេល ២ ឆ្នាំ គាត់នៅតែជា Junior ដដែល។ ថ្ងៃមួយ ក្រោយពីអានសៀវភៅយុទ្ធសាស្ត្រស៊ុនអ៊ូ គាត់បានផ្លាស់ប្តូរផ្នត់គំនិតទាំងស្រុង។ ពេលប្រធានកែការងារ គាត់បានយកសៀវភៅមកកត់ត្រា ហើយសួរដោយស្មោះត្រង់ថា៖ "បង! តើត្រង់ចំណុច Typography នេះ បើខ្ញុំប្តូរទៅប្រើ Font ណាទើបត្រូវនឹង Brand Identity ជាង?" ការបើកចិត្តទទួលយក Feedback នេះ ធ្វើឱ្យស្នាដៃរបស់គាត់រីកចម្រើនលឿនដូចផ្លេកបន្ទោរ។ ត្រឹមតែ ៦ ខែក្រោយមក គាត់ត្រូវបានតម្លើងជា Senior Designer។»', '✅ របៀបស្នើសុំ Feedback ប្រកបដោយភាពចាស់ទុំ៖\n«ជម្រាបសួរបង! ក្នុងគម្រោងកន្លងមកនេះ ខ្ញុំចង់ដឹងថាតើមានចំណុចណាខ្លះដែលខ្ញុំធ្វើបានល្អ ហើយតើមានចំណុចខ្វះខាតណាខ្លះដែលបងចង់ឃើញខ្ញុំកែលម្អក្នុងគម្រោងបន្ទាប់?»', 'កំណត់ចំណុចខ្សោយធំបំផុតមួយរបស់អ្នកក្នុងការងារ (ឧ. ការនិយាយជាសាធារណៈ ឬការប្រើ Excel) ហើយរៀបចំផែនការហ្វឹកហាត់រយៈពេល ៣០ ថ្ងៃ។', 'តើអ្នកមានប្រតិកម្មបែបណានៅពេលនរណាម្នាក់រិះគន់ការងាររបស់អ្នក? តើអ្នកខឹងការពារខ្លួន ឬស្តាប់ដើម្បីរៀនសូត្រ?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ទៅជួបប្រធាន ឬរៀមច្បងម្នាក់ ហើយសួរសំណួរថា «តើចំណុចមួយណាដែលបងចង់ឱ្យខ្ញុំកែលម្អបំផុតក្នុងខែនេះ?»។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-eq-10', 'lesson-eq-10', 'តាមទស្សនវិជ្ជាស៊ុនអ៊ូ (Sun Tzu) តើឥរិយាបថណាដែលជួយឱ្យបុគ្គលិកឈានទៅរកភាពជោគជ័យយូរអង្វែង?', 'According to Sun Tzu philosophy, which attitude leads to long-term professional triumph?', '["A. ជឿជាក់ថាខ្លួនឯងពូកែគ្រប់យ៉ាង ហើយមិនចាំបាច់ស្តាប់យោបល់អ្នកណាទាំងអស់។","B. ស្គាល់ចំណុចខ្លាំង និងចំណុចខ្សោយរបស់ខ្លួនឯងយ៉ាងច្បាស់លាស់ (知己) និងបើកចិត្តកែលម្អតាម Feedback។","C. លាក់បាំងចំណុចខ្សោយរបស់ខ្លួន ហើយបន្ទោសអ្នកដទៃពេលការងារបរាជ័យ។"]', '["A. Believing you know everything and disregarding all advice.","B. Knowing your strengths and weaknesses intimately and constantly refining through feedback.","C. Concealing flaws and shifting blame when projects falter."]', 1, 'ការពន្យល់៖ ស៊ុនអ៊ូបង្រៀនថា «ស្គាល់ខ្លួនឯង» គឺជាជំហានដំបូងនៃជ័យជម្នះ។ ការហ៊ានប្រឈមមុខនឹងចំណុចខ្វះខាតរបស់ខ្លួនឯងធ្វើឱ្យយើងកាន់តែរឹងមាំ។', 'Explanation: Self-knowledge (知己) and relentless self-refinement are the foundation of invincibility.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-lead-1', 'course-leader-delegation', 'mod-1', 1, '១. ក្របខ័ណ្ឌ ៥ កម្រិតនៃការផ្ទេរភារកិច្ច (The 5 Levels of Effective Delegation)', 'The 5 Levels of Effective Delegation', 'text', '• យល់ដឹងពីភាពខុសគ្នារវាងការ "ផ្ទេរភារកិច្ច (Delegation)" និងការ "ទម្លាក់ចោលការងារ (Dumping)"។\n• កំណត់កម្រិតសិទ្ធិសម្រេចចិត្ត ៥ កម្រិតស្របតាមបទពិសោធន៍របស់សមាជិកក្រុម។\n• បង្កើតប្រព័ន្ធតាមដានលទ្ធផលដោយមិនចាំបាច់ Micromanage។', 'មេដឹកនាំល្អមិនមែនជាអ្នកធ្វើការងារទាំងអស់នោះទេ ប៉ុន្តែជាអ្នកបង្កើតបរិយាកាសឱ្យសមាជិកក្រុមអាចរីកចម្រើនតាមរយៈការទទួលខុសត្រូវ។ ការឱបការងារធ្វើម្នាក់ឯងធ្វើឱ្យក្រុមចុះខ្សោយ។', '«បូរ៉ា ឡើងធ្វើជា Team Leader ថ្មីផ្នែកទីផ្សារ។ ដោយសារខ្លាចកូនចៅធ្វើខុស គាត់ឱបក្រសោបការងារសំខាន់ៗធ្វើម្នាក់ឯងរហូតដល់ម៉ោង ៩ យប់រាល់ថ្ងៃ។ កូនចៅគ្មានការរីកចម្រើន ហើយចាប់ផ្តើមមានអារម្មណ៍ថាបូរ៉ាមិនទុកចិត្តពួកគេ។ ទីបំផុត បូរ៉ាធ្លាក់ខ្លួនឈឺចូលមន្ទីរពេទ្យ ហើយការងារក្រុមហ៊ុនត្រូវជាប់គាំងទាំងស្រុង។ ក្រោយមក គាត់បានរៀនបែងចែកការងារជា ៥ កម្រិត៖ បុគ្គលិកថ្មីឱ្យសួរនាំមុនធ្វើ ចំណែកបុគ្គលិកចាស់ឱ្យសិទ្ធិសម្រេចចិត្ត និងរាយការណ៍សង្ខេប។ ក្រុមរបស់គាត់បានក្លាយជាក្រុមដែលមានប្រសិទ្ធភាពខ្ពស់ជាងគេក្នុងក្រុមហ៊ុន។»', '✅ ក្របខ័ណ្ឌ ៥ កម្រិតនៃការផ្ទេរភារកិច្ច៖\nកម្រិត ១៖ រង់ចាំការបញ្ជា (Wait to be told)\nកម្រិត ២៖ សួរនាំ និងសុំការណែនាំមុនធ្វើ (Ask and get guidance)\nកម្រិត ៣៖ ស្រាវជ្រាវ និងស្នើសុំជម្រើសដំណោះស្រាយ (Recommend solutions)\nកម្រិត ៤៖ ធ្វើភ្លាម រួចរាយការណ៍លទ្ធផល (Act and report immediately)\nកម្រិត ៥៖ ស្វ័យភាពពេញលេញ (Full autonomy)។', 'ជ្រើសរើសការងារ ១ ដែលអ្នកកំពុងធ្វើរាល់ថ្ងៃ ហើយសរសេរផែនការផ្ទេរទៅឱ្យសមាជិកក្រុមម្នាក់ស្របតាមកម្រិតសមត្ថភាពរបស់គាត់។', 'តើអ្វីជាការភ័យខ្លាចធំបំផុតរបស់អ្នកនៅពេលប្រគល់ការងារសំខាន់ឱ្យអ្នកដទៃធ្វើ? តើការភ័យខ្លាចនោះពិតជាសមហេតុផលដែរឬទេ?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ប្រគល់ភារកិច្ចមួយដែលអ្នកធ្លាប់ធ្វើតែម្នាក់ឯង ទៅឱ្យសមាជិកក្រុម ដោយបញ្ជាក់គោលដៅ និងកាលវិភាគ Check-in ឱ្យបានច្បាស់។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-lead-1', 'lesson-lead-1', 'សមាជិកក្រុមរបស់អ្នកទើបតែចូលបម្រើការងារបាន ២ សប្តាហ៍។ តើកម្រិតនៃការផ្ទេរភារកិច្ចណាដែលសមស្របបំផុតសម្រាប់គាត់?', 'A team member joined 2 weeks ago. What delegation level is most appropriate for them?', '["A. កម្រិត ៥៖ ទុកឱ្យគាត់សម្រេចចិត្តដោយសេរីពេញលេញដោយមិនចាំបាច់សួរនាំ។","B. កម្រិត ២ ឬ ៣៖ ឱ្យគាត់ស្រាវជ្រាវ ស្នើជម្រើសដំណោះស្រាយ និងសុំការយល់ព្រមពីអ្នកសិនមុននឹងអនុវត្ត។","C. មិនផ្ទេរការងារឱ្យសោះ ហើយឱបការងារធ្វើម្នាក់ឯងរហូត។"]', '["A. Level 5: Full autonomy without asking.","B. Level 2 or 3: Research, recommend options, and get approval before executing.","C. Never delegate anything to them."]', 1, 'ការពន្យល់៖ ជម្រើស B ផ្តល់ការបណ្តុះបណ្តាលជាក់ស្តែង (Scaffolding) និងសុវត្ថិភាពដល់បុគ្គលិកថ្មី មុននឹងឈានទៅរកកម្រិតស្វ័យភាពខ្ពស់។', 'Explanation: Levels 2-3 provide proper guidance and safety net for new hires.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-lead-2', 'course-leader-delegation', 'mod-1', 2, '២. ការសន្ទនា 1-on-1 Feedback តាមទម្រង់ SBI (Situation-Behavior-Impact)', 'Constructive Feedback using the SBI Framework', 'text', '• ប្រើប្រាស់ទម្រង់ SBI ដើម្បីផ្តល់ Feedback ដោយមិនធ្វើឱ្យប៉ះពាល់ដល់ផ្លូវចិត្តបុគ្គលិក។\n• ជៀសវាងការប្រើពាក្យទូទៅដូចជា "អ្នកធ្វើការមិនសូវល្អ" ឬ "អ្នកខ្វះការយកចិត្តទុកដាក់"។\n• បង្កើតកិច្ចព្រមព្រៀងកែលម្អប្រកបដោយកិច្ចសហការ។', 'Feedback ត្រូវតែផ្តោតលើទង្វើជាក់ស្តែងដែលអាចវាស់វែងបាន និងផលប៉ះពាល់ដែលកើតមាន មិនមែនលើអត្តចរិត ឬតម្លៃបុគ្គលឡើយ។', '«ជំនួសឱ្យការនិយាយបន្ទោសថា "អ្នកឯងគ្មានទំនួលខុសត្រូវ និងមិនគោរពពេលវេលា!" មេដឹកនាំវិជ្ជាជីវៈបានកោះហៅជួបជាឯកជន ហើយនិយាយតាមទម្រង់ SBI ថា៖ "នៅក្នុងការប្រជុំជាមួយអតិថិជនកាលពីព្រឹកមិញម៉ោង ៩ (Situation) ប្អូនបានមកដល់យឺត ២០ នាទីដោយមិនបានផ្តល់ដំណឹងជាមុន (Behavior) ដែលធ្វើឱ្យអតិថិជនគិតថាក្រុមហ៊ុនយើងខ្វះវិជ្ជាជីវៈ និងធ្វើឱ្យខ្ញុំត្រូវពន្យារពេលបទបង្ហាញ (Impact)។ តើមានរឿងអ្វីកើតឡើងចំពោះប្អូនព្រឹកមិញដែរទេ?"។ បុគ្គលិកមានអារម្មណ៍ថាគ្មានការវាយប្រហារផ្ទាល់ខ្លួន ក៏បានទទួលស្គាល់កំហុសដោយស្មោះត្រង់ និងសន្យាមិនឱ្យកើតមានទៀតឡើយ។»', '✅ រូបមន្ត SBI Word-for-Word៖\n• Situation (ពេលណា នៅឯណា)៖ "កាលពីថ្ងៃពុធ ក្នុងការប្រជុំគម្រោង..."\n• Behavior (ទង្វើជាក់លាក់)៖ "ប្អូនបានកាត់សម្តីសហការី ៣ ដង..."\n• Impact (ផលប៉ះពាល់)៖ "វាធ្វើឱ្យគាត់មានអារម្មណ៍មិនស្រួលក្នុងការបញ្ចេញមតិ..."\n• Next Step៖ "តើយើងអាចសហការគ្នាយ៉ាងណាដើម្បីកែលម្អចំណុចនេះ?"', 'សរសេរសេចក្តីព្រាង Feedback តាមទម្រង់ SBI សម្រាប់សមាជិកក្រុមម្នាក់ដែលតែងតែយឺតយ៉ាវក្នុងការផ្ញើរបាយការណ៍។', 'តើការរិះគន់បែបណាដែលធ្លាប់ធ្វើឱ្យអ្នកឈឺចាប់ និងបាក់ទឹកចិត្តកាលពីអតីតកាល? តើទម្រង់ SBI អាចជួយការពាររឿងនោះយ៉ាងដូចម្តេច?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ផ្តល់ Feedback វិជ្ជមានមួយតាមទម្រង់ SBI ទៅកាន់សមាជិកក្រុមដែលបានបំពេញការងារបានល្អ។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-lead-2', 'lesson-lead-2', 'សមាជិកក្រុមម្នាក់មិនបានផ្ញើទិន្នន័យឱ្យទាន់ពេលសម្រាប់របាយការណ៍គម្រោង។ តើសេចក្តីថ្លែងការណ៍ណាដែលត្រូវតាមទម្រង់ SBI ត្រឹមត្រូវបំផុត?', 'A team member missed a data deadline. Which statement follows the SBI framework accurately?', '["A. \\"ប្អូនឯងខ្ជិលណាស់ មិនដែលយកចិត្តទុកដាក់លើការងារក្រុមសោះ!\\"","B. \\"កាលពីល្ងាចម្សិលមិញ (S) ប្អូនមិនបានផ្ញើទិន្នន័យលក់តាមការសន្យាម៉ោង ៤ ទេ (B) ដែលធ្វើឱ្យខ្ញុំត្រូវនៅធ្វើការដល់ម៉ោង ៨ យប់ដើម្បីបង្ហើយរបាយការណ៍ (I)\\"។","C. \\"កុំឱ្យរឿងហ្នឹងកើតឡើងទៀត បើមិនអញ្ចឹងប្រាក់ខែនឹងត្រូវកាត់!\\""]', '["A. \\"You are so lazy and never care about the team!\\"","B. \\"Yesterday afternoon (S), you did not send the sales data by 4 PM (B), causing me to stay until 8 PM to finish (I).\\"","C. \\"Do not let it happen again or salary will be cut!\\""]', 1, 'ការពន្យល់៖ ជម្រើស B បញ្ជាក់ច្បាស់នូវកាលបរិច្ឆេទ ទង្វើជាក់លាក់ និងផលប៉ះពាល់ពិតប្រាកដ ដោយគ្មានការវាយប្រហារអត្តចរិត។', 'Explanation: Option B sticks strictly to observable facts and measurable impact.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-lead-3', 'course-leader-delegation', 'mod-1', 3, '៣. របៀបដឹកនាំការប្រជុំ Stand-up ១៥ នាទីឱ្យមានប្រសិទ្ធភាព (High-Impact 15-min Standup Meetings)', 'Leading High-Impact 15-Minute Standup Meetings', 'text', '• បង្កើតរបៀបវារៈប្រជុំច្បាស់លាស់ និងកំណត់អ្នកកត់ត្រា Action Items។\n• អនុវត្តទម្រង់ Stand-up ១៥ នាទីដោយផ្តោតលើសំណួរគន្លឹះ ៣។\n• កាត់ផ្តាច់ការជជែកវែកញែកស៊ីជម្រៅដែលធ្វើឱ្យខាតពេលវេលារបស់អ្នកដទៃ។', 'ការប្រជុំដែលគ្មានរបៀបវារៈ គឺជាការខ្ជះខ្ជាយថវិកា និងពេលវេលារបស់ក្រុមហ៊ុន។ ប្រសិនបើអាចដោះស្រាយតាមអ៊ីមែល ឬ Telegram បាន កុំបើកការប្រជុំ។', '«ក្រុមការងារអភិវឌ្ឍន៍កម្មវិធីធ្លាប់ចំណាយពេលប្រជុំ ២ ម៉ោងរៀងរាល់ព្រឹកច័ន្ទដោយគ្មានលទ្ធផល ព្រោះសមាជិកចាប់ផ្តើមជជែកវែកញែករឿងរ៉ាវផ្ទាល់ខ្លួន និងជម្លោះបច្ចេកទេស។ ប្រធានក្រុមថ្មីបានកែប្រែមកជា "Stand-up Meeting ១៥ នាទី" ដោយតម្រូវឱ្យសមាជិកទាំងអស់ឈរជុំគ្នា ហើយម្នាក់ៗឆ្លើយតែ ៣ សំណួរ៖\n១. តើបានធ្វើអ្វីខ្លះម្សិលមិញ?\n២. តើថ្ងៃនេះនឹងធ្វើអ្វី?\n៣. តើកំពុងជួបបញ្ហារាំងស្ទះ (Blocker) អ្វីខ្លះ?\nប្រសិនបើមានបញ្ហាស្មុគស្មាញ គាត់ឱ្យជួបដោះស្រាយក្រៅម៉ោងតែពីរនាក់ប៉ុណ្ណោះ។ លទ្ធផល៖ ផលិតភាពការងារកើនឡើង ៣៥% ហើយក្រុមការងារសប្បាយចិត្ត។»', '✅ ក្បួនមាស Stand-up ១៥ នាទី៖\n• មិនឱ្យលើសពី ២ នាទីក្នុងម្នាក់។\n• ប្រសិនបើការជជែកលើសពី ៣ នាទីលើប្រធានបទមួយ សូមនិយាយថា៖ "ចូរយើងកត់ត្រារឿងនេះជាចំណុចដាច់ដោយឡែក ហើយជួបគ្នា ១០ នាទីក្រោយការប្រជុំ"។', 'រៀបចំរបៀបវារៈប្រជុំរយៈពេល ១៥ នាទីសម្រាប់ក្រុមរបស់អ្នក ហើយអនុវត្តការកំណត់ម៉ោងជាក់ស្តែង។', 'តើការប្រជុំនៅក្នុងកន្លែងធ្វើការរបស់អ្នកបច្ចុប្បន្ន មានប្រសិទ្ធភាពកម្រិតណា? តើមានការប្រជុំណាខ្លះដែលអាចកាត់បន្ថយ ឬជំនួសដោយសារខ្លីបាន?', '🎯 សកម្មភាពថ្ងៃនេះ៖ កំណត់ម៉ោងបញ្ចប់ការប្រជុំបន្ទាប់ឱ្យបានច្បាស់លាស់ និងបញ្ជាក់ Action Items មុនពេលរំសាយ។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-lead-3', 'lesson-lead-3', 'ក្នុងពេលប្រជុំ Stand-up ១៥ នាទី មានសមាជិក ២ នាក់ចាប់ផ្តើមជជែកវែកញែកស៊ីជម្រៅលើបញ្ហាបច្ចេកទេសតែពីរនាក់អស់ពេល ១០ នាទី។ តើអ្នកដឹកនាំគួរធ្វើបែបណា?', 'During a 15-min standup, two members dive deep into a technical debate for 10 minutes. What should the leader do?', '["A. បណ្តោយឱ្យពួកគេជជែករហូតដល់ចប់ ទោះបីជាលើសម៉ោងក៏ដោយ។","B. កាត់សម្តីដោយគួរសម ស្នើសុំឱ្យពួកគេទុកការជជែកនោះក្រៅម៉ោងប្រជុំ (Offline) ហើយបន្តទៅកាន់សមាជិកបន្ទាប់។","C. ខឹងច្រឡោត និងដេញពួកគេចេញពីបន្ទប់ប្រជុំ។"]', '["A. Let them argue until finished regardless of overtime.","B. Politely intervene, park the topic offline for the two of them, and move to the next member.","C. Get angry and expel them from the room."]', 1, 'ការពន្យល់៖ ជម្រើស B ការពារពេលវេលារបស់សមាជិកដទៃទៀត (Meeting hygiene) និងរក្សាប្រសិទ្ធភាពនៃការប្រជុំ។', 'Explanation: Parking detailed topics offline respects the entire team time.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-lead-4', 'course-leader-delegation', 'mod-1', 4, '៤. ការលើកទឹកចិត្ត និងការការពារក្រុមពីការបាក់ទឹកចិត្ត (Team Motivation & Preventing Burnout)', 'Team Motivation & Preventing Workplace Burnout', 'text', '• កត់សម្គាល់សញ្ញាដំបូងនៃការហត់នឿយផ្លូវចិត្ត (Burnout) និងការដកខ្លួនរបស់សមាជិកក្រុម។\n• អនុវត្តគោលការណ៍សរសើរជាសាធារណៈ និងកែលម្អជាឯកជន (Praise in Public, Criticize in Private)។\n• បង្កើតវប្បធម៌ការងារយុត្តិធម៌ និងការទទួលស្គាល់ស្នាដៃជាក់ស្តែង។', 'បុគ្គលិកដែលមានសមត្ថភាពមិនមែនចាកចេញពីក្រុមហ៊ុនដោយសារប្រាក់ខែតែមួយមុខនោះទេ ភាគច្រើនគឺចាកចេញពីមេដឹកនាំដែលមិនចេះយល់ចិត្ត និងការងារដែលគ្មានការទទួលស្គាល់។', '«ក្រោយបញ្ចប់គម្រោងធំដែលត្រូវធ្វើការថែមម៉ោងរយៈពេល ២ ខែ សមាជិកក្រុមទាំងអស់ហត់នឿយ និងចាប់ផ្តើមឈឺ។ ប្រធានក្រុមមិនត្រឹមតែផ្ញើអ៊ីមែលអរគុណនោះទេ គាត់បានរៀបចំអាហារថ្ងៃត្រង់ជុំគ្នា ថ្លែងការកោតសរសើរសមាជិកម្នាក់ៗតាមចំណុចខ្លាំងជាក់លាក់ និងបានស្នើសុំថ្នាក់លើផ្តល់ពេលសម្រាកកន្លះថ្ងៃដល់ក្រុម។ សមាជិកទាំងអស់មានអារម្មណ៍កក់ក្តៅ និងមានកម្លាំងចិត្តឡើងវិញ។ ផ្ទុយទៅវិញ ក្រុមមួយទៀតដែលមេដឹកនាំបន្តដាក់សម្ពាធការងារថ្មីភ្លាមៗ បានបាត់បង់បុគ្គលិកឆ្នើម ៣ នាក់ក្នុងខែបន្ទាប់។»', '✅ សកម្មភាពលើកទឹកចិត្តជាក់ស្តែង៖\n• សរសើរចំឈ្មោះ និងចំសកម្មភាព៖ "អរគុណកញ្ញាធារី ដែលបានជួយសម្រួលឯកសារនេះយ៉ាងស្អាត..."\n• សួរនាំសុខទុក្ខដោយស្មោះត្រង់ក្នុងកិច្ចសន្ទនា 1-on-1 ដោយមិននិយាយពីរឿងការងារតែមួយមុខ។', 'កំណត់បញ្ជីឈ្មោះសមាជិកក្រុមដែលកំពុងមានបន្ទុកការងារធ្ងន់ធ្ងរ ហើយរកវិធីជួយសម្រាលការងាររបស់ពួកគេ។', 'តើអ្នកដឹងទេថាសមាជិកក្រុមរបស់អ្នកម្នាក់ៗមានកម្លាំងចិត្តធ្វើការដោយសារអ្វី (ប្រាក់ខែ ការរៀនសូត្រ ឬការទទួលស្គាល់)?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ផ្ញើសារថ្លែងអំណរគុណជាក់លាក់មួយទៅកាន់សមាជិកក្រុមម្នាក់ដែលបានខិតខំប្រឹងប្រែង។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-lead-4', 'lesson-lead-4', 'សមាជិកឆ្នើមម្នាក់ក្នុងក្រុមស្រាប់តែចាប់ផ្តើមដកថយ ឆ្លើយសារយឺតយ៉ាវ និងមានទឹកមុខហត់នឿយ។ តើសកម្មភាពដំបូងដែលមេដឹកនាំគួរធ្វើគឺជាអ្វី?', 'A top performer suddenly withdraws, responds slowly, and looks exhausted. What should the leader do first?', '["A. គំរាមកំហែងកាត់ប្រាក់ខែភ្លាមៗដោយសារធ្លាក់ចុះផលិតភាព។","B. រៀបចំការជួបសន្ទនា 1-on-1 ដោយស្ងប់ស្ងាត់ សួរនាំសុខទុក្ខដោយការយល់ចិត្ត និងពិនិត្យសម្រាលបន្ទុកការងារ។","C. ធ្វើមិនដឹងមិនឮព្រោះគិតថាជារឿងផ្ទាល់ខ្លួនរបស់គាត់។"]', '["A. Threaten salary deductions immediately.","B. Hold a supportive 1-on-1, check in with empathy, and explore ways to rebalance workload.","C. Ignore it thinking it is personal business."]', 1, 'ការពន្យល់៖ ជម្រើស B ជួយស្រោចស្រង់បុគ្គលិកឆ្នើមទាន់ពេលវេលា មុនពេលឈានដល់ការបាក់ទឹកចិត្តធ្ងន់ធ្ងរ ឬការលាលែងពីការងារ។', 'Explanation: Proactive, empathetic check-in prevents irreversible burnout and resignation.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-lead-5', 'course-leader-delegation', 'mod-1', 5, '៥. ក្បួនរៀបចំកិច្ចប្រជុំប្រចាំសប្តាហ៍ឱ្យមានប្រសិទ្ធភាពត្រឹម ៣០ នាទី (High-Impact Weekly Standup)', 'Conducting High-Impact 30-Minute Weekly Standup Meetings', 'text', '• លុបបំបាត់កិច្ចប្រជុំអូសបន្លាយដែលខ្ជះខ្ជាយពេលវេលា និងគ្មានលទ្ធផលជាក់លាក់។\n• អនុវត្តរបៀបវារៈ ៣ ដំណាក់កាល៖ Review KPIs (១០ នាទី), Solve Bottlenecks (១៥ នាទី), Next Actions (៥ នាទី)។\n• រក្សាការតម្រង់ទិសដៅ និងថាមពលវិជ្ជមានរបស់សមាជិកក្រុមរៀងរាល់ដើមសប្តាហ៍។', 'កិច្ចប្រជុំល្អមិនមែនជាការអង្គុយរាយការណ៍វែងអន្លាយនោះទេ ប៉ុន្តែជាវេទិកាសម្រេចចិត្ត ដោះស្រាយឧបសគ្គកកស្ទះ និងបែងចែកសកម្មភាពបន្តឱ្យបានច្បាស់លាស់។', '«ក្រុមការងារផ្នែកលក់មួយធ្លាប់ជួបប្រជុំរៀងរាល់ព្រឹកថ្ងៃចន្ទរយៈពេល ២ ម៉ោងកន្លះ។ ម្នាក់ៗអង្គុយងោក និងមានអារម្មណ៍ធុញថប់។ សុជាតិ (Team Leader ថ្មី) បានផ្លាស់ប្តូរទម្រង់មកជា Standup Meeting ៣០ នាទី៖ តម្រូវឱ្យសមាជិកផ្ញើតួលេខចូល Telegram Group ជាមុន ពេលប្រជុំផ្តោតតែលើការដោះស្រាយអតិថិជនណាដែលកំពុងជាប់គាំង។ លទ្ធផល៖ សមាជិកក្រុមសន្សំបាន ២ ម៉ោងសម្រាប់ចេញទៅជួបអតិថិជន ហើយការលក់កើនឡើង ៣៥% ក្នុងខែដំបូង។»', '✅ របៀបបើកកិច្ចប្រជុំ ៣០ នាទី៖\n«សួស្តីក្រុមការងារទាំងអស់គ្នា! យើងមានពេល ៣០ នាទីថ្ងៃនេះ។ យើងនឹងមិនចំណាយពេលរៀបរាប់អ្វីដែលបានសរសេរក្នុងរបាយការណ៍រួចហើយនោះទេ។ យើងផ្តោតតែលើសំណួរ ២ ប៉ុណ្ណោះ៖ ១. តើមានអ្វីកកស្ទះដែលត្រូវការការសម្រេចចិត្តបន្ទាន់? ២. តើអ្នកណាទទួលបន្ទុកជំហានបន្ទាប់?»', 'បង្កើតសេចក្តីព្រាងរបៀបវារៈប្រជុំ ៣០ នាទី (Agenda) សម្រាប់កិច្ចប្រជុំបន្ទាប់របស់ក្រុមអ្នក។', 'តើកិច្ចប្រជុំក្រុមរបស់អ្នកកន្លងមកបានចំណាយពេលលើការអានរបាយការណ៍ច្រើនជាងការដោះស្រាយបញ្ហាដែរឬទេ?', '🎯 សកម្មភាពថ្ងៃនេះ៖ កំណត់ម៉ោងប្រជុំបន្ទាប់របស់អ្នកឱ្យនៅត្រឹម ៣០ នាទី ហើយប្រកាសរបៀបវារៈជាមុន។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-lead-5', 'lesson-lead-5', 'តើអ្វីជាក្បួនសំខាន់បំផុតដើម្បីការពារកុំឱ្យកិច្ចប្រជុំក្រុមអូសបន្លាយពេលយូរឥតប្រយោជន៍?', 'What is the most critical rule to prevent team meetings from dragging on pointlessly?', '["A. មិនបាច់កំណត់ពេលវេលាទេ ចាំជជែកគ្នារហូតដល់អស់រឿងនិយាយ។","B. កំណត់របៀបវារៈ និងម៉ោងច្បាស់លាស់ តម្រូវឱ្យអានទិន្នន័យជាមុន និងផ្តោតតែលើការដោះស្រាយឧបសគ្គ និងការសម្រេចចិត្ត។","C. ហាមឃាត់មិនឱ្យសមាជិកក្រុមនិយាយអ្វីទាំងអស់ ក្រៅពីស្តាប់មេដឹកនាំនិយាយតែម្នាក់ឯង។"]', '["A. No time limits, chat until everyone runs out of things to say.","B. Strict agenda and timebox, require pre-reading data, and focus purely on bottlenecks and decisions.","C. Prohibit members from speaking except the leader."]', 1, 'ការពន្យល់៖ ជម្រើស B គោរពពេលវេលារបស់សមាជិក និងជំរុញឱ្យការប្រជុំក្លាយជាកន្លែងដោះស្រាយបញ្ហាពិតប្រាកដ។', 'Explanation: Pre-reading data and timeboxing decisions turns meetings into productive engines.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-lead-6', 'course-leader-delegation', 'mod-1', 6, '៦. ការជួយស្រោចស្រង់សមាជិកក្រុមដែលអសកម្ម ឬមានសមត្ថភាពធ្លាក់ចុះ (Underperformer Turnaround)', 'Coaching and Turning Around Underperforming Team Members', 'text', '• យល់ដឹងពីមូលហេតុពិតប្រាកដដែលបុគ្គលិកធ្លាក់ចុះផលិតភាព (បញ្ហាជំនាញ, បញ្ហាទឹកចិត្ត ឬបញ្ហាផ្ទាល់ខ្លួន)។\n• អនុវត្តផែនការកែលម្អសមត្ថភាពរយៈពេល ៣០ ថ្ងៃ (30-Day Performance Improvement Plan - PIP) ប្រកបដោយការគាំទ្រ។\n• រក្សាតុល្យភាពរវាងការយល់ចិត្ត (Empathy) និងទំនួលខុសត្រូវលើលទ្ធផល (Accountability)។', 'ការបណ្តេញបុគ្គលិកចេញភ្លាមៗគឺជារឿងងាយស្រួល ប៉ុន្តែការបង្វឹក និងជួយស្រោចស្រង់បុគ្គលិកឱ្យក្លាយជាមនុស្សពូកែឡើងវិញ គឺជាសញ្ញាសម្គាល់នៃមេដឹកនាំឆ្នើម។', '«ធារ៉ា ជាអ្នករចនា Graphic Designer ដែលធ្លាប់ធ្វើការបានល្អ ស្រាប់តែប្រគល់ការងារយឺតយ៉ាវជាញឹកញាប់ និងមានទឹកមុខស្រពាប់ស្រពោន។ ប្រធានក្រុមមិនបានស្រែកបន្ទោស ឬដាក់ទណ្ឌកម្មឡើយ។ គាត់បានអញ្ជើញធារ៉ាពិភាក្សា 1-on-1 ដោយស្មោះត្រង់។ គាត់បានដឹងថា ធារ៉ាកំពុងជួបបញ្ហាសុខភាពម្តាយនៅស្រុក ហើយអារម្មណ៍មិនមូល។ ប្រធានក្រុមបានជួយសម្រួលឱ្យធារ៉ាធ្វើការពីផ្ទះ ២ ថ្ងៃក្នុងមួយសប្តាហ៍ និងរៀបចំបញ្ជីការងារច្បាស់លាស់។ មួយខែក្រោយមក ធារ៉ាបានវិលត្រឡប់មករកទម្រង់លេងល្អបំផុតវិញ និងថ្លែងអំណរគុណដល់ប្រធានដែលបានជឿជាក់លើគាត់។»', '✅ របៀបចាប់ផ្តើមការសន្ទនាបង្វឹកកែលម្អ៖\n«ប្អូនធារ៉ា! បងកត់សម្គាល់ឃើញថាសប្តាហ៍នេះការងាររបស់ប្អូនមានការយឺតយ៉ាវជាងមុន។ បងដឹងច្បាស់ពីសមត្ថភាពពូកែរបស់ប្អូនពីមុនមក។ តើមានបញ្ហាប្រឈមអ្វីដែលកំពុងរារាំងប្អូន ហើយតើបងអាចជួយសម្របសម្រួលបែបណាខ្លះ?»', 'សរសេរសេចក្តីព្រាងផែនការ PIP ៣០ ថ្ងៃសាមញ្ញមួយ (៣ គោលដៅជាក់ស្តែង និងកាលបរិច្ឆេទត្រួតពិនិត្យប្រចាំសប្តាហ៍)។', 'តើអ្នកធ្លាប់ជួយសហការីម្នាក់ឱ្យផ្លាស់ប្តូរពីភាពអសកម្ម មកជាមនុស្សសកម្មវិញដែរឬទេ? តើអ្នកមានអារម្មណ៍បែបណា?', '🎯 សកម្មភាពថ្ងៃនេះ៖ កំណត់សមាជិកក្រុមម្នាក់ដែលកំពុងត្រូវការការជួយគាំទ្រ ហើយកក់ម៉ោងជួបសន្ទនាជាមួយគាត់។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-lead-6', 'lesson-lead-6', 'នៅពេលសមាជិកក្រុមម្នាក់ចាប់ផ្តើមធ្លាក់ចុះលទ្ធផលការងារ តើជំហានដំបូងបំផុតដែល Team Leader គួរធ្វើគឺជាអ្វី?', 'When a team member starts underperforming, what is the very first step a Team Leader should take?', '["A. កាត់ប្រាក់ខែ និងបង្ហោះសារបន្ទោសក្នុងគ្រុប Telegram ឱ្យខ្មាសគេ។","B. ជួបសន្ទនាផ្ទាល់ខ្លួន 1-on-1 ដោយស្វែងយល់ពីឫសគល់បញ្ហា (ជំនាញ ឬទឹកចិត្ត) និងរួមគ្នាបង្កើតផែនការកែលម្អ។","C. ដកហូតការងារទាំងអស់ ហើយបណ្តេញចេញភ្លាមៗ។"]', '["A. Cut salary and publicly shame them in Telegram group.","B. Hold a private 1-on-1 to discover the root cause (skill vs motivation) and co-create an improvement plan.","C. Strip duties and fire immediately."]', 1, 'ការពន្យល់៖ ជម្រើស B ផ្តល់ឱកាសយុត្តិធម៌ និងស្វែងយល់ពីឫសគល់ មុននឹងឈានទៅដល់វិធានការរដ្ឋបាល។', 'Explanation: Understanding the root cause privately preserves dignity and often turns performance around.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-leader-7', 'course-leader-delegation', 'mod-1', 7, '៧. ការកសាងសុវត្ថិភាពផ្លូវចិត្ត និងការនិយាយត្រង់ (Alibaba: Candor & Psychological Safety)', 'Psychological Safety & Radical Candor: The Alibaba Iron Army Culture', 'text', '• យល់ដឹងពីគោលគំនិតសុវត្ថិភាពផ្លូវចិត្ត (Psychological Safety) របស់ Google Project Aristotle។\n• អនុវត្តវប្បធម៌និយាយត្រង់ដោយក្តីស្រឡាញ់ (Radical Candor: Care Personally, Challenge Directly)។\n• បង្កើតវេទិកាពិភាក្សាដែលសមាជិកហ៊ានរាយការណ៍ពីកំហុសដោយមិនខ្លាចការសងសឹក ឬស្តីបន្ទោស។', 'នៅក្រុមហ៊ុន Alibaba វប្បធម៌កងទ័ពដែក (阿里铁军) ផ្អែកលើការនិយាយត្រង់ (坦诚)។ ក្រុមការងារដែលគ្រោះថ្នាក់បំផុត មិនមែនជាក្រុមដែលមានការប្រកែកគ្នានោះទេ ប៉ុន្តែជាក្រុមដែល «ស្ងៀមស្ងាត់ ញញឹមដាក់គ្នា ប៉ុន្តែលាក់កំហុស និងការមិនពេញចិត្តទុកក្នុងចិត្ត»។ Team Leader ឆ្នើមត្រូវតែកសាងបរិយាកាសសុវត្ថិភាពផ្លូវចិត្ត ដែលសមាជិកគ្រប់គ្នាហ៊ានបញ្ចេញមតិ ហ៊ានចោទសួរ និងហ៊ានសារភាពកំហុសភ្លាមៗ។', '«លោក មករា ជា Team Leader ផ្នែកអភិវឌ្ឍន៍ផលិតផល។ ដំបូងឡើយ រាល់ពេលសមាជិកធ្វើខុស គាត់តែងតែស្តីបន្ទោសយ៉ាងចាស់ដៃនៅចំពោះមុខអ្នកដទៃ។ ជាលទ្ធផល សមាជិកលែងហ៊ានបញ្ចេញគំនិតច្នៃប្រឌិតថ្មីៗ ហើយពេលមានបញ្ហាអតិថិជនរអ៊ូរទាំ ពួកគេនាំគ្នាលាក់បាំងរហូតដល់បញ្ហារីករាលដាលធំ។ \nក្រោយពីយល់ដឹងពី Radical Candor មករាបានកែប្រែស្ទីលដឹកនាំ៖ គាត់បានបើកកិច្ចប្រជុំសារភាពកំហុសផ្ទាល់ខ្លួនជាគំរូមុនគេ។ គាត់បានបង្កើតក្បួន "ជជែកទាស់គំនិតគ្នាក្នុងបន្ទប់ប្រជុំឱ្យអស់ចិត្ត ប៉ុន្តែចេញមកក្រៅស្រឡាញ់គ្នាដូចបងប្អូន"។ ក្រុមការងាររបស់គាត់បានប្រែក្លាយជាក្រុមដែលមានភាពស្អិតរមួតបំផុត និងមានទិន្នផលការងារកើនឡើង ៤០%។»', '✅ របៀបនិយាយត្រង់ដោយក្តីមេត្តា (Radical Candor Formula)៖\n«ប្អូនដឹងទេថាខ្ញុំយកចិត្តទុកដាក់ និងចង់ឃើញប្អូនជោគជ័យខ្លាំងកម្រិតណា។ ដោយសារក្តីបារម្ភនេះហើយ ទើបខ្ញុំត្រូវតែប្រាប់ប្អូនដោយស្មោះត្រង់ថា របាយការណ៍លើកនេះខ្វះទិន្នន័យសំខាន់ចំនួន ២ ដែលធ្វើឱ្យអតិថិជនបាត់បង់ទំនុកចិត្ត។ តើយើងអាចកែប្រែវាឡើងវិញយ៉ាងដូចម្តេច?»', 'រៀបចំកិច្ចប្រជុំបើកចំហ (Open Forum) រយៈពេល ៣០ នាទីជាមួយក្រុមរបស់អ្នក ដើម្បីស្តាប់ការលំបាក និងមតិយោបល់របស់ពួកគេដោយមិនធ្វើការស្តីបន្ទោស។', 'តើសមាជិកក្រុមរបស់អ្នកហ៊ានប្រាប់អ្នកដោយស្មោះត្រង់ទេនៅពេលអ្នកធ្វើការសម្រេចចិត្តខុស? បើមិនហ៊ាន តើមកពីអ្នកមានប្រតិកម្មបែបណា?', '🎯 សកម្មភាពថ្ងៃនេះ៖ នៅក្នុងកិច្ចប្រជុំបន្ទាប់ ចូរថ្លែងអំណរគុណជាសាធារណៈដល់សមាជិកណាដែលហ៊ានចង្អុលបង្ហាញកំហុស ឬភាពខ្វះខាតនៃគម្រោង។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-leader-7', 'lesson-leader-7', 'តើអ្វីជាសញ្ញាសម្គាល់នៃក្រុមការងារដែលមានសុវត្ថិភាពផ្លូវចិត្តខ្ពស់ (High Psychological Safety)?', 'What is the hallmark of a team with high psychological safety?', '["A. សមាជិកទាំងអស់យល់ស្របតាម Leader គ្រប់រឿងដោយមិនដែលប្រកែក។","B. សមាជិកហ៊ានចោទសួរ ហ៊ានសារភាពកំហុសទាន់ពេល និងហ៊ានបញ្ចេញគំនិតខុសប្លែកពីគេដោយគ្មានការភ័យខ្លាច។","C. សមាជិកមិនដែលនិយាយរកគ្នាដើម្បីកុំឱ្យមានជម្លោះ។"]', '["A. Everyone always agrees nodding passively with the leader.","B. Teammates openly ask questions, admit mistakes early, and voice differing opinions without fear of retribution.","C. Teammates stay silent to prevent disputes."]', 1, 'ការពន្យល់៖ សុវត្ថិភាពផ្លូវចិត្តអនុញ្ញាតឱ្យមនុស្សហ៊ានប្រថុយ ហ៊ានសារភាពកំហុស និងហ៊ានច្នៃប្រឌិត ដែលជាកត្តាលេខ ១ នៃក្រុមការងារដែលមានទិន្នផលខ្ពស់។', 'Explanation: Psychological safety allows vulnerability, rapid mistake recovery, and fearless innovation.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-leader-8', 'course-leader-delegation', 'mod-1', 8, '៨. ការវាយតម្លៃបុគ្គលិកតាមក្បួន ២-៧-១ (Alibaba & GE 2-7-1 Talent Differentiation)', 'Performance Calibration & Talent Differentiation: The 2-7-1 Framework', 'text', '• យល់ដឹងពីក្បួនចាត់ថ្នាក់បុគ្គលិក ២-៧-១ (២០% ឆ្នើម, ៧០% មធ្យមរឹងមាំ, ១០% ក្រោមស្តង់ដារ)។\n• ចៀសវាងកំហុស «មនុស្សល្អគ្រប់គ្នា» (Equally Nice Bias) ដែលធ្វើឱ្យបុគ្គលិកឆ្នើមបាក់ទឹកចិត្ត។\n• បង្កើតផែនការកែលម្អការងារ (Performance Improvement Plan - PIP) សម្រាប់បុគ្គលិកក្រោមស្តង់ដារ។', 'នៅក្រុមហ៊ុន Alibaba និង General Electric (Jack Welch) ក្បួនដែកនៃការគ្រប់គ្រងគឺ «ការបែងចែកឱ្យដាច់ស្រេច» (Differentiation)៖ ២០% ជាបុគ្គលិកឆ្នើម (Star Performers) ដែលត្រូវផ្តល់រង្វាន់ និងឱកាសខ្ពស់បំផុត, ៧០% ជាឆ្អឹងខ្នងរឹងមាំ (Solid Contributors) ដែលត្រូវលើកទឹកចិត្ត និងអភិវឌ្ឍ, និង ១០% ជាបុគ្គលិកក្រោមស្តង់ដារ (Underperformers) ដែលត្រូវផ្តល់ឱកាសកែលម្អ ឬផ្លាស់ប្តូរចេញ។ ការធ្វើជាមេដឹកនាំដែលចង់ផ្គាប់ចិត្តមនុស្សគ្រប់គ្នា គឺជាការអយុត្តិធម៌បំផុតចំពោះបុគ្គលិកដែលខិតខំធ្វើការ។', '«លោក ចាន់ថុល ជាប្រធានក្រុមផ្នែកលក់។ ក្នុងពិធីចែកប្រាក់លើកទឹកចិត្ត (Incentive) ចុងឆ្នាំ ដោយសារខ្លាចសមាជិកមួយចំនួនអន់ចិត្ត គាត់បានសម្រេចចិត្តយកប្រាក់រង្វាន់សរុបមកចែកស្មើគ្នាដល់មនុស្សទាំងអស់ ទាំងអ្នកដែលសម្រេចបាន ១៥០% នៃ Target និងអ្នកដែលសម្រេចបានតែ ៤០%។ \nលទ្ធផល៖ វិរៈ ដែលជាបុគ្គលិកឆ្នើមលក់ដាច់បំផុត មានអារម្មណ៍ខកចិត្តយ៉ាងខ្លាំងព្រោះការខិតខំរបស់គាត់គ្មានតម្លៃខុសពីអ្នកដទៃ ហើយបានសម្រេចចិត្តលាលែងទៅក្រុមហ៊ុនគូប្រជែង។ រីឯបុគ្គលិកខ្ជិលច្រអូសនៅតែបន្តខ្ជិលដដែល។ ក្រោយពីបាត់បង់បុគ្គលិកឆ្នើម ចាន់ថុលទើបយល់ច្បាស់ថា "ភាពយុត្តិធម៌មិនមែនជាការចែកស្មើគ្នានោះទេ ប៉ុន្តែជាការផ្តល់ផលតបស្នងតាមលទ្ធផលការងារជាក់ស្តែង"។»', '✅ របៀបចាត់ចែងបុគ្គលិកតាមក្បួន ២-៧-១៖\n• ២០% កំពូល៖ ផ្តល់ប្រាក់រង្វាន់ខ្ពស់ ការសរសើរជាសាធារណៈ និងប្រគល់កិច្ចការយុទ្ធសាស្ត្រថ្មីៗ។\n• ៧០% កណ្តាល៖ បង្វឹកបំប៉នជំនាញ (Upskilling) និងជំរុញឱ្យពួកគេឈានចូលក្នុងក្រុម ២០%។\n• ១០% បាត៖ ជួបសន្ទនាត្រង់ៗ ដាក់ចេញ KPI កែលម្អរយៈពេល ៣០-៦០ ថ្ងៃ (PIP) ដោយច្បាស់លាស់។', 'ធ្វើតារាងវាយតម្លៃសមាជិកក្រុមរបស់អ្នកដោយបែងចែកតាមក្រុម ២-៧-១ និងកំណត់យុទ្ធសាស្ត្រគាំទ្រសម្រាប់មនុស្សម្នាក់ៗ។', 'តើអ្នកធ្លាប់មានការស្ទាក់ស្ទើរក្នុងការផ្តល់ Feedback អវិជ្ជមានដល់បុគ្គលិកដែលធ្វើការខ្សោយព្រោះខ្លាចគេខឹងដែរឬទេ?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ជួបសន្ទនាជាលក្ខណៈបុគ្គល (1-on-1) ជាមួយបុគ្គលិកកំពូលរបស់អ្នក ដើម្បីថ្លែងអំណរគុណ និងពិភាក្សាពីផែនការអភិវឌ្ឍអាជីពរបស់ពួកគេ។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-leader-8', 'lesson-leader-8', 'ហេតុអ្វីបានជាការចែករំលែកប្រាក់រង្វាន់ស្មើគ្នាដល់មនុស្សគ្រប់គ្នា (Equal Distribution) ត្រូវបានចាត់ទុកថាជាកំហុសនៃការដឹកនាំ?', 'Why is equal bonus distribution considered a critical leadership failure?', '["A. ព្រោះវាធ្វើឱ្យបុគ្គលិកឆ្នើម (High Performers) បាត់បង់ទឹកចិត្ត និងជំរុញឱ្យបុគ្គលិកខ្ជិលបន្តទម្លាប់អសកម្ម។","B. ព្រោះប្រធានក្រុមហ៊ុនមិនចូលចិត្តឃើញបុគ្គលិកសប្បាយចិត្ត។","C. ព្រោះវាខុសច្បាប់ការងារអន្តរជាតិ។"]', '["A. It demoralizes high performers and subsidizes mediocrity, driving top talent to leave.","B. Because corporate executives dislike seeing employees happy.","C. Because it violates international labor laws."]', 0, 'ការពន្យល់៖ ការចែកស្មើគ្នាគឺជាភាពអយុត្តិធម៌ចំពោះអ្នកដែលខិតខំប្រឹងប្រែង។ ការបែងចែករង្វាន់តាមស្នាដៃ (Meritocracy) ទើបជាកម្លាំងចលករនៃកំណើនស្ថាប័ន។', 'Explanation: Rewarding mediocrity equally penalizes top performers and degrades organizational culture.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-leader-9', 'course-leader-delegation', 'mod-1', 9, '៩. ការបង្វឹកសមាជិកតាមគំរូ GROW (The GROW Coaching Framework for Leaders)', 'Coaching Through Inquiry: The GROW Model for Developing Autonomous Thinkers', 'text', '• យល់ដឹងពីភាពខុសគ្នារវាងការបញ្ជា (Telling) និងការបង្វឹក (Coaching)។\n• អនុវត្តគំរូ GROW (Goal, Reality, Options, Will/Way forward) ក្នុងការប្រជុំ 1-on-1។\n• ជួយសមាជិកក្រុមឱ្យចេះគិត និងស្វែងរកដំណោះស្រាយដោយខ្លួនឯង ជំនួសឱ្យការពឹងផ្អែកលើមេដឹកនាំ។', 'ប្រសិនបើអ្នកតែងតែឆ្លើយសំណួរ និងដោះស្រាយបញ្ហាជំនួសសមាជិកក្រុមរាល់ពេល ពួកគេនឹងមិនចេះធំធាត់ឡើយ ហើយអ្នកនឹងក្លាយជា «ដបស្ទះ» (Bottleneck) នៃការងារ។ មេដឹកនាំពូកែមិនមែនជាអ្នកដែលមានចម្លើយគ្រប់យ៉ាងនោះទេ ប៉ុន្តែជាអ្នកដែល «ចេះចោទសួរសំណួរដាស់គំនិត» (Socratic Coaching) ដើម្បីជំរុញឱ្យសមាជិកទាញយកសក្តានុពល និងការទទួលខុសត្រូវចេញពីខ្លួនឯង។', '«លោកស្រី សុជាតា ជា Team Leader ផ្នែកសេវាកម្មអតិថិជន។ រាល់ពេលមានអតិថិជនពិបាក សមាជិកឈ្មោះ ធារ៉ា តែងតែរត់មកសួរថា៖ "បង! ករណីនេះខ្ញុំត្រូវធ្វើយ៉ាងណា?" កាលពីមុន សុជាតាតែងតែប្រាប់ចម្លើយភ្លាមៗ។ ក្រោយមក នាងបានប្តូរមកប្រើវិធីសាស្ត្រ GROW៖ \n• Goal: "តើគោលដៅដែលប្អូនចង់សម្រេចជាមួយអតិថិជននេះគឺជាអ្វី?" (ធារ៉ា៖ ចង់ឱ្យគាត់ស្ងប់ចិត្ត និងមិនទារលុយវិញ)\n• Reality: "តើស្ថានភាពជាក់ស្តែងឥឡូវនេះមានអ្វីខ្លះ?" (ធារ៉ា៖ គាត់ខឹងព្រោះទំនិញខូច)\n• Options: "តើប្អូនគិតថាមានជម្រើសអ្វីខ្លះដើម្បីដោះស្រាយ?" (ធារ៉ា៖ ជម្រើស ១ ប្តូរទំនិញថ្មីជូនភ្លាម, ជម្រើស ២ ជូនប័ណ្ណបញ្ចុះតម្លៃ ២០%)\n• Will: "តើប្អូនសម្រេចចិត្តជ្រើសរើសមួយណា ហើយចាប់ផ្តើមធ្វើនៅពេលណា?" (ធារ៉ា៖ ខ្ញុំជ្រើសរើសជម្រើស ១ ហើយខលទៅគាត់ឥឡូវនេះ!) \nតាមរយៈការសួរបែបនេះ ត្រឹមតែមួយខែ ធារ៉ាអាចដោះស្រាយបញ្ហាបានយ៉ាងស្ទាត់ជំនាញដោយមិនចាំបាច់រត់មករំខានសុជាតាទៀតឡើយ។»', '✅ ឈុតសំណួរបង្វឹកតាម GROW Model៖\n• G (Goal)៖ "តើលទ្ធផលល្អឥតខ្ចោះដែលអ្នកចង់ឃើញគឺបែបណា?"\n• R (Reality)៖ "តើឧបសគ្គធំបំផុតដែលកំពុងរារាំងអ្នកនៅពេលនេះគឺជាអ្វី?"\n• O (Options)៖ "ប្រសិនបើគ្មានឧបសគ្គថវិកាទេ តើអ្នកនឹងដោះស្រាយតាមវិធីណាខ្លះ?"\n• W (Will)៖ "តើជំហានដំបូងបំផុតដែលអ្នកនឹងចាប់ផ្តើមធ្វើនៅថ្ងៃនេះគឺជាអ្វី?"', 'អនុវត្តការសួរសំណួរតាម GROW Model ជាមួយសមាជិកម្នាក់ដែលមករកជំនួយពីអ្នកនៅថ្ងៃនេះ ដោយមិនប្រាប់ចម្លើយភ្លាមៗ។', 'តើអ្នកធ្លាប់មានអារម្មណ៍ហត់នឿយព្រោះសមាជិកក្រុមរត់មករកអ្នកគ្រប់រឿងតូចតាចដែរឬទេ? តើអ្នកបានបង្វឹកពួកគេឱ្យចេះគិតហើយឬនៅ?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ពេលសមាជិកមករកជំនួយថ្ងៃនេះ ចូរទប់ចិត្តកុំទាន់ប្រាប់ចម្លើយ ហើយសួរថា «ចុះប្អូនផ្ទាល់មានគំនិតយ៉ាងណាដែរ?»។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-leader-9', 'lesson-leader-9', 'នៅពេលសមាជិករត់មកសួររកដំណោះស្រាយ តើ Team Leader បែប Coach គួរធ្វើបែបណាជាដំបូង?', 'When a team member approaches asking for a solution, what should a coaching leader do first?', '["A. ប្រាប់ចម្លើយភ្លាមៗដើម្បីចំណេញពេលវេលា។","B. ចោទសួរសំណួរដាស់គំនិត (ដូចជាតាមគំរូ GROW) ដើម្បីជួយឱ្យពួកគេគិតរកជម្រើសដំណោះស្រាយដោយខ្លួនឯង។","C. ដណ្តើមការងារនោះមកធ្វើដោយខ្លួនឯងព្រោះគិតថាសមាជិកធ្វើមិនកើត។"]', '["A. Hand down the solution instantly to save minutes.","B. Ask probing questions using frameworks like GROW to guide them toward generating their own solutions.","C. Confiscate the task and do it personally."]', 1, 'ការពន្យល់៖ ការចោទសួរសំណួរជួយកសាងសាច់ដុំនៃការត្រិះរិះ និងភាពម្ចាស់ការរបស់បុគ្គលិក ជួយសម្រាលបន្ទុកមេដឹកនាំក្នុងរយៈពេលវែង។', 'Explanation: Socratic inquiry builds cognitive capability and self-reliance in team members.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-leader-10', 'course-leader-delegation', 'mod-1', 10, '១០. ការធ្វើជាខ្នងបង្អែកការពារក្រុម និងការគ្រប់គ្រងនយោបាយផ្ទៃក្នុង (Shielding the Team)', 'Shielding the Team & Navigating Internal Organizational Politics', 'text', '• យល់ដឹងពីតួនាទីរបស់ Team Leader ក្នុងការធ្វើជា «ឆត្រការពារ» (Umbrella Shield) ពីសម្ពាធមិនសមហេតុផល។\n• គ្រប់គ្រងនយោបាយផ្ទៃក្នុងស្ថាប័នដោយឈរលើផលប្រយោជន៍រួម និងគុណធម៌វិជ្ជាជីវៈ។\n• ទទួលខុសត្រូវលើការបរាជ័យ (Extreme Ownership) និងផ្តល់កិត្តិយសនៃជោគជ័យដល់កូនក្រុម។', 'មេដឹកនាំទន់ខ្សោយតែងតែ «ស្រូបយកកិត្តិយសពេលជោគជ័យ ហើយទម្លាក់កំហុសលើកូនក្រុមពេលបរាជ័យ»។ ផ្ទុយទៅវិញ មេដឹកនាំឆ្នើមគឺជាខ្នងបង្អែកដ៏រឹងមាំ (The Shield)៖ នៅពេលមានសម្ពាធ ឬការរិះគន់ពីថ្នាក់លើ ពួកគេឈរចេញមុខការពារក្រុម ប៉ុន្តែនៅពេលក្រុមសម្រេចបានជោគជ័យ ពួកគេរុញសមាជិកឱ្យឡើងទៅទទួលការកោតសរសើរ។ នេះគឺជាប្រភពនៃភក្តីភាព និងការលះបង់ពិតប្រាកដរបស់ក្រុមការងារ។', '«ក្នុងអំឡុងពេលប្រជុំគណៈគ្រប់គ្រង នាយកប្រតិបត្តិបានស្តីបន្ទោសយ៉ាងខ្លាំងព្រោះគម្រោងចេញផ្សាយ App យឺតយ៉ាវ ២ ថ្ងៃ។ លោក វិទូ ជា Team Leader មិនបានចង្អុលមុខបន្ទោស Developer ម្នាក់ណាឡើយ។ គាត់បានក្រោកឈរហើយនិយាយដោយស្ងប់ស្ងាត់ថា៖ "នេះជាទំនួលខុសត្រូវរបស់ខ្ញុំសុទ្ធសាធ។ ខ្ញុំបានប៉ាន់ប្រមាណពេលវេលាខ្វះខាត និងមិនបានផ្តល់ធនធានគ្រប់គ្រាន់ដល់ក្រុម។ ក្រុមការងារបានខិតខំអស់ពីសមត្ថភាពទាំងយប់ទាំងថ្ងៃ។ ខ្ញុំសូមទទួលខុសត្រូវ និងធានាថានឹងបញ្ចប់នៅថ្ងៃស្អែក"។ \nទង្វើដ៏ថ្លៃថ្នូរនេះបានធ្វើឱ្យសមាជិកក្រុមមានការគោរព និងស្រឡាញ់វិទូជាទីបំផុត។ យប់នោះ សមាជិកទាំងអស់បានស្ម័គ្រចិត្តជួយគ្នារហូតដល់ចប់សព្វគ្រប់។ ក្រោយមក ក្រុមការងាររបស់វិទូបានក្លាយជាក្រុមដែលមានអត្រាលាលែងពីការងារ (Turnover Rate) ទាបបំផុតនៅក្នុងក្រុមហ៊ុន។»', '✅ ក្បួនមាសនៃការទទួលខុសត្រូវរបស់មេដឹកនាំ (Extreme Ownership)៖\n• ពេលការងារបរាជ័យ៖ និយាយពាក្យថា "ខ្ញុំជាអ្នកទទួលខុសត្រូវ!" (Look in the mirror)\n• ពេលការងារជោគជ័យ៖ និយាយពាក្យថា "ដោយសារការខិតខំរបស់ក្រុមការងារទាំងអស់គ្នា!" (Look out the window)', 'គិតអំពីការបរាជ័យថ្មីៗមួយរបស់ក្រុមអ្នក ហើយសរសេរសារទទួលខុសត្រូវក្នុងនាមជា Leader ដោយមិនបន្ទោសសមាជិកណាម្នាក់ឡើយ។', 'តើអ្នកធ្លាប់មានអារម្មណ៍ចង់ទម្លាក់កំហុសលើសមាជិកក្រុមនៅចំពោះមុខថ្នាក់លើដែរឬទេ? តើទង្វើនោះបំផ្លាញទំនុកចិត្តរបស់ក្រុមយ៉ាងដូចម្តេច?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ប្រសិនបើមានបញ្ហាក្នុងក្រុមថ្ងៃនេះ ចូរទទួលខុសត្រូវជាមុន និងជួបកែលម្អជាមួយសមាជិកដោយស្ងាត់ស្ងៀមនៅខាងក្នុងបន្ទប់បិទជិត។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-leader-10', 'lesson-leader-10', 'នៅពេលគម្រោងជួបការយឺតយ៉ាវ ហើយថ្នាក់លើស្តីបន្ទោស តើទង្វើរបស់ Team Leader ដ៏គំរូគឺជាអ្វី?', 'When a project is delayed and senior executives criticize the team, what is the exemplary response of a Team Leader?', '["A. ប្រាប់ឈ្មោះសមាជិកដែលធ្វើការយឺតយ៉ាវឱ្យថ្នាក់លើដឹង ដើម្បីការពារខ្លួនឯងកុំឱ្យខូចឈ្មោះ។","B. ឈរចេញមុខទទួលខុសត្រូវក្នុងនាមជាអ្នកដឹកនាំក្រុម (Extreme Ownership) និងការពារក្រុមពីសម្ពាធអវិជ្ជមាន។","C. លាលែងពីការងារភ្លាមៗដើម្បីគេចវេះពីទំនួលខុសត្រូវ។"]', '["A. Name and shame the slowest junior teammate to preserve personal reputation.","B. Step forward, assume extreme ownership as leader, and shield the team from toxic panic.","C. Resign abruptly to evade responsibility."]', 1, 'ការពន្យល់៖ មេដឹកនាំពិតប្រាកដអនុវត្ត Extreme Ownership៖ ទទួលខុសត្រូវចំពោះភាពខ្វះខាតរបស់ក្រុម និងការពារក្រុមឱ្យមានស្មារតីរឹងមាំក្នុងការដោះស្រាយបញ្ហា។', 'Explanation: Exemplary leadership hinges on extreme ownership—absorbing blame and deflecting praise onto the team.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-man-1', 'course-manager-conflict', 'mod-1', 1, '១. ក្របខ័ណ្ឌសម្រុះសម្រួលជម្លោះរវាងសមាជិកក្រុម (Mediation & Conflict Resolution Framework)', 'Workplace Mediation & Conflict Resolution Framework', 'text', '• យល់ដឹងពីក្របខ័ណ្ឌសម្រុះសម្រួល ៤ ជំហាន៖ Separate, Listen, Bring Together, Agree។\n• ជៀសវាងការកាន់ជើងភាគីណាមួយ និងរក្សាជំហរជាភាគីកណ្តាលប្រកបដោយយុត្តិធម៌។\n• កសាងកិច្ចព្រមព្រៀងសហការជាលាយលក្ខណ៍អក្សរ (Working Agreement)។', 'ជម្លោះនៅកន្លែងធ្វើការមិនមែនសុទ្ធតែជារឿងអាក្រក់នោះទេ បើសិនជាចេះដោះស្រាយ វាអាចជាឱកាសបង្កើតការផ្លាស់ប្តូរ និងការយល់ចិត្តគ្នាកាន់តែស៊ីជម្រៅ។', '«គីមសួរ (ប្រធានផ្នែកលក់) និង វីរៈ (ប្រធានផ្នែកប្រតិបត្តិការ) បានខ្វែងគំនិតគ្នាយ៉ាងខ្លាំងរឿងនីតិវិធីដឹកជញ្ជូនឱ្យអតិថិជន VIP រហូតដល់មិននិយាយរកគ្នា ២ សប្តាហ៍។ ការងាររាំងស្ទះទាំងស្រុង។ អ្នកគ្រប់គ្រងទូទៅមិនបានស្រែកបន្ទោសពួកគេក្នុងការប្រជុំធំទេ គាត់បានកោះហៅជួបដាច់ដោយឡែកពីគ្នាម្នាក់ម្តងដើម្បីស្តាប់ទុក្ខកង្វល់ និងអារម្មណ៍របស់ពួកគេ។ បន្ទាប់មក គាត់បាននាំពួកគេទាំងពីរមកអង្គុយតុជុំគ្នា ហើយសួរថា៖ "តើយើងទាំងអស់គ្នាចង់ឱ្យអតិថិជនសប្បាយចិត្ត និងក្រុមហ៊ុនរីកចម្រើនដូចគ្នាទេ?"។ នៅពេលឃើញគោលដៅរួម ពួកគេទាំងពីរបានយល់ព្រមបត់បែននីតិវិធីម្នាក់បន្តិច ហើយការងារបានដើររលូនឡើងវិញ។»', '✅ ៤ ជំហានសម្រុះសម្រួលជម្លោះ៖\n១. SEPARATE៖ ជួបសន្ទនាដាច់ដោយឡែកជាមួយភាគីនីមួយៗដើម្បីឱ្យពួកគេបញ្ចេញអារម្មណ៍។\n២. LISTEN៖ ស្វែងរក "តម្រូវការស្នូល (Underlying Needs)" មិនមែនគ្រាន់តែពាក្យតវ៉ា។\n៣. BRING TOGETHER៖ រៀបចំជំនួបមុខទល់មុខក្នុងបន្ទប់ស្ងប់ស្ងាត់។\n៤. AGREE ON BEHAVIOR៖ បង្កើតកិច្ចព្រមព្រៀងជាក់លាក់លើទង្វើទៅថ្ងៃអនាគត។', 'កំណត់បញ្ហាខ្វែងគំនិតមួយក្នុងស្ថាប័នរបស់អ្នក ហើយសរសេរចំណុចកណ្តាលនៃផលប្រយោជន៍រួមរវាងភាគីទាំងសងខាង។', 'តើទំនោរធម្មជាតិរបស់អ្នកចំពោះជម្លោះគឺជាការគេចវេះ ឬការប្រឈមមុខ? តើការគេចវេសពីជម្លោះអាចបង្កផលវិបាកអ្វីខ្លះដល់ក្រុម?', '🎯 សកម្មភាពថ្ងៃនេះ៖ កត់ត្រាសញ្ញាដំបូងនៃជម្លោះក្នុងក្រុមដែលមិនទាន់ផ្ទុះឡើង ហើយរៀបចំការសន្ទនាស្ងប់ស្ងាត់មុនពេលវារាលដាល។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-man-1', 'lesson-man-1', 'សមាជិកគន្លឹះពីរនាក់មានជម្លោះខ្លាំងរឿងបែងចែកការងារ និងមិនព្រមនិយាយរកគ្នា។ តើជំហានដំបូងរបស់អ្នកគ្រប់គ្រងគួរធ្វើអ្វី?', 'Two key members have a major conflict over workload and refuse to speak. What should the manager do first?', '["A. កោះហៅប្រជុំបន្ទាន់ចំពោះមុខក្រុមទាំងមូល ហើយបង្ខំឱ្យពួកគេសុំទោសគ្នាភ្លាមៗ។","B. ជួបសន្ទនាដោយឡែកពីគ្នាម្នាក់ម្តង (1-on-1) ដោយស្ងប់ស្ងាត់ ដើម្បីស្តាប់ទស្សនៈ និងអារម្មណ៍របស់ពួកគេ។","C. បណ្តេញភាគីណាដែលនិយាយតិចជាងគេចេញពីក្រុមហ៊ុន។"]', '["A. Call an all-hands meeting and force them to apologize publicly.","B. Meet with each person individually in a calm setting to listen to their perspective and underlying concerns.","C. Fire the quieter party immediately."]', 1, 'ការពន្យល់៖ ជម្រើស B បង្កើតបរិយាកាសសុវត្ថិភាពដើម្បីស្វែងយល់ពីឫសគល់នៃជម្លោះ ដោយមិនធ្វើឱ្យភាគីណាមួយបាក់មុខ។', 'Explanation: Individual discovery creates safety and prevents public embarrassment.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-man-2', 'course-manager-conflict', 'mod-1', 2, '២. ការរុករកនយោបាយកន្លែងធ្វើការដោយរក្សាសីលធម៌ (Navigating Workplace Politics Ethically)', 'Navigating Workplace Politics with Integrity', 'text', '• យល់ដឹងពីភាពខុសគ្នារវាងនយោបាយបំផ្លាញ (Toxic Politics) និងឥទ្ធិពលវិជ្ជមាន (Positive Influence)។\n• កសាងតម្លាភាព និងកំណត់ហេតុការងារជាលាយលក្ខណ៍អក្សរដើម្បីការពារក្រុម។\n• បង្កើតសម្ព័ន្ធភាពវិជ្ជាជីវៈផ្អែកលើការជួយគ្នាទៅវិញទៅមក។', 'នយោបាយកន្លែងធ្វើការកើតឡើងនៅគ្រប់ទីកន្លែងដែលមានមនុស្សធ្វើការជាមួយគ្នា។ អ្នកមិនចាំបាច់ក្លាយជាមនុស្សទុច្ចរិតនោះទេ ប៉ុន្តែអ្នកត្រូវឆ្លាតវៃគ្រប់គ្រាន់ដើម្បីការពារក្រុម និងជំរុញគម្រោងឱ្យជោគជ័យ។', '«លីដា ជាអ្នកគ្រប់គ្រងគម្រោងថ្មី។ នាងបានសង្កេតឃើញថាមានអ្នកគ្រប់គ្រងជាន់ខ្ពស់ម្នាក់តែងតែនិយាយដើម និងព្យាយាមរារាំងថវិកាគម្រោងរបស់នាង។ ជំនួសឱ្យការតបតដោយការនិយាយដើមវិញ លីដាបានធ្វើរឿង ៣ យ៉ាង៖ ទីមួយ នាងកត់ត្រារាល់ការសម្រេចចិត្តក្នុងអ៊ីមែលផ្លូវការ (Minutes of Meeting)។ ទីពីរ នាងអញ្ជើញអ្នកគ្រប់គ្រងនោះចូលរួមពិនិត្យគម្រោងជាមុនដើម្បីកុំឱ្យគាត់មានអារម្មណ៍ថាបាត់បង់អំណាច។ ទីបី នាងបង្ហាញទិន្នន័យជាក់ស្តែងពីផលចំណេញដែលក្រុមហ៊ុននឹងទទួលបាន។ ទីបំផុត អ្នកគ្រប់គ្រងនោះបានប្រែក្លាយពីអ្នករារាំងមកជាអ្នកគាំទ្រគម្រោងរបស់នាងវិញ។»', '✅ យុទ្ធសាស្ត្រការពារក្រុមប្រកបដោយសីលធម៌៖\n• Paper Trail៖ រាល់កិច្ចសន្យា ឬការសម្រេចចិត្តសំខាន់ ត្រូវមានអ៊ីមែលសង្ខេបបញ្ជាក់ជានិច្ច។\n• Stakeholder Mapping៖ ស្គាល់ច្បាស់ថាអ្នកណាជាអ្នកគាំទ្រ អ្នកណានៅកណ្តាល និងអ្នកណាជាអ្នកជំទាស់ ដើម្បីរៀបចំវិធីសាស្ត្រសន្ទនាឱ្យសមស្រប។', 'កំណត់បញ្ជីឈ្មោះបុគ្គលពាក់ព័ន្ធសំខាន់ៗ (Stakeholders) ចំពោះគម្រោងរបស់អ្នក និងកំណត់យុទ្ធសាស្ត្រកសាងទំនុកចិត្តជាមួយពួកគេ។', 'តើអ្នកអាចរក្សាភាពស្មោះត្រង់ និងសីលធម៌វិជ្ជាជីវៈបានកម្រិតណា នៅពេលស្ថិតក្នុងបរិយាកាសការងារដែលមានការប្រកួតប្រជែងស្មុគស្មាញ?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ផ្ញើអ៊ីមែលសង្ខេបលទ្ធផលការងារមួយ ដោយទទួលស្គាល់ការចូលរួមចំណែករបស់សមាជិកក្រុមទាំងអស់ជាផ្លូវការ។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-man-2', 'lesson-man-2', 'មានអ្នកគ្រប់គ្រងម្នាក់ព្យាយាមយកស្នាដៃនៃគម្រោងដែលក្រុមរបស់អ្នកបានខិតខំធ្វើទៅរាយការណ៍ថាជាស្នាដៃរបស់គាត់ផ្ទាល់។ តើអ្នកគួរដោះស្រាយបែបណាប្រកបដោយវិជ្ជាជីវៈ?', 'Another manager tries to claim sole credit for a project your team built. How do you handle this professionally?', '["A. ទៅឈ្លោះប្រកែកគ្នា និងជេរប្រមាថគាត់នៅកណ្តាលបន្ទប់ធ្វើការ។","B. ផ្ញើអ៊ីមែលសង្ខេបលទ្ធផលគម្រោងជាផ្លូវការទៅកាន់ថ្នាក់ដឹកនាំជាន់ខ្ពស់ ដោយភ្ជាប់របាយការណ៍លម្អិត និងថ្លែងអំណរគុណដល់សមាជិកក្រុមម្នាក់ៗតាមតួនាទីជាក់ស្តែង។","C. ស្ងៀមស្ងាត់ហើយយំតែម្នាក់ឯងព្រោះគិតថាមិនអាចតស៊ូជាមួយគេបាន។"]', '["A. Start a screaming match in the hallway.","B. Send a transparent, data-backed completion report to executive leadership, explicitly recognizing each team member contribution.","C. Stay passive and silently accept it."]', 1, 'ការពន្យល់៖ ជម្រើស B ប្រើប្រាស់តម្លាភាព និងទិន្នន័យជាក់ស្តែង (Facts over Drama) ដើម្បីការពារសិទ្ធិ និងកិត្តិយសរបស់ក្រុមការងារប្រកបដោយសីលធម៌ខ្ពស់។', 'Explanation: Transparent, documented reporting publicly cements team contributions ethically.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-man-3', 'course-manager-conflict', 'mod-1', 3, '៣. ការចរចាប្រាក់ខែ និងកញ្ចប់អត្ថប្រយោជន៍ផ្អែកលើសមិទ្ធផល (Merit-Based Compensation Negotiation)', 'Merit-Based Compensation Negotiation', 'text', '• រៀបចំសំណើសុំឡើងប្រាក់ខែផ្អែកលើទិន្នន័យសេដ្ឋកិច្ច (Business ROI) មិនមែនផ្អែកលើតម្រូវការផ្ទាល់ខ្លួន។\n• យល់ដឹងពីទិន្នន័យទីផ្សារការងារ (Market Benchmarking) នៅកម្ពុជា។\n• ចេះចរចាអត្ថប្រយោជន៍មិនមែនសាច់ប្រាក់ (Non-monetary perks) នៅពេលថវិកាក្រុមហ៊ុនមានកម្រិត។', 'ការចរចាប្រាក់ខែដែលជោគជ័យមិនមែនជាការសុំក្តីមេត្តានោះទេ ប៉ុន្តែជាការបង្ហាញពីតម្លៃបន្ថែមដែលអ្នក ឬក្រុមរបស់អ្នកបានបង្កើតឡើងសម្រាប់ក្រុមហ៊ុន។', '«ពិសិដ្ឋ ជាអ្នកគ្រប់គ្រងចង់ស្នើសុំដំឡើងប្រាក់ខែឱ្យបុគ្គលិកឆ្នើមម្នាក់ដែលកំពុងមានការផ្តល់ជូនពីក្រុមហ៊ុនផ្សេង។ ពិសិដ្ឋមិនបានទៅប្រាប់នាយកប្រតិបត្តិថា "បុគ្គលិកនេះត្រូវការលុយមើលម្តាយឈឺ" នោះទេ (ព្រោះនោះជាបញ្ហាផ្ទាល់ខ្លួន)។ ផ្ទុយទៅវិញ ពិសិដ្ឋបានរៀបចំឯកសារមួយទំព័របង្ហាញថា៖ ក្នុងរយៈពេល ៩ ខែ បុគ្គលិកនេះបានជួយសន្សំថ្លៃចំណាយទីផ្សារបាន $18,000 និងនាំមកនូវអតិថិជនថ្មីចំនួន ៤៥ នាក់។ ប្រសិនបើគាត់ចាកចេញ ការជ្រើសរើស និងបណ្តុះបណ្តាលមនុស្សថ្មីនឹងត្រូវចំណាយយ៉ាងតិច $6,000 និងខាតពេល ៣ ខែ។ នាយកប្រតិបត្តិបានយល់ព្រមដំឡើងប្រាក់ខែ ២៥% ភ្លាមៗដោយគ្មានការស្ទាក់ស្ទើរ។»', '✅ រូបមន្តសំណើសុំឡើងប្រាក់ខែផ្អែកលើសមិទ្ធផល៖\n១. តម្លៃដែលបានបង្កើត (Value Created)៖ "ក្នុងឆ្នាំកន្លងមក ខ្ញុំបានសម្រេច..."\n២. ទិន្នន័យទីផ្សារ (Market Benchmark)៖ "យោងតាមទីផ្សារបច្ចុប្បន្នសម្រាប់តួនាទីនេះ..."\n៣. សំណើជាក់លាក់ (Specific Ask)៖ "ខ្ញុំសូមគោរពស្នើសុំការកែសម្រួលប្រាក់បំណាច់..."\n៤. ផែនការអនាគត (Future Commitment)៖ "ដើម្បីបន្តជួយក្រុមហ៊ុនសម្រេចគោលដៅ..."', 'គណនាតម្លៃសេដ្ឋកិច្ចជាក់ស្តែង (ROI) ដែលអ្នកបានជួយក្រុមហ៊ុនសន្សំប្រាក់ ឬរកចំណូលក្នុងរយៈពេល ៦ ខែចុងក្រោយ។', 'តើអ្នកបានកត់ត្រាទិន្នន័យសមិទ្ធផលការងាររបស់អ្នកជាប្រចាំដែរឬទេ? តើអ្នកអាចវាស់វែងតម្លៃការងាររបស់អ្នកជាតួលេខដោយរបៀបណា?', '🎯 សកម្មភាពថ្ងៃនេះ៖ កត់ត្រាតួលេខស្នាដៃធំៗ ៣ របស់អ្នកដែលបានជួយក្រុមហ៊ុនសន្សំពេលវេលា ឬបង្កើនប្រាក់ចំណេញ។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-man-3', 'lesson-man-3', 'នៅពេលថ្នាក់លើបដិសេធសំណើសុំដំឡើងប្រាក់ខែភ្លាមៗដោយសារថវិកាក្រុមហ៊ុនតឹងតែង តើអ្នកគ្រប់គ្រងគួរចរចាជម្រើសអ្វីបន្ត?', 'When upper management denies salary increases due to tight budgets, what should you negotiate next?', '["A. លួចយកសម្ភារការិយាល័យទៅលក់ដើម្បីប៉ះប៉ូវ។","B. ចរចាកញ្ចប់អត្ថប្រយោជន៍ផ្សេងទៀត (ដូចជា ការបត់បែនម៉ោងធ្វើការ, វគ្គបណ្តុះបណ្តាលជំនាញ, ឬកិច្ចព្រមព្រៀងពិនិត្យប្រាក់ខែឡើងវិញក្នុងរយៈពេល ៦ ខែក្រោយ)។","C. ឈប់ធ្វើការងារទាំងអស់ហើយមកអង្គុយលេងទូរស័ព្ទ។"]', '["A. Steal office supplies to compensate.","B. Negotiate non-monetary perks (flexible hours, funded certifications, or a written 6-month review milestone).","C. Stop working completely and waste time."]', 1, 'ការពន្យល់៖ ជម្រើស B រក្សាទ្វារចរចា និងបង្កើតឱកាសរីកចម្រើនរយៈពេលវែង ទោះបីជាថវិកាបច្ចុប្បន្នមានកម្រិតក៏ដោយ។', 'Explanation: Alternative perks and written milestones keep career growth moving forward.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-man-4', 'course-manager-conflict', 'mod-1', 4, '៤. ការសន្ទនាស្មុគស្មាញស្តីពីការកែលម្អការងារ (Difficult Conversations & Ethical PIPs)', 'Difficult Conversations & Performance Improvement Plans', 'text', '• ដឹកនាំការសន្ទនាត្រង់ទៅត្រង់មកស្តីពីការអនុវត្តការងារខ្សោយ (Underperformance) ប្រកបដោយការគោរព។\n• បង្កើតផែនការកែលម្អការងាររយៈពេល ៣០ ថ្ងៃ (30-Day PIP) ដែលមានគោលដៅជាក់លាក់ និងអាចវាស់វែងបាន។\n• ស្គាល់ពីនីតិវិធីច្បាប់ការងារ និងក្រមសីលធម៌ក្នុងការគ្រប់គ្រងធនធានមនុស្ស។', 'ការគេចវេសមិនព្រមនិយាយពីចំណុចខ្វះខាតរបស់បុគ្គលិក គឺជាអំពើអយុត្តិធម៌ចំពោះបុគ្គលិកនោះ និងចំពោះសមាជិកក្រុមដទៃទៀតដែលខំប្រឹងប្រែង។ ការសន្ទនាស្មោះត្រង់ជួយសង្គ្រោះអាជីពការងារ។', '«សុផាត ត្រូវជួបសន្ទនាជាមួយបុគ្គលិកចាស់វស្សាម្នាក់ដែលយឺតយ៉ាវការងារជាប្រចាំ និងតែងតែធ្វើឱ្យប៉ះពាល់ដល់ស្មារតីក្រុម។ ពីមុន សុផាតតែងតែគេចវេសព្រោះខ្លាចប៉ះពាល់មនោសញ្ចេតនា។ ប៉ុន្តែសមាជិកដទៃទៀតចាប់ផ្តើមត្អូញត្អែរ។ សុផាតបានកោះហៅគាត់ជួបឯកជន ហើយនិយាយដោយម៉ឺងម៉ាត់តែគួរសម៖ "បងជាមនុស្សសំខាន់ក្នុងក្រុមយើង ប៉ុន្តែក្នុងរយៈពេល ២ ខែចុងក្រោយនេះ លទ្ធផលការងាររបស់បងធ្លាក់ចុះ ៤០% ធៀបនឹងស្តង់ដារ។ ខ្ញុំចង់ជួយបងឱ្យទទួលបានជោគជ័យឡើងវិញ។ នេះជាផែនការកែលម្អ ៣០ ថ្ងៃ។ តើបងត្រូវការជំនួយអ្វីខ្លះពីខ្ញុំ?"។ បុគ្គលិកនោះភ្ញាក់រលឹក និងបានកែលម្អការងារឡើងវិញបានយ៉ាងល្អប្រសើរ។»', '✅ រចនាសម្ព័ន្ធផែនការកែលម្អ ៣០ ថ្ងៃ (PIP)៖\n១. គម្លាតការងារបច្ចុប្បន្ន (Current Gap)៖ "កំហុសទិន្នន័យកើតឡើង ៥ ដងក្នុងមួយខែ..."\n២. ស្តង់ដាររំពឹងទុក (Expected Standard)៖ "កំហុសមិនឱ្យលើសពី ១ ដង..."\n៣. ធនធានគាំទ្រ (Support Provided)៖ "ការបណ្តុះបណ្តាលបន្ថែម និងការ Check-in រៀងរាល់ថ្ងៃសុក្រ..."\n៤. កាលបរិច្ឆេទវាយតម្លៃចុងក្រោយ (Evaluation Date)។', 'សរសេរសេចក្តីព្រាងចំណុចចាប់ផ្តើមនៃការសន្ទនាលំបាកមួយចំពោះបុគ្គលិកដែលធ្វើការមិនទាន់តាមការរំពឹងទុក។', 'តើការគេចវេសពីការសន្ទនាលំបាក ធ្លាប់ធ្វើឱ្យបញ្ហាក្នុងក្រុមរបស់អ្នកកាន់តែរីកធំឡើងដែរឬទេ?', '🎯 សកម្មភាពថ្ងៃនេះ៖ កំណត់បញ្ហាស្មុគស្មាញមួយដែលអ្នកបានពន្យារពេលយូរមកហើយ ហើយកំណត់កាលវិភាគជជែកដោះស្រាយក្នុងសប្តាហ៍នេះ។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-man-4', 'lesson-man-4', 'បុគ្គលិកម្នាក់មិនបានបំពេញតាមការរំពឹងទុកជាបន្តបន្ទាប់។ តើវិធីសាស្ត្រដឹកនាំការសន្ទនាដ៏ត្រឹមត្រូវបំផុតគឺជាអ្វី?', 'A staff member consistently underperforms. What is the most ethical conversation approach?', '["A. ស្រែកគំរាមបណ្តេញចេញភ្លាមៗក្នុងការប្រជុំធំដើម្បីធ្វើជាគំរូដល់អ្នកដទៃ។","B. ជួបសន្ទនាឯកជន បង្ហាញទិន្នន័យជាក់លាក់ កំណត់ការរំពឹងទុកច្បាស់លាស់ និងបង្កើតផែនការគាំទ្រកែលម្អរយៈពេលជាក់លាក់។","C. មិននិយាយអ្វីទាំងអស់ ហើយលួចដកការងារគាត់ចេញស្ងាត់ៗ។"]', '["A. Scream termination threats publicly to intimidate others.","B. Hold a private meeting, present factual data, clarify expectations, and establish a supported improvement timeline.","C. Say nothing and secretly reassign all their duties."]', 1, 'ការពន្យល់៖ ជម្រើស B ផ្តល់ឱកាសយុត្តិធម៌ដល់បុគ្គលិកក្នុងការកែប្រែខ្លួន ដោយរក្សាភាពថ្លៃថ្នូរ និងគោរពសិទ្ធិការងារ។', 'Explanation: Objective, private feedback with structured support is the gold standard of ethical leadership.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-mgr-5', 'course-manager-conflict', 'mod-1', 5, '៥. ការចរចាថវិកា និងការបែងចែកធនធានរវាងនាយកដ្ឋាន (Cross-Department Budget Negotiation)', 'Cross-Department Budgeting & Resource Allocation', 'text', '• យល់ដឹងពីវិធីចរចាដណ្តើមធនធាន ឬថវិកា (Budget) ដោយមិនបង្កើតជម្លោះជាមួយប្រធានផ្នែកដទៃ។\n• បង្ហាញការវិភាគ ROI (Return on Investment) ជាក់ស្តែងជូនថ្នាក់ដឹកនាំជាន់ខ្ពស់។\n• កសាងសម្ព័ន្ធភាពអន្តរផ្នែក (Cross-functional Alliances) ដើម្បីផលប្រយោជន៍រួមរបស់ស្ថាប័ន។', 'ការចរចាថវិកាមិនមែនជាល្បែងដណ្តើមចំណិតនំខេក (Zero-sum Game) នោះទេ។ អ្នកគ្រប់គ្រងឆ្នើមបង្ហាញឱ្យឃើញថា ធនធានដែលវិនិយោគលើផ្នែករបស់ខ្លួននឹងជួយឱ្យនាយកដ្ឋានផ្សេងទៀតសម្រេច KPI បានលឿនជាងមុន។', '«ក្នុងកិច្ចប្រជុំបែងចែកថវិកាប្រចាំឆ្នាំ ផ្នែក Marketing និងផ្នែក Sales តែងតែឈ្លោះគ្នាដណ្តើមថវិកាផ្សាយពាណិជ្ជកម្ម។ វណ្ណី (Marketing Manager) មិនបានចូលទៅទាមទារដោយអារម្មណ៍ឡើយ។ នាងបានធ្វើបទបង្ហាញបង្ហាញថា ប្រសិនបើផ្តល់ថវិកា $10,000 លើយុទ្ធនាការឌីជីថល ក្រុម Sales នឹងទទួលបាន Lead អតិថិជនសក្តានុពល ២,០០០ នាក់បន្ថែម ដែលអាចបម្លែងជាការលក់បាន $50,000។ ប្រធានផ្នែក Sales មិនត្រឹមតែមិនជំទាស់ទេ ថែមទាំងគាំទ្រសំណើរបស់វណ្ណីយ៉ាងពេញទំហឹង។»', '✅ របៀបស្នើសុំថវិកាដោយផ្អែកលើ ROI៖\n«ការវិនិយោគ $5,000 លើឧបករណ៍ស្វ័យប្រវត្តនេះ នឹងកាត់បន្ថយពេលវេលាដំណើរការទិន្នន័យរបស់ក្រុមយើង ៥០% ដែលជួយឱ្យយើងឆ្លើយតបអតិថិជនបានលឿនជាងមុន ២ ដង និងបង្កើនចំណូលសរុបស្ថាប័នយ៉ាងហោចណាស់ $20,000 ក្នុងមួយឆ្នាំ។»', 'សរសេរសំណើសុំថវិកា ឬធនធានមួយទំព័រសម្រាប់គម្រោងថ្មី ដោយបញ្ជាក់ពីផលចំណេញ (ROI) ច្បាស់លាស់។', 'តើសំណើសុំថវិការបស់អ្នកកន្លងមក ធ្លាប់បានផ្តោតលើផលប្រយោជន៍រួមរបស់ក្រុមហ៊ុន ឬគ្រាន់តែជាតម្រូវការខាងក្នុងផ្នែក?', '🎯 សកម្មភាពថ្ងៃនេះ៖ គណនា ROI លើឧបករណ៍ ឬដំណើរការការងារមួយដែលផ្នែករបស់អ្នកកំពុងចង់ស្នើសុំ។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-mgr-5', 'lesson-mgr-5', 'តើវិធីសាស្ត្រចរចាសុំថវិកាបន្ថែមណាដែលមានប្រសិទ្ធភាពបំផុតនៅចំពោះមុខគណៈនាយក?', 'Which budget negotiation approach is most effective with executive leadership?', '["A. ត្អូញត្អែរថាផ្នែកខ្លួនខ្វះខាតលុយខ្លាំង ហើយបន្ទោសផ្នែកផ្សេងថាបានច្រើនពេក។","B. បង្ហាញទិន្នន័យ ROI ជាក់ស្តែងថា តើថវិកានេះនឹងជួយក្រុមហ៊ុនបង្កើតចំណូល ឬសន្សំការខាតបង់បានប៉ុន្មាន។","C. គំរាមថាបើមិនឱ្យថវិកា ក្រុមខ្លួននឹងមិនទទួលខុសត្រូវលើលទ្ធផលការងារឡើយ។"]', '["A. Complain about lack of money and blame other departments.","B. Present concrete ROI data showing how the investment drives revenue or cuts costs.","C. Threaten to disown performance outcomes."]', 1, 'ការពន្យល់៖ ជម្រើស B និយាយជាភាសាធុរកិច្ច (Business language of ROI) ដែលគណៈនាយកយកចិត្តទុកដាក់បំផុត។', 'Explanation: Executives speak the language of ROI and measurable business impact.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-mgr-6', 'course-manager-conflict', 'mod-1', 6, '៦. ការដឹកនាំស្ថាប័នឆ្លងកាត់ការផ្លាស់ប្តូរ និងវិបត្តិ (Change Management Framework)', 'Leading Organizations Through Change & Crisis', 'text', '• យល់ដឹងពីចិត្តសាស្ត្រនៃការប្រឆាំងនឹងការផ្លាស់ប្តូររបស់មនុស្ស (Resistance to Change)។\n• អនុវត្តគំរូ ៨ ជំហានរបស់ Kotter ក្នុងការដឹកនាំការផ្លាស់ប្តូរ (Kotter\'s 8-Step Change Model)។\n• ទំនាក់ទំនងប្រកបដោយតម្លាភាពដើម្បីកាត់បន្ថយការភ័យខ្លាច និងពាក្យចចាមអារ៉ាមក្នុងស្ថាប័ន។', 'ការផ្លាស់ប្តូរប្រព័ន្ធ ឬរចនាសម្ព័ន្ធស្ថាប័នបរាជ័យ មិនមែនដោយសារបច្ចេកវិទ្យាខ្សោយនោះទេ ប៉ុន្តែដោយសារអ្នកដឹកនាំមិនបានរៀបចំផ្នត់គំនិត និងចិត្តសាស្ត្ររបស់មនុស្សឱ្យត្រៀមខ្លួនជាមុន។', '«ក្រុមហ៊ុនមួយបានប្តូរពីការកត់ត្រាលើក្រដាស មកប្រើប្រាស់ប្រព័ន្ធ ERP ថ្មី។ បុគ្គលិកចាស់ៗជាច្រើនបានរអ៊ូរទាំ និងលួចកត់ក្រដាសដដែល។ ប្រធានផ្នែកថ្មីមិនបានដាក់ពិន័យឡើយ។ គាត់បានរៀបចំវគ្គចែករំលែកសួរសុខទុក្ខ បង្កើតកម្មវិធីបង្វឹកផ្ទាល់ដៃ (Mentorship) និងបង្ហាញថាប្រព័ន្ធថ្មីនេះជួយឱ្យពួកគេបានចេញទៅផ្ទះទាន់ម៉ោង ៥ ល្ងាចដោយមិនបាច់ធ្វើការថែមម៉ោង។ ត្រឹមតែ ២ ខែ បុគ្គលិកទាំងអស់បានប្រើប្រាស់ប្រព័ន្ធ ERP យ៉ាងស្ទាត់ជំនាញ។»', '✅ របៀបប្រាស្រ័យទាក់ទងពេលមានការផ្លាស់ប្តូរធំ៖\n«ការផ្លាស់ប្តូរនេះអាចធ្វើឱ្យយើងមានអារម្មណ៍មិនទម្លាប់ក្នុងសប្តាហ៍ដំបូង។ ប៉ុន្តែគោលដៅចម្បងគឺជួយកាត់បន្ថយបន្ទុកការងារស្មុគស្មាញរបស់ក្រុមយើង និងជួយឱ្យយើងមានឱកាសរីកចម្រើនក្នុងអាជីព។ យើងនឹងនៅក្បែរបងប្អូនដើម្បីគាំទ្រគ្រប់ជំហាន។»', 'កំណត់ការផ្លាស់ប្តូរមួយដែលក្រុមហ៊ុនរបស់អ្នកកំពុងអនុវត្ត ហើយសរសេរសារពន្យល់ ៣ ចំណុចដើម្បីបន្ធូរបន្ថយការព្រួយបារម្ភរបស់ក្រុម។', 'តើអ្នកផ្ទាល់ជាមនុស្សដែលបើកចិត្តចំពោះការផ្លាស់ប្តូរថ្មីៗ ឬតែងតែមានការភ័យខ្លាចចំពោះអ្វីដែលមិនធ្លាប់ស្គាល់?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ស្វែងយល់ និងសាកល្បងប្រើប្រាស់ឧបករណ៍បច្ចេកវិទ្យាថ្មីមួយ (ឧ. AI ឬ Productivity Tool) ក្នុងការងាររបស់អ្នក។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-mgr-6', 'lesson-mgr-6', 'នៅពេលក្រុមហ៊ុនប្រកាសផ្លាស់ប្តូរប្រព័ន្ធការងារថ្មី ហើយបុគ្គលិកចាប់ផ្តើមរអ៊ូរទាំ តើអ្នកគ្រប់គ្រងគួរឆ្លើយតបបែបណា?', 'When the company rolls out a new system and staff complain, how should the manager respond?', '["A. ស្រែកគំរាមថាអ្នកណាមិនធ្វើតាមនឹងត្រូវដកចេញ។","B. ស្តាប់ក្តីកង្វល់ដោយការយល់ចិត្ត បញ្ជាក់ឡើងវិញពីគុណតម្លៃ និងផ្តល់ការបណ្តុះបណ្តាលគាំទ្រជាប់លាប់។","C. បោះបង់ការផ្លាស់ប្តូរចោល ហើយត្រឡប់ទៅរកទម្លាប់ចាស់វិញ។"]', '["A. Threaten to fire anyone who resists.","B. Listen to concerns with empathy, reaffirm benefits, and provide continuous training support.","C. Abandon change and revert to old habits."]', 1, 'ការពន្យល់៖ ជម្រើស B ជួយកាត់បន្ថយភាពភ័យខ្លាច និងបង្កើតទំនុកចិត្តក្នុងការសម្របខ្លួនទៅនឹងស្តង់ដារថ្មី។', 'Explanation: Empathetic listening combined with proactive training overcomes natural resistance to change.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-manager-7', 'course-manager-conflict', 'mod-1', 7, '៧. សិល្បៈយុទ្ធសាស្ត្រស៊ុនអ៊ូ «កសាងកម្លាំងរុញច្រាន មិនបន្ទោសមនុស្ស» (Sun Tzu: Momentum over Blame)', 'Sun Tzu Art of War: Creating Strategic Momentum Instead of Blaming People', 'text', '• យល់ដឹងពីទស្សនវិជ្ជាស៊ុនអ៊ូ (Sun Tzu): «善战者 求之于势 不责于人» (អ្នកចម្បាំងដ៏ចំណាន ស្វែងរកជ័យជម្នះពីកម្លាំងរុញច្រាននៃកាលៈទេសៈ មិនបន្ទោសមនុស្សឡើយ)។\n• បង្កើតប្រព័ន្ធការងារ និងការលើកទឹកចិត្តដែលជំរុញឱ្យមនុស្សចង់ខិតខំប្រឹងប្រែងដោយស្វ័យប្រវត្តិ។\n• ផ្លាស់ប្តូរការគ្រប់គ្រងពី «ការតាមស្តីបន្ទោសបុគ្គលិក» មកជា «ការរៀបចំកម្លាំងយុទ្ធសាស្ត្រ (Shi / 势)»។', 'ទស្សនវិទូយុទ្ធសាស្ត្រ ស៊ុនអ៊ូ បានបង្រៀនថា ប្រសិនបើអ្នករុញដុំថ្មមូលមួយឱ្យរមៀលចុះពីលើកំពូលភ្នំកម្ពស់រាប់ពាន់ម៉ែត្រ ដុំថ្មនោះនឹងមានកម្លាំងរុញច្រានមហិមាដែលគ្មានអ្វីអាចទប់ស្កាត់បាន។ នេះហៅថា «កម្លាំងរុញច្រាននៃកាលៈទេសៈ (势 - Shi)»។ អ្នកគ្រប់គ្រងទន់ខ្សោយតែងតែខឹង និងស្តីបន្ទោសបុគ្គលិកថាខ្ជិល។ រីឯ Manager ឆ្នើមយល់ថា៖ មនុស្សធ្វើសកម្មភាពតាមប្រព័ន្ធ និងរចនាសម្ព័ន្ធលើកទឹកចិត្ត (Incentive Structure)។ បង្កើតកម្លាំងរុញច្រានត្រឹមត្រូវ មនុស្សធម្មតានឹងបង្កើតលទ្ធផលអស្ចារ្យ។', '«លោក សុវណ្ណ ជា Manager ផ្នែកលក់អចលនទ្រព្យ។ កាលពីមុន បុគ្គលិកផ្នែកលក់មិនសូវសហការជាមួយផ្នែកទីផ្សារទេ ហើយតែងតែបន្ទោសគ្នាទៅវិញទៅមកពេលលក់មិនដាច់។ សុវណ្ណតែងតែខឹង និងកោះប្រជុំស្តីបន្ទោសរាល់សប្តាហ៍ ប៉ុន្តែស្ថានភាពនៅតែដដែល។ \nក្រោយពីយល់ដឹងពីក្បួនស៊ុនអ៊ូ «求之于势 不责于人» គាត់បានផ្លាស់ប្តូរប្រព័ន្ធទាំងស្រុង៖ គាត់បានបង្កើតរចនាសម្ព័ន្ធកម្រៃជើងសាររួម (Shared Commission Pool) ដែលផ្នែកលក់ និងផ្នែកទីផ្សារទទួលបានប្រាក់រង្វាន់បន្ថែមជាមួយគ្នាប្រសិនបើអត្រាបិទការលក់កើនឡើង។ ភ្លាមៗនោះ កម្លាំងរុញច្រាន (势) បានកើតឡើង៖ ផ្នែកលក់បានស្ម័គ្រចិត្តទៅជួយផ្នែកទីផ្សារផលិតវីដេអូ ហើយផ្នែកទីផ្សារបានជួយតាមដានភ្ញៀវ។ ការលក់បានកើនឡើង ៣០០% ដោយសុវណ្ណមិនបាច់ស្រែកស្តីបន្ទោសមនុស្សម្នាក់ណាឡើយ។»', '✅ របៀបបង្កើតកម្លាំងរុញច្រានយុទ្ធសាស្ត្រ (Building Strategic "Shi")៖\n១. [Incentive Alignment]៖ តម្រឹមផលប្រយោជន៍របស់បុគ្គលិកឱ្យស្របគ្នាជាមួយផលប្រយោជន៍របស់ក្រុមហ៊ុន។\n②. [Remove Friction]៖ កាត់បន្ថយឧបសគ្គស្មុគស្មាញ និងដំណើរការអនុម័តដែលរារាំងល្បឿនការងារ។\n៣. [Celebrate Small Wins]៖ បង្កើតជ័យជម្នះតូចៗជាប្រចាំដើម្បីកសាងទំនុកចិត្ត និងសន្ទុះចិត្តសាស្ត្រក្នុងក្រុម។', 'វិភាគបញ្ហាមួយក្នុងនាយកដ្ឋានរបស់អ្នកដែលអ្នកធ្លាប់ស្តីបន្ទោសបុគ្គលិក ហើយស្វែងរកវិធីកែសម្រួលប្រព័ន្ធ ឬរចនាសម្ព័ន្ធលើកទឹកចិត្តដើម្បីដោះស្រាយវាដោយស្វ័យប្រវត្តិ។', 'តើអ្នកកំពុងចំណាយថាមពលច្រើនលើការព្យាយាម "កែប្រែមនុស្ស" ឬលើ "ការកែប្រែប្រព័ន្ធលើកទឹកចិត្ត" របស់ពួកគេ?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ពិនិត្យមើលរចនាសម្ព័ន្ធ KPI និងការលើកទឹកចិត្តរបស់ក្រុមអ្នក ថាតើវាជំរុញកិច្ចសហការ ឬបង្កជម្លោះ។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-manager-7', 'lesson-manager-7', 'តាមទស្សនវិជ្ជាស៊ុនអ៊ូ (Sun Tzu) តើអ្វីជាវិធីសាស្ត្ររបស់មេដឹកនាំដ៏ចំណាន (善战者)?', 'According to Sun Tzu, how does a masterful leader achieve victory?', '["A. តាមដានចាប់កំហុស និងដាក់ទណ្ឌកម្មបុគ្គលិកឱ្យបានធ្ងន់ធ្ងរបំផុត។","B. ស្វែងរកជ័យជម្នះពីការរៀបចំកម្លាំងរុញច្រាន និងបរិបទយុទ្ធសាស្ត្រ (势) ជាជាងការបន្ទោសបុគ្គលិកម្នាក់ៗ (求之于势 不责于人)។","C. បង្ខំបុគ្គលិកឱ្យធ្វើការ ២៤ ម៉ោងដោយគ្មានសម្រាក។"]', '["A. Micromanage and inflict severe punishments on individuals.","B. Harness strategic momentum and system incentives (Shi) rather than placing blame on individuals.","C. Force 24-hour work shifts without rest."]', 1, 'ការពន្យល់៖ ស៊ុនអ៊ូបង្រៀនឱ្យពឹងផ្អែកលើកម្លាំងរុញច្រាននៃប្រព័ន្ធ និងបរិបទយុទ្ធសាស្ត្រ ព្រោះកម្លាំងប្រព័ន្ធខ្លាំងជាងការបង្ខំមនុស្ស។', 'Explanation: Masterful commanders engineer favorable conditions and systemic momentum rather than scolding individuals.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-manager-8', 'course-manager-conflict', 'mod-1', 8, '៨. ការសម្រុះសម្រួលជម្លោះអំណាចរវាងនាយកដ្ឋាន (Resolving Inter-Departmental Turf Wars)', 'Mediating Inter-Departmental Conflicts: Principled Negotiation Frameworks', 'text', '• យល់ដឹងពីឫសគល់នៃសង្គ្រាមដណ្តើមទឹកដី (Turf Wars) និងថវិការវាងនាយកដ្ឋាននីមួយៗ។\n• អនុវត្តវិធីសាស្ត្រចរចាតាមគោលការណ៍របស់ Harvard (Principled Negotiation: Separate People from Problem)។\n• បង្កើតកិច្ចព្រមព្រៀងកម្រិតសេវាកម្មផ្ទៃក្នុង (Internal Service Level Agreement - SLA) ប្រកបដោយតម្លាភាព។', 'នៅពេលក្រុមហ៊ុនរីកធំឡើង Manager នីមួយៗច្រើនតែចាប់ផ្តើមកសាង «អាណាចក្រផ្ទាល់ខ្លួន» (Empire Building) ដោយការពារថវិកា និងធនធានរបស់ខ្លួនយ៉ាងស្វិតស្វាញ ដែលបង្កជាជម្លោះអន្តរនាយកដ្ឋាន។ Manager ដែលមានភាពចាស់ទុំយល់ថា៖ ជ័យជម្នះរបស់នាយកដ្ឋានមួយ មិនត្រូវធ្វើឱ្យខូចខាតដល់ក្រុមហ៊ុនទាំងមូលឡើយ។ ពួកគេចេះប្រើប្រាស់វិធីសាស្ត្រចរចាផ្អែកលើ «ផលប្រយោជន៍រួម (Interests)» មិនមែនលើ «ជំហររឹងរូស (Positions)» ឡើយ។', '«នៅក្រុមហ៊ុនបច្ចេកវិទ្យាហិរញ្ញវត្ថុមួយ ជម្លោះធ្ងន់ធ្ងរបានកើតឡើងរវាងនាយកដ្ឋានទីផ្សារ និងនាយកដ្ឋានគ្រប់គ្រងហានិភ័យ (Risk & Compliance)។ ទីផ្សារចង់ឱ្យការចុះឈ្មោះអតិថិជនមានភាពងាយស្រួលដោយមិនបាច់ស្កេនអត្តសញ្ញាណប័ណ្ណ ដើម្បីបង្កើនចំនួនអ្នកប្រើប្រាស់។ រីឯផ្នែក Risk បានបដិសេធដាច់ខាតដោយសារខ្លាចការបោកប្រាស់។ នាយកដ្ឋានទាំងពីរបានឈ្លោះគ្នាក្នុងកិច្ចប្រជុំរហូតដល់គម្រោងគាំង ៣ ខែ។ \nលោក វិបុល ជា General Manager បានកោះប្រជុំចរចាតាមគោលការណ៍ Harvard៖ គាត់បានញែកមនុស្សចេញពីបញ្ហា ហើយកំណត់ផលប្រយោជន៍ស្នូលរួមគឺ "កំណើនអ្នកប្រើប្រាស់ប្រកបដោយសុវត្ថិភាព"។ ពួកគេបានព្រមព្រៀងលើដំណោះស្រាយកណ្តាល៖ អនុញ្ញាតឱ្យចុះឈ្មោះងាយស្រួលសម្រាប់ប្រតិបត្តិការក្រោម $50 ប៉ុន្តែតម្រូវឱ្យស្កេនអត្តសញ្ញាណប័ណ្ណសម្រាប់ប្រតិបត្តិការធំជាងនេះ។ ដំណោះស្រាយនេះបានជួយឱ្យក្រុមហ៊ុនកើនអ្នកប្រើប្រាស់ ៥០% ដោយគ្មានបញ្ហាហានិភ័យផ្លូវច្បាប់ឡើយ។»', '✅ ជំហាន ៤ នៃការចរចាសម្រុះសម្រួលជម្លោះអន្តរនាយកដ្ឋាន (Harvard Model)៖\n១. [Separate People from Problem]៖ វាយប្រហារលើបញ្ហា កុំវាយប្រហារលើបុគ្គលិកលក្ខណៈរបស់ដៃគូសន្ទនា។\n②. [Focus on Interests, Not Positions]៖ កុំជជែកថា "ខ្ញុំចង់បានចំណុច A" ប៉ុន្តែត្រូវសួរថា "ហេតុអ្វីបានជាចំណុច A សំខាន់ចំពោះអ្នក?"\n៣. [Invent Options for Mutual Gain]៖ រួមគ្នាបំផុសគំនិតរកជម្រើសថ្មីៗដែលផ្តល់ផលប្រយោជន៍ដល់ភាគីទាំងសងខាង (Win-Win)។\n៤. [Use Objective Criteria]៖ ប្រើប្រាស់ទិន្នន័យទីផ្សារ ឬច្បាប់ជាគោល មិនប្រើអារម្មណ៍ផ្ទាល់ខ្លួន។', 'គិតអំពីជម្លោះ ឬការខ្វែងគំនិតគ្នាបច្ចុប្បន្នរវាងផ្នែករបស់អ្នក និងផ្នែកដទៃ ហើយរៀបចំបញ្ជីផលប្រយោជន៍រួម (Shared Interests) ចំនួន ៣ ដើម្បីយកទៅជជែកជាមួយពួកគេ។', 'តើអ្នកធ្លាប់ប្រកាន់ជំហររឹងរូសជាមួយផ្នែកដទៃរហូតដល់ភ្លេចគិតពីផលប្រយោជន៍រួមរបស់ក្រុមហ៊ុនទាំងមូលដែរឬទេ?', '🎯 សកម្មភាពថ្ងៃនេះ៖ អញ្ជើញ Manager នៃនាយកដ្ឋានដែលធ្លាប់មានការខ្វែងគំនិតជាមួយអ្នក ទៅញ៉ាំកាហ្វេដើម្បីស្វែងយល់ពីគោលដៅ និងសម្ពាធការងាររបស់ពួកគេ។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-manager-8', 'lesson-manager-8', 'នៅក្នុងវិធីសាស្ត្រចរចាតាមគោលការណ៍ (Principled Negotiation) តើអ្វីជាភាពខុសគ្នារវាង Positions និង Interests?', 'In Principled Negotiation, what is the crucial difference between Positions and Interests?', '["A. Positions គឺជាផលប្រយោជន៍លាក់កំបាំង រីឯ Interests គឺជាតំណែងការងារ។","B. Positions គឺជាអ្វីដែលភាគីទាមទារជាក់ស្តែង (ជំហរខាងក្រៅ) រីឯ Interests គឺជាតម្រូវការ ឬការបារម្ភពិតប្រាកដដែលនៅពីក្រោយការទាមទារនោះ។","C. Positions និង Interests មានន័យដូចគ្នាទាំងស្រុង។"]', '["A. Positions are hidden agendas while Interests are job titles.","B. Positions are rigid external demands, whereas Interests are the underlying needs, fears, and desires driving those demands.","C. Positions and Interests are identical."]', 1, 'ការពន្យល់៖ ជម្លោះច្រើនតែកកស្ទះដោយសារភាគីតោងទាមជំហរខាងក្រៅ (Positions)។ នៅពេលយើងស្វែងយល់ពីតម្រូវការពិតប្រាកដ (Interests) យើងនឹងរកឃើញដំណោះស្រាយ Win-Win។', 'Explanation: Uncovering underlying interests unlocks creative solutions that rigid positional bargaining obscures.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-manager-9', 'course-manager-conflict', 'mod-1', 9, '៩. ការដោះស្រាយបុគ្គលិកពូកែតែបំពានវប្បធម៌ «ក្បួនឆ្កែព្រៃរបស់ Alibaba» (Alibaba: Eliminating Wild Dogs)', 'Handling Toxic High-Performers: The Alibaba "Wild Dog" (野狗) Culture Matrix', 'text', '• យល់ដឹងពីម៉ាទ្រីសបុគ្គលិករបស់ Alibaba (តារា, ទន្សាយស, ឆ្កែព្រៃ, សត្វឆ្កែ)។\n• ស្គាល់ពីគ្រោះថ្នាក់នៃ «ឆ្កែព្រៃ» (Wild Dog: បុគ្គលិកលក់ដាច់ខ្លាំង ឬបច្ចេកទេសពូកែ តែមានចរិត Toxic បំពានសីលធម៌)។\n• ហ៊ានធ្វើការសម្រេចចិត្តដ៏ឈឺចាប់ដើម្បីការពារវប្បធម៌ និងគុណតម្លៃស្នូលរបស់ស្ថាប័ន។', 'នៅក្រុមហ៊ុន Alibaba ស្ថាបនិក Jack Ma បានបែងចែកបុគ្គលិកជា ៤ ប្រភេទ៖ \n១. សត្វឆ្កែ (Dog)៖ សមត្ថភាពខ្សោយ វប្បធម៌ខ្សោយ -> ត្រូវបណ្តេញចេញភ្លាមៗ។\n②. ទន្សាយស (White Rabbit)៖ មនុស្សល្អរួសរាយ តែគ្មានសមត្ថភាព -> ត្រូវបង្វឹក ឬផ្លាស់ប្តូរចេញបើមិនរីកចម្រើន។\n៣. តារា (Star)៖ សមត្ថភាពឆ្នើម វប្បធម៌ឆ្នើម -> ជាឆ្អឹងខ្នងក្រុមហ៊ុនដែលត្រូវលើកតម្កើង។\n៤. ឆ្កែព្រៃ (Wild Dog / 野狗)៖ សមត្ថភាពខ្ពស់ខ្លាំង លក់ដាច់ខ្លាំង ប៉ុន្តែបំពានច្បាប់ បំផ្លាញវប្បធម៌ និងជិះជាន់អ្នកដទៃ។ ក្បួនដែករបស់ Alibaba គឺ៖ «ឆ្កែព្រៃត្រូវតែសម្លាប់ចោលភ្លាមៗ (Fire the Wild Dog)» ព្រោះបើទុកយូរ ស្ថាប័ននឹងត្រូវរលាយ។', '«លោក សុភ័ក្ត្រ ជាបុគ្គលិកលក់កំពូល (Top Sales) នៅក្រុមហ៊ុនចែកចាយរថយន្តមួយ ដោយគាត់ម្នាក់ឯងរកចំណូលបាន ៣៥% នៃចំណូលសរុបរបស់ក្រុមហ៊ុន។ ប៉ុន្តែ សុភ័ក្ត្រមានចរិតក្រអឺតក្រទម តែងតែជេរប្រមាថបុគ្គលិករដ្ឋបាល លួចទិន្នន័យភ្ញៀវរបស់សហការី និងមិនដែលចូលរួមប្រជុំក្រុមហ៊ុនឡើយ។ បុគ្គលិកល្អៗជាច្រើនបានលាលែងពីការងារដោយសារទ្រាំនឹងគាត់មិនបាន។ \nManager មុនៗមិនហ៊ានប៉ះពាល់គាត់ទេ ព្រោះខ្លាចបាត់បង់ចំណូល។ ប៉ុន្តែនៅពេលលោកស្រី លីដា ចូលកាន់តំណែងជា General Manager នាងបានព្រមានសុភ័ក្ត្រ ២ ដងអំពីរឿងក្រមសីលធម៌។ នៅពេលសុភ័ក្ត្រនៅតែបំពាន នាងបានសម្រេចចិត្តបញ្ចប់កិច្ចសន្យាការងាររបស់គាត់ភ្លាមៗ។ \nដំបូងឡើយ ការលក់ធ្លាក់ចុះបន្តិចក្នុងខែទីមួយ ប៉ុន្តែបរិយាកាសការងារប្រែជាស្រស់ស្រាយ និងមានទំនុកចិត្តឡើងវិញ។ បុគ្គលិកផ្សេងទៀតបានរួបរួមគ្នាខិតខំប្រឹងប្រែង ហើយត្រឹមតែ ៣ ខែក្រោយមក ការលក់សរុបរបស់ក្រុមហ៊ុនបានកើនឡើងលើសកាលពីមុនទៅទៀត។»', '✅ សញ្ញាសម្គាល់បុគ្គលិកប្រភេទ «ឆ្កែព្រៃ» (Toxic High-Performer Signs)៖\n• បង្កើតលទ្ធផលលេខល្អ ប៉ុន្តែបន្សល់ទុកនូវ «ជនរងគ្រោះ» ជាច្រើននៅជុំវិញខ្លួន។\n• គិតថាខ្លួនឯងធំជាងក្រុមហ៊ុន ហើយច្បាប់ ឬវិន័យស្ថាប័នមិនអាចអនុវត្តលើខ្លួនបាន។\n• បង្កើតបក្សពួកនិយម និងនិយាយដើមបង្ខូចកេរ្តិ៍ឈ្មោះថ្នាក់ដឹកនាំនៅពីក្រោយខ្នង។', 'វាយតម្លៃក្រុមការងាររបស់អ្នកតាមម៉ាទ្រីស Alibaba (Star, Rabbit, Wild Dog, Dog) ហើយរៀបចំវិធានការដោះស្រាយឱ្យបានទាន់ពេលវេលា។', 'តើនៅក្នុងស្ថាប័នរបស់អ្នកមានបុគ្គលិកណាដែលពូកែ ប៉ុន្តែគ្រប់គ្នានៅក្បែរមានអារម្មណ៍ភ័យខ្លាច និងធុញទ្រាន់ដែរឬទេ? តើអ្នកមានភាពក្លាហានក្នុងការចាត់វិធានការលើពួកគេឬនៅ?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ពិនិត្យមើលថាតើការវាយតម្លៃបុគ្គលិកក្នុងផ្នែករបស់អ្នកបានដាក់ពិន្ទុលើ «គុណតម្លៃ និងវប្បធម៌» ស្មើនឹង «លទ្ធផលការងារ (KPI)» ហើយឬនៅ។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-manager-9', 'lesson-manager-9', 'ហេតុអ្វីបានជាទស្សនវិជ្ជាគ្រប់គ្រងរបស់ Alibaba តម្រូវឱ្យបណ្តេញបុគ្គលិកប្រភេទ «ឆ្កែព្រៃ» (Wild Dog: ពូកែតែ Toxic) ចេញពីក្រុមហ៊ុន?', 'Why does Alibaba management philosophy mandate the termination of "Wild Dogs" (toxic high-performers)?', '["A. ព្រោះក្រុមហ៊ុនមិនចូលចិត្តមនុស្សដែលរកលុយបានច្រើន។","B. ព្រោះបើទុកឱ្យបុគ្គលិក Toxic នៅបន្ត ពួកគេនឹងបំផ្លាញវប្បធម៌ស្ថាប័ន បណ្តេញបុគ្គលិកល្អៗដទៃទៀតឱ្យចាកចេញ និងបង្កមហន្តរាយរយៈពេលវែង។","C. ព្រោះចង់សន្សំប្រាក់កម្រៃជើងសារ (Commission) របស់ពួកគេ។"]', '["A. Because companies dislike employees who generate too much revenue.","B. Because toxic high-performers poison institutional culture, drive away ethical talent, and eventually destroy the enterprise.","C. To cut commission payouts."]', 1, 'ការពន្យល់៖ វប្បធម៌ និងគុណតម្លៃស្នូលមានតម្លៃថ្លៃជាងលទ្ធផលលក់បណ្តោះអាសន្ន។ ការអត់ឱនចំពោះមនុស្ស Toxic គឺជាការបំផ្លាញស្ថាប័នពីខាងក្នុង។', 'Explanation: Tolerating toxic high-performers destroys organizational trust and triggers an exodus of good talent.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-manager-10', 'course-manager-conflict', 'mod-1', 10, '១០. យុទ្ធសាស្ត្ររក្សាបុគ្គលិកឆ្នើម «កិច្ចសម្ភាសន៍មុនពេលគេចាកចេញ» (Stay Interviews)', 'Proactive Talent Retention: Conducting High-Impact Stay Interviews', 'text', '• យល់ដឹងពីភាពខុសគ្នារវាង Exit Interview (សម្ភាសន៍ពេលគេដាក់ពាក្យឈប់ហើយ) និង Stay Interview (សម្ភាសន៍ដើម្បីរក្សាទុក)។\n• កំណត់សញ្ញាព្រមានដំបូងនៃការបាក់ទឹកចិត្ត (Burnout) និងការលាលែងដោយស្ងៀមស្ងាត់ (Quiet Quitting)។\n• បង្កើតផែនការរក្សាបុគ្គលិកឆ្នើម (Retention Strategy) ដោយផ្អែកលើការលើកទឹកចិត្តផ្លូវចិត្ត មិនមែនត្រឹមតែលុយ។', 'អ្នកគ្រប់គ្រងភាគច្រើនរង់ចាំរហូតដល់បុគ្គលិកឆ្នើមកាន់លិខិតលាលែងពីការងារមកដាក់លើតុ ទើបភ្ញាក់ផ្អើល និងសួរនាំ (Exit Interview) ដែលនៅពេលនោះវាបានយឺតពេលទៅហើយ។ Manager ឆ្លាតវៃតែងតែរៀបចំ «Stay Interview» — ការជជែកពិភាក្សាដោយស្មោះត្រង់ជាមួយបុគ្គលិកឆ្នើមក្នុងពេលដែលពួកគេនៅមានក្តីសប្បាយរីករាយក្នុងការងារ ដើម្បីស្វែងយល់ថាតើអ្វីដែលធ្វើឱ្យពួកគេបន្តនៅជាមួយក្រុមហ៊ុន និងអ្វីដែលអាចធ្វើឱ្យពួកគេចាកចេញ។', '«កញ្ញា សុជាតា ជា Senior Marketing Specialist ដ៏ឆ្នើមម្នាក់។ នាងធ្វើការបានយ៉ាងល្អឥតខ្ចោះ ប៉ុន្តែមួយរយៈចុងក្រោយនេះ នាងចាប់ផ្តើមស្ងាត់ស្ងៀមក្នុងកិច្ចប្រជុំ។ \nManager របស់នាងគឺលោក ពិសិដ្ឋ បានកត់សម្គាល់ឃើញភ្លាមៗ។ គាត់មិនបានរង់ចាំទេ គាត់បានអញ្ជើញសុជាតាមកញ៉ាំកាហ្វេ និងធ្វើ Stay Interview ដោយសួរថា៖ "សុជាតា ប្អូនជាកម្លាំងស្នូលដ៏មានតម្លៃរបស់ក្រុមហ៊ុន។ តើអ្វីដែលធ្វើឱ្យប្អូនចូលចិត្តបំផុតក្នុងការងារបច្ចុប្បន្ន? ហើយតើមានចំណុចណាខ្លះដែលធ្វើឱ្យប្អូនមានអារម្មណ៍ធុញទ្រាន់ ឬអស់កម្លាំងចិត្ត?" \nសុជាតាបានសារភាពដោយស្មោះត្រង់ថានាងមានអារម្មណ៍ជាប់គាំង ព្រោះនាងចង់រៀនជំនាញយុទ្ធសាស្ត្រទិន្នន័យ (Data Strategy) ប៉ុន្តែរាល់ថ្ងៃត្រូវរវល់តែរៀបចំ Event តូចតាច។ ពិសិដ្ឋបានកែសម្រួលការងាររបស់នាងភ្លាមៗ ដោយផ្ទេរការងារ Event ទៅឱ្យ Junior និងផ្តល់ថវិកាឱ្យនាងរៀនវគ្គ Data Analytics។ សុជាតាមានការរំភើបយ៉ាងខ្លាំង ហើយបានបដិសេធការផ្តល់ការងារពីក្រុមហ៊ុនដទៃដែលឱ្យប្រាក់ខែខ្ពស់ជាង។»', '✅ សំណួរគន្លឹះ ៥ សម្រាប់ Stay Interview៖\n១. "តើអ្វីដែលធ្វើឱ្យអ្នកទន្ទឹងរង់ចាំមកធ្វើការនៅរាល់ព្រឹក?"\n②. "តើអ្វីដែលអ្នកចង់រៀនសូត្រ ឬអភិវឌ្ឍបន្ថែមក្នុងឆ្នាំនេះ?"\n៣. "ប្រសិនបើអ្នកមានដំបងសិល្ប៍ តើចំណុចមួយណាដែលអ្នកចង់ផ្លាស់ប្តូរក្នុងការងារបច្ចុប្បន្ន?"\n៤. "តើអ្នកធ្លាប់មានអារម្មណ៍ថាការខិតខំរបស់អ្នកត្រូវបានគេមើលរំលងដែរឬទេ?"\n៥. "តើខ្ញុំក្នុងនាមជា Manager អាចជួយគាំទ្រអ្នកឱ្យជោគជ័យជាងនេះដោយរបៀបណា?"', 'កំណត់បុគ្គលិកឆ្នើម ២ នាក់នៅក្នុងក្រុមរបស់អ្នក ហើយរៀបចំកាលវិភាគធ្វើ Stay Interview រយៈពេល ៣០ នាទីជាមួយពួកគេក្នុងសប្តាហ៍នេះ។', 'តើអ្នកដឹងច្បាស់ទេថាតើបុគ្គលិកឆ្នើមបំផុតរបស់អ្នកកំពុងសប្បាយចិត្ត ឬកំពុងលួចរៀបចំ CV ស្វែងរកការងារថ្មី?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ផ្ញើសារអញ្ជើញបុគ្គលិកឆ្នើមម្នាក់របស់អ្នកជួបសន្ទនា Stay Interview ដោយបើកចំហ និងស្មោះត្រង់។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-manager-10', 'lesson-manager-10', 'តើអ្វីជាអត្ថប្រយោជន៍ចម្បងនៃ Stay Interview ធៀបនឹង Exit Interview?', 'What is the primary advantage of a Stay Interview compared to an Exit Interview?', '["A. ចំណាយពេលតិចជាង។","B. វាជាវិធានការបង្ការជាមុន (Proactive Retention) ដែលជួយដោះស្រាយបញ្ហាមុនពេលបុគ្គលិកសម្រេចចិត្តដើរចេញ មិនមែនរង់ចាំទាល់តែបាត់បង់ទើបស្តាយក្រោយ។","C. ដើម្បីកាត់បន្ថយប្រាក់ខែបុគ្គលិក។"]', '["A. It requires less time.","B. It is a proactive retention tool uncovering flight risks and addressing frustrations while top talent is still engaged, rather than conducting post-mortems after resignation.","C. It helps decrease employee pay."]', 1, 'ការពន្យល់៖ Stay Interview គឺជាការការពារជាមុន។ ការស្វែងយល់ពីតម្រូវការរបស់បុគ្គលិកឆ្នើមនៅពេលពួកគេនៅធ្វើការ ជួយសង្គ្រោះក្រុមហ៊ុនពីការបាត់បង់ធនធានមនុស្សដ៏មានតម្លៃ។', 'Explanation: Stay interviews proactively identify disengagement triggers while talent can still be retained.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-found-1', 'course-founder-sme', 'mod-1', 1, '១. យុទ្ធសាស្ត្រជ្រើសរើសបុគ្គលិកសម្រាប់ SME (Attitude-First Hiring for SME Culture)', 'Hiring for Attitude & Cultural Fit in SMEs', 'text', '• យល់ដឹងពីគ្រោះថ្នាក់នៃការជ្រើសរើសមនុស្សខុសក្នុងក្រុមតូច (Toxic Apple effect)។\n• របៀបសម្ភាសន៍ដើម្បីស្វែងរកមនុស្សដែលមានស្មារតីម្ចាស់ការ (Ownership Mindset)។\n• កំណត់គុណតម្លៃស្នូល (Core Values) ដែលមិនអាចចរចាបាន (Non-negotiables)។', 'សម្រាប់ SME បុគ្គលិកម្នាក់មិនមែនគ្រាន់តែជាកម្លាំងពលកម្មទេ គាត់គឺជា 10% ទៅ 20% នៃវប្បធម៌ក្រុមហ៊ុនទាំងមូល។ ចូរជ្រើសរើសមនុស្សដែលមានអត្តចរិតល្អ ស្មោះត្រង់ រួចបណ្តុះបណ្តាលជំនាញតាមក្រោយ។', '«ស្ថាបនិកហាងកាហ្វេ និងនំប៉័ង SME មួយនៅសៀមរាប បានជ្រើសរើស Barista ពូកែមានបទពិសោធន៍ ៥ ឆ្នាំ ប៉ុន្តែគាត់មានចរិតឆ្មើងឆ្មៃ មិនស្តាប់យោបល់ និងបង្កជម្លោះរាល់ថ្ងៃ។ ក្នុងរយៈពេល ២ ខែ បុគ្គលិកចាស់ៗដែលស្មោះត្រង់បានលាលែងអស់ ៣ នាក់ ហើយអតិថិជនចាប់ផ្តើមរត់ចោល។ ក្រោយមក ម្ចាស់អាជីវកម្មបានប្តូរយុទ្ធសាស្ត្រមកជ្រើសរើសយុវជនថ្មីដែលមានស្នាមញញឹម ស្រលាញ់សេវាកម្ម រួចបញ្ជូនទៅរៀនឆុងកាហ្វេបន្ថែម។ អាជីវកម្មបានវិលត្រឡប់មករីករាយ និងមានអតិថិជនពេញៗហាងវិញ។»', '✅ សំណួរសម្ភាសន៍ស្វែងរក Ownership Mindset៖\n• "សូមរៀបរាប់ពីកំហុសធំបំផុតដែលអ្នកធ្លាប់បានធ្វើនៅកន្លែងការងារចាស់? តើអ្នកបានដោះស្រាយវាដោយរបៀបណា?"\n• "ប្រសិនបើអ្នកឃើញឥដ្ឋការ៉ូក្នុងហាងបាក់បែក ឬសំរាមធ្លាក់លើដី ដែលមិនមែនជាតួនាទីអ្នក តើអ្នកនឹងធ្វើដូចម្តេច?"', 'បង្កើតបញ្ជីគុណតម្លៃស្នូល ៣ យ៉ាង (Core Values) ដែលបុគ្គលិកគ្រប់រូបក្នុងអាជីវកម្មរបស់អ្នកត្រូវតែមានជាដាច់ខាត។', 'តើអ្នកធ្លាប់ជ្រើសរើសបុគ្គលិកដោយសារតែ CV ស្អាត ប៉ុន្តែចរិតមិនត្រូវគ្នាដែរឬទេ? តើបទពិសោធន៍នោះបង្រៀនអ្វីខ្លះដល់អ្នក?', '🎯 សកម្មភាពថ្ងៃនេះ៖ កំណត់ច្បាស់នូវចំណុចដែលអ្នកមិនអាចទទួលយកបាន (Non-negotiables) ក្នុងការជ្រើសរើសបុគ្គលិកបន្ទាប់។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-found-1', 'lesson-found-1', 'នៅពេលសម្ភាសន៍ជ្រើសរើសបុគ្គលិកដំបូងសម្រាប់អាជីវកម្ម SME តើកត្តាណាដែលស្ថាបនិកគួរផ្តល់អាទិភាពខ្ពស់បំផុត?', 'When hiring early team members for an SME, what factor should the founder prioritize most?', '["A. សញ្ញាបត្រខ្ពស់ៗពីបរទេស ទោះបីជាគាត់មានអត្តចរិតឆ្មើងឆ្មៃ និងមិនចង់ចុះធ្វើការជាក់ស្តែងក៏ដោយ។","B. អត្តចរិតល្អ ភាពស្មោះត្រង់ ឆន្ទៈរៀនសូត្រ និងស្មារតីម្ចាស់ការដែលស្របនឹងវប្បធម៌ក្រុម។","C. អ្នកដែលទាមទារប្រាក់ខែថោកបំផុតទោះបីជាគ្មានការទទួលខុសត្រូវក៏ដោយ។"]', '["A. Elite foreign degrees even if arrogant and unwilling to get hands dirty.","B. Strong work ethic, integrity, eagerness to learn, and ownership mindset aligned with culture.","C. The cheapest salary candidate regardless of reliability."]', 1, 'ការពន្យល់៖ ជម្រើស B ធានាថាក្រុមការងារអាចសហការគ្នាបានរលូន និងមានភាពស្មោះត្រង់ក្នុងដំណាក់កាលកសាងអាជីវកម្ម។ ជំនាញបច្ចេកទេសអាចបង្រៀនបាន តែអត្តចរិតពិបាកកែប្រែណាស់។', 'Explanation: Skills can be trained rapidly, but character and attitude are difficult to alter.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-found-2', 'course-founder-sme', 'mod-1', 2, '២. ការគ្រប់គ្រងលំហូរសាច់ប្រាក់ និងវិន័យហិរញ្ញវត្ថុ SME (Cash Flow Survival & Financial Runway)', 'Cash Flow Survival & Financial Literacy for Founders', 'text', '• បែងចែកដាច់រវាង "ប្រាក់ចំណេញលើក្រដាស (Accounting Profit)" និង "សាច់ប្រាក់ជាក់ស្តែងក្នុងដៃ (Cash in Bank)"។\n• គណនារយៈពេលសាច់ប្រាក់បម្រុង (Runway) ឱ្យបានយ៉ាងតិច ៣ ទៅ ៦ ខែសម្រាប់ចំណាយថេរ។\n• អនុវត្តគោលការណ៍ទារបំណុល និងការតម្រូវឱ្យកក់ប្រាក់មុន។', 'អាជីវកម្មមិនមែនដួលរលំដោយសារគ្មានប្រាក់ចំណេញនោះទេ ភាគច្រើនដួលរលំដោយសារដាច់សាច់ប្រាក់បង្វិល (Cash Crunch)។ សាច់ប្រាក់គឺជាអុកស៊ីសែននៃអាជីវកម្ម។', '«ក្រុមហ៊ុនលក់សម្ភារបច្ចេកវិទ្យាមួយមានការកុម្ម៉ង់ទិញរាប់ម៉ឺនដុល្លារក្នុងមួយខែ។ ម្ចាស់អាជីវកម្មសប្បាយចិត្តដោយគិតថាខ្លួនកំពុងចំណេញធំ។ ប៉ុន្តែគាត់អនុញ្ញាតឱ្យអតិថិជនជំពាក់ ៦០ ថ្ងៃ ខណៈដែលគាត់ត្រូវបើកប្រាក់ខែបុគ្គលិក និងបង់ថ្លៃជួលរាល់ខែ។ នៅខែទី ៣ អតិថិជនធំ ២ នាក់ពន្យារពេលសងលុយ ធ្វើឱ្យក្រុមហ៊ុនគ្មានលុយបើកប្រាក់ខែឱ្យកូនចៅ។ ស្ថាបនិកត្រូវបង្ខំចិត្តខ្ចីការប្រាក់ក្រៅប្រព័ន្ធយ៉ាងវេទនា។ ក្រោយមក គាត់បានកែប្រែគោលការណ៍តម្រូវឱ្យកក់ ៥០% មុនជានិច្ច ទើបស្រោចស្រង់ស្ថានភាពហិរញ្ញវត្ថុបានរឹងមាំឡើងវិញ។»', '✅ ក្បួនមាសគ្រប់គ្រងលំហូរសាច់ប្រាក់៖\n• Runway = [សាច់ប្រាក់សុទ្ធក្នុងធនាគារ] ÷ [ចំណាយថេរប្រចាំខែ (Fixed Costs)]\n• ប្រសិនបើ Runway តិចជាង ៣ ខែ ត្រូវកាត់បន្ថយចំណាយមិនចាំបាច់ភ្លាមៗ និងបង្កើនល្បឿនទារបំណុលចាស់ៗ។', 'គណនាចំណាយថេរប្រចាំខែ (Fixed Costs) របស់អាជីវកម្មរបស់អ្នក និងចំនួនខែនៃ Runway ដែលអ្នកមានបច្ចុប្បន្ន។', 'តើអ្នកធ្លាប់ជួបវិបត្តិគេជំពាក់លុយមិនសងរហូតដល់គ្មានលុយបង្វិលដែរឬទេ? តើអ្នកមានប្រព័ន្ធតាមដានលំហូរសាច់ប្រាក់ប្រចាំសប្តាហ៍ហើយឬនៅ?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ពិនិត្យមើលបញ្ជីបំណុលដែលអតិថិជនជំពាក់ហួសកាលកំណត់ ហើយទូរស័ព្ទតាមដានភ្លាមៗនៅថ្ងៃនេះ។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-found-2', 'lesson-found-2', 'អាជីវកម្មរបស់អ្នកមានរបាយការណ៍គណនេយ្យបង្ហាញថាចំណេញ $5,000 ក្នុងខែនេះ ប៉ុន្តែគណនីធនាគារសល់លុយមិនគ្រប់បើកប្រាក់ខែបុគ្គលិក។ តើបញ្ហាពិតប្រាកដមកពីអ្វី?', 'Your accounting statement shows $5,000 profit, but your bank account lacks cash for payroll. What is the root cause?', '["A. ធនាគារលួចកាត់លុយដោយមិនដឹងខ្លួន។","B. វិបត្តិលំហូរសាច់ប្រាក់ (Cash Flow crunch) ដោយសារប្រាក់ចំណេញជាប់គាំងលើបំណុលដែលអតិថិជនមិនទាន់សង ឬទំនិញគរក្នុងស្តុកច្រើនពេក។","C. បុគ្គលិកគណនេយ្យធ្វើលេខខុសទាំងស្រុង។"]', '["A. Bank silently stole the money.","B. Cash flow crunch caused by uncollected receivables or capital tied up in slow inventory.","C. Accounting staff fabricated everything."]', 1, 'ការពន្យល់៖ ជម្រើស B ពន្យល់ពីគម្លាតរវាងប្រាក់ចំណេញលើក្រដាស (Accrual Profit) និងសាច់ប្រាក់ជាក់ស្តែង (Real Cash)។ ការគ្រប់គ្រងបំណុល និងស្តុកមានសារៈសំខាន់ស្មើនឹងការលក់។', 'Explanation: Accrual profit does not equal cash in bank when receivables and stock lock liquidity.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-found-3', 'course-founder-sme', 'mod-1', 3, '៣. របៀបចាកចេញពីតួនាទីជា "អ្នកធ្វើការ" ទៅជា "អ្នកដឹកនាំ" (Working ON vs IN Business & SOPs)', 'Transitioning from Doer to Strategic Leader with SOPs', 'text', '• យល់ដឹងពីសៀវភៅប្រតិបត្តិការស្តង់ដារ (SOPs) ដើម្បីកុំឱ្យអាជីវកម្មពឹងផ្អែកតែលើរូបអ្នកម្នាក់ឯង។\n• កសាងប្រព័ន្ធប្រតិបត្តិការដែលដំណើរការដោយស្វ័យប្រវត្ត (Self-sustaining systems)។\n• បែងចែកពេលវេលាសម្រាប់យុទ្ធសាស្ត្រពង្រីកទីផ្សារ ជំនួសឱ្យការដោះស្រាយបញ្ហាតូចតាចរាល់ថ្ងៃ។', 'ប្រសិនបើអាជីវកម្មរបស់អ្នកមិនអាចដំណើរការបាននៅពេលអ្នកឈឺ ឬចេញទៅក្រៅ ២ សប្តាហ៍ មានន័យថាអ្នកមិនមែនជាម្ចាស់អាជីវកម្មទេ អ្នកគ្រាន់តែទិញការងារមួយមកឱ្យខ្លួនឯងធ្វើប៉ុណ្ណោះ។', '«ម្ចាស់អាជីវកម្មលក់រាយម្នាក់ត្រូវរត់ទិញទំនិញខ្លួនឯង ឆ្លើយតប Chat អតិថិជនខ្លួនឯង និងធ្វើគណនេយ្យខ្លួនឯងរហូតដល់គ្មានពេលសម្រាកជាមួយគ្រួសារ និងគ្មានពេលគិតរឿងពង្រីកសាខាថ្មី។ ក្រោយមក គាត់បានចំណាយពេល ២ សប្តាហ៍ថតវីដេអូខ្លីៗ និងសរសេរ SOP មួយទំព័រសម្រាប់រាល់កិច្ចការដដែលៗ រួចបណ្តុះបណ្តាលបុគ្គលិកឱ្យធ្វើតាម។ ឥឡូវនេះ ហាងរបស់គាត់ដំណើរការយ៉ាងរលូនទោះបីជាគាត់មិននៅ ហើយគាត់មានពេលគ្រប់គ្រាន់ដើម្បីបើកសាខាទី ២ និងទី ៣ ដោយជោគជ័យ។»', '✅ ជំហានកសាង SOP ៣ ជំហាន៖\n១. Record៖ ថតសកម្មភាពអេក្រង់ ឬថតវីដេអូពេលអ្នកកំពុងធ្វើការងារនោះ។\n២. Document Checklist៖ សរសេរជាជំហាន ១, ២, ៣ យ៉ាងសាមញ្ញបំផុត។\n៣. Delegate & Review៖ ឱ្យបុគ្គលិកអនុវត្តតាម ហើយកែសម្រួលចំណុចដែលមិនទាន់ច្បាស់។', 'ជ្រើសរើសការងារដដែលៗមួយដែលអ្នកចំណាយពេលលើសពី ២ ម៉ោងក្នុងមួយសប្តាហ៍ ហើយបង្កើតឯកសារ SOP សង្ខេបមួយសម្រាប់កូនចៅ។', 'តើមានអ្វីកើតឡើងចំពោះអាជីវកម្មរបស់អ្នក ប្រសិនបើអ្នកមិនអាចចូលមើលការខុសត្រូវរយៈពេល ១ ខែពេញ?', '🎯 សកម្មភាពថ្ងៃនេះ៖ កត់ត្រារាល់សកម្មភាពដែលអ្នកបានធ្វើថ្ងៃនេះ រួចគូសចំណាំការងារណាដែលអាចផ្ទេរឱ្យអ្នកដទៃធ្វើតាមរយៈ SOP។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-found-3', 'lesson-found-3', 'ម្ចាស់អាជីវកម្មម្នាក់ត្រូវបុគ្គលិកទូរស័ព្ទមកសួរនាំ និងសុំការសម្រេចចិត្តរាល់រឿងតូចតាចរៀងរាល់ ១០ នាទីម្តង។ តើដំណោះស្រាយយូរអង្វែងគឺជាអ្វី?', 'A founder gets interrupted every 10 minutes for minor decisions. What is the long-term solution?', '["A. បិទទូរស័ព្ទចោល ហើយស្តីបន្ទោសបុគ្គលិកថាមិនចេះគិត។","B. បង្កើត SOPs ច្បាស់លាស់ និងកំណត់កម្រិតសិទ្ធិសម្រេចចិត្ត (Authority Matrix) ឱ្យបុគ្គលិកអាចដោះស្រាយរឿងក្រោម $50 ដោយខ្លួនឯង។","C. ជួលមនុស្សបន្ថែមមកចាំទទួលទូរស័ព្ទជំនួស។"]', '["A. Turn off phone and scold employees for not thinking.","B. Build clear SOPs and establish an authority matrix empowering staff to resolve matters under $50 autonomously.","C. Hire more people just to answer questions."]', 1, 'ការពន្យល់៖ ជម្រើស B ផ្តល់សិទ្ធិអំណាច និងក្របខ័ណ្ឌច្បាស់លាស់ដល់ក្រុមការងារ ដែលជួយរំដោះពេលវេលាម្ចាស់អាជីវកម្មមកផ្តោតលើយុទ្ធសាស្ត្រធំៗ។', 'Explanation: Clear SOPs and decision authority boundaries free founders from daily firefighting.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-found-4', 'course-founder-sme', 'mod-1', 4, '៤. ការកសាងទំនុកចិត្ត និងការរក្សាបុគ្គលិកឆ្នើម (Talent Retention & Profit Sharing in SME)', 'Retaining Top Performers in Growing SMEs', 'text', '• បង្កើតផែនការរីកចម្រើនក្នុងអាជីព (Growth Pathway) ទោះបីជាក្រុមហ៊ុនខ្នាតតូចក៏ដោយ។\n• យល់ដឹងពីរចនាសម្ព័ន្ធលើកទឹកចិត្តតាមរយៈការបែងចែកប្រាក់ចំណេញ (Profit Sharing & Performance Bonus)។\n• កសាងទំនាក់ទំនងស្និទ្ធស្នាល និងការគោរពតម្លៃដែលក្រុមហ៊ុនធំៗមិនអាចផ្តល់ជូនបាន។', 'ក្រុមហ៊ុន SME មិនអាចប្រកួតប្រជែងប្រាក់ខែជាមួយសាជីវកម្មពហុជាតិបានទេ ប៉ុន្តែ SME អាចផ្តល់នូវភាពស្និទ្ធស្នាល ឱកាសរៀនសូត្រលឿន ភាពបត់បែន និងចំណែកនៃភាពជោគជ័យពិតប្រាកដ។', '«ស្ថាបនិកក្រុមហ៊ុនបច្ចេកវិទ្យាខ្នាតតូចមួយ បានជួបបញ្ហាបុគ្គលិកពូកែចង់លាលែងទៅធ្វើការនៅធនាគារធំ។ ស្ថាបនិកបានជួបសន្ទនាដោយស្មោះត្រង់ ហើយបានផ្តល់នូវកញ្ចប់លើកទឹកចិត្តថ្មី៖ គាត់ផ្តល់ឱកាសឱ្យបុគ្គលិកនោះធ្វើជាដៃគូគម្រោង (Project Partner) និងទទួលបានចំណែកភាគរយពីប្រាក់ចំណេញសុទ្ធនៃផលិតផលថ្មី ១៥%។ បុគ្គលិកនោះបានបដិសេធសំណើធនាគារ ព្រោះគាត់មើលឃើញថានៅទីនេះគាត់ជាសហគ្រិន និងមានអនាគតរីកចម្រើនគ្មានដែនកំណត់។ ពីរឆ្នាំក្រោយមក ផលិតផលនោះទទួលបានជោគជ័យខ្លាំង ហើយពួកគេទាំងពីរក្លាយជាដៃគូអាជីវកម្មដ៏រឹងមាំ។»', '✅ យុទ្ធសាស្ត្ររក្សាមនុស្សឆ្នើម ៣ ចំណុចសម្រាប់ SME៖\n១. Autonomy៖ ផ្តល់សិទ្ធិសម្រេចចិត្តលើគម្រោងដែលពួកគេស្រលាញ់។\n២. Mastery៖ ឧបត្ថម្ភការរៀនសូត្រ និងវគ្គបណ្តុះបណ្តាលវិជ្ជាជីវៈកម្រិតខ្ពស់។\n៣. Purpose & Stake៖ ចែករំលែកផលចំណេញជាក់ស្តែងនៅពេលក្រុមហ៊ុនសម្រេចគោលដៅ។', 'រៀបចំរចនាសម្ព័ន្ធកញ្ចប់លើកទឹកចិត្តផ្អែកលើលទ្ធផលការងារ (Performance Incentive) សម្រាប់បុគ្គលិកគន្លឹះរបស់អ្នក។', 'តើហេតុអ្វីបានជាមនុស្សពូកែគួរនៅបន្តធ្វើការជាមួយអាជីវកម្មរបស់អ្នក ជំនួសឱ្យការទៅធ្វើការនៅក្រុមហ៊ុនធំៗ? តើអ្នកបានផ្តល់អ្វីខ្លះដល់អនាគតរបស់ពួកគេ?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ជួបសន្ទនា 1-on-1 ជាមួយបុគ្គលិកឆ្នើមម្នាក់របស់អ្នក ហើយថ្លែងអំណរគុណចំពោះការខិតខំ និងសួរនាំពីក្តីសុបិនអាជីពរបស់គាត់។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-found-4', 'lesson-found-4', 'បុគ្គលិកឆ្នើមម្នាក់ក្នុង SME របស់អ្នកកំពុងពិចារណាទៅធ្វើការនៅក្រុមហ៊ុនធំមួយ។ តើយុទ្ធសាស្ត្រចរចារក្សាគាត់ដែលសមស្របបំផុតសម្រាប់ SME គឺជាអ្វី?', 'A top performer is considering leaving for a corporate job. What is the most effective SME retention strategy?', '["A. គំរាមកំហែង និងនិយាយបង្ខូចកេរ្តិ៍ឈ្មោះក្រុមហ៊ុនធំនោះឱ្យគាត់ខ្លាច។","B. សន្ទនា 1-on-1 ដោយស្មោះត្រង់ ផ្តល់ឱកាសដឹកនាំគម្រោងសំខាន់ បង្កើតផ្លូវឡើងតំណែងច្បាស់លាស់ និងផ្តល់កញ្ចប់ចែករំលែកប្រាក់ចំណេញ (Profit Sharing)។","C. មិនខ្វល់ខ្វាយព្រោះគិតថាមនុស្សងាយស្រួលរកជំនួសណាស់។"]', '["A. Threaten them and badmouth the large corporation.","B. Hold a sincere 1-on-1, offer key project leadership, clear growth pathways, and profit-sharing incentives.","C. Do nothing, assuming people are easily replaced."]', 1, 'ការពន្យល់៖ ជម្រើស B ផ្តល់នូវអ្វីដែលសាជីវកម្មធំៗពិបាកផ្តល់ជូន គឺល្បឿននៃការរីកចម្រើន អារម្មណ៍ជាម្ចាស់ការ និងចំណែកនៃភាពជោគជ័យផ្ទាល់។', 'Explanation: Autonomy, rapid progression, and direct profit-sharing outshine rigid corporate bureaucracy.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-fnd-5', 'course-founder-sme', 'mod-1', 5, '៥. ការរៀបចំប្រព័ន្ធ SOP និងស្វ័យប្រវត្តិកម្មអាជីវកម្ម (Business Systemization & SOP)', 'Business Systemization & Standard Operating Procedures', 'text', '• យល់ដឹងពីរបៀបកសាងប្រព័ន្ធការងារដែលដំណើរការដោយរលូន ទោះបីជាគ្មានវត្តមានស្ថាបនិកក៏ដោយ។\n• បង្កើតឯកសារ SOP (Standard Operating Procedure) សាមញ្ញ ១ ទំព័រសម្រាប់ដំណើរការអាជីវកម្មស្នូល។\n• ប្រើប្រាស់បច្ចេកវិទ្យា និង Cloud Tools ដើម្បីកាត់បន្ថយកិច្ចការដដែលៗដោយដៃ។', 'ប្រសិនបើអាជីវកម្មរបស់អ្នកមិនអាចដំណើរការបាននៅពេលអ្នកឈប់សម្រាក នោះអ្នកមិនទាន់ជាម្ចាស់អាជីវកម្មពិតប្រាកដនៅឡើយទេ អ្នកគ្រាន់តែជាអ្នកធ្វើការឱ្យខ្លួនឯងប៉ុណ្ណោះ។ ប្រព័ន្ធ SOP ជួយដោះលែងស្ថាបនិកពីប្រតិបត្តិការប្រចាំថ្ងៃ។', '«ប៊ុនណារិទ្ធ បានបើកហាងកាហ្វេ និងសេវាកម្ម Catering រហូតដល់ ៣ សាខា។ គាត់រវល់តាំងពីម៉ោង ៦ ព្រឹកដល់ម៉ោង ១០ យប់៖ រត់ទិញគ្រឿងទេស ដោះស្រាយអតិថិជនរអ៊ូរទាំ និងគិតលុយដោយខ្លួនឯង។ គាត់អស់កម្លាំងដល់ថ្នាក់ធ្លាក់ខ្លួនឈឺ។ ពេលសម្រាកនៅមន្ទីរពេទ្យ គាត់បានដឹងច្បាស់ថាអាជីវកម្មខ្វះប្រព័ន្ធ។ គាត់ចាប់ផ្តើមសរសេរ SOP សម្រាប់រាល់ការងារ៖ របៀបឆុងកាហ្វេតាមក្បួនខ្នាតស្តង់ដារ បញ្ជីត្រួតពិនិត្យអនាម័យពេលព្រឹក និងទម្រង់ឆ្លើយតបអតិថិជន។ គាត់បានបណ្តុះបណ្តាលមេការសាខាឱ្យអនុវត្តតាម SOP។ ប្រាំមួយខែក្រោយមក គាត់អាចឈប់សម្រាក ១ សប្តាហ៍បានយ៉ាងស្ងប់ចិត្ត ហើយចំណូលហាងថែមទាំងកើនឡើង ២០%។»', '✅ រូបមន្តសរសេរ SOP សាមញ្ញ ៤ ជំហាន៖\n១. គោលបំណង (Purpose)៖ ហេតុអ្វីត្រូវធ្វើការងារនេះ?\n២. អ្នកទទួលខុសត្រូវ (Who)៖ តួនាទីណាដែលត្រូវអនុវត្ត?\n obstacles (Checklist)៖ បញ្ជីជំហាន ១, ២, ៣ យ៉ាងសាមញ្ញដែលកូនក្មេងក៏អាចធ្វើតាមបាន។\n៤. ស្តង់ដារសម្រេច (Quality Standard)៖ លទ្ធផលល្អឥតខ្ចោះមើលទៅបែបណា?', 'សរសេរ SOP ១ ទំព័រសម្រាប់កិច្ចការប្រតិបត្តិការដ៏សំខាន់មួយក្នុងអាជីវកម្មរបស់អ្នក។', 'ប្រសិនបើអ្នកត្រូវឈប់សម្រាកបន្ទាន់រយៈពេល ២ សប្តាហ៍ តើអាជីវកម្មរបស់អ្នកអាចបន្តដំណើរការបានរលូនដែរឬទេ?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ជ្រើសរើសដំណើរការការងារមួយដែលកំពុងកើតមានកំហុសញឹកញាប់ ហើយសរសេរ SOP មួយទំព័រដើម្បីណែនាំក្រុម។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-fnd-5', 'lesson-fnd-5', 'តើអ្វីជាអត្ថប្រយោជន៍ធំបំផុតនៃការរៀបចំប្រព័ន្ធ SOP សម្រាប់អាជីវកម្ម SME?', 'What is the greatest benefit of standard operating procedures (SOPs) for an SME?', '["A. ធ្វើឱ្យឯកសារក្រាស់ដើម្បីបង្អួតភ្ញៀវ។","B. ធានាគុណភាពផលិតផល និងសេវាកម្មមានស្តង់ដារថេរ ជួយឱ្យអាជីវកម្មពង្រីកសាខាបាន និងដោះលែងស្ថាបនិកពីការងារប្រតិបត្តិការលម្អិត។","C. ដាក់កំហិតមិនឱ្យបុគ្គលិកមានគំនិតច្នៃប្រឌិតអ្វីទាំងអស់។"]', '["A. Create thick binders to impress visitors.","B. Guarantee consistent quality, enable scalability across branches, and free the founder from micromanagement.","C. Suppress employee creativity."]', 1, 'ការពន្យល់៖ ជម្រើស B បង្ហាញពីគោលបំណងស្នូលនៃប្រព័ន្ធស្ថាប័នដែលអនុញ្ញាតឱ្យក្រុមហ៊ុនរីកចម្រើនប្រកបដោយចីរភាព។', 'Explanation: SOPs ensure scalable consistency and liberate the founder to focus on strategic growth.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-fnd-6', 'course-founder-sme', 'mod-1', 6, '៦. យុទ្ធសាស្ត្រគ្រប់គ្រងលំហូរសាច់ប្រាក់ និងការត្រៀមបម្រុងពេលវិបត្តិ (Cash Flow & Runway)', 'Cash Flow Management & 6-Month Emergency Runway for SMEs', 'text', '• បែងចែកឱ្យច្បាស់រវាង «ប្រាក់ចំណេញលើក្រដាស (Accounting Profit)» និង «សាច់ប្រាក់សុទ្ធក្នុងដៃ (Real Cash Flow)»។\n• កសាងមូលនិធិបម្រុងសង្គ្រោះបន្ទាន់យ៉ាងតិច ៦ ខែ (6-Month Operating Runway)។\n• អនុវត្តក្បួនគ្រប់គ្រងបំណុលអតិថិជន (Accounts Receivable) ដើម្បីកុំឱ្យកកស្ទះសាច់ប្រាក់។', 'អាជីវកម្មជាច្រើនក្ស័យធនមិនមែនដោយសារមិនមានការលក់នោះទេ ប៉ុន្តែដោយសារដាច់លំហូរសាច់ប្រាក់ (Run out of cash)។ សាច់ប្រាក់គឺជាឈាមរត់របស់សហគ្រាស។', '«ក្រុមហ៊ុនផ្គត់ផ្គង់សំណង់មួយទទួលបានកិច្ចសន្យាធំតម្លៃ $100,000។ ម្ចាស់សប្បាយចិត្តយ៉ាងខ្លាំង ហើយបានកុម្ម៉ង់ឥវ៉ាន់ និងជួលបុគ្គលិកបន្ថែមភ្លាមៗ។ ប៉ុន្តែអតិថិជនសុំពន្យារពេលទូទាត់ ៩០ ថ្ងៃ។ ដល់ដំណាច់ខែ ក្រុមហ៊ុនគ្មានលុយសុទ្ធបើកប្រាក់ខែ និងបង់ថ្លៃឈ្នួលអាគារឡើយ ដែលនាំឱ្យជាប់គាំងស្ទើរតែដួលរលំ។ ក្រោយពេលឆ្លងផុតវិបត្តិនេះ ស្ថាបនិកបានបង្កើតច្បាប់ដែក៖ តែងតែរក្សាសាច់ប្រាក់បម្រុងសម្រាប់ចំណាយប្រតិបត្តិការ (OPEX) យ៉ាងហោចណាស់ ៦ ខែ និងតម្រូវឱ្យអតិថិជនកក់ប្រាក់យ៉ាងតិច ៣០% មុនពេលចាប់ផ្តើម។»', '✅ ក្បួនមាសគ្រប់គ្រងលំហូរសាច់ប្រាក់ SME៖\n១. ដក ៥% ទៅ ១០% នៃចំណូលសរុបរាល់សប្តាហ៍ ចូលក្នុងគណនីបម្រុងសង្គ្រោះបន្ទាន់ (Emergency Runway Account)។\n២. តាមដានថ្ងៃផុតកំណត់ទូទាត់បំណុលអតិថិជនរៀងរាល់ថ្ងៃសុក្រ។\n៣. កុំទិញទ្រព្យសកម្មថ្លៃៗ (CapEx) ដោយប្រើសាច់ប្រាក់សុទ្ធប្រតិបត្តិការឡើយ។', 'គណនាចំណាយប្រតិបត្តិការប្រចាំខែ (Monthly Burn Rate) របស់អាជីវកម្មអ្នក ហើយពិនិត្យមើលថាតើសាច់ប្រាក់បម្រុងបច្ចុប្បន្នអាចទ្រទ្រង់បានប៉ុន្មានខែ។', 'តើសហគ្រាសរបស់អ្នកមានសាច់ប្រាក់បម្រុងគ្រប់គ្រាន់សម្រាប់ទប់ទល់នឹងវិបត្តិដែលគ្មានចំណូលរយៈពេល ៦ ខែដែរឬទេ?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ពិនិត្យមើលគណនីធនាគាររបស់ស្ថាប័ន ហើយបើកគណនីដាច់ដោយឡែកមួយសម្រាប់មូលនិធិបម្រុងសង្គ្រោះបន្ទាន់។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-fnd-6', 'lesson-fnd-6', 'ហេតុអ្វីបានជាអាជីវកម្មមួយដែលមានប្រាក់ចំណេញលើបញ្ជីគណនេយ្យ នៅតែអាចប្រឈមនឹងការក្ស័យធន?', 'Why can a business with accounting profits on paper still face bankruptcy?', '["A. ដោយសារម្ចាស់ក្រុមហ៊ុនមិនបានផ្សាយពាណិជ្ជកម្មលើ Facebook។","B. ដោយសារសាច់ប្រាក់សុទ្ធកកស្ទះក្នុងស្តុកទំនិញ ឬបំណុលអតិថិជនមិនទាន់ប្រមូលបាន ធ្វើឱ្យគ្មានលុយសុទ្ធបើកប្រាក់ខែ និងបង់ចំណាយប្រតិបត្តិការ (Insolvency)។","C. ដោយសារគ្មានបុគ្គលិកផ្នែក IT។"]', '["A. Because the founder did not advertise on Facebook.","B. Because real cash is trapped in unpaid customer receivables or slow inventory, leading to an inability to pay daily operational obligations.","C. Because they lack IT staff."]', 1, 'ការពន្យល់៖ ជម្រើស B ពន្យល់ពីភាពខុសគ្នារវាង Accrual Profit និង Liquidity/Cash Flow ដែលជាមូលហេតុចម្បងនៃបរាជ័យធុរកិច្ច។', 'Explanation: Profit is an accounting opinion, cash is an empirical fact. Lack of liquidity causes insolvency.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-founder-7', 'course-founder-sme', 'mod-1', 7, '៧. ក្បួនគ្រប់គ្រងធនធានមនុស្សតាមទស្សនវិជ្ជា ហាន ហ្វៃជឺ «ច្បាប់ សិល្បៈ អំណាច» (Han Feizi: Fa, Shu, Shi)', 'Han Feizi Classical Statecraft for Founders: The Triad of Law, Art, and Strategic Power', 'text', '• យល់ដឹងពីទស្សនវិជ្ជាគ្រប់គ្រងបែបនីតិនិយមរបស់ ហាន ហ្វៃជឺ (Han Feizi): ច្បាប់ (Fa / 法), សិល្បៈ (Shu / 术), និងអំណាចនៃកាលៈទេសៈ (Shi / 势)។\n• បញ្ឈប់ការគ្រប់គ្រងក្រុមហ៊ុនតាមតែ «អារម្មណ៍ និងការទុកចិត្តខ្វាក់ភ្នែក»។\n• បង្កើតប្រព័ន្ធគ្រប់គ្រងដែលផ្តល់រង្វាន់យ៉ាងច្បាស់លាស់ដល់អ្នកមានស្នាដៃ និងដាក់ទណ្ឌកម្មលើអ្នកបំពានច្បាប់ (Carrot & Stick System)។', 'ស្ថាបនិកទស្សនវិជ្ជានីតិនិយមចិន ហាន ហ្វៃជឺ (Han Feizi) បានបង្រៀនថា៖ មនុស្សធម្មជាតិធ្វើសកម្មភាពតាមផលប្រយោជន៍ និងការការពារខ្លួន។ ប្រសិនបើស្ថាបនិកក្រុមហ៊ុន SME គ្រប់គ្រងដោយពឹងផ្អែកតែលើ «ភាពជាបងប្អូន និងការទុកចិត្តដោយគ្មានប្រព័ន្ធ» ក្រុមហ៊ុននោះនឹងត្រូវវិនាសដោយសារការក្បត់ និងការកិបកេង។ ដើម្បីដឹកនាំអាជីវកម្មឱ្យរីកធំ ស្ថាបនិកត្រូវក្តោបក្តាប់ក្បួន ៣ យ៉ាង៖ \n១. ច្បាប់ (Fa / 法)៖ បទបញ្ជាផ្ទៃក្នុង និង SOP ត្រូវតែច្បាស់លាស់ និងអនុវត្តស្មើភាពគ្នា។\n②. សិល្បៈ (Shu / 术)៖ វិធីសាស្ត្រសម្ងាត់ក្នុងការវាយតម្លៃ និងសាកល្បងចិត្តមនុស្ស។\n៣. អំណាចកាលៈទេសៈ (Shi / 势)៖ ការក្តោបក្តាប់ធនធានហិរញ្ញវត្ថុ និងសិទ្ធិអំណាចសម្រេចចិត្តដាច់ខាត។', '«លោក វិបុល ជាស្ថាបនិកក្រុមហ៊ុនចែកចាយសម្ភារសំណង់ SME មួយ។ ដោយសារគាត់ជាមនុស្សចិត្តល្អ គាត់បានចាត់ទុកបុគ្គលិកទាំងអស់ដូចជាបងប្អូនសាច់ញាតិ ដោយមិនដែលបង្កើតកិច្ចសន្យាការងារច្បាស់លាស់ មិនដែលឆែកឆេរឃ្លាំងទំនិញ និងមិនដែលដាក់ទោសអ្នកធ្វើខុសឡើយ។ \nជាលទ្ធផល បុគ្គលិកផ្នែកលក់បានលួចបង្កើតក្រុមហ៊ុនក្រៅដើម្បីប្រជែងជាមួយគាត់ មេឃ្លាំងបានលួចលក់ទំនិញយកលុយចាយផ្ទាល់ខ្លួន ហើយគណនេយ្យករបានកិបកេងប្រាក់ក្រុមហ៊ុនរាប់ម៉ឺនដុល្លារ។ ក្រុមហ៊ុនស្ទើរតែក្ស័យធន។ \nក្រោយពីសិក្សាក្បួន ហាន ហ្វៃជឺ វិបុលបានភ្ញាក់រលឹក៖ គាត់បានដាក់ចេញនូវប្រព័ន្ធ "Fa (法)" យ៉ាងម៉ត់ចត់៖ តម្លើងប្រព័ន្ធកាមេរ៉ាសុវត្ថិភាព ធ្វើសវនកម្មឃ្លាំងរៀងរាល់សប្តាហ៍ បង្កើតកិច្ចសន្យាការងារច្បាស់លាស់ និងដាក់ចេញនូវប្រព័ន្ធរង្វាន់ និងទណ្ឌកម្ម (Two Handles)។ បុគ្គលិកខិលខូចត្រូវបានបណ្តេញចេញ រីឯបុគ្គលិកស្មោះត្រង់ទទួលបានប្រាក់រង្វាន់ខ្ពស់។ ត្រឹមតែ ៦ ខែ ប្រាក់ចំណេញរបស់ក្រុមហ៊ុនបានកើនឡើង ៣ ដង ហើយក្រុមហ៊ុនដំណើរការយ៉ាងរលូន។»', '✅ របៀបអនុវត្តក្បួន «法 术 势» ក្នុងអាជីវកម្ម SME៖\n• Fa (ច្បាប់)៖ បទបញ្ជាផ្ទៃក្នុង សៀវភៅ SOP និងកិច្ចសន្យាការងារត្រូវតែសរសេរជាលាយលក្ខណ៍អក្សរច្បាស់លាស់ (គ្មានការលើកលែងសូម្បីតែបងប្អូនបង្កើត)។\n• Shu (សិល្បៈ)៖ ប្រើប្រាស់ការផ្ទៀងផ្ទាត់ឆ្លងកាត់ (Cross-Checks) — មិនឱ្យមនុស្សម្នាក់ក្តោបក្តាប់ទាំងការបញ្ជាទិញ និងការទូទាត់លុយឡើយ។\n• Shi (អំណាច)៖ ស្ថាបនិកត្រូវតែក្តោបក្តាប់ហត្ថលេខាមូលប្បទានប័ត្រ និងទិន្នន័យអតិថិជនស្នូល។', 'ពិនិត្យមើលអាជីវកម្មរបស់អ្នកថ្ងៃនេះ តើមានចំណុចណាខ្លះដែលអ្នកកំពុងពឹងផ្អែកលើ «ការទុកចិត្តបុគ្គល» ដោយគ្មានប្រព័ន្ធត្រួតពិនិត្យ (Fa) ការពារ?', 'តើនៅក្នុងក្រុមហ៊ុនរបស់អ្នកមាន «មនុស្សដែលមិនអាចប៉ះពាល់បាន» ដោយសារជាបងប្អូន ឬជាមិត្តភក្តិ ដែលកំពុងបំពានច្បាប់ស្ថាប័នដែរឬទេ?', '🎯 សកម្មភាពថ្ងៃនេះ៖ កំណត់នីតិវិធីត្រួតពិនិត្យហិរញ្ញវត្ថុមួយដែលបច្ចុប្បន្នកំពុងពឹងផ្អែកលើការទុកចិត្ត ហើយដាក់ប្រព័ន្ធ Two-Person Approval ភ្លាមៗ។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-founder-7', 'lesson-founder-7', 'តាមទស្សនវិជ្ជា ហាន ហ្វៃជឺ (Han Feizi) ហេតុអ្វីបានជាការគ្រប់គ្រងស្ថាប័នដោយពឹងផ្អែកតែលើ «ភាពជាបងប្អូន និងការទុកចិត្តផ្ទាល់ខ្លួន» តែងតែនាំទៅរកការបរាជ័យ?', 'According to Han Feizi legalist statecraft, why does managing an enterprise purely on personal trust and brotherly affection lead to ruin?', '["A. ព្រោះមនុស្សគ្រប់គ្នាសុទ្ធតែជាចោរ។","B. ព្រោះបើគ្មានច្បាប់ និងប្រព័ន្ធត្រួតពិនិត្យរឹងមាំ (Fa) ទេ ធម្មជាតិមនុស្សនឹងងាយរងការល្បួងដោយផលប្រយោជន៍ផ្ទាល់ខ្លួន ដែលបង្កឱ្យមានការកិបកេង និងបក្សពួកនិយម។","C. ព្រោះច្បាប់បុរាណមិនអនុញ្ញាតឱ្យមានមិត្តភាព។"]', '["A. Because all humans are inherently thieves.","B. Because in the absence of explicit institutional laws, transparent metrics, and systemic oversight, self-interest inexorably breeds corruption and betrayal.","C. Because ancient laws forbade personal friendships."]', 1, 'ការពន្យល់៖ ហាន ហ្វៃជឺ បង្រៀនឱ្យពឹងផ្អែកលើប្រព័ន្ធ និងច្បាប់ (Fa) មិនមែនពឹងលើចិត្តមនុស្សដែលប្រែប្រួលនោះទេ។ ប្រព័ន្ធល្អការពារមនុស្សកុំឱ្យធ្វើខុស។', 'Explanation: Institutional mechanisms (Fa) safeguard against moral frailty far more reliably than blind sentimentality.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-founder-8', 'course-founder-sme', 'mod-1', 8, '៨. ក្បួនសង្គ្រោះសាច់ប្រាក់ និងច្បាប់ទុនបម្រុង ៦ ខែសម្រាប់ SME (SME Cash Flow Survival)', 'Cash Flow Survival: The 6-Month Liquidity Rule & Working Capital Mastery for SMEs', 'text', '• យល់ដឹងពីមូលហេតុលេខ ១ នៃការក្ស័យធនរបស់ SME៖ «ដាច់សាច់ប្រាក់បង្វិល (Cash Insolvency)» ទោះបីជាអាជីវកម្មមានប្រាក់ចំណេញលើក្រដាសក៏ដោយ។\n• អនុវត្តច្បាប់ដែក «សាច់ប្រាក់បម្រុង ៦ ខែ» (The 6-Month Runway Rule)។\n• គ្រប់គ្រងវដ្តបង្វិលសាច់ប្រាក់ (Cash Conversion Cycle - CCC)៖ ទារលុយពីម៉ូយឱ្យលឿន ពន្យារពេលសងអ្នកផ្គត់ផ្គង់ឱ្យស្របច្បាប់។', 'ជាង ៨០% នៃអាជីវកម្ម SME ដែលដួលរលំ មិនមែនដោយសារគ្មានអតិថិជននោះទេ ប៉ុន្តែដោយសារ «ដាច់សាច់ប្រាក់» (Ran Out of Cash)។ ស្ថាបនិកជាច្រើនច្រឡំរវាង «ចំណូលលក់ (Revenue)» និង «សាច់ប្រាក់ក្នុងដៃ (Cash)»។ នៅពេលអ្នកលក់ទំនិញជំពាក់បាន $50,000 អ្នកមានចំណូលលើក្រដាស ប៉ុន្តែអ្នកគ្មានលុយបើកប្រាក់ខែបុគ្គលិក និងបង់ថ្លៃផ្ទះឡើយ។ ស្ថាបនិកឆ្លាតវៃតែងតែតាមដានរបាយការណ៍សាច់ប្រាក់ប្រចាំថ្ងៃ និងរក្សាទុនបម្រុងសុទ្ធយ៉ាងហោចណាស់ ៦ ខែ។', '«កញ្ញា សុគន្ធា ជាម្ចាស់អាជីវកម្មផ្គត់ផ្គង់សម្ភារការិយាល័យ។ ក្នុងឆ្នាំទី ២ ការលក់របស់នាងបានកើនឡើងដល់ $100,000 ក្នុងមួយខែ។ ដោយរំភើបនឹងតួលេខ នាងបានយល់ព្រមឱ្យក្រុមហ៊ុនធំៗជំពាក់ប្រាក់រហូតដល់ ៩០ ថ្ងៃ។ \nដល់ចុងខែ នាងត្រូវបើកប្រាក់ខែបុគ្គលិក $15,000 និងបង់ថ្លៃទំនិញឱ្យរោងចក្រ $40,000 ប៉ុន្តែក្នុងគណនីធនាគាររបស់នាងសល់លុយត្រឹមតែ $3,000! ក្រុមហ៊ុនធំៗដែលជំពាក់មិនព្រមបើកលុយឱ្យទាន់ពេលឡើយ។ នាងស្ទើរតែត្រូវធនាគាររឹបអូសផ្ទះដោយសារកង្វះសាច់ប្រាក់។ \nក្រោយពីដោះស្រាយរួច នាងបានរៀបចំក្បួនសាច់ប្រាក់ឡើងវិញ៖ \n១. អតិថិជនត្រូវកក់ប្រាក់ ៥០% មុនប្រគល់ទំនិញ។\n②. កាត់បន្ថយរយៈពេលជំពាក់មកត្រឹមអតិបរមា ៣០ ថ្ងៃ។\n៣. បង្កើតគណនីបម្រុងដាច់ដោយឡែកមួយដែលមានសាច់ប្រាក់ស្មើនឹង ៦ ខែនៃថ្លៃប្រតិបត្តិការ (OPEX) ដែលដាច់ខាតមិនត្រូវប៉ះពាល់ឡើយ។ ចាប់ពីពេលនោះមក អាជីវកម្មរបស់នាងមានស្ថេរភាពរឹងមាំ និងលែងស្គាល់ពាក្យថាភ័យស្លន់ស្លោទៀតហើយ។»', '✅ រូបមន្តគ្រប់គ្រងវដ្តសាច់ប្រាក់ (Cash Conversion Cycle - CCC)៖\n• CCC = ថ្ងៃស្តុកទំនិញ (DIO) + ថ្ងៃទារលុយពីម៉ូយ (DSO) - ថ្ងៃជំពាក់អ្នកផ្គត់ផ្គង់ (DPO)\n• គោលដៅ៖ ធ្វើឱ្យ CCC កាន់តែខ្លី ឬអវិជ្ជមាន (ដូចជា ទទួលលុយសុទ្ធពីភ្ញៀវភ្លាមៗ ប៉ុន្តែសងរោងចក្រក្រោយ ៣០ ថ្ងៃ)។\n• ច្បាប់ទុនបម្រុង ៦ ខែ៖ ប្រសិនបើថ្លៃចំណាយប្រចាំខែ (Rent + Salary + Utilities) = $5,000 នោះទុនបម្រុងបន្ទាន់ត្រូវតែមាន $30,000 នៅក្នុងធនាគារជានិច្ច។', 'គណនាថ្លៃចំណាយប្រតិបត្តិការប្រចាំខែ (Monthly Burn Rate) របស់អាជីវកម្មអ្នក ហើយពិនិត្យមើលថាតើសាច់ប្រាក់បច្ចុប្បន្នអាចទប់ទល់បានប៉ុន្មានខែ (Runway Months)។', 'តើអាជីវកម្មរបស់អ្នកកំពុងមានកូនបំណុលជំពាក់ប្រាក់ច្រើនលើសលប់ដែរឬទេ? តើអ្នកមានវិធានការទារប្រាក់យ៉ាងម៉ត់ចត់កម្រិតណា?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ពិនិត្យបញ្ជីគណនីត្រូវទារ (Accounts Receivable Aging Report) ហើយចាត់តាំងក្រុមការងារទារប្រាក់ដែលជំពាក់លើសពី ៣០ ថ្ងៃជាបន្ទាន់។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-founder-8', 'lesson-founder-8', 'តើអ្វីជាមូលហេតុចម្បងបំផុតដែលធ្វើឱ្យអាជីវកម្ម SME ជាច្រើនក្ស័យធន ទោះបីជាមានការបញ្ជាទិញច្រើនពីអតិថិជនក៏ដោយ?', 'What is the number one cause of SME bankruptcy despite growing sales orders?', '["A. ការខ្វះបុគ្គលិកលក់។","B. វិបត្តិដាច់សាច់ប្រាក់បង្វិល (Cash Flow Crisis) ដោយសារឱ្យម៉ូយជំពាក់លុយយូរពេក ខណៈដែលថ្លៃចំណាយប្រចាំខែត្រូវបើកទាន់ពេលវេលា។","C. ការចំណាយលើការបង់ពន្ធច្រើនពេក។"]', '["A. Shortage of frontline salespeople.","B. Cash flow starvation caused by uncollected accounts receivable alongside unavoidable fixed monthly cash outflows.","C. Excessive tax payments."]', 1, 'ការពន្យល់៖ "Profit is an opinion, Cash is a fact"។ ការលក់ដាច់តែមិនទារលុយបាន នឹងធ្វើឱ្យក្រុមហ៊ុនក្ស័យធនដោយសារគ្មានសាច់ប្រាក់បើកប្រាក់ខែ និងថ្លៃទំនិញ។', 'Explanation: Profit is accounting theory; cash is enterprise oxygen. Over-extended receivables trigger insolvency.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-founder-9', 'course-founder-sme', 'mod-1', 9, '៩. ការចាកចេញពីអន្ទាក់ស្ថាបនិក «ក្បួនលែងដៃដើម្បីពង្រីកខ្លួន» (Overcoming the Founder’s Trap)', 'Escaping the Founder’s Trap: Transitioning from Chief Everything Officer to True Leader', 'text', '• យល់ដឹងពីគ្រោះថ្នាក់នៃ «អន្ទាក់ស្ថាបនិក» (The Founder’s Trap: គ្រប់រឿងត្រូវឆ្លងកាត់ដៃស្ថាបនិកទាំងអស់)។\n• បំប្លែងខ្លួនពី «អ្នកធ្វើការងារជំនាញ (Technician)» មកជា «ស្ថាបត្យករបង្កើតប្រព័ន្ធ (System Architect)» (The E-Myth)។\n• ផ្ទេរសិទ្ធិអំណាចសម្រេចចិត្ត (Delegation with Boundaries) ដើម្បីឱ្យអាជីវកម្មអាចដំណើរការបានដោយគ្មានវត្តមានស្ថាបនិក។', 'ស្ថាបនិក SME ភាគច្រើនមិនមែនជាម្ចាស់អាជីវកម្មពិតប្រាកដនោះទេ ប៉ុន្តែជា «អ្នកស៊ីឈ្នួលឱ្យអាជីវកម្មខ្លួនឯង» (Self-Employed Trap)៖ ពួកគេធ្វើជាអ្នកលក់ផង រៀបចំទំនិញផង ធ្វើគណនេយ្យផង និងសម្អាតការិយាល័យផង។ ប្រសិនបើពួកគេឈប់សម្រាក ២ ថ្ងៃ អាជីវកម្មនឹងត្រូវគាំង។ ការចាកចេញពីអន្ទាក់ស្ថាបនិកទាមទារការផ្លាស់ប្តូរផ្នត់គំនិត៖ ឈប់ធ្វើការងារ «នៅក្នុងអាជីវកម្ម (Work IN the business)» ហើយប្តូរមកធ្វើការងារ «លើអាជីវកម្ម (Work ON the business)» តាមរយៈការបង្កើត SOP និងប្រព័ន្ធស្វ័យប្រវត្តិ។', '«លោក តារា ជាស្ថាបនិកភោជនីយដ្ឋានដ៏ល្បីមួយ។ អស់រយៈពេល ៥ ឆ្នាំ គាត់ត្រូវភ្ញាក់ពីម៉ោង ៤ ទៀបភ្លឺទៅទិញសាច់នៅផ្សារ និងឈរមើលការខុសត្រូវរហូតដល់ម៉ោង ១១ យប់ជារៀងរាល់ថ្ងៃ។ គាត់មានអារម្មណ៍ហត់នឿយ បាក់កម្លាំង និងគ្មានពេលសម្រាប់ក្រុមគ្រួសារសូម្បីតែបន្តិច។ គាត់ចង់បើកសាខាទី ២ ប៉ុន្តែមិនអាចធ្វើទៅរួច ព្រោះគ្មានអ្នកណាអាចធ្វើការងារជំនួសគាត់បាន។ \nក្រោយពីបានអានសៀវភៅ The E-Myth គាត់បានចំណាយពេល ៣ ខែធ្វើការកែទម្រង់៖ \n១. គាត់បានចងក្រងរូបមន្តធ្វើម្ហូប និងក្បួនទិញទំនិញទាំងអស់ជាឯកសារ SOP ច្បាស់លាស់។\n②. គាត់បានជួល Restaurant Manager ម្នាក់ និងបង្វឹកឱ្យចេះគ្រប់គ្រងបុគ្គលិក និងគណនេយ្យ។\n៣. គាត់បានសាកល្បងដើរចេញទៅសម្រាកនៅមាត់សមុទ្រ ៧ ថ្ងៃដោយមិនបើកទូរស័ព្ទ។ \nលទ្ធផល៖ ភោជនីយដ្ឋានដំណើរការយ៉ាងរលូន ១០០% ដោយគ្មានបញ្ហាអ្វីកើតឡើងឡើយ។ ក្រោយពីដោះលែងខ្លួនឯងពីការងារប្រតិបត្តិការ តារាមានពេលគ្រប់គ្រាន់ដើម្បីរៀបចំយុទ្ធសាស្ត្រ ហើយក្នុងរយៈពេល ២ ឆ្នាំក្រោយមក គាត់បានពង្រីកសាខាបាន ៥ បន្ថែមទៀតដោយជោគជ័យ។»', '✅ តេស្តសាកល្បង «តើអ្នកជាប់ក្នុង Founder Trap ដែរឬទេ?»៖\n• សំណួរ ១៖ តើអាជីវកម្មរបស់អ្នកអាចដំណើរការ និងរកចំណេញបានដែរឬទេ ប្រសិនបើអ្នកទៅវិស្សមកាល ៣០ ថ្ងៃដោយគ្មានទូរស័ព្ទ?\n• សំណួរ ២៖ តើបុគ្គលិកត្រូវមករកអ្នកដើម្បីសុំការអនុម័តលើការចំណាយក្រោម $50 ដែរឬទេ?\n• បើឆ្លើយថា "មិនបាន / ត្រូវមកសុំ" មានន័យថាអ្នកកំពុងជាប់ក្នុងអន្ទាក់ស្ថាបនិក ១០០%។\n• ដំណោះស្រាយ៖ បង្កើតច្បាប់ផ្ទេរសិទ្ធិ (Delegation Limits)៖ អនុញ្ញាតឱ្យ Manager សម្រេចចិត្តចំណាយក្រោម $200 ដោយស្វ័យប្រវត្តិ។', 'កំណត់កិច្ចការប្រតិបត្តិការប្រចាំថ្ងៃចំនួន ៣ ដែលអ្នកកំពុងធ្វើដោយផ្ទាល់ដៃ ហើយរៀបចំផ្ទេរវាទៅឱ្យសមាជិកក្រុមក្នុងរយៈពេល ១៤ ថ្ងៃខាងមុខ។', 'តើមានកិច្ចការណាខ្លះដែលអ្នកមិនព្រមលែងដៃឱ្យកូនចៅធ្វើ ដោយសារតែគិតថា «គ្មានអ្នកណាធ្វើបានល្អដូចខ្ញុំ»?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ជ្រើសរើសកិច្ចការទម្លាប់មួយដែលស៊ីពេលអ្នក ២ ម៉ោងក្នុងមួយថ្ងៃ ហើយផ្ទេរវាទៅឱ្យបុគ្គលិកម្នាក់ធ្វើចាប់ពីថ្ងៃស្អែក។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-founder-9', 'lesson-founder-9', 'តាមទ្រឹស្តី The E-Myth តើអ្វីជាភាពខុសគ្នារវាងការធ្វើការ «Work IN the business» និង «Work ON the business»?', 'According to The E-Myth, what is the critical difference between working IN versus ON your business?', '["A. គ្មានភាពខុសគ្នាអ្វីឡើយ។","B. \\"Work IN\\" គឺការជាប់រវល់ធ្វើកិច្ចការប្រតិបត្តិការប្រចាំថ្ងៃដូចជាបុគ្គលិកទូទៅ រីឯ \\"Work ON\\" គឺការផ្តោតលើការកសាងប្រព័ន្ធ យុទ្ធសាស្ត្រ និងការបណ្តុះបណ្តាលដើម្បីឱ្យអាជីវកម្មដើរដោយស្វ័យប្រវត្តិ។","C. \\"Work ON\\" គឺការធ្វើការតែនៅថ្ងៃចុងសប្តាហ៍។"]', '["A. There is no meaningful difference.","B. Working IN means getting trapped executing tactical daily chores; working ON means architecting systems, business models, and leadership capability so the enterprise operates without founder dependency.","C. Working ON means working solely on weekends."]', 1, 'ការពន្យល់៖ ស្ថាបនិកដែលចង់ពង្រីកអាជីវកម្មឱ្យធំ ត្រូវតែដោះលែងខ្លួនឯងពីការងារប្រតិបត្តិការតូចតាច (Work IN) មកផ្តោតលើការកសាងប្រព័ន្ធស្ថាប័ន (Work ON)។', 'Explanation: Systematizing processes allows founders to elevate from technician roles to enterprise architects.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-founder-10', 'course-founder-sme', 'mod-1', 10, '១០. សិល្បៈចងចិត្តកងទ័ពដែក និងការបែងចែកភាគហ៊ុនដៃគូ (Retaining Core Soldiers & Partnership)', 'Retaining the Iron Core: SME Partnership Models, Equity Vesting & Profit Pools', 'text', '• យល់ដឹងពីរបៀបរក្សាកងទ័ពដែក (Core Soldiers) ដែលបានរួមសុខរួមទុក្ខតាំងពីបាតដៃទទេកុំឱ្យចាកចេញ។\n• អនុវត្តកិច្ចសន្យាបែងចែកភាគហ៊ុនតាមដំណាក់កាល (4-Year Equity Vesting with 1-Year Cliff)។\n• បង្កើតសម្ព័ន្ធភាពផលប្រយោជន៍ដ៏រឹងមាំរវាងស្ថាបនិក និងបុគ្គលិកស្នូល ដើម្បីរួមគ្នាពង្រីកអាជីវកម្មឱ្យក្លាយជាក្រុមហ៊ុនធំ។', 'សោកនាដកម្មធំបំផុតរបស់ស្ថាបនិក SME គឺ៖ នៅពេលអាជីវកម្មចាប់ផ្តើមមានឈ្មោះបោះសំឡេង បុគ្គលិកពូកែៗ និងសហស្ថាបនិកដែលធ្លាប់តស៊ូជាមួយគ្នាតាំងពីដំបូង បែរជានាំគ្នាលាលែងចេញទៅបើកក្រុមហ៊ុនប្រកួតប្រជែង ឬទៅធ្វើការឱ្យគេ។ មូលហេតុគឺដោយសារស្ថាបនិក «កំណាញ់ភាគហ៊ុន និងប្រាក់ចំណេញ»។ ស្ថាបនិកដែលឆ្លាតវៃយល់ថា៖ «កាន់កាប់ ១០០% នៃក្រុមហ៊ុនដែលស្មើនឹង ០ ដុល្លារ មិនស្មើនឹងកាន់កាប់ ៦០% នៃក្រុមហ៊ុនដែលមានតម្លៃ ១០ លានដុល្លារនោះឡើយ»។ ចូរចេះចែករំលែកដើម្បីប្រមូលផ្តុំកម្លាំង។', '«លោក សុវណ្ណ បានបើកក្រុមហ៊ុនផ្គត់ផ្គង់បច្ចេកវិទ្យាតូចមួយជាមួយសហការីឆ្នើម ២ នាក់ឈ្មោះ វីរៈ (ផ្នែកលក់) និង ដារ៉ា (ផ្នែកបច្ចេកទេស)។ ក្នុងរយៈពេល ៣ ឆ្នាំដំបូង ពួកគេបានខិតខំទាំងយប់ទាំងថ្ងៃរហូតដល់ក្រុមហ៊ុនមានអតិថិជនរាប់រយ។ ប៉ុន្តែ សុវណ្ណបានកាន់កាប់ភាគហ៊ុន ១០០% តែម្នាក់ឯង និងបើកត្រឹមតែប្រាក់ខែធម្មតាដល់អ្នកទាំងពីរ។ \nនៅដើមឆ្នាំទី ៤ វីរៈ និងដារ៉ាបានជួបគ្នាដោយស្ងាត់ស្ងៀម ហើយគ្រោងនឹងលាលែងទៅបើកក្រុមហ៊ុនថ្មីជាមួយគ្នា។ សុវណ្ណបានដឹងរឿងនេះទាន់ពេល។ គាត់មិនបានខឹងទេ ប៉ុន្តែបានបន្ទោសខ្លួនឯង។ គាត់បានកោះប្រជុំភ្លាមៗ ហើយបានផ្តល់កិច្ចសន្យាភាពជាដៃគូជាផ្លូវការ៖ គាត់បានកាត់ភាគហ៊ុន ១៥% ឱ្យវីរៈ និង ១៥% ឱ្យដារ៉ា (តាមកិច្ចសន្យា Vesting ៤ ឆ្នាំ) និងបង្កើតប្រព័ន្ធបែងចែកប្រាក់ចំណេញសុទ្ធ ២០% ជារៀងរាល់ឆ្នាំ។ \nវីរៈ និងដារ៉ាមានការរំភើប និងស្មោះត្រង់យ៉ាងខ្លាំង។ ពួកគេបានលុបចោលគម្រោងចាកចេញ ហើយបានប្រឹងប្រែងអស់ពីកម្លាំងកាយចិត្ត។ ប្រាំឆ្នាំក្រោយមក ក្រុមហ៊ុនបានរីកចម្រើនក្លាយជាក្រុមហ៊ុនបច្ចេកវិទ្យាកំពូលមួយដែលមានតម្លៃទីផ្សារជាង $8,000,000 ហើយអ្នកទាំងបីបានក្លាយជាសេដ្ឋីជាមួយគ្នា។»', '✅ គំរូកិច្ចសន្យាភាគហ៊ុនស្ដង់ដារ (4-Year Vesting with 1-Year Cliff)៖\n• ឆ្នាំទី ១ (The Cliff)៖ បុគ្គលិកស្នូលត្រូវធ្វើការឱ្យគ្រប់ ១ ឆ្នាំពេញ ទើបទទួលបានសិទ្ធិ ២៥% ដំបូងនៃភាគហ៊ុន (ប្រសិនបើឈប់មុន ១ ឆ្នាំ មិនទទួលបានភាគហ៊ុនឡើយ)។\n• ឆ្នាំទី ២, ៣, ៤៖ ភាគហ៊ុនដែលនៅសល់ ៧៥% នឹងត្រូវផ្ទេរជូនបន្តិចម្តងៗជារៀងរាល់ខែ (Monthly Vesting)។\n• Buyback Clause៖ ប្រសិនបើបុគ្គលិកចាកចេញ ស្ថាបនិកមានសិទ្ធិទិញភាគហ៊ុននោះត្រឡប់មកវិញតាមតម្លៃទីផ្សារកំណត់ទុកជាមុន ដើម្បីការពារកុំឱ្យភាគហ៊ុនធ្លាក់ទៅលើដៃគូប្រជែង។', 'កំណត់ឈ្មោះបុគ្គលិកគន្លឹះ ២ ទៅ ៣ នាក់ដែលអាជីវកម្មរបស់អ្នកមិនអាចខ្វះបាន ហើយរៀបចំផែនការចែករំលែកប្រាក់ចំណេញ ឬភាគហ៊ុននិម្មិតដើម្បីចងចិត្តពួកគេរយៈពេលវែង។', 'តើអ្នកសុខចិត្តកាន់កាប់ភាគហ៊ុន ១០០% នៃក្រុមហ៊ុនតូចមួយ ឬកាន់កាប់ ៦០% នៃក្រុមហ៊ុនធំដែលមានកងទ័ពដែកដ៏ស្មោះត្រង់នៅក្បែរខ្លួន?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ជួបសន្ទនាស្មោះត្រង់ជាមួយបុគ្គលិកឆ្នើមបំផុតរបស់អ្នក ដើម្បីបង្ហាញពីចក្ខុវិស័យភាពជាដៃគូ និងផលប្រយោជន៍រយៈពេលវែងដែលពួកគេនឹងទទួលបាន។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-founder-10', 'lesson-founder-10', 'ហេតុអ្វីបានជាកិច្ចសន្យាផ្ទេរភាគហ៊ុនត្រូវតែមានលក្ខខណ្ឌ «1-Year Cliff» នៅក្នុងកិច្ចព្រមព្រៀងដៃគូ (Vesting Agreement)?', 'Why must equity vesting agreements include a mandatory "1-Year Cliff"?', '["A. ដើម្បីសន្សំថ្លៃសេវាច្បាប់របស់មេធាវី។","B. ដើម្បីការពារស្ថាប័នកុំឱ្យបាត់បង់ភាគហ៊ុនទៅលើមនុស្សដែលចូលមកធ្វើការតែពីរបីខែហើយលាលែងចេញដោយមិនបានបង្កើតតម្លៃពិតប្រាកដ (Protection from free-riders)។","C. ដើម្បីកុំឱ្យបុគ្គលិកទទួលបានប្រាក់ខែ។"]', '["A. To minimize external legal drafting expenses.","B. To protect the enterprise capitalization table from being permanently fractured by individuals who depart after a few months without delivering real value.","C. To withhold basic salary."]', 1, 'ការពន្យល់៖ 1-Year Cliff ការពារស្ថាបនិកពីអ្នកដែលចូលមកធ្វើការមួយភ្លែតហើយចាកចេញ។ បេក្ខជនត្រូវតែបង្ហាញការលះបង់យ៉ាងតិច ១ ឆ្នាំទើបចាប់ផ្តើមទទួលបានភាគហ៊ុន។', 'Explanation: The one-year cliff prevents equity dilution from short-tenured hires who fail to commit long-term.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-snr-1', 'course-senior-mentorship', 'mod-1', 1, '១. ការក្លាយជាអ្នកជំនាញឯកទេស (Subject Matter Expert) និងការដោះស្រាយបញ្ហាស្មុគស្មាញ', 'Becoming a Subject Matter Expert & Complex Problem Solving', 'text', '• កសាងជម្រៅជំនាញឯកទេស (Deep Domain Expertise) ដែលពិបាករកមនុស្សជំនួសបាន។\n• ម្ចាស់ការលើការដោះស្រាយឧបសគ្គបច្ចេកទេសស្មុគស្មាញដោយមិនបាច់រង់ចាំការណែនាំពីថ្នាក់លើ។\n• បង្កើតឯកសារ Best Practices និង Architecture សម្រាប់ស្ថាប័ន។', 'ភាពជា Senior មិនមែនគ្រាន់តែជាចំនួនឆ្នាំធ្វើការនោះទេ ប៉ុន្តែជាសមត្ថភាពដោះស្រាយបញ្ហាស្មុគស្មាញដោយស្ងប់ស្ងាត់ និងបង្កើតស្តង់ដារការងារខ្ពស់សម្រាប់ស្ថាប័នទាំងមូល។', '«ពិសិដ្ឋ ជាវិស្វករកម្មវិធីជាន់ខ្ពស់។ នៅពេលប្រព័ន្ធទូទាត់ប្រាក់របស់ក្រុមហ៊ុនគាំងនៅថ្ងៃបើកប្រាក់ខែ មនុស្សគ្រប់គ្នាកំពុងស្លន់ស្លោ។ ពិសិដ្ឋបានពិនិត្យមើល System Log ដោយស្ងប់ចិត្ត រកឃើញបញ្ហាកកស្ទះទិន្នន័យ (Database Deadlock) និងដោះស្រាយបញ្ហាបានត្រឹមតែ ១៥ នាទី។ ក្រោយមក គាត់បានសរសេរឯកសារស្ថាបត្យកម្មថ្មី និងរៀបចំយន្តការបម្រុង (Failover) ដើម្បីកុំឱ្យបញ្ហានេះកើតឡើងម្តងទៀត។ ថ្នាក់ដឹកនាំបានកោតសរសើរគាត់ជាសសរទ្រូងដ៏សំខាន់របស់ក្រុមហ៊ុន។»', '✅ របៀបបង្ហាញភាពជា Senior ក្នុងការងារ៖\n«នៅពេលមានបញ្ហាកើតឡើង ខ្ញុំមិនគ្រាន់តែរាយការណ៍ថាមានបញ្ហានោះទេ។ ខ្ញុំមកជួបប្រធានជាមួយជម្រើសដំណោះស្រាយ ២ យ៉ាង ព្រមទាំងការវិភាគពីគុណសម្បត្តិ និងគុណវិបត្តិនៃជម្រើសនីមួយៗ។»', 'ចងក្រងឯកសារ Best Practice ១ ទំព័រសម្រាប់ជំនាញឯកទេសរបស់អ្នក ដើម្បីទុកជាមេរៀនដល់សមាជិកដទៃ។', 'តើអ្នកកំពុងធ្វើជាមនុស្សដែលគ្រាន់តែយកបញ្ហាទៅប្រគល់ឱ្យមេ ឬជាមនុស្សដែលយកដំណោះស្រាយទៅជូនមេ?', '🎯 សកម្មភាពថ្ងៃនេះ៖ រាល់ពេលលើកឡើងពីបញ្ហាក្នុងថ្ងៃនេះ សូមភ្ជាប់មកជាមួយនូវដំណោះស្រាយយ៉ាងហោចណាស់ ១ ជម្រើស។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-snr-1', 'lesson-snr-1', 'តើអ្វីជាភាពខុសគ្នាសំខាន់បំផុតរវាងបុគ្គលិក Junior និងបុគ្គលិក Senior នៅពេលជួបបញ្ហាស្មុគស្មាញ?', 'What is the key difference between a Junior and Senior when encountering a complex problem?', '["A. Senior ធ្វើការច្រើនម៉ោងជាង Junior។","B. Senior មានភាពម្ចាស់ការ ស្វែងរកឫសគល់បញ្ហា និងផ្តល់ជម្រើសដំណោះស្រាយជាស្រេច ខណៈដែល Junior គ្រាន់តែរត់មករាយការណ៍បញ្ហា។","C. Senior មិនដែលជួបកំហុសការងារទាល់តែសោះ។"]', '["A. Seniors work longer hours.","B. Seniors take autonomous ownership, analyze root causes, and propose vetted solutions instead of just escalating problems.","C. Seniors never make mistakes."]', 1, 'ការពន្យល់៖ ជម្រើស B បង្ហាញពីភាពចាស់ទុំវិជ្ជាជីវៈ (Professional Ownership) របស់ Senior។', 'Explanation: Autonomous problem solving and vetted solutions define senior-level capability.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-snr-2', 'course-senior-mentorship', 'mod-1', 2, '២. សិល្បៈនៃការធ្វើជា Mentor បង្វឹកសមាជិកជំនាន់ក្រោយ (The Art of Mentoring Juniors)', 'The Art of Mentoring & Upskilling Junior Talent', 'text', '• យល់ដឹងថាការបណ្តុះបណ្តាលអ្នកដទៃ គឺជាគន្លឹះដំឡើងខ្លួនឯងឱ្យឡើងទៅកាន់តំណែង Lead ឬ Manager។\n• អនុវត្តវិធីសាស្ត្រណែនាំ "Show, Do, Review" ដោយមិនដណ្តើមការងារគេមកធ្វើខ្លួនឯង។\n• កសាងទំនុកចិត្ត និងផ្តល់កន្លែងសុវត្ថិភាពផ្លូវចិត្តសម្រាប់សមាជិកថ្មីក្នុងការរៀនសូត្រ។', 'Senior ពិតប្រាកដមិនមែនជាមនុស្សដែលចេះការងារតែម្នាក់ឯងហើយលាក់ចំណេះនោះទេ ប៉ុន្តែជាអ្នកដែលបង្កើតមនុស្សពូកែៗជាច្រើននៅជុំវិញខ្លួន (Force Multiplier)។', '«សុខា ជា Senior Developer ដែលមានចំណេះដឹងទូលំទូលាយ។ ពីមុន ពេលកូនចៅធ្វើការខុស គាត់តែងតែដណ្តើមយកមកធ្វើខ្លួនឯងព្រោះគិតថាលឿនជាង។ លទ្ធផលគឺគាត់រវល់ដកដង្ហើមមិនដល់ ហើយកូនចៅមិនចេះរីកចម្រើន។ ក្រោយមក គាត់បានផ្លាស់ប្តូរមកអនុវត្តក្បួន Mentor៖ គាត់ពន្យល់គោលការណ៍ ទុកឱ្យកូនចៅអនុវត្ត ហើយជួយកែសម្រួលនៅជំហានចុងក្រោយ។ ត្រឹមតែ ៦ ខែ ក្រុមរបស់គាត់រឹងមាំខ្លាំង ហើយសុខាត្រូវបានតែងតាំងជា Lead Architect។»', '✅ រូបមន្តបង្វឹក ៣ ជំហាន៖\n១. ខ្ញុំធ្វើឱ្យមើល (I do, you watch)។\n២. យើងធ្វើជាមួយគ្នា (We do together)។\n៣. ឯងធ្វើ ហើយខ្ញុំចាំជួយមើល (You do, I coach)។', 'ជ្រើសរើសសមាជិក Junior ម្នាក់ ហើយបង្រៀនគាត់នូវបច្ចេកទេសការងារមួយដែលអ្នកចេះច្បាស់ក្នុងសប្តាហ៍នេះ។', 'តើអ្នកមានអារម្មណ៍ពេញចិត្តកម្រិតណា នៅពេលឃើញសមាជិកដែលអ្នកធ្លាប់បង្វឹក ទទួលបានជោគជ័យ និងឡើងតំណែង?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ចំណាយពេល ២០ នាទីជួយពន្យល់កិច្ចការស្មុគស្មាញមួយដល់សហការី Junior ម្នាក់។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-snr-2', 'lesson-snr-2', 'ហេតុអ្វីបានជា Senior មិនគួរដណ្តើមការងារពី Junior មកធ្វើខ្លួនឯង នៅពេលឃើញពួកគេធ្វើការយឺត?', 'Why should a Senior avoid taking over tasks from a Junior when they work slowly?', '["A. ព្រោះធ្វើបែបនេះនឹងធ្វើឱ្យ Senior ខ្ជិល។","B. ព្រោះការដណ្តើមធ្វើធ្វើឱ្យ Junior បាត់បង់ឱកាសរៀនសូត្រ បង្កើតការពឹងផ្អែក និងធ្វើឱ្យ Senior ផ្ទុកការងារហួសកម្លាំង។","C. ព្រោះក្រុមហ៊ុនហាមឃាត់មិនឱ្យ Senior ធ្វើការងារតូចតាច។"]', '["A. Because it makes the Senior lazy.","B. It robs the Junior of learning, creates unhealthy dependency, and overburdens the Senior.","C. Because company rules forbid it."]', 1, 'ការពន្យល់៖ ជម្រើស B បង្ហាញពីគោលការណ៍កសាងសមត្ថភាពក្រុមប្រកបដោយនិរន្តរភាព។', 'Explanation: Coaching requires patience; taking over work creates bottlenecks and stunts junior growth.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-senior-3', 'course-senior-mentorship', 'mod-1', 3, '៣. ភាពជាម្ចាស់ការដោះស្រាយបញ្ហាស្មុគស្មាញដោយគ្មានការត្រួតពិនិត្យ (Autonomous Problem Solving)', 'Autonomous Problem Solving: Delivering Results Without Supervision', 'text', '• យល់ដឹងពីភាពខុសគ្នារវាង Junior (ត្រូវការការណែនាំ) និង Senior (ដោះស្រាយបញ្ហាស្វយ័ត)។\n• ចេះគ្រប់គ្រងគម្រោងមិនច្បាស់លាស់ (Ambiguity) ដោយបំបែកវាជាផែនការអនុវត្តជាក់ស្តែង។\n• បង្កើតដំណោះស្រាយដែលរឹងមាំ និងមានចីរភាពយូរអង្វែងសម្រាប់ស្ថាប័ន។', 'ភាពជា Senior មិនត្រូវបានកំណត់ដោយចំនួនឆ្នាំធ្វើការនោះទេ ប៉ុន្តែត្រូវបានកំណត់ដោយសមត្ថភាព «ទទួលការងារមិនច្បាស់លាស់ ហើយប្រគល់លទ្ធផលច្បាស់លាស់ដោយគ្មានការត្រួតពិនិត្យ» (Managing Ambiguity)។ នៅពេលថ្នាក់លើប្រគល់បញ្ហាស្មុគស្មាញមួយ Senior ពិតប្រាកដនឹងមិនរត់ទៅសួរថា "តើខ្ញុំត្រូវធ្វើម៉េចបន្ត?" នោះទេ ប៉ុន្តែពួកគេនឹងត្រឡប់មកវិញជាមួយនឹងផែនការសកម្មភាព និងលទ្ធផលសម្រេច។', '«ក្នុងអំឡុងពេលប្រព័ន្ធទូទាត់ប្រាក់ឌីជីថលរបស់ធនាគារមួយជួបការគាំងស្ទះធ្ងន់ធ្ងរនៅចុងខែ លោក វិបុល ជា Senior Systems Engineer មិនបានរង់ចាំឱ្យប្រធានផ្នែក IT បញ្ជាឡើយ។ គាត់បានដឹកនាំក្រុមការងារវិភាគ Log ទិន្នន័យ ឯកោបញ្ហា (Isolate the fault) បង្កើត Patch សង្គ្រោះបន្ទាន់ និងដំឡើងប្រព័ន្ធ Fail-over ក្នុងរយៈពេលតែ ៤៥ នាទី។ នៅពេលប្រធានផ្នែកមកដល់ វិបុលបានរៀបចំរួចរាល់ទាំងប្រព័ន្ធដំណើរការឡើងវិញ និងរបាយការណ៍ Root-Cause Analysis។ សមត្ថភាពម្ចាស់ការកម្រិតខ្ពស់នេះបានជួយសង្គ្រោះក្រុមហ៊ុនពីការខាតបង់រាប់សែនដុល្លារ។»', '✅ របៀបធ្វើការងារបែប Senior Autonomous Mindset៖\n១. បកស្រាយគោលបំណងធុរកិច្ច (Business Intent) ពីសំណើរមិនច្បាស់លាស់របស់ថ្នាក់លើ។\n២. ធ្វើតេស្តសាកល្បងដំណោះស្រាយក្នុងបរិយាកាសសុវត្ថិភាព (Sandbox) មុននឹងអនុវត្តលើផលិតកម្ម។\n៣. ផ្តល់របាយការណ៍សង្ខេបអំពីលទ្ធផល និងអនុសាសន៍ការពារហានិភ័យទៅថ្ងៃអនាគត។', 'ជ្រើសរើសបញ្ហាប្រព័ន្ធការងារចាស់មួយដែលគ្មានអ្នកណាដោះស្រាយក្នុងផ្នែករបស់អ្នក ហើយរៀបចំដំណោះស្រាយស្វ័យប្រវត្តិដើម្បីដោះស្រាយវា។', 'តើអ្នកនៅតែរង់ចាំការណែនាំពីប្រធានគ្រប់ជំហាន ឬអ្នកជាមនុស្សដែលបង្កើតដំណោះស្រាយដោយខ្លួនឯង?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ទទួលយកកិច្ចការស្មុគស្មាញមួយដែលគ្មានអ្នកណាចង់ធ្វើ ហើយដោះស្រាយវាឱ្យចប់សព្វគ្រប់ដោយម្ចាស់ការ។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-senior-3', 'lesson-senior-3', 'តើចរិតលក្ខណៈស្នូលដែលញែកបុគ្គលិក Senior ចេញពី Junior គឺជាអ្វី?', 'What is the core trait that distinguishes a true Senior from a Junior?', '["A. មានអាយុច្រើនជាង និងទាមទារប្រាក់ខែខ្ពស់ដោយមិនបាច់ធ្វើការងារលម្អិត។","B. សមត្ថភាពម្ចាស់ការក្នុងការដោះស្រាយបញ្ហាស្មុគស្មាញដោយខ្លួនឯង និងប្រគល់លទ្ធផលដោយមិនចាំបាច់មានអ្នកតាមដាន។","C. ចូលចិត្តស្តីបន្ទោស Junior នៅពេលមានកំហុសកើតឡើង។"]', '["A. Being older and demanding higher pay without hands-on work.","B. Ability to autonomously tackle ambiguous, complex problems and deliver results without supervision.","C. Frequently scolding junior teammates."]', 1, 'ការពន្យល់៖ បុគ្គលិក Senior ពិតប្រាកដគឺជាអ្នកដោះស្រាយបញ្ហាដោយស្វ័យភាព (Autonomous Problem Solver) ដែលថ្នាក់លើអាចទុកចិត្តបាន ១០០%។', 'Explanation: True seniority is defined by autonomous problem solving and delivering clarity out of ambiguity.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-senior-4', 'course-senior-mentorship', 'mod-1', 4, '៤. សិល្បៈនៃការបង្វឹក និងផ្ទេរចំណេះដឹង (Huawei Mentorship: 传帮带)', 'Mentorship Excellence: The Huawei "Pass, Help, Guide" Talent Development Model', 'text', '• យល់ដឹងពីប្រព័ន្ធបង្វឹកដ៏ល្បីរបស់ក្រុមហ៊ុន Huawei «传帮带» (Pass Knowledge, Help Execute, Guide Growth)។\n• បង្កើតវិធីសាស្ត្រផ្ទេរជំនាញបច្ចេកទេសដោយមិនកំណាញ់ចំណេះដឹង (Knowledge Sharing Culture)។\n• រៀនផ្តល់ Feedback ស្ថាបនាដល់ Junior ដោយមិនធ្វើឱ្យពួកគេបាក់ទឹកចិត្ត។', 'នៅក្រុមហ៊ុន Huawei រាល់បុគ្គលិកថ្មីទាំងអស់សុទ្ធតែត្រូវបានផ្គូផ្គងជាមួយ «គ្រូបង្វឹក» (Senior Mentor/师傅)។ ទស្សនវិជ្ជា «传帮带» (ឈ័ន-ប៉ាង-តាយ) បង្រៀនថា៖ ការរីកចម្រើនរបស់ Senior ត្រូវបានវាស់វែងលើ «ចំនួនមនុស្សដែលអ្នកបានបណ្តុះបណ្តាលឱ្យពូកែដូចអ្នក ឬលើសអ្នក»។ បុគ្គលិក Senior ដែលកំណាញ់ចំណេះដឹង ព្រោះខ្លាចគេដណ្តើមតំណែង គឺជាមនុស្សដែលមានផ្នត់គំនិតចង្អៀតចង្អល់ និងមិនអាចឡើងទៅកាន់តំណែងគ្រប់គ្រងបានឡើយ។', '«លោក សម្បត្តិ ជា Senior Accountant នៅក្រុមហ៊ុនផលិតកម្មធំមួយ។ កន្លងមក គាត់មិនដែលចែករំលែករបៀបធ្វើរបាយការណ៍បិទបញ្ជីគណនេយ្យពន្ធដារដល់អ្នកណាឡើយ។ ជាលទ្ធផល រាល់ពេលដល់ចុងខែ គាត់ត្រូវធ្វើការថែមម៉ោងរហូតដល់ម៉ោង ១១ យប់តែម្នាក់ឯង ហើយពេលគាត់ឈឺ គ្មានអ្នកណាអាចជំនួសបានឡើយ។ ក្រោយពីយល់ដឹងពីក្បួន Mentorship គាត់បានចំណាយពេលបង្វឹក Junior ២ នាក់តាមដំណាក់កាល៖ ១. គាត់ធ្វើឱ្យមើល ២. ឱ្យ Junior ធ្វើដោយគាត់ឈរជួយ ៣. ឱ្យ Junior ធ្វើដោយឯករាជ្យ។ ត្រឹមតែ ២ ខែ Junior ទាំងពីរអាចបិទបញ្ជីបានយ៉ាងស្ទាត់ជំនាញ។ សម្បត្តិបានរួចដៃពីការងារទម្លាប់ប្រចាំថ្ងៃ ហើយត្រូវបានថ្នាក់លើតម្លើងជា Accounting Manager ព្រោះគាត់បានបង្ហាញសមត្ថភាពដឹកនាំ និងកសាងក្រុម។»', '✅ ជំហាន ៣ នៃការបង្វឹកបែប Huawei 传帮带 (The 3-Step Mentorship)៖\n១. [传 - Pass]៖ ពន្យល់ពីគោលការណ៍ និងបង្ហាញគំរូជាក់ស្តែង ("មើលខ្ញុំធ្វើសិន")\n២. [帮 - Help]៖ ឱ្យសិស្សអនុវត្តផ្ទាល់ ដោយយើងឈរនៅក្បែរចាំជួយណែនាំ ("ឯងធ្វើម្តង ខ្ញុំចាំជួយ")\n៣. [带 - Guide]៖ បណ្តោយឱ្យសិស្សធ្វើដោយឯករាជ្យ និងត្រួតពិនិត្យតែលទ្ធផលចុងក្រោយ ("ឯងធ្វើដោយខ្លួនឯង ខ្ញុំជាខ្នងបង្អែក")', 'ជ្រើសរើសជំនាញបច្ចេកទេសមួយរបស់អ្នក ហើយរៀបចំការបង្រៀនរយៈពេល ៣០ នាទីដល់សមាជិក Junior ម្នាក់ក្នុងក្រុមនៅសប្តាហ៍នេះ។', 'តើអ្នកធ្លាប់មានការស្ទាក់ស្ទើរក្នុងការបង្រៀនអ្នកដទៃព្រោះខ្លាចគេពូកែជាងខ្លួនឯងដែរឬទេ? តើផ្នត់គំនិតនោះរារាំងការឡើងតំណែងរបស់អ្នកយ៉ាងដូចម្តេច?', '🎯 សកម្មភាពថ្ងៃនេះ៖ កំណត់ Junior ម្នាក់ដែលអ្នកត្រូវធ្វើជា Mentor ហើយរៀបចំការសន្ទនាបង្វឹក ១-on-១ លើកដំបូង។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-senior-4', 'lesson-senior-4', 'តាមទស្សនវិជ្ជាបណ្តុះបណ្តាលបុគ្គលិក Huawei «传帮带» តើអ្វីជារង្វាស់នៃភាពជោគជ័យពិតប្រាកដរបស់ Senior Specialist?', 'In Huawei mentorship philosophy (传帮带), what is the true metric of success for a senior specialist?', '["A. រក្សាការសម្ងាត់បច្ចេកទេសតែម្នាក់ឯង ដើម្បីកុំឱ្យគេដណ្តើមតំណែង។","B. សមត្ថភាពផ្ទេរចំណេះដឹង និងបណ្តុះបណ្តាលសមាជិកជំនាន់ក្រោយឱ្យរីកចម្រើន និងអាចធ្វើការជំនួសខ្លួនបាន។","C. ធ្វើការថែមម៉ោងរាល់យប់ដើម្បីបង្ហាញថាខ្លួនឯងរវល់ជាងគេ។"]', '["A. Guarding technical secrets to protect job security.","B. Ability to transfer skills and develop junior talent to work autonomously and scale team output.","C. Working overtime every night to appear the busiest."]', 1, 'ការពន្យល់៖ Senior ឆ្នើមគឺជារៀមច្បងដែលកសាងអ្នកបន្តវេន។ ការជួយអ្នកដទៃឱ្យពូកែ ជួយពង្រីកឥទ្ធិពល និងបើកផ្លូវឱ្យខ្លួនឯងឡើងទៅកាន់តំណែងដឹកនាំ។', 'Explanation: Elevating others expands organizational leverage and qualifies the senior for executive leadership.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-senior-5', 'course-senior-mentorship', 'mod-1', 5, '៥. ការគិតជាប្រព័ន្ធ និងស្ថាបត្យកម្មការងារ (System Thinking & Architecture)', 'System Architecture & Scalability: Designing Long-Term Robust Solutions', 'text', '• យល់ដឹងពីការគិតជាប្រព័ន្ធ (System Thinking)៖ មើលឃើញព្រៃទាំងមូល មិនមែនមើលឃើញតែដើមឈើមួយដើម។\n• រចនាដំណោះស្រាយការងារដែលអាចពង្រីកទំហំបាន (Scalability) និងងាយស្រួលថែទាំ (Maintainability)។\n• កាត់បន្ថយបំណុលបច្ចេកទេស (Technical Debt) និងថ្លៃដើមប្រតិបត្តិការរយៈពេលវែង។', 'Junior ផ្តោតលើការធ្វើឱ្យការងារ «ដើរ» (Make it work) ប៉ុន្តែ Senior ផ្តោតលើការធ្វើឱ្យប្រព័ន្ធ «រឹងមាំ ពង្រីកបាន និងមានសុវត្ថិភាព» (Make it scalable, robust, and maintainable)។ ការគិតជាប្រព័ន្ធតម្រូវឱ្យអ្នកវិភាគថាតើការសម្រេចចិត្តបច្ចេកទេសនៅថ្ងៃនេះ នឹងជះឥទ្ធិពលបែបណាចំពោះស្ថាប័នក្នុងរយៈពេល ៦ ខែ ឬ ៣ ឆ្នាំខាងមុខ។', '«ក្នុងគម្រោងបង្កើតប្រព័ន្ធគ្រប់គ្រងឃ្លាំងទំនិញថ្មី Junior Developer ចង់សរសេរ Code កាត់ៗដើម្បីឱ្យរួចទាន់ Deadline ២ សប្តាហ៍។ ប៉ុន្តែ លោក សុខា ជា Senior Architect បានជំទាស់។ គាត់បានពន្យល់ថា ប្រសិនបើធ្វើបែបនេះ ពេលទំនិញកើនឡើងដល់ ១០០,០០០ មុខ ប្រព័ន្ធនឹងគាំង ហើយត្រូវរុះរើធ្វើឡើងវិញទាំងអស់ដែលខាតពេល ៦ ខែ។ គាត់បានរចនាស្ថាបត្យកម្មបែប Modular Architecture ដែលអនុញ្ញាតឱ្យប្រព័ន្ធពង្រីកបានដោយរលូន។ មួយឆ្នាំក្រោយមក នៅពេលក្រុមហ៊ុនពង្រីកសាខាទូទាំង ២៥ ខេត្តក្រុង ប្រព័ន្ធនៅតែដំណើរការយ៉ាងលឿន និងមានស្ថេរភាពខ្ពស់។»', '✅ បញ្ជីត្រួតពិនិត្យស្ថាបត្យកម្មបែប Senior (System Design Checklist)៖\n១. [Scalability]៖ តើប្រព័ន្ធនេះអាចទ្រទ្រង់ទិន្នន័យកើនឡើង ១០ ដងបានដែរឬទេ?\n២. [Maintainability]៖ តើសមាជិកថ្មីអាចចូលមកអាន និងកែប្រែបានងាយស្រួលដែរឬទេ?\n៣. [Security & Compliance]៖ តើមានប្រព័ន្ធការពារការលួចទិន្នន័យ និងការបម្រុងទុក (Backup) ហើយឬនៅ?', 'ពិនិត្យឡើងវិញនូវប្រព័ន្ធ ឬដំណើរការការងារបច្ចុប្បន្នក្នុងផ្នែករបស់អ្នក ហើយកំណត់ចំណុចដែលអាចក្លាយជា Technical Debt នាពេលអនាគត។', 'តើការងារដែលអ្នកកំពុងកសាងនៅថ្ងៃនេះ អាចដំណើរការបានយ៉ាងរលូនដែរឬទេ ប្រសិនបើទិន្នន័យ ឬចំនួនអតិថិជនកើនឡើង ១០ ដង?', '🎯 សកម្មភាពថ្ងៃនេះ៖ សរសេរឯកសារណែនាំស្ថាបត្យកម្ម (Architecture Document) ១ ទំព័រសម្រាប់គម្រោងបច្ចុប្បន្នរបស់អ្នក។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-senior-5', 'lesson-senior-5', 'តើអ្វីជាភាពខុសគ្នាសំខាន់បំផុតរវាងដំណោះស្រាយដែលបង្កើតដោយ Junior និង Senior?', 'What is the most crucial difference between solutions built by Juniors vs. Seniors?', '["A. Junior ប្រើកុំព្យូទ័រយឺតជាង Senior។","B. Junior ផ្តោតលើការធ្វើឱ្យការងារដើរបានលឿនជាបណ្តោះអាសន្ន រីឯ Senior គិតគូរពីស្ថេរភាព រយៈពេលវែង និងការពង្រីកទំហំ (Scalability)។","C. Senior មិនដែលសរសេរឯកសារណែនាំការងារឡើយ។"]', '["A. Juniors use slower computers than Seniors.","B. Juniors focus on immediate temporary fixes, while Seniors architect for long-term scalability and resilience.","C. Seniors never write documentation."]', 1, 'ការពន្យល់៖ Senior គិតគូរពីប្រព័ន្ធទាំងមូល (System Thinking) និងការពារកុំឱ្យកើតមានបំណុលបច្ចេកទេស (Technical Debt) នាពេលអនាគត។', 'Explanation: Seniors architect for long-term maintainability, edge cases, and enterprise scalability.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-senior-6', 'course-senior-mentorship', 'mod-1', 6, '៦. ការបកប្រែបច្ចេកទេសទៅជាភាសាធុរកិច្ច (Translating Tech to Business Value)', 'Business Acumen for Specialists: Translating Technical Jargon to ROI', 'text', '• ចេះបកប្រែពាក្យបច្ចេកទេសស្មុគស្មាញ (Technical Jargon) ទៅជាភាសាផលចំណេញធុរកិច្ច (ROI, Revenue, Cost)។\n• បង្ហាញតម្លៃនៃការងារបច្ចេកទេសទៅកាន់ថ្នាក់ដឹកនាំជាន់ខ្ពស់ និងផ្នែកលក់។\n• ជៀសវាងការជជែកដេញដោលបច្ចេកទេសសុទ្ធសាធដែលមិនទាក់ទងនឹងគោលដៅយុទ្ធសាស្ត្រក្រុមហ៊ុន។', 'មូលហេតុចម្បងដែលគម្រោងបច្ចេកទេសល្អៗជាច្រើនមិនត្រូវបានអនុម័តថវិកា គឺដោយសារតែអ្នកជំនាញនិយាយជាភាសាកូដ ឬភាសាវិស្វកម្មដែលថ្នាក់ដឹកនាំមិនយល់។ Senior ដែលមានតម្លៃខ្ពស់បំផុត គឺជាអ្នកដែលអាចធ្វើជា «អ្នកបកប្រែ» — បង្ហាញឱ្យឃើញច្បាស់ថា តើការកែលម្អប្រព័ន្ធនេះនឹងជួយសន្សំប្រាក់បានប៉ុន្មាន ឬជួយរកចំណូលបានប៉ុន្មានដល់ក្រុមហ៊ុន។', '«លោក សារ៉េត ជា Senior Data Analyst ចង់ស្នើសុំថវិកា $15,000 ទិញ Tool វិភាគទិន្នន័យថ្មី។ លើកដំបូងគាត់បានពន្យល់ CEO ថា៖ "Tool នេះប្រើក្បួនដោះស្រាយ Machine Learning Random Forest និងមាន Latency ត្រឹម 20ms!" CEO បានបដិសេធភ្លាមៗព្រោះមិនយល់។ លើកទីពីរ សារ៉េតបានប្តូររបៀបនិយាយ៖ "ប្រសិនបើយើងប្រើប្រព័ន្ធនេះ វានឹងជួយកាត់បន្ថយអត្រាអតិថិជនឈប់ប្រើប្រាស់ (Churn Rate) ចំនួន ៥% ដែលជួយរក្សាចំណូលប្រចាំឆ្នាំបាន $80,000 ស្មើនឹងផលចំណេញលើការវិនិយោគ (ROI) ៥០០% ក្នុងឆ្នាំដំបូង"។ CEO បានចុះហត្ថលេខាយល់ព្រមភ្លាមៗក្នុងរយៈពេល ៥ នាទី។»', '✅ រូបមន្តបកប្រែបច្ចេកទេសទៅជាធុរកិច្ច (The Tech-to-ROI Translation Formula)៖\n• ជំនួសឱ្យការនិយាយ៖ "យើងត្រូវ Refactor Code ព្រោះវាមាន Code Smells ច្រើន!"\n• ចូរនិយាយថា៖ "ការកែលម្អរចនាសម្ព័ន្ធកូដនេះ នឹងជួយកាត់បន្ថយពេលចេញមុខងារថ្មីពី ៤ សប្តាហ៍មកត្រឹម ១ សប្តាហ៍ ដែលជួយឱ្យយើងវាយលុកទីផ្សារបានលឿនជាងគូប្រជែង ៣ សប្តាហ៍។"', 'ជ្រើសរើសសំណើបច្ចេកទេសមួយរបស់អ្នក ហើយសរសេរវាឡើងវិញដោយប្រើតួលេខហិរញ្ញវត្ថុ ឬផលចំណេញធុរកិច្ចសុទ្ធសាធ។', 'តើអ្នកធ្លាប់មានអារម្មណ៍ខកចិត្តដែលថ្នាក់លើមិនយល់ពីតម្លៃនៃការងារបច្ចេកទេសរបស់អ្នកដែរឬទេ? តើអ្នកបានព្យាយាមនិយាយជាភាសាហិរញ្ញវត្ថុជាមួយពួកគេហើយឬនៅ?', '🎯 សកម្មភាពថ្ងៃនេះ៖ បំប្លែងរបាយការណ៍បច្ចេកទេសបន្ទាប់របស់អ្នកឱ្យមានផ្នែក «ផលប៉ះពាល់ធុរកិច្ច» (Business Impact Summary) នៅទំព័រមុខបង្អស់។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-senior-6', 'lesson-senior-6', 'នៅពេលអ្នកជំនាញបច្ចេកទេស (Senior Specialist) ចង់ស្នើសុំថវិកាពី CEO តើរបៀបនិយាយណាដែលជោគជ័យបំផុត?', 'When a senior specialist pitches for budget to the CEO, which framing is most persuasive?', '["A. រៀបរាប់ពីកូដ និងពាក្យបច្ចេកទេសស្មុគស្មាញឱ្យបានច្រើនដើម្បីបង្ហាញពីភាពឆ្លាតវៃ។","B. បង្ហាញពីផលប៉ះពាល់ធុរកិច្ច (Business Impact) ដូចជា ការបង្កើនចំណូល ការសន្សំថ្លៃដើម ឬការកាត់បន្ថយហានិភ័យ។","C. ប្រាប់ CEO ថាបើមិនយល់ព្រមទេ គាត់នឹងលាលែងពីការងារ។"]', '["A. Overload with complex technical jargon to sound intellectual.","B. Quantify the business impact: revenue growth, cost reduction, customer retention, or risk mitigation.","C. Threaten to resign if not approved."]', 1, 'ការពន្យល់៖ ថ្នាក់ដឹកនាំជាន់ខ្ពស់សម្រេចចិត្តលើផលចំណេញធុរកិច្ច (Business Value & ROI)។ ការចេះបកប្រែបច្ចេកទេសជាភាសាធុរកិច្ចគឺជាជំនាញស្នូលរបស់ Senior។', 'Explanation: Senior leaders care about ROI, margins, and strategic advantage over technical implementation details.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-senior-7', 'course-senior-mentorship', 'mod-1', 7, '៧. ការស៊ើបអង្កេតឧប្បត្តិហេតុដោយគ្មានការស្តីបន្ទោស (Blameless Post-Mortem)', 'Blameless Post-Mortem: Transforming Failures into Institutional Wisdom', 'text', '• យល់ដឹងពីវប្បធម៌ Blameless Post-Mortem របស់ក្រុមហ៊ុន Google និង Etsy។\n• បង្កើតរបាយការណ៍វិភាគឧប្បត្តិហេតុ (Incident Report) ដែលផ្តោតលើភាពខ្វះខាតនៃប្រព័ន្ធ មិនមែនបុគ្គល។\n• ដឹកនាំកិច្ចប្រជុំ Post-Mortem ប្រកបដោយភាពស្ថាបនា និងបង្កើតទំនុកចិត្តផ្លូវចិត្ត (Psychological Safety)។', 'នៅពេលប្រព័ន្ធការងារជួបការបរាជ័យធំ ក្រុមហ៊ុនដែលទន់ខ្សោយនឹងប្រញាប់ស្វែងរក «អ្នកណាជាអ្នកខុស» ដើម្បីស្តីបន្ទោស ឬបណ្តេញចេញ។ ផ្ទុយទៅវិញ ក្រុមហ៊ុនកម្រិតពិភពលោកយល់ថា៖ «កំហុសរបស់មនុស្សកើតចេញពីភាពទន់ខ្សោយនៃប្រព័ន្ធ»។ Senior ដឹកនាំកិច្ចប្រជុំវិភាគឧប្បត្តិហេតុដោយគ្មានការស្តីបន្ទោស (Blameless Post-Mortem) ដើម្បីកែប្រែប្រព័ន្ធការពារកុំឱ្យនរណាម្នាក់អាចបង្កើតកំហុសដដែលនោះបានទៀតឡើយ។', '«នៅក្រុមហ៊ុនទូរគមនាគមន៍មួយ វិស្វករថ្មីម្នាក់បានចុចច្រឡំលុបទិន្នន័យ Routing Table ធ្វើឱ្យបណ្តាញអ៊ីនធឺណិតដាច់ទូទាំងប្រទេសអស់រយៈពេល ២ ម៉ោង។ ជំនួសឱ្យការបណ្តេញវិស្វករនោះចេញ លោក រិទ្ធី ជា Principal Engineer បានដឹកនាំការប្រជុំ Blameless Post-Mortem។ \nគាត់បានចោទសួរសំណួរថា៖ "ហេតុអ្វីបានជាប្រព័ន្ធរបស់យើងអនុញ្ញាតឱ្យវិស្វករម្នាក់ចុចពាក្យ Delete ដោយគ្មានការផ្ទៀងផ្ទាត់ពីមនុស្សទីពីរ? ហេតុអ្វីគ្មានប្រព័ន្ធ Backup ស្វ័យប្រវត្ត?" ក្រុមការងារបានបន្ថែមប្រព័ន្ធ Two-Person Approval និង Automated Rollback។ ការធ្វើបែបនេះបានកសាងទំនុកចិត្តយ៉ាងខ្លាំងក្នុងចំណោមវិស្វករ ហើយបណ្តាញមិនដែលដាច់ម្តងណាទៀតឡើយ។»', '✅ គ្រោងការណ៍របាយការណ៍ Blameless Post-Mortem៖\n១. [Incident Summary]៖ តើមានអ្វីកើតឡើង? ដាច់ប្រព័ន្ធប៉ុន្មាននាទី? ប៉ះពាល់អ្នកប្រើប្រាស់ប៉ុន្មាននាក់?\n②. [Timeline]៖ កាលប្បវត្តិនៃព្រឹត្តិការណ៍ចាប់ពីពេលកើតហេតុ រហូតដល់ពេលដោះស្រាយរួច។\n៣. [Root Causes]៖ មូលហេតុស្នូលក្នុងប្រព័ន្ធដែលបង្កឱ្យមានឧប្បត្តិហេតុ។\n៤. [Action Items]៖ បញ្ជីកិច្ចការបង្ការការពារ (Preventative Actions) អមជាមួយអ្នកទទួលខុសត្រូវ។', 'ជ្រើសរើសឧប្បត្តិហេតុ ឬកំហុសការងារថ្មីៗមួយក្នុងក្រុមរបស់អ្នក ហើយសរសេរសេចក្តីព្រាងរបាយការណ៍ Post-Mortem ដោយគ្មានការស្តីបន្ទោសបុគ្គល។', 'តើក្រុមការងាររបស់អ្នកមានវប្បធម៌ស្តីបន្ទោស ឬវប្បធម៌រៀនសូត្រពីកំហុស? តើអ្នកអាចជួយផ្លាស់ប្តូរវាដោយរបៀបណា?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ពេលមានកំហុសកើតឡើង សូមឈប់សួរថា «អ្នកណាធ្វើ?» ហើយប្តូរមកសួរថា «តើប្រព័ន្ធរបស់យើងខ្វះអ្វីបានជាធ្វើឱ្យមានកំហុសនេះ?»។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-senior-7', 'lesson-senior-7', 'តើអ្វីជាគោលការណ៍គ្រឹះនៃកិច្ចប្រជុំវិភាគកំហុសបែប Blameless Post-Mortem?', 'What is the fundamental principle of a Blameless Post-Mortem?', '["A. រកឱ្យឃើញអ្នកចុចខុសដើម្បីដកតំណែងជាសាធារណៈ។","B. សន្មតថាមនុស្សគ្រប់គ្នាសុទ្ធតែមានចេតនាល្អ ហើយកំហុសកើតឡើងដោយសារប្រព័ន្ធ ឬដំណើរការការងារមានចន្លោះប្រហោង។","C. លុបភស្តុតាងចោលដើម្បីកុំឱ្យអតិថិជនដឹងពីរឿងអាស្រូវ។"]', '["A. Identify who pushed the wrong button and demote them publicly.","B. Assume good intentions and focus on uncovering systemic vulnerabilities to strengthen defenses.","C. Delete incident logs to hide mistakes from customers."]', 1, 'ការពន្យល់៖ Blameless Post-Mortem ជឿជាក់ថាមនុស្សគ្រប់គ្នាមានចេតនាល្អ។ ប្រសិនបើប្រព័ន្ធអនុញ្ញាតឱ្យមនុស្សម្នាក់បង្កើតកំហុសធ្ងន់ធ្ងរបាន នោះប្រព័ន្ធគឺជាអ្នកដែលមានបញ្ហា។', 'Explanation: Human error is a symptom of systemic failure; blameless post-mortems fortify processes.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-senior-8', 'course-senior-mentorship', 'mod-1', 8, '៨. ការបង្កើតស្តង់ដារគុណភាព និងការពិនិត្យការងារ (Code Review & Quality Gatekeeping)', 'Quality Gatekeeping & Constructive Peer Review Mastery', 'text', '• ចេះបង្កើត និងអនុវត្តស្តង់ដារគុណភាពការងារ (Quality Standards & SOPs) សម្រាប់ក្រុមទាំងមូល។\n• អនុវត្តការពិនិត្យការងារ (Peer Review / Code Review) ប្រកបដោយភាពម៉ត់ចត់ និងការលើកទឹកចិត្ត។\n• កសាងប្រព័ន្ធស្វ័យប្រវត្តិកម្ម (Linters, CI/CD, Automated Tests) ដើម្បីការពារគុណភាពស្ថាប័ន។', 'Senior គឺជាអ្នកយាមទ្វារនៃគុណភាព (Quality Gatekeeper)។ ការពិនិត្យការងារ (Review) មិនមែនជាការចាប់កំហុសតូចតាចដើម្បីបង្ហាញអំណាចនោះទេ ប៉ុន្តែជាឱកាសបណ្តុះបណ្តាល និងជាការការពារកេរ្តិ៍ឈ្មោះរបស់ស្ថាប័ន។ Senior ឆ្នើមតែងតែសរសើរចំណុចល្អជាសាធារណៈ និងផ្តល់អនុសាសន៍កែលម្អជាក់លាក់ជាមួយការពន្យល់ពីមូលហេតុ (The "Why" behind the rule)។', '«កញ្ញា មុនីកា ជា Senior Graphic & Brand Specialist។ រាល់ពេល Junior ប្រគល់ស្នាដៃរចនា នាងមិនគ្រាន់តែនិយាយថា "មិនស្អាត ទៅកែឡើងវិញ!" នោះទេ។ នាងបានបង្កើត Brand Guidelines ច្បាស់លាស់មួយក្បាល និងរៀបចំតារាង Review Checklist។ \nពេលពិនិត្យការងារ នាងបានពន្យល់ថា៖ "ចំណុចដាក់ពណ៌ផ្ទៃខាងក្រោយនេះស្អាតណាស់! ប៉ុន្តែត្រង់ Margin ខាងស្តាំនេះខ្វះ 5px ធៀបនឹង Brand Standard។ ប្អូនជួយកែសម្រួលដើម្បីឱ្យមានតុល្យភាពភ្នែក"។ Junior មិនត្រឹមតែមិនអន់ចិត្តទេ ថែមទាំងរៀនបានច្រើនពីនាង និងខិតខំកែលម្អការងារទ្វេដង។»', '✅ របៀបផ្តល់ Review Feedback ប្រកបដោយវិជ្ជាជីវៈ (The Praise-Explain-Suggest Model)៖\n១. [កោតសរសើរ]៖ "Code/ការងារត្រង់ផ្នែកនេះរៀបចំបានស្អាត និងមានរបៀបណាស់!"\n២. [ពន្យល់ពីហានិភ័យ]៖ "ប៉ុន្តែត្រង់ចំណុច X នេះ បើសិនជាមានទិន្នន័យច្រើន វានឹងស៊ី Memory ខ្ពស់..."\n៣. [ផ្តល់អនុសាសន៍]៖ "តើប្អូនគិតយ៉ាងណាដែរបើយើងប្តូរមកប្រើវិធីសាស្ត្រ Y វិញ? នេះជា Link ឯកសារយោង..."', 'បង្កើត Quality Checklist ខ្លីមួយ (ប្រហែល ៥ ទៅ ៧ ចំណុច) សម្រាប់ត្រួតពិនិត្យគុណភាពការងារមុននឹងបញ្ជូនទៅកាន់អតិថិជន ឬថ្នាក់លើ។', 'តើការ Review របស់អ្នកកន្លងមកបានជួយឱ្យសហការីរីកចម្រើន ឬធ្វើឱ្យពួកគេមានអារម្មណ៍ភ័យខ្លាច?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ពិនិត្យការងារសហការីម្នាក់ដោយប្រើរូបមន្ត Praise-Explain-Suggest និងពន្យល់ពីមូលហេតុនៃការកែប្រែឱ្យបានច្បាស់លាស់។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-senior-8', 'lesson-senior-8', 'តើគោលដៅចម្បងនៃការពិនិត្យការងារ (Peer Review / Code Review) ដោយ Senior គឺជាអ្វី?', 'What is the primary goal of peer review conducted by a Senior specialist?', '["A. បង្ហាញថាខ្លួនឯងពូកែជាង និងបំបាក់មុខសមាជិកដទៃ។","B. ធានាស្តង់ដារគុណភាព ការពារកំហុសមិនឱ្យធ្លាយទៅក្រៅ និងជាឱកាសផ្ទេរចំណេះដឹងដល់ក្រុម។","C. ពន្យារពេលការងារឱ្យយឺតយ៉ាវដើម្បីកុំឱ្យអតិថិជនទារការងារថ្មី។"]', '["A. Show off superiority and demoralize peers.","B. Uphold quality standards, catch edge-case bugs early, and mentor team members through feedback.","C. Artificially delay projects."]', 1, 'ការពន្យល់៖ Review គឺជាឧបករណ៍នៃការធានាគុណភាព (Quality Assurance) និងការបង្វឹកបង្រៀន (Mentorship) មិនមែនជាការចាប់កំហុសឡើយ។', 'Explanation: Code and work reviews safeguard production quality while elevating peer capabilities.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-senior-9', 'course-senior-mentorship', 'mod-1', 9, '៩. ការរៀបចំផែនទីបង្ហាញផ្លូវ និងការប៉ាន់ប្រមាណធនធាន (Roadmapping & Capacity Planning)', 'Technical Roadmapping & Resource Capacity Planning for Specialists', 'text', '• ចេះរៀបចំផែនទីបង្ហាញផ្លូវបច្ចេកទេស (Technical Roadmap) រយៈពេល ៦ ដល់ ១២ ខែ។\n• ប៉ាន់ប្រមាណពេលវេលា និងកម្លាំងពលកម្ម (Effort & Capacity Estimation) ឱ្យបានត្រឹមត្រូវជៀសវាងការសន្យាហួសការពិត។\n• តម្រឹមផែនការបច្ចេកទេសឱ្យស្របគ្នាជាមួយគោលដៅលូតលាស់នៃអាជីវកម្ម (Business Growth Alignment)។', 'កំហុសធំបំផុតរបស់អ្នកជំនាញគឺ ការសន្យា Deadline តាមអារម្មណ៍ ឬការយល់ព្រមគ្រប់រឿងដោយមិនបានគណនាកម្លាំងជាក់ស្តែង (Over-promising, under-delivering)។ Senior ដែលមានវិជ្ជាជីវៈខ្ពស់ចេះប្រើប្រាស់ទិន្នន័យអតីតកាលដើម្បីប៉ាន់ប្រមាណទំហំការងារ (Velocity & Capacity) និងរៀបចំ Roadmap ដែលមានភាពបត់បែន និងអាចសម្រេចបានពិតប្រាកដ។', '«ក្នុងកិច្ចប្រជុំរៀបចំផែនការឆ្នាំថ្មី ថ្នាក់ដឹកនាំចង់ឱ្យនាយកដ្ឋាន IT បញ្ចប់គម្រោងធំៗចំនួន ៨ ក្នុងរយៈពេល ៦ ខែ។ លោក ចាន់រិទ្ធ ជា Senior Project Lead មិនបានបដិសេធដោយកំហឹងទេ ហើយក៏មិនយល់ព្រមទាំងងងឹតងងល់ដែរ។ \nគាត់បានបង្ហាញតារាង Capacity Planning ច្បាស់លាស់៖ ក្រុមការងារមានវិស្វករ ៥ នាក់ ស្មើនឹង ១៦០ ម៉ោង/សប្តាហ៍។ ដោយដកម៉ោងថែទាំប្រព័ន្ធចាស់ ក្រុមនៅសល់ម៉ោងផលិតកម្មដែលអាចបញ្ចប់គម្រោងបានតែ ៤ ប៉ុណ្ណោះ។ គាត់បានស្នើឱ្យថ្នាក់ដឹកនាំជ្រើសរើសគម្រោងអាទិភាពកំពូល ៤ មុន។ ថ្នាក់ដឹកនាំបានយល់ព្រមភ្លាមៗ ហើយគម្រោងទាំង ៤ ត្រូវបានបញ្ចប់ទាន់ពេល ១០០% ដោយគ្មានបុគ្គលិកណាម្នាក់បាក់កម្លាំងឡើយ។»', '✅ របៀបរៀបចំ Capacity Plan សង្ខេប៖\n១. [Gross Capacity]៖ ៥ នាក់ x ៤០ ម៉ោង = ២០០ ម៉ោង/សប្តាហ៍\n②. [Buffer & Operational Overhead]៖ ដក ២៥% សម្រាប់កិច្ចប្រជុំ សម្រាក និងដោះស្រាយបញ្ហាបន្ទាន់ = នៅសល់ ១៥០ ម៉ោងផលិតកម្មសុទ្ធ\n៣. [Project Allocation]៖ បែងចែកម៉ោងផលិតកម្មទៅគម្រោងអាទិភាពខ្ពស់បំផុត។', 'គណនាទំហំម៉ោងផលិតកម្មពិតប្រាកដរបស់ក្រុមអ្នកសម្រាប់សប្តាហ៍ក្រោយ ដោយដកម៉ោងប្រជុំ និងការងាររដ្ឋបាលចេញ។', 'តើអ្នកធ្លាប់សន្យាថានឹងបញ្ចប់ការងារ ប៉ុន្តែចុងក្រោយធ្វើមិនទាន់ដោយសារមិនបានគិតគូរពី Capacity ដែរឬទេ?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ពិនិត្យមើលបញ្ជីការងារសប្តាហ៍នេះ ហើយដាក់ Buffer ២០% សម្រាប់ទប់ទល់នឹងរឿងបន្ទាន់ដែលមិនបានគ្រោងទុក។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-senior-9', 'lesson-senior-9', 'នៅពេលថ្នាក់លើដាក់បន្ទុកការងារច្រើនលើសលប់ដែលមិនអាចធ្វើទាន់ តើ Senior Specialist គួរឆ្លើយតបបែបណា?', 'When executives demand an unrealistic volume of deliverables, how should a senior specialist respond?', '["A. យល់ព្រមទទួលយកទាំងអស់សិន រួចចាំដល់ថ្ងៃកំណត់ទើបប្រាប់ថាធ្វើមិនទាន់។","B. បង្ហាញទិន្នន័យកម្លាំងជាក់ស្តែង (Capacity Plan) ដោយសុជីវធម៌ និងស្នើឱ្យថ្នាក់លើជួយកំណត់អាទិភាពគម្រោង (Prioritization)។","C. ឈ្លោះប្រកែក និងស្រែកតវ៉ាក្នុងកិច្ចប្រជុំ។"]', '["A. Agree blindly to everything and announce failure only at deadline.","B. Transparently present real capacity metrics and facilitate executive prioritization tradeoffs.","C. Argue angrily in the boardroom."]', 1, 'ការពន្យល់៖ ភាពជាអ្នកជំនាញគឺការនិយាយដោយផ្អែកលើទិន្នន័យ និងតួលេខជាក់ស្តែង (Data-driven negotiation) ជួយឱ្យថ្នាក់លើមើលឃើញការពិត និងជ្រើសរើសអាទិភាពត្រឹមត្រូវ។', 'Explanation: Data-backed capacity planning enables mature trade-off conversations without emotional drama.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-senior-10', 'course-senior-mentorship', 'mod-1', 10, '១០. ការកសាងអ្នកបន្តវេនដើម្បីបើកផ្លូវឡើងតំណែង (Succession Planning & Scalability)', 'Succession Planning: Building Replacements to Unlock Your Own Promotion', 'text', '• យល់ដឹងពីច្បាប់មាសនៃការឡើងតំណែង៖ «ប្រសិនបើគ្មានអ្នកណាអាចជំនួសអ្នកបានទេ អ្នកក៏មិនអាចឡើងតំណែងបានដែរ»។\n• បង្កើតផែនការផ្ទេរតំណែង (Succession Plan) និងឯកសារ SOPs សំខាន់ៗ។\n• ត្រៀមលក្ខណៈផ្លូវចិត្ត និងជំនាញដើម្បីឈានជើងចេញពីតួនាទី Specialist ទៅជា Leader/Manager។', 'បុគ្គលិកជាច្រើនគិតខុសថា ការក្តោបការងារសំខាន់ៗតែម្នាក់ឯងដោយមិនឱ្យអ្នកណាដឹង គឺជាការការពារតំណែងរបស់ខ្លួន (Job Security)។ ការពិតជាក់ស្តែង ថ្នាក់ដឹកនាំក្រុមហ៊ុនមិនអាចតម្លើងតំណែងអ្នកឱ្យទៅដឹកនាំផ្នែក ឬនាយកដ្ឋានបានឡើយ ប្រសិនបើគ្មានអ្នកណាអាចធ្វើការងារចាស់របស់អ្នកបាននោះ។ ដើម្បីឡើងតំណែង អ្នកត្រូវតែបណ្តុះបណ្តាលអ្នកបន្តវេនឱ្យរួចរាល់ជាមុនសិន។', '«លោក សុភា ជា Senior Marketing Specialist ដ៏ពូកែម្នាក់។ នៅពេលតំណែង Marketing Manager ទំនេរ អគ្គនាយកបានពិចារណាលើរូបគាត់ ប៉ុន្តែមានការស្ទាក់ស្ទើរ ព្រោះប្រសិនបើសុភាឡើងតំណែង គ្មានអ្នកណាចេះរៀបចំយុទ្ធនាការផ្សាយពាណិជ្ជកម្ម Digital ជំនួសគាត់ឡើយ។ \nសំណាងល្អ សុភាបានគិតគូររឿងនេះ ៦ ខែមុនរួចស្រេចទៅហើយ។ គាត់បានបង្ហាញឯកសារ SOP ពេញលេញ និងបានបណ្តុះបណ្តាល Junior ម្នាក់ឈ្មោះ ដារ៉ា ឱ្យចេះគ្រប់គ្រង Ads ទាំងអស់ជំនួសគាត់បាន ៩៥%។ សុភាបានប្រាប់អគ្គនាយកថា៖ "ដារ៉ាត្រៀមខ្លួនរួចរាល់ហើយក្នុងការទទួលការងារចាស់របស់ខ្ញុំ"។ អគ្គនាយកសប្បាយចិត្តយ៉ាងខ្លាំង ហើយបានចុះហត្ថលេខាតម្លើងតំណែងសុភាជា Manager ភ្លាមៗនៅថ្ងៃនោះ។»', '✅ ជំហាន ៣ នៃការរៀបចំអ្នកបន្តវេន (Succession Blueprint)៖\n១. [Document Knowledge]៖ សរសេរឯកសារដំណើរការការងារ (SOP) សម្រាប់គ្រប់ការងារប្រចាំថ្ងៃរបស់អ្នក។\n②. [Shadowing & Delegation]៖ ឱ្យសមាជិកដែលមានសក្តានុពលខ្ពស់មកអង្កេត និងសាកល្បងទទួលខុសត្រូវកិច្ចការធំៗ ៣០%។\n៣. [Empowerment]៖ ផ្តល់សិទ្ធិអំណាចឱ្យពួកគេសម្រេចចិត្ត និងធ្វើជាខ្នងបង្អែកផ្តល់យោបល់នៅពីក្រោយ។', 'កំណត់ឈ្មោះសមាជិកក្រុមម្នាក់ដែលអាចក្លាយជាអ្នកបន្តវេនរបស់អ្នក ហើយរៀបចំបញ្ជីជំនាញចំនួន ៣ ដែលអ្នកត្រូវផ្ទេរឱ្យគេក្នុងរយៈពេល ៩០ ថ្ងៃ។', 'តើមានការងារណាខ្លះដែលប្រសិនបើអ្នកឈប់សម្រាកមួយសប្តាហ៍ ក្រុមទាំងមូលនឹងត្រូវគាំង? តើអ្នកអាចបណ្តុះបណ្តាលអ្នកដទៃឱ្យចេះធ្វើវាដោយរបៀបណា?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ចាប់ផ្តើមកត់ត្រា SOP នៃកិច្ចការស្មុគស្មាញបំផុតរបស់អ្នកទុកក្នុង Shared Drive សម្រាប់អ្នកបន្តវេន។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-senior-10', 'lesson-senior-10', 'ហេតុអ្វីបានជាបុគ្គលិកដែលក្តោបការងារទាំងអស់តែម្នាក់ឯង ពិបាកនឹងទទួលបានការតម្លើងតំណែងជាថ្នាក់ដឹកនាំ?', 'Why do specialists who hoard all critical knowledge struggle to get promoted to leadership?', '["A. ព្រោះថ្នាក់លើមិនចូលចិត្តមនុស្សដែលធ្វើការងារច្រើន។","B. ព្រោះស្ថាប័នមិនអាចផ្លាស់ប្តូរគាត់បានឡើយ ប្រសិនបើគ្មានអ្នកណាអាចជំនួសការងារប្រតិបត្តិការបច្ចុប្បន្នរបស់គាត់។","C. ព្រោះគាត់គ្មានសញ្ញាបត្របរទេស។"]', '["A. Because bosses dislike hard-working people.","B. Because the organization cannot afford to move them if their current daily operations would collapse without a successor.","C. Because they lack foreign degrees."]', 1, 'ការពន្យល់៖ ប្រសិនបើអ្នកមិនអាចជំនួសបាន អ្នកក៏មិនអាចឡើងតំណែងបានដែរ (If you cannot be replaced, you cannot be promoted)។ ការកសាងអ្នកបន្តវេនគឺជាកាតព្វកិច្ចចម្បង។', 'Explanation: Unlocking promotion requires rendering yourself dispensable in your current operational role through succession.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-sup-1', 'course-supervisor-ops', 'mod-1', 1, '១. ការគ្រប់គ្រង និងត្រួតពិនិត្យស្តង់ដារគុណភាព QA/QC (Operational Quality Control)', 'Operational Supervision & QA/QC Quality Control', 'text', '• បង្កើតបញ្ជីត្រួតពិនិត្យគុណភាព (Quality Checklist) សម្រាប់ប្រតិបត្តិការប្រចាំថ្ងៃ។\n• កាត់បន្ថយអត្រាកំហុស និងការខាតបង់ផលិតផល/សេវាកម្ម (Defect Reduction)។\n• ត្រួតពិនិត្យការអនុវត្តតាម SOP ដោយម៉ត់ចត់ និងយុត្តិធម៌។', 'Supervisor គឺជាអ្នកចាំយាមទ្វារនៃគុណភាពស្ថាប័ន (Guardian of Quality)។ បើ Supervisor ធ្វេសប្រហែស កំហុសនឹងធ្លាយដល់ដៃអតិថិជន ដែលធ្វើឱ្យខូចកេរ្តិ៍ឈ្មោះក្រុមហ៊ុន។', '«មុនីនាថ ជា Supervisor ផ្នែកបម្រើអតិថិជននៅសណ្ឋាគារមួយ។ នាងបានបង្កើតទម្លាប់ដើរត្រួតពិនិត្យបន្ទប់តាមបញ្ជី Check-in មុនពេលភ្ញៀវចូលស្នាក់នៅ ១ ម៉ោងជារៀងរាល់ថ្ងៃ។ នៅពេលបុគ្គលិករៀបចំខ្វះកន្សែង ឬភ្លេចដាក់ទឹក នាងចង្អុលបង្ហាញភ្លាមៗដោយចិត្តល្អ តែម៉ត់ចត់។ សណ្ឋាគាររបស់នាងទទួលបានពិន្ទុ Review ៩.៨/១០ នៅលើ Booking.com ហើយនាងទទួលបានពានរង្វាន់អ្នកគ្រប់គ្រងឆ្នើមប្រចាំឆ្នាំ។»', '✅ របៀបត្រួតពិនិត្យគុណភាពដោយមិនធ្វើឱ្យបុគ្គលិកមានអារម្មណ៍តានតឹង៖\n«ការត្រួតពិនិត្យនេះមិនមែនដើម្បីចាប់កំហុសដាក់ពិន័យបងប្អូននោះទេ ប៉ុន្តែដើម្បីធានាថាភ្ញៀវទទួលបានបទពិសោធន៍ល្អឥតខ្ចោះបំផុត ដែលនឹងជួយការពារកេរ្តិ៍ឈ្មោះ និងការងាររបស់ពួកយើងទាំងអស់គ្នា។»', 'បង្កើត Quality Checklist ៥ ចំណុចសម្រាប់សេវាកម្ម ឬផលិតផលដែលផ្នែករបស់អ្នកផលិត។', 'តើផ្នែករបស់អ្នកមានបញ្ជីត្រួតពិនិត្យគុណភាពជាលាយលក្ខណ៍អក្សរច្បាស់លាស់ហើយឬនៅ?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ធ្វើការត្រួតពិនិត្យផ្ទាល់ដៃលើកិច្ចការមួយមុនពេលប្រគល់ជូនអតិថិជន ឬថ្នាក់លើ។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-sup-1', 'lesson-sup-1', 'តើវិធីសាស្ត្រត្រួតពិនិត្យគុណភាព (QA/QC) ណាដែលល្អបំផុតសម្រាប់ Supervisor?', 'What is the best quality control method for an operational supervisor?', '["A. អង្គុយក្នុងបន្ទប់ម៉ាស៊ីនត្រជាក់ ហើយចាំភ្ញៀវត្អូញត្អែរទើបចេញទៅស្តីបន្ទោសកូនចៅ។","B. ដើរត្រួតពិនិត្យផ្ទាល់ជាក់ស្តែង (Gemba Walk) តាម Checklist ច្បាស់លាស់ និងកែតម្រូវទាន់ពេលវេលា។","C. ជឿជាក់ ១០០% លើការស្មានដោយមិនបាច់ត្រួតពិនិត្យឡើយ។"]', '["A. Sit in AC room and only yell at staff after customers complain.","B. Conduct on-site inspections (Gemba Walk) with clear checklists and coach real-time corrections.","C. Rely 100% on guesswork without verification."]', 1, 'ការពន្យល់៖ ជម្រើស B ជាការអនុវត្តបែប Gemba Walk ដែលជួយទប់ស្កាត់កំហុសមុនពេលធ្លាយដល់ដៃអតិថិជន។', 'Explanation: On-site verification with objective checklists prevents errors before customer delivery.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-sup-2', 'course-supervisor-ops', 'mod-1', 2, '២. ការគ្រប់គ្រងផលិតភាពប្រចាំថ្ងៃ និងការរៀបចំកាលវិភាគការងារ (Daily Capacity & Shift Planning)', 'Capacity Management & Shift Scheduling', 'text', '• រៀបចំកាលវិភាគវេនការងារ (Shift Roster) ឱ្យមានតុល្យភាព និងយុត្តិធម៌។\n• តាមដានទិន្នផលការងារប្រចាំថ្ងៃ និងដោះស្រាយកង្វះកម្លាំងពលកម្មទាន់ពេល។\n• កាត់បន្ថយការចំណាយលើការថែមម៉ោង (Overtime) ដែលមិនចាំបាច់។', 'ការរៀបចំកាលវិភាគការងារល្អ ជួយឱ្យក្រុមហ៊ុនសន្សំសំចៃថ្លៃដើម និងជួយឱ្យបុគ្គលិកមានតុល្យភាពជីវិត និងការងារ ដែលកាត់បន្ថយអត្រាលាលែងពីការងារ។', '«នៅរោងចក្រវេចខ្ចប់មួយ ជារៀងរាល់ចុងខែ បុគ្គលិកតែងតែត្អូញត្អែររឿងធ្វើការថែមម៉ោងហួសកម្លាំង ខណៈដែលដើមខែគ្មានការងារធ្វើ។ សម្បត្តិ (Supervisor ថ្មី) បានសិក្សាពីលំហូរការងារ និងរៀបចំប្រព័ន្ធរង្វិលជុំវេនការងារថ្មី (Staggered Shifts)។ លទ្ធផល៖ ការងារត្រូវបានចែកចាយស្មើដៃ ផលិតភាពកើនឡើង ១៥% និងកាត់បន្ថយការចំណាយ Overtime អស់ $3,000 ក្នុងមួយខែ។»', '✅ របៀបដោះស្រាយសំណើសុំច្បាប់ឈប់សម្រាកប្រជែងគ្នា៖\n«ដើម្បីរក្សាយុត្តិធម៌ យើងអនុវត្តតាមគោលការណ៍ First-come, First-served ប៉ុន្តែធានាថាក្នុងថ្ងៃបុណ្យធំៗ បុគ្គលិកគ្រប់គ្នានឹងបានឆ្លាស់វេនគ្នាទៅជួបជុំគ្រួសារស្មើៗគ្នា។»', 'គូរតារាងបែងចែកបន្ទុកការងារសប្តាហ៍ក្រោយសម្រាប់សមាជិកក្នុងក្រុមរបស់អ្នក។', 'តើការបែងចែកវេនការងារក្នុងក្រុមរបស់អ្នកមានភាពយុត្តិធម៌ និងតម្លាភាពគ្រប់គ្រាន់ហើយឬនៅ?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ពិនិត្យមើលកាលវិភាគការងារសប្តាហ៍នេះ ដើម្បីធានាថាមិនមានសមាជិកណាម្នាក់កំពុងផ្ទុកការងារលើសកម្លាំង។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-sup-2', 'lesson-sup-2', 'តើគោលដៅចម្បងនៃការរៀបចំកាលវិភាគការងារ (Work Schedule) គឺជាអ្វី?', 'What is the primary goal of work scheduling and shift planning?', '["A. ដាក់បន្ទុកការងារធ្ងន់លើមនុស្សស្លូតៗ ហើយបន្ធូរបន្ថយឱ្យមនុស្សដែលជិតស្និទ្ធនឹងខ្លួន។","B. ធានាតុល្យភាពរវាងផលិតភាពអាជីវកម្ម ភាពយុត្តិធម៌ និងសុខុមាលភាពរបស់បុគ្គលិក។","C. បង្ខំឱ្យបុគ្គលិកធ្វើការថែមម៉ោងរាល់យប់។"]', '["A. Overload quiet workers and favor friends.","B. Balance business productivity, operational fairness, and employee well-being.","C. Force daily overtime."]', 1, 'ការពន្យល់៖ ជម្រើស B ធានាទាំងប្រសិទ្ធភាពធុរកិច្ច និងការរក្សាមនុស្សយូរអង្វែង។', 'Explanation: Fair scheduling balances company output with team sustainability.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-supervisor-3', 'course-supervisor-ops', 'mod-1', 3, '៣. ការចុះពិនិត្យទីតាំងជាក់ស្តែង «ក្បួនដើរពិនិត្យ Gemba Walk» (Toyota Frontline Inspection)', 'Gemba Walk: Frontline Operational Observation & Waste Elimination', 'text', '• យល់ដឹងពីទស្សនវិជ្ជាផលិតកម្មបែបជប៉ុន និងចិន «Gemba Walk / 走动管理» (ការចុះទៅកន្លែងកើតហេតុជាក់ស្តែង)។\n• ជៀសវាងការអង្គុយបញ្ជាការងារតែក្នុងបន្ទប់ម៉ាស៊ីនត្រជាក់ដោយមិនដឹងពីការលំបាករបស់បុគ្គលិកជួរមុខ។\n• សង្កេតរកចំណុចកកស្ទះ គ្រោះថ្នាក់ការងារ និងការខ្ជះខ្ជាយពេលវេលាដោយផ្ទាល់ភ្នែក។', 'ពាក្យថា «Gemba» (现场 - ស៊ានឆាង) នៅក្នុងទស្សនវិជ្ជាគ្រប់គ្រងបែបតូយ៉ូតាមានន័យថា «ទីកន្លែងដែលបង្កើតតម្លៃពិតប្រាកដ» ដូចជា រោងចក្រ ឃ្លាំងទំនិញ ឬកន្លែងទទួលភ្ញៀវ។ អ្នកត្រួតពិនិត្យ (Supervisor) ដែលអង្គុយមើលតែរបាយការណ៍លើក្រដាស នឹងត្រូវបានគេបោកប្រាស់ដោយតួលេខ។ Supervisor ពូកែត្រូវតែចុះដើរពិនិត្យទីតាំងជាក់ស្តែងជារៀងរាល់ថ្ងៃ ដើម្បីមើល ស្វែងយល់ និងជួយសម្រួលឧបសគ្គដល់បុគ្គលិកជួរមុខ។', '«លោក សុខុម ជា Supervisor គ្រប់គ្រងភោជនីយដ្ឋានធំមួយនៅសៀមរាប។ ក្នុងរបាយការណ៍ ប្រព័ន្ធកត់ត្រាថាការបញ្ជាម្ហូបដំណើរការល្អ ប៉ុន្តែភ្ញៀវតែងតែរអ៊ូរទាំថាម្ហូបចេញយឺត។ \nជំនួសឱ្យការស្តីបន្ទោសមេចុងភៅតាមទូរស័ព្ទ សុខុមបានចុះទៅឈរនៅក្នុងផ្ទះបាយរយៈពេល ២ ម៉ោងក្នុងម៉ោងរវល់បំផុត (Gemba Walk)។ គាត់បានសង្កេតឃើញថា ចុងភៅត្រូវដើរទៅមកចម្ងាយ ១៥ ម៉ែត្ររាល់ពេលចង់យកគ្រឿងទេស ព្រោះទូគ្រឿងទេសដាក់នៅឆ្ងាយពីចង្ក្រាន។ សុខុមបានរៀបចំរើទូគ្រឿងទេសមកដាក់ក្បែរដៃចង្ក្រានភ្លាមៗ។ ជាលទ្ធផល ពេលវេលាចម្អិនម្ហូបត្រូវបានកាត់បន្ថយ ៨ នាទីក្នុងមួយមុខ ហើយការត្អូញត្អែររបស់ភ្ញៀវបានធ្លាក់ចុះដល់សូន្យ។»', '✅ វិធានមាស ៣ យ៉ាងក្នុងការចុះ Gemba Walk៖\n១. [Go and See]៖ ចុះទៅកន្លែងធ្វើការជាក់ស្តែងដោយផ្ទាល់ កុំចាំតែស្តាប់របាយការណ៍បន្តកន្ទុយ។\n២. [Ask Why, with Respect]៖ សួរដោយការគោរព និងស្វែងយល់ពីមូលហេតុ មិនមែនចុះទៅដើម្បីចាប់កំហុស ឬបំភ័យបុគ្គលិកឡើយ។\n៣. [Show Empathy & Assist]៖ ជួយកែសម្រួលឧបករណ៍ និងដំណើរការការងារភ្លាមៗដើម្បីសម្រាលបន្ទុកបុគ្គលិក។', 'អនុវត្តការដើរចុះពិនិត្យទីតាំងការងារជួរមុខ (Gemba Walk) រយៈពេល ៣០ នាទីនៅថ្ងៃនេះ និងកត់ត្រាចំណុចរអាក់រអួលចំនួន ២ ដែលអ្នកបានឃើញដោយផ្ទាល់ភ្នែក។', 'តើអ្នកចំណាយពេលប៉ុន្មានភាគរយក្នុងមួយថ្ងៃនៅតុធ្វើការ ហើយប៉ុន្មានភាគរយចុះទៅមើលការងារជាក់ស្តែងនៅជួរមុខ?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ក្រោកពីកៅអីការិយាល័យ ហើយចុះទៅដើរពិនិត្យកន្លែងធ្វើការជួរមុខរយៈពេល ៣០ នាទីដោយយកចិត្តទុកដាក់។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-supervisor-3', 'lesson-supervisor-3', 'តើអ្វីជាគោលបំណងចម្បងនៃការចុះពិនិត្យការងារតាមក្បួន Gemba Walk របស់អ្នកត្រួតពិនិត្យ (Supervisor)?', 'What is the primary objective of a Supervisor conducting a Gemba Walk?', '["A. ចុះទៅចាប់កំហុសបុគ្គលិកដើម្បីកាត់ប្រាក់រង្វាន់។","B. ចុះទៅសង្កេតដំណើរការការងារជាក់ស្តែង យល់ពីការលំបាករបស់បុគ្គលិក និងស្វែងរកចំណុចកែលម្អប្រព័ន្ធ។","C. ចុះទៅថតរូបដើម្បីបង្ហាញថ្នាក់លើថាខ្លួនឯងធ្វើការងារច្រើន។"]', '["A. Catch employees making mistakes to cut their bonuses.","B. Directly observe the actual workflow, empathize with frontline friction, and eliminate systemic bottlenecks.","C. Take photos to display personal activity to executives."]', 1, 'ការពន្យល់៖ Gemba Walk គឺជាការចុះទៅស្វែងយល់ការពិតនៅជួរមុខ ដើម្បីកែលម្អប្រព័ន្ធការងារ និងជួយសម្រាលបន្ទុកបុគ្គលិក មិនមែនជាការចាប់កំហុសឡើយ។', 'Explanation: Gemba walks focus on observing reality, uncovering waste, and supporting frontline staff.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-supervisor-4', 'course-supervisor-ops', 'mod-1', 4, '៤. ការរចនានីតិវិធីការពារកំហុសស្វ័យប្រវត្តិ (Poka-Yoke & Mistake-Proofing)', 'SOP Design & Poka-Yoke: Mistake-Proofing Operational Workflows', 'text', '• យល់ដឹងពីគោលការណ៍ Poka-Yoke (防呆 - ហ្វាងតាយ៖ ប្រព័ន្ធរចនាដែលមិនអាចឱ្យមនុស្សធ្វើខុសបាន)។\n• បង្កើតនីតិវិធីប្រតិបត្តិការស្តង់ដារ (SOP) ដែលមានរូបភាព និងងាយយល់បំផុត។\n• កាត់បន្ថយការខាតបង់ដែលបណ្តាលមកពីការធ្វេសប្រហែសរបស់មនុស្ស (Human Error)។', 'អ្នកត្រួតពិនិត្យទន់ខ្សោយតែងតែនិយាយថា៖ «ខ្ញុំបានប្រាប់គេហើយ តែគេនៅតែធ្វើខុស!»។ រីឯ Supervisor កម្រិតអន្តរជាតិយល់ថា៖ ប្រសិនបើប្រព័ន្ធអនុញ្ញាតឱ្យបុគ្គលិកធ្វើខុសបាន នោះប្រព័ន្ធគឺជាអ្នកខុស។ គោលការណ៍ «Poka-Yoke» (Mistake-Proofing) គឺជាការរចនាឧបករណ៍ ឬដំណើរការការងារដែល «មិនអាចធ្វើខុសបានជាដាច់ខាត» (ដូចជា រន្ធដោតស៊ីមកាតទូរស័ព្ទដែលរចនាឱ្យកាត់ជ្រុងមួយ ដែលធ្វើឱ្យយើងមិនអាចដោតបញ្ច្រាសទិសបាន)។', '«នៅរោងចក្រដំឡើងគ្រឿងអេឡិចត្រូនិកមួយ កម្មករតែងតែភ្លេចដាក់វីសមួយគ្រាប់ចូលក្នុងប្រអប់ទំនិញ ធ្វើឱ្យអតិថិជននៅអឺរ៉ុបប្តឹងទារសំណងរាប់ពាន់ដុល្លារ។ \nលោកស្រី គឹមសួរ ជា Quality Supervisor មិនបានដាក់ពិន័យកម្មករទេ។ នាងបានបង្កើតប្រព័ន្ធ Poka-Yoke ដ៏សាមញ្ញមួយ៖ នាងរៀបចំថាសតូចមួយដែលមានរន្ធចំនួន ៤ សម្រាប់ដាក់វីស ៤ គ្រាប់។ កម្មករត្រូវយកវីសពីថាសនោះមកខ្ទាស់។ ប្រសិនបើនៅសល់វីស ១ គ្រាប់ក្នុងថាស ម៉ាស៊ីនបិទកេសស្វ័យប្រវត្តិនឹងមិនព្រមដំណើរការឡើយ។ តាមរយៈប្រព័ន្ធនេះ កំហុសភ្លេចវីសបានធ្លាក់ចុះមកត្រឹម ០% ជារៀងរហូត។»', '✅ របៀបបង្កើតប្រព័ន្ធ Mistake-Proofing (Poka-Yoke) ក្នុងការិយាល័យ៖\n• ក្នុង Google Form ឬ Excel៖ កំណត់ Data Validation ដើម្បីកុំឱ្យបុគ្គលិកអាចវាយបញ្ចូលលេខទូរស័ព្ទខ្វះលេខ ឬច្រឡំអក្សរ។\n• ក្នុងអ៊ីមែល៖ ប្រើប្រព័ន្ធព្រមានស្វ័យប្រវត្តិនៅពេលសរសេរពាក្យ "Attach" ប៉ុន្តែភ្លេចភ្ជាប់ File។\n• ក្នុងឃ្លាំងទំនិញ៖ ប្រើកូដពណ៌ (Color Coding) សម្រាប់បែងចែកប្រភេទឥវ៉ាន់ឱ្យដាច់ពីគ្នា។', 'ស្វែងរកកំហុសឆ្គងមួយដែលបុគ្គលិករបស់អ្នកតែងតែភ្លេចភ្លាំង ហើយរចនាគំរូ Poka-Yoke មួយដើម្បីការពារកុំឱ្យកំហុសនោះកើតឡើងបានទៀត។', 'តើមានការងារណាខ្លះក្នុងផ្នែករបស់អ្នកដែលកំពុងពឹងផ្អែកលើ «ការចងចាំរបស់មនុស្ស» ហើយងាយនឹងភ្លេចភ្លាំង? តើអ្នកអាចបង្កើត Poka-Yoke ជួយពួកគេដោយរបៀបណា?', '🎯 សកម្មភាពថ្ងៃនេះ៖ កែសម្រួលទម្រង់បែបបទ ឬឯកសារការងារមួយដោយដាក់ Data Validation ឬ Checklist ច្បាស់លាស់។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-supervisor-4', 'lesson-supervisor-4', 'តើទស្សនវិជ្ជា Poka-Yoke (Mistake-Proofing) មានគោលបំណងចម្បងអ្វីក្នុងការគ្រប់គ្រងគុណភាព?', 'What is the primary philosophy of Poka-Yoke in operations and quality control?', '["A. រចនាប្រព័ន្ធការងារឱ្យមានភាពស្មុគស្មាញដើម្បីសាកល្បងភាពឆ្លាតវៃរបស់បុគ្គលិក។","B. រចនាដំណើរការការងារ ឬឧបករណ៍ដែលការពារកុំឱ្យកំហុសរបស់មនុស្សអាចកើតមានឡើងបាន (Fool-proof by design)។","C. ដកហូតឧបករណ៍ការងារពីបុគ្គលិកដែលធ្លាប់ធ្វើខុស។"]', '["A. Make systems overly complex to test worker IQ.","B. Engineer physical or procedural constraints so mistakes become physically or logically impossible.","C. Confiscate tools from workers who make mistakes."]', 1, 'ការពន្យល់៖ Poka-Yoke ផ្តោតលើការរចនាប្រព័ន្ធការពារកំហុសជាមុន (Design out error) ជាជាងការរង់ចាំស្តីបន្ទោសមនុស្សក្រោយពេលខូចខាត។', 'Explanation: Poka-Yoke designs mechanisms that prevent errors from occurring by physical or logical constraints.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-supervisor-5', 'course-supervisor-ops', 'mod-1', 5, '៥. ការគ្រប់គ្រងរបៀបរៀបរយតាមក្បួន 5S (5S Lean Workplace Organization)', '5S Methodology: Sort, Set in Order, Shine, Standardize, Sustain', 'text', '• យល់ដឹងពីជំហានទាំង ៥ នៃ 5S (រើសចោល រៀបចំ បោសសម្អាត ស្តង់ដារ និរន្តរភាព)។\n• អនុវត្ត 5S ទាំងលើកន្លែងធ្វើការជាក់ស្តែង និងលើទិន្នន័យឌីជីថល (Digital 5S)។\n• កាត់បន្ថយពេលវេលាស្វែងរកឯកសារ និងបង្កើនសុវត្ថិភាពការងារដល់បុគ្គលិក។', '5S មិនមែនគ្រាន់តែជាការសម្អាតអនាម័យធម្មតានោះទេ ប៉ុន្តែជាមូលដ្ឋានគ្រឹះនៃវិន័យប្រតិបត្តិការ (Operational Discipline)។ ការសិក្សាបង្ហាញថា បុគ្គលិកការិយាល័យជាមធ្យមចំណាយពេលរហូតដល់ ២.៥ ម៉ោងក្នុងមួយសប្តាហ៍គ្រាន់តែដើម្បី «ស្វែងរកឯកសារ ឬឧបករណ៍ដែលបាត់»។ ការអនុវត្ត 5S បង្កើតបរិយាកាសការងារដែលមានប្រសិទ្ធភាពខ្ពស់ និងបង្កើនទំនុកចិត្តដល់អតិថិជនដែលមកទស្សនកិច្ច។', '«នៅឃ្លាំងស្តុកគ្រឿងបន្លាស់រថយន្តមួយ ជាងជួសជុលតែងតែចំណាយពេល ១៥ ទៅ ២០ នាទីរាល់ពេលត្រូវការស្វែងរកប្រដាប់រឹតប៊ូឡុង ធ្វើឱ្យការជួសជុលឡានយឺតយ៉ាវជាប្រចាំ។ \nលោក វណ្ណា ជា Supervisor ថ្មី បានដឹកនាំធ្វើ 5S៖ \n១. Sort (សេរី)៖ បោះចោលដែក និងឧបករណ៍ដែលខូចប្រើលែងកើតចេញ។\n②. Set in Order (សេតុន)៖ គូសបន្ទាត់លើជញ្ជាំង និងព្យួរឧបករណ៍តាមទំហំ ដោយមានស្លាកឈ្មោះច្បាស់លាស់ (Shadow Board)។\n៣. Shine (សេសូ)៖ សម្អាតប្រេង និងធូលីចេញឱ្យភ្លឺរលោង។\n៤. Standardize (សេកេតស៊ុ)៖ បង្កើតច្បាប់ "យកពីណា ទុកនៅកន្លែងនោះវិញភ្លាម"។\n៥. Sustain (ស៊ីតស៊ូកេ)៖ ត្រួតពិនិត្យវិន័យរៀងរាល់ល្ងាច។ \nលទ្ធផល៖ ពេលវេលាស្វែងរកឧបករណ៍បានធ្លាក់ចុះមកត្រឹម ៥ វិនាទី ហើយទិន្នផលជួសជុលរថយន្តបានកើនឡើង ៣៥% ក្នុងខែដំបូង។»', '✅ របៀបអនុវត្ត Digital 5S លើកុំព្យូទ័រ និង Google Drive៖\n• Sort៖ លុប File ចាស់ៗ ឬ Duplicate files ចេញពី Desktop។\n• Set in Order៖ បង្កើតរចនាសម្ព័ន្ធ Folder ច្បាស់លាស់៖ [ឆ្នាំ] > [ឈ្មោះនាយកដ្ឋាន] > [ឈ្មោះគម្រោង]។\n• Standardize៖ កំណត់ស្តង់ដារដាក់ឈ្មោះ File ដូចជា៖ YYYY-MM-DD_ProjectName_v1.0.pdf។', 'ជ្រើសរើសតំបន់មួយ (តុធ្វើការ ឃ្លាំង ឬ Shared Google Drive) ហើយអនុវត្តជំហាន 5S ឱ្យបានស្អាតបាតក្នុងរយៈពេល ៤៥ នាទី។', 'តើកន្លែងធ្វើការ ឬកុំព្យូទ័ររបស់អ្នកមានភាពរញ៉េរញ៉ៃដែលធ្វើឱ្យអ្នកខាតពេលស្វែងរកឯកសារដែរឬទេ? តើអ្នកនឹងរៀបចំវាឡើងវិញនៅពេលណា?', '🎯 សកម្មភាពថ្ងៃនេះ៖ សម្អាត Desktop កុំព្យូទ័ររបស់អ្នកឱ្យនៅសល់តែ Icon ចាំបាច់ និងលុបឯកសារដែលលែងប្រើចោល។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-supervisor-5', 'lesson-supervisor-5', 'តើជំហានណាដែលពិបាកបំផុត ប៉ុន្តែសំខាន់បំផុតនៅក្នុងដំណើរការ 5S?', 'Which phase of 5S is typically the most difficult yet crucial for long-term success?', '["A. ជំហានទី ១ (Sort - បោះចោលរបស់ចាស់)។","B. ជំហានទី ៥ (Sustain - ការរក្សាទម្លាប់ និងវិន័យឱ្យមាននិរន្តរភាពយូរអង្វែង)។","C. ជំហានទី ៣ (Shine - ជូតសម្អាតធូលី)។"]', '["A. Phase 1 (Sort - discarding old materials).","B. Phase 5 (Sustain - embedding discipline so habits never backslide).","C. Phase 3 (Shine - wiping dust)."]', 1, 'ការពន្យល់៖ ជំហានទី ៥ (Sustain/Shitsuke) គឺជាការកសាងវិន័យ និងវប្បធម៌។ ការសម្អាតម្តងមិនពិបាកទេ តែការរក្សាវាឱ្យនៅស្អាតរាល់ថ្ងៃទើបជាការលំបាកពិតប្រាកដ។', 'Explanation: Sustaining operational discipline against backsliding is the hallmark of true lean culture.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-supervisor-6', 'course-supervisor-ops', 'mod-1', 6, '៦. កិច្ចប្រជុំត្រួតពិនិត្យពេលព្រឹក «ក្បួនប្រជុំឈរ ១៥ នាទី» (Daily Standup: 朝会)', 'Daily Standup & Rapid Bottleneck Clearance: The 15-Minute Morning Huddle', 'text', '• យល់ដឹងពីក្បួនរៀបចំការប្រជុំឈរពេលព្រឹក (Morning Standup / 朝会 - ឆាវហួយ) ក្នុងរយៈពេល ១៥ នាទី។\n• ផ្តោតតែលើសំណួរគន្លឹះ ៣ (ម្សិលមិញធ្វើអ្វី? ថ្ងៃនេះធ្វើអ្វី? ជួបឧបសគ្គអ្វី?)។\n• បង្កើតស្មារតីរួបរួម និងដោះស្រាយការកកស្ទះការងារភ្លាមៗតាំងពីដើមថ្ងៃ។', 'នៅក្រុមហ៊ុនផលិតកម្ម និងបច្ចេកវិទ្យាកំពូលៗរបស់ចិន ជប៉ុន និងលោកខាងលិច ការប្រជុំពេលព្រឹក (朝会) មិនមែនជាការអង្គុយស្តាប់មេនិយាយតែម្នាក់ឯងនោះទេ ប៉ុន្តែជាការប្រជុំ «ឈរ» រយៈពេលខ្លី ១០ ទៅ ១៥ នាទី។ ការឈរជួយកុំឱ្យមនុស្សនិយាយរឿងឥតប្រយោជន៍ និងធ្វើឱ្យគ្រប់គ្នាយល់ដឹងច្បាស់ពីទិសដៅការងាររួមប្រចាំថ្ងៃ។', '«លោកស្រី ពិសី ជា Supervisor ផ្នែកបម្រើសេវាអតិថិជនតាមទូរស័ព្ទ (Call Center)។ កាលពីមុន នាងតែងតែរៀបចំការប្រជុំអង្គុយ ១ ម៉ោងនៅរៀងរាល់ព្រឹកថ្ងៃចន្ទ ដែលធ្វើឱ្យបុគ្គលិកងងុយដេក និងធុញទ្រាន់។ \nក្រោយមក នាងបានប្តូរមកជា "កិច្ចប្រជុំឈរ ១០ នាទីរាល់ព្រឹក" នៅម៉ោង ៨:០០ ដល់ ៨:១០ នាទី។ សមាជិកម្នាក់ៗចំណាយពេលត្រឹមតែ ៤៥ វិនាទីឆ្លើយសំណួរ ៣៖ ១. ម្សិលមិញបិទបញ្ហាបានប៉ុន្មាន? ២. ថ្ងៃនេះត្រូវដោះស្រាយបញ្ហាធំមួយណា? ៣. តើត្រូវការឱ្យ Supervisor ឬផ្នែកដទៃជួយសម្រួលអ្វីខ្លះ? កិច្ចប្រជុំនេះបានជំរុញថាមពលការងារយ៉ាងខ្លាំង ហើយបញ្ហាស្មុគស្មាញត្រូវបានលើកមកដោះស្រាយភ្លាមៗនៅព្រឹកនោះ។»', '✅ ក្បួនដឹកនាំ Daily Standup ១៥ នាទី៖\n• ម៉ោង ០-២ នាទី៖ ស្វាគមន៍ ផ្តល់ព័ត៌មានបន្ទាន់ ឬសរសើរសមាជិកដែលមានស្នាដៃម្សិលមិញ។\n• ម៉ោង ៣-១២ នាទី៖ សមាជិកម្នាក់ៗរាយការណ៍តាមទម្រង់ ៣ សំណួរ (កុំនិយាយវែងអន្លាយ)។\n• ម៉ោង ១៣-១៥ នាទី៖ Supervisor សង្ខេបចំណុចត្រូវជួយដោះស្រាយ និង hô ស្មារតីចាប់ផ្តើមការងារ!', 'អនុវត្តការរៀបចំកិច្ចប្រជុំឈរពេលព្រឹក (Standup Meeting) រយៈពេល ១៥ នាទីជាមួយក្រុមការងាររបស់អ្នកនៅព្រឹកស្អែក។', 'តើកិច្ចប្រជុំនៅក្នុងក្រុមរបស់អ្នកកន្លងមកតែងតែអូសបន្លាយពេលយូរដោយគ្មានលទ្ធផលច្បាស់លាស់ដែរឬទេ? តើអ្នកអាចប្តូរមកជា Standup បានដោយរបៀបណា?', '🎯 សកម្មភាពថ្ងៃនេះ៖ កំណត់ម៉ោង Standup ១៥ នាទីសម្រាប់ព្រឹកស្អែក និងរំលឹកសមាជិកឱ្យត្រៀមចម្លើយ ៣ សំណួរជាមុន។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-supervisor-6', 'lesson-supervisor-6', 'ហេតុអ្វីបានជាកិច្ចប្រជុំ Daily Standup ត្រូវតម្រូវឱ្យអ្នកចូលរួម «ឈរ» ជំនួសឱ្យការអង្គុយ?', 'Why are participants required to stand during a Daily Standup meeting?', '["A. ដើម្បីដាក់ទោសបុគ្គលិកដែលមកយឺត។","B. ដើម្បីរក្សាការប្រជុំឱ្យខ្លី ចំគោលដៅ និងការពារកុំឱ្យមនុស្សនិយាយរឿងវែងអន្លាយឥតប្រយោជន៍។","C. ដោយសារគ្មានកៅអីគ្រប់គ្រាន់នៅក្នុងការិយាល័យ។"]', '["A. To penalize employees who arrived late.","B. To keep the meeting concise, focused, and prevent drifting into comfortable, rambling debates.","C. Because of an office chair shortage."]', 1, 'ការពន្យល់៖ ការឈរជួយឱ្យមនុស្សមានស្មារតីប្រុងប្រយ័ត្ន ផ្តោតអារម្មណ៍ និងរក្សាពេលវេលាប្រជុំឱ្យនៅត្រឹម ១៥ នាទីតាមស្តង់ដារ។', 'Explanation: Standing creates natural urgency, keeping reports concise and preventing comfortable time-wasting.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-supervisor-7', 'course-supervisor-ops', 'mod-1', 7, '៧. រង្វង់គ្រប់គ្រងគុណភាព និងការកែលម្អជាប្រចាំ (Quality Circles & Kaizen: 改善)', 'Quality Control Circles (QCC) & Kaizen: Continuous Frontline Innovation', 'text', '• យល់ដឹងពីទស្សនវិជ្ជា Kaizen (改善 - កែលម្អជាប្រចាំដើម្បីភាពល្អប្រសើរ)។\n• បង្កើតរង្វង់ត្រួតពិនិត្យគុណភាព (Quality Control Circles - QCC) ក្នុងចំណោមបុគ្គលិកប្រតិបត្តិការ។\n• លើកទឹកចិត្ត និងផ្តល់រង្វាន់ដល់គំនិតកែលម្អតូចតាចដែលជួយសន្សំពេលវេលា និងថវិកា។', 'Kaizen (កៃហ្សិន) គឺជាជំនឿថា៖ «គ្មានដំណើរការណាដែលល្អឥតខ្ចោះរហូតដល់មិនអាចកែលម្អបាននោះឡើយ»។ ការផ្លាស់ប្តូរធំៗមិនចាំបាច់ទាល់តែចំណាយលុយរាប់ម៉ឺនដុល្លារទិញបច្ចេកវិទ្យាថ្មីនោះទេ ប៉ុន្តែវាអាចកើតចេញពីគំនិតកែលម្អតូចៗរបស់បុគ្គលិកជួរមុខរាល់ថ្ងៃ។ Supervisor ឆ្នើមតែងតែបង្កើតបរិយាកាសដែលបុគ្គលិកគ្រប់គ្នាសប្បាយចិត្តនឹងស្វែងរកវិធីធ្វើការងារឱ្យលឿនជាងមុន និងមានសុវត្ថិភាពជាងមុន។', '«នៅក្នុងសណ្ឋាគារមួយ បុគ្គលិកផ្នែកបោកអ៊ុតតែងតែត្អូញត្អែរពីការឈឺខ្នងដោយសារត្រូវឱនរើសកម្រាលពូកចេញពីកន្ត្រកធំៗ។ \nលោក សាន ជា Housekeeping Supervisor បានបង្កើតការប្រជុំ QCC ជាមួយបុគ្គលិកបោកអ៊ុតដើម្បីពិភាក្សា។ បុគ្គលិកម្នាក់ឈ្មោះ ពៅ បានស្នើគំនិត Kaizen ដ៏ឆ្លាតវៃ៖ ដាក់រ៉ក និង lò xo នៅបាតកន្ត្រក ដើម្បីឱ្យបាតកន្ត្រករុញកម្រាលពូកឡើងលើស្វ័យប្រវត្តិកាលណាទម្ងន់ថយចុះ។ ការកែលម្អនេះចំណាយលុយត្រឹមតែ $15 ក្នុងមួយកន្ត្រក ប៉ុន្តែបានជួយកាត់បន្ថយជំងឺឈឺចង្កេះរបស់បុគ្គលិក ៨០% និងបង្កើនល្បឿនបោកអ៊ុត ២៥%។ សណ្ឋាគារបានផ្តល់រង្វាន់លើកទឹកចិត្ត $200 ដល់ពៅភ្លាមៗ។»', '✅ របៀបបង្កើតប្រព័ន្ធប្រអប់គំនិត Kaizen (The Kaizen Teian System)៖\n១. លើកទឹកចិត្តឱ្យបុគ្គលិកដាក់ស្នើគំនិតកែលម្អតូចៗ (សូម្បីតែកាត់បន្ថយការដើរ ២ ជំហាន ឬសន្សំក្រដាស ១ សន្លឹក)។\n២. Supervisor ត្រូវពិនិត្យ និងឆ្លើយតបចំពោះគ្រប់គំនិតក្នុងរយៈពេល ៤៨ ម៉ោង (កុំទុកចោល)។\n៣. ប្រសិនបើគំនិតនោះត្រូវបានអនុវត្ត ត្រូវផ្តល់រង្វាន់លើកទឹកចិត្ត និងបិទរូបសរសើរលើក្តារព័ត៌មាន។', 'សួរនាំបុគ្គលិកជួរមុខរបស់អ្នកនៅថ្ងៃនេះថា៖ «តើមានកិច្ចការណាដែលធ្វើឱ្យអ្នកពិបាក ឬធុញទ្រាន់បំផុត?» ហើយសហការជាមួយពួកគេដើម្បីបង្កើតដំណោះស្រាយ Kaizen តូចមួយ។', 'តើបុគ្គលិកក្នុងផ្នែករបស់អ្នកហ៊ានបញ្ចេញគំនិតកែលម្អការងារទេ? តើអ្នកបានផ្តល់ការកោតសរសើរដល់គំនិតរបស់ពួកគេកម្រិតណា?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ទទួលយកគំនិតកែលម្អតូចមួយពីសមាជិកជួរមុខ ហើយជួយពួកគេអនុវត្តវាឱ្យចេញជាលទ្ធផលក្នុងសប្តាហ៍នេះ។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-supervisor-7', 'lesson-supervisor-7', 'តើទស្សនវិជ្ជា Kaizen (改善) ផ្តោតលើប្រភេទនៃការកែលម្អបែបណា?', 'What type of improvement does Kaizen (改善) fundamentally focus on?', '["A. ការរុះរើរចនាសម្ព័ន្ធក្រុមហ៊ុនទាំងមូល និងការវិនិយោគទុនរាប់លានដុល្លារតែម្តង។","B. ការកែលម្អបន្តិចម្តងៗជាប្រចាំ និងជាបន្តបន្ទាប់ដោយបុគ្គលិកគ្រប់ជាន់ថ្នាក់ (Small, continuous daily incremental improvements)។","C. ការទិញបច្ចេកវិទ្យាបរទេសថ្លៃៗដោយមិនបាច់បណ្តុះបណ្តាលបុគ្គលិក។"]', '["A. Massive restructuring and multi-million dollar capital investments.","B. Small, continuous daily incremental improvements contributed by all employees.","C. Buying expensive foreign technology without staff training."]', 1, 'ការពន្យល់៖ Kaizen គឺជាទស្សនវិជ្ជាកែលម្អជាប្រចាំពីមួយថ្ងៃទៅមួយថ្ងៃ ដោយចាប់ផ្តើមពីចំណុចតូចតាចដែលបុគ្គលិកជួរមុខអាចធ្វើបានភ្លាមៗ។', 'Explanation: Kaizen champions relentless small-scale daily refinements executed continuously by everyone.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-supervisor-8', 'course-supervisor-ops', 'mod-1', 8, '៨. ការលុបបំបាត់ការខ្ជះខ្ជាយធំៗ ៨ យ៉ាងក្នុងប្រតិបត្តិការ (Lean: The 8 Wastes - TIMWOODS)', 'Operational Lean Excellence: Identifying & Eliminating the 8 Wastes (Muda)', 'text', '• ស្គាល់ច្បាស់ពីការខ្ជះខ្ជាយទាំង ៨ (TIMWOODS: Transport, Inventory, Motion, Waiting, Overproduction, Over-processing, Defects, Skills)។\n• ចេះគណនាថ្លៃដើមដែលបាត់បង់ដោយសារការរង់ចាំ និងការកែកំហុសឡើងវិញ (Rework)។\n• បង្កើនទិន្នផលប្រតិបត្តិការដោយមិនចាំបាច់បន្ថែមបុគ្គលិក ឬបង្កើនម៉ោងធ្វើការ។', 'នៅក្នុងប្រព័ន្ធគ្រប់គ្រងបែប Lean (Muda / 无駄) ប្រាក់ចំណេញរបស់ក្រុមហ៊ុនមិនមែនកើតឡើងត្រឹមតែពីការបង្កើនការលក់នោះទេ ប៉ុន្តែកើតចេញពី «ការកាត់បន្ថយការខ្ជះខ្ជាយដែលលាក់កំបាំង»។ ការខ្ជះខ្ជាយរួមមាន៖ ការរង់ចាំឯកសារ (Waiting), ការផលិតលើសតម្រូវការ (Overproduction), ការកែការងារខុសឡើងវិញ (Defects), និងការមិនប្រើប្រាស់សមត្ថភាពបុគ្គលិកឱ្យអស់លទ្ធភាព (Underutilized Talent)។ Supervisor ឆ្នើមគឺជាអ្នកប្រមាញ់ការខ្ជះខ្ជាយ។', '«នៅរោងពុម្ពមួយ លោក ដារ៉ា ជា Production Supervisor បានកត់សម្គាល់ឃើញថា ជាងពុម្ពតែងតែឈររង់ចាំក្រដាសពីឃ្លាំងជាមធ្យម ៤០ នាទីរាល់ព្រឹក (Waiting Waste)។ លើសពីនេះ ដោយសារខ្លាចខ្វះ ពួកគេតែងតែព្រីនលើសចំនួន ៥០០ សន្លឹកក្នុងមួយក្បាលដែលគ្មានអ្នកណាទិញ (Overproduction Waste)។ \nដារ៉ាបានរៀបចំប្រព័ន្ធបញ្ជាទិញក្រដាសជាមុន ១ ថ្ងៃ (Just-In-Time) និងកំណត់ស្តង់ដារព្រីនលើសត្រឹមតែ ២% សម្រាប់តេស្តពណ៌។ ត្រឹមតែមួយខែ រោងពុម្ពបានសន្សំថ្លៃក្រដាសបាន $4,500 និងសន្សំម៉ោងរង់ចាំរបស់ជាងពុម្ពបាន ១២០ ម៉ោង។ ក្រុមហ៊ុនបានយកប្រាក់ចំណេញដែលសន្សំបាននេះមកដំឡើងប្រាក់ខែឱ្យបុគ្គលិកទាំងអស់។»', '✅ ក្បួនត្រួតពិនិត្យការខ្ជះខ្ជាយ ៨ យ៉ាង (The TIMWOODS Framework)៖\n• T (Transport)៖ ការដឹកជញ្ជូនឯកសារ ឬសម្ភារៈទៅមកច្រើនដងដោយមិនចាំបាច់។\n• I (Inventory)៖ ការស្តុកទំនិញច្រើនហួសប្រមាណធ្វើឱ្យកប់ដើមទុន។\n• M (Motion)៖ ការដើរ ឬចលនារាងកាយដែលឥតប្រយោជន៍។\n• W (Waiting)៖ ការឈររង់ចាំការអនុម័ត ឬរង់ចាំវត្ថុធាតុដើម។\n• O (Overproduction)៖ ការធ្វើការងារមុនតម្រូវការ ឬច្រើនជាងតម្រូវការ។\n• O (Over-processing)៖ ការរចនា ឬត្រួតពិនិត្យច្រើនតង់ហួសពីការចង់បានរបស់អតិថិជន។\n• D (Defects)៖ ការងារខូចដែលត្រូវចំណាយពេលកែឡើងវិញ (Rework)។\n• S (Skills)៖ ការមិនប្រើប្រាស់ទេពកោសល្យ និងគំនិតច្នៃប្រឌិតរបស់បុគ្គលិក។', 'ដើរពិនិត្យការងាររបស់អ្នកនៅថ្ងៃនេះ ហើយស្វែងរកយ៉ាងហោចណាស់ការខ្ជះខ្ជាយចំនួន ២ ក្នុងចំណោម TIMWOODS រួចរៀបចំផែនការកាត់បន្ថយវា។', 'តើមានកិច្ចការណាខ្លះដែលអ្នក និងក្រុមការងារកំពុងធ្វើជារៀងរាល់ថ្ងៃ ប៉ុន្តែមិនបានបង្កើតតម្លៃបន្ថែមដល់អតិថិជនសូម្បីតែបន្តិច?', '🎯 សកម្មភាពថ្ងៃនេះ៖ កំណត់ដំណើរការរង់ចាំ (Waiting time) មួយនៅក្នុងផ្នែករបស់អ្នក ហើយកាត់បន្ថយវាឱ្យបាន ៥០% តាមរយៈការសម្រួលការអនុម័ត។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-supervisor-8', 'lesson-supervisor-8', 'ក្នុងចំណោមការខ្ជះខ្ជាយទាំង ៨ (TIMWOODS) តើការខ្ជះខ្ជាយមួយណាដែលចាត់ទុកថាគ្រោះថ្នាក់បំផុតព្រោះវាបង្កើតការខ្ជះខ្ជាយដទៃទៀត?', 'Among the 8 Lean wastes (TIMWOODS), which waste is considered the most hazardous because it breeds all other wastes?', '["A. Overproduction (ការផលិតលើសតម្រូវការជាក់ស្តែង)។","B. Motion (ចលនារាងកាយ)។","C. Transport (ការដឹកជញ្ជូន)។"]', '["A. Overproduction (producing more or earlier than customer demand).","B. Motion (excess movement).","C. Transport (moving materials)."]', 0, 'ការពន្យល់៖ Overproduction គឺជាមេនៃការខ្ជះខ្ជាយទាំងអស់ ព្រោះវាបង្កឱ្យកើតមានការស្តុកទុក (Inventory) ការដឹកជញ្ជូនលើស (Transport) និងការខូចខាត (Defects)។', 'Explanation: Overproduction ties up working capital, forces storage overhead, and multiplies defect risks.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-supervisor-9', 'course-supervisor-ops', 'mod-1', 9, '៩. ការផ្ទេរវេនការងារ និងការរក្សាស្ថេរភាពប្រតិបត្តិការ (Shift Handover Excellence)', 'Shift Handover Protocols: Ensuring Zero-Defect Operational Continuity', 'text', '• យល់ដឹងពីសារៈសំខាន់នៃការផ្ទេរវេនការងារ (Shift Handover) ក្នុងការការពារការដាច់ចង្វាក់ផលិតកម្ម។\n• អនុវត្តទម្រង់កត់ត្រាការផ្ទេរវេន (Handover Logbook) ដែលច្បាស់លាស់ទាំងផ្ទាល់មាត់ និងជាលាយលក្ខណ៍អក្សរ។\n• ធានាថារាល់បញ្ហាមិនប្រក្រតី (Abnormalities) ត្រូវបានបញ្ជូនទៅវេនបន្ទាប់ដោយគ្មានការបាត់បង់ព័ត៌មាន។', 'ការសិក្សាផ្នែកសុវត្ថិភាពឧស្សាហកម្មបានរកឃើញថា ជាង ៧០% នៃគ្រោះថ្នាក់ការងារ និងការខូចខាតឧបករណ៍ធ្ងន់ធ្ងរ កើតឡើងក្នុងអំឡុងពេល «៣០ នាទីដំបូងនៃការប្តូរវេនការងារ»។ មូលហេតុគឺដោយសារការផ្ទេរព័ត៌មានមិនពេញលេញរវាងវេនចេញ និងវេនចូល។ Supervisor ត្រូវតែបង្កើតពិធីសារផ្ទេរវេនដ៏ម៉ត់ចត់ (The Handover Protocol) ដើម្បីធានាថាប្រតិបត្តិការដំណើរការដូចខ្សែទឹកហូរដោយគ្មានការរអាក់រអួល។', '«នៅរោងចក្រផលិតចំណីអាហារមួយ វេនយប់បានកត់សម្គាល់ឃើញថាសីតុណ្ហភាពម៉ាស៊ីនត្រជាក់បន្ទប់ស្តុកសាច់ឡើងកម្តៅខុសធម្មតា ប៉ុន្តែពេលចប់ម៉ោងនៅម៉ោង ៦ ព្រឹក ពួកគេគ្រាន់តែនិយាយប្រាប់វេនព្រឹកដោយផ្ទាល់មាត់កាត់ៗថា "មើលម៉ាស៊ីនផង!" រួចប្រញាប់ទៅផ្ទះ។ \nវេនព្រឹកមិនបានដឹងពីភាពបន្ទាន់ឡើយ។ ពីរម៉ោងក្រោយមក ម៉ាស៊ីនត្រជាក់បានខូចទាំងស្រុង ធ្វើឱ្យសាច់មាន់ស្រស់ទម្ងន់ ៣ តោនត្រូវខូចគុណភាព ខាតបង់ប្រាក់ជាង $8,000។ ក្រោយឧបទ្ទវហេតុនេះ Supervisor ក្រុមហ៊ុនបានដាក់ចេញនូវក្បួន Handover ស្តង់ដារ៖ Supervisor វេនទាំងពីរត្រូវដើរពិនិត្យផ្ទៀងផ្ទាត់ជាមួយគ្នាផ្ទាល់ភ្នែក និងចុះហត្ថលេខាលើ Logbook រួមគ្នា។ ចាប់ពីពេលនោះមក គ្មានឧប្បត្តិហេតុបែបនេះកើតឡើងម្តងទៀតឡើយ។»', '✅ ពិធីសារផ្ទេរវេន ៣ ជំហាន (The 3-Step Handover Protocol)៖\n១. [Written Log]៖ វេនចាស់កត់ត្រាស្ថានភាពគ្រឿងចក្រ បញ្ជីទំនិញសម្រេច និងបញ្ហាមិនប្រក្រតីក្នុង Logbook ៣០ នាទីមុនចប់វេន។\n②. [Face-to-Face Walkthrough]៖ មេវេនទាំងពីរជួបគ្នា និងដើរពិនិត្យកន្លែងធ្វើការជាមួយគ្នាផ្ទាល់រយៈពេល ១០ នាទី។\n៣. [Sign-off]៖ មេវេនថ្មីសួរបញ្ជាក់ឱ្យអស់ចម្ងល់ រួចចុះហត្ថលេខាទទួលខុសត្រូវជាផ្លូវការ។', 'បង្កើតទម្រង់ Shift Handover Checklist មួយទំព័រសម្រាប់ក្រុមការងាររបស់អ្នក ដើម្បីប្រើប្រាស់ក្នុងការផ្ទេរការងាររវាងវេន ឬរវាងថ្ងៃ។', 'តើការងារក្នុងក្រុមរបស់អ្នកធ្លាប់ជួបបញ្ហាដោយសារការផ្ទេរការងារមិនច្បាស់លាស់រវាងសហការីដែរឬទេ?', '🎯 សកម្មភាពថ្ងៃនេះ៖ មុននឹងចេញពីធ្វើការ ចូររៀបចំកំណត់ហេតុផ្ទេរការងារ (Handover Notes) យ៉ាងច្បាស់លាស់ជូនអ្នកដែលត្រូវបន្តការងារស្អែក។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-supervisor-9', 'lesson-supervisor-9', 'តើវិធីសាស្ត្រផ្ទេរវេនការងារ (Shift Handover) បែបណាដែលមានសុវត្ថិភាព និងវិជ្ជាជីវៈបំផុត?', 'Which shift handover methodology is the most secure and professional?', '["A. ស្រែកប្រាប់ពីចម្ងាយពេលដើរចេញទៅផ្ទះ។","B. ការរួមបញ្ចូលគ្នារវាងកំណត់ហេតុជាលាយលក្ខណ៍អក្សរ (Logbook) និងការដើរពិនិត្យផ្ទៀងផ្ទាត់ផ្ទាល់មាត់រវាងមេវេនទាំងពីរ (Face-to-face walk)។","C. មិនបាច់ប្រាប់អ្វីទាំងអស់ ទុកឱ្យវេនបន្ទាប់ស្វែងយល់ដោយខ្លួនឯង។"]', '["A. Shouting verbal notes while rushing to the parking lot.","B. Structured written logbook paired with a mandatory joint face-to-face walkthrough and sign-off.","C. Saying nothing and letting the incoming shift discover issues."]', 1, 'ការពន្យល់៖ ការផ្ទេរវេនប្រកបដោយវិជ្ជាជីវៈទាមទារទាំងឯកសារកត់ត្រាច្បាស់លាស់ និងការជួបផ្ទៀងផ្ទាត់ដោយផ្ទាល់ ដើម្បីការពារការបាត់បង់ព័ត៌មានសំខាន់ៗ។', 'Explanation: Dual-verification via written logs and visual walkthrough eliminates dangerous operational blind spots.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-supervisor-10', 'course-supervisor-ops', 'mod-1', 10, '១០. ការបំប្លែងយុទ្ធសាស្ត្រថ្នាក់លើទៅជាទិន្នផលប្រចាំថ្ងៃ (Translating Strategy to Daily Quotas)', 'Translating Corporate Strategy into Daily Frontline Shift Quotas', 'text', '• យល់ដឹងពីតួនាទីស្នូលរបស់ Supervisor ក្នុងនាមជា «ស្ពានតភ្ជាប់» រវាងនាយកប្រតិបត្តិ និងបុគ្គលិកជួរមុខ។\n• ចេះបំបែកគោលដៅប្រចាំឆ្នាំ ឬប្រចាំត្រីមាស ទៅជាកូតាប្រចាំខែ ប្រចាំសប្តាហ៍ និងប្រចាំម៉ោង។\n• បង្កើតផ្ទាំងគ្រប់គ្រងមើលឃើញដោយភ្នែក (Visual Management Board) សម្រាប់តាមដានទិន្នផលជាក់ស្តែង។', 'ថ្នាក់ដឹកនាំជាន់ខ្ពស់និយាយជាភាសាយុទ្ធសាស្ត្រដូចជា «បង្កើន EBITDA ១៥%» ឬ «កាត់បន្ថយ OPEX» ដែលបុគ្គលិកជួរមុខមិនយល់ និងមិនខ្វល់ឡើយ។ តម្លៃពិតប្រាកដរបស់ Supervisor គឺសមត្ថភាពក្នុងការ «បកប្រែ» គោលដៅអរូបីទាំងនោះ ឱ្យទៅជាសកម្មភាពជាក់ស្តែងប្រចាំថ្ងៃ៖ «ថ្ងៃនេះវេនយើងត្រូវផលិតឱ្យបាន ៥០០ កេស ដោយមិនឱ្យខូចលើសពី ៣ កេស»។ នៅពេលគោលដៅច្បាស់លាស់ បុគ្គលិកនឹងមានទឹកចិត្តប្រឹងប្រែង។', '«ក្នុងកិច្ចប្រជុំប្រចាំឆ្នាំ CEO បានប្រកាសថា ក្រុមហ៊ុនត្រូវបង្កើនប្រាក់ចំណេញសុទ្ធ ២០% តាមរយៈការកាត់បន្ថយថ្លៃដើមដឹកជញ្ជូន។ បុគ្គលិកផ្នែកឃ្លាំងបានស្តាប់ហើយមានអារម្មណ៍ធុញទ្រាន់ ព្រោះគិតថាមិនទាក់ទងនឹងពួកគេ។ \nប៉ុន្តែ លោក ចាន់ណា ជា Warehouse Supervisor បានបំប្លែងយុទ្ធសាស្ត្រនេះមកជាភាសាសាមញ្ញនៅលើក្តារព័ត៌មានធំមួយនៅមាត់ទ្វារឃ្លាំង៖ "ដើម្បីជួយក្រុមហ៊ុនសម្រេចគោលដៅ ក្រុមយើងត្រូវវេចខ្ចប់ទំនិញឱ្យបាន ២០ កេសក្នុងមួយម៉ោង ហើយរៀបចំជង់លើ Pallet ឱ្យត្រឹមត្រូវដើម្បីកុំឱ្យទំនិញបាក់បែក"។ គាត់បានបង្កើតការប្រកួតប្រជែងតូចមួយ និងតាមដានលេខរៀងរាល់ ២ ម៉ោងម្តង។ បុគ្គលិកឃ្លាំងយល់ច្បាស់ពីតួនាទីរបស់ខ្លួន ហើយបានជួយក្រុមហ៊ុនកាត់បន្ថយការខូចខាតទំនិញបាន ៣០%។»', '✅ រូបមន្តបំប្លែងគោលដៅយុទ្ធសាស្ត្រជាទិន្នផលជួរមុខ៖\n១. [យុទ្ធសាស្ត្រក្រុមហ៊ុន]៖ "បង្កើនការពេញចិត្តរបស់អតិថិជន (CSAT) ឡើងដល់ ៩០%"\n②. [បកប្រែជាភាសា Supervisor]៖ "ឆ្លើយតបការហៅចូលរបស់ភ្ញៀវក្នុងរយៈពេលតិចជាង ៣ រោទ៍ និងមិនទុកឱ្យភ្ញៀវរង់ចាំលើសពី ៣០ វិនាទី"\n៣. [ការវាស់វែងជាក់ស្តែង]៖ បង្ហាញតួលេខលើអេក្រង់ផ្សាយផ្ទាល់ (Live Dashboard) ឱ្យបុគ្គលិកមើលឃើញទាំងអស់គ្នា។', 'យកគោលដៅធំមួយរបស់ក្រុមហ៊ុនអ្នកនៅត្រីមាសនេះ ហើយបំបែកវាទៅជាសកម្មភាពជាក់លាក់ប្រចាំថ្ងៃសម្រាប់ក្រុមការងាររបស់អ្នក។', 'តើសមាជិកក្រុមជួរមុខរបស់អ្នកដឹងច្បាស់ទេថា ការងារប្រចាំថ្ងៃរបស់ពួកគេជួយដល់ភាពជោគជ័យរបស់ក្រុមហ៊ុនទាំងមូលដោយរបៀបណា?', '🎯 សកម្មភាពថ្ងៃនេះ៖ សរសេរគោលដៅទិន្នផលជាក់លាក់ប្រចាំថ្ងៃលើក្តារព័ត៌មាន ឬ Group Chat របស់ក្រុមនៅព្រឹកនេះ។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-supervisor-10', 'lesson-supervisor-10', 'តើវិធីណាដែលល្អបំផុតសម្រាប់ Supervisor ក្នុងការពន្យល់គោលដៅយុទ្ធសាស្ត្ររបស់ក្រុមហ៊ុនទៅកាន់បុគ្គលិកជួរមុខ?', 'What is the best way for a supervisor to convey corporate strategic goals to frontline workers?', '["A. អានឯកសារយុទ្ធសាស្ត្រហិរញ្ញវត្ថុរបស់ Board of Directors ទាំងស្រុងឱ្យពួកគេស្តាប់។","B. បំប្លែងយុទ្ធសាស្ត្រធំៗទៅជាទិន្នផលសកម្មភាពប្រចាំថ្ងៃជាក់ស្តែង (Daily actionable quotas) ដែលបុគ្គលិកយល់ និងអាចគ្រប់គ្រងបាន។","C. គំរាមកំហែងថានឹងបណ្តេញចេញប្រសិនបើក្រុមហ៊ុនមិនសម្រេចគោលដៅប្រាក់ចំណេញ។"]', '["A. Read the entire complex financial strategy document verbatim.","B. Deconstruct high-level goals into simple, concrete daily quotas and behavioral metrics frontline workers control directly.","C. Threaten mass layoffs if enterprise profitability dips."]', 1, 'ការពន្យល់៖ បុគ្គលិកជួរមុខត្រូវការភាពច្បាស់លាស់៖ តើថ្ងៃនេះខ្ញុំត្រូវធ្វើអ្វីឱ្យបានប៉ុន្មាន? ការបកប្រែគោលដៅធំជាទិន្នផលប្រចាំថ្ងៃគឺជាជំនាញស្នូលរបស់ Supervisor។', 'Explanation: Translating abstract corporate metrics into tangible frontline daily quotas drives real execution.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-hod-1', 'course-hod-strategy', 'mod-1', 1, '១. ការគ្រប់គ្រងថវិកាប្រចាំឆ្នាំ និងគណនេយ្យភាព P&L (Departmental Budgeting & P&L Mastery)', 'Departmental Annual Budgeting & P&L Accountability', 'text', '• យល់ដឹងពីរបៀបអាន និងគ្រប់គ្រងរបាយការណ៍ចំណេញ-ខាត (P&L Statement) នៃនាយកដ្ឋាន។\n• រៀបចំថវិកាចំណាយប្រតិបត្តិការ (OPEX) និងថវិកាវិនិយោគ (CAPEX) ប្រចាំឆ្នាំ។\n• គ្រប់គ្រងការចំណាយឱ្យស្ថិតក្នុងដែនកំណត់ និងបង្កើនប្រសិទ្ធភាពចំណូល។', 'ប្រធានផ្នែកមិនមែនគ្រាន់តែជាអ្នកដឹកនាំមនុស្សនោះទេ ប៉ុន្តែជាអ្នកគ្រប់គ្រងក្រុមហ៊ុនតូចមួយនៅក្នុងក្រុមហ៊ុនធំ ដែលទទួលខុសត្រូវលើប្រាក់ចំណូល និងចំណាយពិតប្រាកដ។', '«គង់ សម្បត្តិ ត្រូវបានតែងតាំងជាប្រធានផ្នែកលក់ និងទីផ្សារ។ ពីមុន គាត់ផ្តោតតែលើការចំណាយលុយផ្សាយពាណិជ្ជកម្ម។ ក្រោយពេលបានរៀនពីការគ្រប់គ្រង P&L គាត់ចាប់ផ្តើមពិនិត្យមើលតម្លៃដើមនៃការទាក់ទាញអតិថិជន (CAC) ធៀបនឹងតម្លៃជីវិតរបស់អតិថិជន (LTV)។ គាត់បានកាត់បន្ថយយុទ្ធនាការដែលខាតបង់ និងបង្កើនការវិនិយោគលើបណ្តាញដែលផ្តល់ផលចំណេញខ្ពស់។ ក្នុងរយៈពេល ១ ឆ្នាំ នាយកដ្ឋានរបស់គាត់បានបង្កើនប្រាក់ចំណេញសុទ្ធ ៤០% ជូនក្រុមហ៊ុន។»', '✅ របៀបបង្ហាញរបាយការណ៍ P&L ជូនអគ្គនាយក៖\n«ក្នុងត្រីមាសនេះ នាយកដ្ឋានយើងបានគ្រប់គ្រង OPEX ឱ្យទាបជាងផែនការ ៨% ខណៈដែលចំណូលកើនឡើង ១៥% ដែលបង្កើតប្រាក់ចំណេញប្រតិបត្តិការបន្ថែម $35,000។»', 'គូសវាសតារាងសង្ខេបចំណាយ OPEX ធំៗទាំង ៣ នៃផ្នែករបស់អ្នក និងរកមើលចំណុចដែលកាត់បន្ថយការខាតបង់បាន។', 'តើនាយកដ្ឋានរបស់អ្នកកំពុងជា Cost Center (ចំណាយលុយ) ឬជា Profit Driver (បង្កើតចំណេញ) ដល់ក្រុមហ៊ុន?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ស្នើសុំមើលរបាយការណ៍ចំណាយជាក់ស្តែងនៃផ្នែករបស់អ្នកក្នុងខែមុន ដើម្បីស្វែងយល់ពីតួលេខ។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-hod-1', 'lesson-hod-1', 'ហេតុអ្វីបានជាប្រធានផ្នែក (Head of Department) ត្រូវយល់ដឹងពីរបាយការណ៍ P&L ឱ្យបានច្បាស់លាស់?', 'Why must a Head of Department understand the P&L statement thoroughly?', '["A. ដើម្បីដណ្តើមការងាររបស់ផ្នែកគណនេយ្យ។","B. ដើម្បីអាចសម្រេចចិត្តជាយុទ្ធសាស្ត្រលើការវិនិយោគ និងដឹងថានាយកដ្ឋានរបស់ខ្លួនកំពុងបង្កើតប្រាក់ចំណេញ ឬកំពុងខាតបង់។","C. មិនចាំបាច់យល់ដឹងទេ ព្រោះជាតួនាទីរបស់ CEO ម្នាក់ឯង។"]', '["A. To steal accounting duties.","B. To make strategic investment decisions and know whether their department is generating profit or leaking cash.","C. Not necessary as it belongs solely to the CEO."]', 1, 'ការពន្យល់៖ ជម្រើស B បង្ហាញពីគណនេយ្យភាពហិរញ្ញវត្ថុដែលថ្នាក់ដឹកនាំជាន់ខ្ពស់ត្រូវតែមាន។', 'Explanation: P&L mastery equips department heads to make commercially sound decisions.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-hod-2', 'course-hod-strategy', 'mod-1', 2, '២. ការដឹកនាំកិច្ចសហការអន្តរនាយកដ្ឋាន (Cross-Functional Alignment & Synergy)', 'Cross-Functional Alignment & Breaking Down Departmental Silos', 'text', '• បំបែករបាំងការពារខ្លួនរវាងនាយកដ្ឋាន (Breaking Silos) ដើម្បីសម្រេចគោលដៅរួម។\n• កំណត់គោលដៅ OKRs រួមគ្នាជាមួយប្រធានផ្នែកផ្សេងៗ។\n• ដោះស្រាយបញ្ហារុញដាក់គ្នានៅពេលគម្រោងឆ្លងកាត់នាយកដ្ឋានជាច្រើន។', 'ភាពបរាជ័យធំបំផុតរបស់ក្រុមហ៊ុនធំៗ គឺការដែលនាយកដ្ឋាននីមួយៗគិតតែពីផលប្រយោជន៍ខ្លួនឯង (Silo Mentality)។ Head of Department ឆ្នើមកសាងស្ពានមិត្តភាព និងកិច្ចសហការដើម្បីផលប្រយោជន៍រួម។', '«ផ្នែក IT និងផ្នែក Marketing ធ្លាប់ឈ្លោះគ្នាជាញឹកញាប់រឿងការកែប្រែគេហទំព័រ។ Marketing ចោទថា IT ធ្វើការយឺត រីឯ IT ចោទថា Marketing ផ្លាស់ប្តូរតម្រូវការញឹកញាប់ពេក។ ប្រធានផ្នែកទាំងពីរបានព្រមព្រៀងគ្នារៀបចំការប្រជុំរួមប្រចាំពីរសប្តាហ៍ម្តង (Bi-weekly Sync) និងកំណត់គោលដៅ OKR រួមគ្នា។ ពួកគេបានប្តូរពីការបន្ទោសគ្នា មកជាការសហការជិតស្និទ្ធ ដែលជួយឱ្យគម្រោង App ថ្មីចេញលក់បានមុនកាលកំណត់ ១ ខែ។»', '✅ របៀបនិយាយបំបែក Silo៖\n«អតិថិជនមិនខ្វល់ថាកំហុសជាកំហុសរបស់ផ្នែក IT ឬផ្នែក Operations នោះទេ។ អតិថិជនមើលឃើញតែឈ្មោះក្រុមហ៊ុនយើងទាំងមូល។ ដូច្នេះ តើយើងអាចអង្គុយដោះស្រាយជាមួយគ្នាយ៉ាងដូចម្តេច?»', 'កំណត់នាយកដ្ឋានមួយដែលផ្នែករបស់អ្នកកំពុងមានបញ្ហារអាក់រអួលជាមួយ ហើយរៀបចំការជជែកពិភាក្សាស្និទ្ធស្នាលមួយ។', 'តើផ្នែករបស់អ្នកធ្លាប់ធ្វើឱ្យប៉ះពាល់ដល់ការងាររបស់នាយកដ្ឋានផ្សេងទៀតដោយសារខ្វះការប្រាស្រ័យទាក់ទងដែរឬទេ?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ផ្ញើសារសួរសុខទុក្ខ និងថ្លែងអំណរគុណដល់ប្រធានផ្នែកម្នាក់ទៀតដែលបានជួយគាំទ្រផ្នែករបស់អ្នក។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-hod-2', 'lesson-hod-2', 'តើអ្វីជាវិធីសាស្ត្រល្អបំផុតដើម្បីលុបបំបាត់បញ្ហានាយកដ្ឋានគិតតែពីផលប្រយោជន៍ខ្លួនឯង (Silos)?', 'What is the most effective approach to break down departmental silos?', '["A. ដាក់ទណ្ឌកម្មលើគ្រប់នាយកដ្ឋានទាំងអស់។","B. បង្កើតគោលដៅរួម (Shared OKRs/KPIs) និងបង្កើតវេទិកាទំនាក់ទំនងទៀងទាត់រវាងប្រធានផ្នែក។","C. ហាមមិនឱ្យបុគ្គលិកឆ្លងផ្នែកនិយាយរកគ្នា។"]', '["A. Punish all departments.","B. Establish shared goals (Shared OKRs) and regular cross-department communication forums.","C. Forbid inter-department talk."]', 1, 'ការពន្យល់៖ ជម្រើស B ជំរុញឱ្យនាយកដ្ឋានទាំងអស់មានផលប្រយោជន៍ស្របគ្នា។', 'Explanation: Shared OKRs align incentives and naturally dissolve counter-productive silos.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-hod-3', 'course-hod-strategy', 'mod-1', 3, '៣. យុទ្ធសាស្ត្រវាយលុកឆ្អែតឆ្អន់របស់ Huawei (Huawei Saturated Attack Strategy: 饱和攻击)', 'Concentrated Resource Allocation: Huawei Saturated Attack Strategy', 'text', '• យល់ដឹងពីទ្រឹស្តីយុទ្ធសាស្ត្រ «饱和攻击» (Saturated Attack) របស់ស្ថាបនិកក្រុមហ៊ុន Huawei លោក Ren Zhengfei។\n• បញ្ឈប់ការបែងចែកថវិកា និងធនធានបែប «ព្រួចទឹកលើខ្សាច់» (Scattered Resources)។\n• ប្រមូលផ្តុំកម្លាំងមនុស្ស ថវិកា និងពេលវេលា វាយទម្លុះចំណុចយុទ្ធសាស្ត្រតែមួយគត់ដើម្បីដណ្តើមឧត្តមភាពទីផ្សារ។', 'ស្ថាបនិកក្រុមហ៊ុន Huawei លោក Ren Zhengfei តែងតែលើកឡើងថា៖ «ក្រុមហ៊ុនទន់ខ្សោយស្លាប់ដោយសារការពង្រាយកម្លាំងគ្រប់ទិសទី រីឯក្រុមហ៊ុនខ្លាំងឈ្នះដោយសារការប្រមូលផ្តុំកម្លាំង»។ ទ្រឹស្តី «Saturated Attack» (ការវាយលុកឆ្អែតឆ្អន់) បង្រៀនឱ្យប្រធាននាយកដ្ឋាន (HOD) មិនត្រូវបែងចែកធនធានស្មើៗគ្នាលើគម្រោងតូចតាចរាប់សិបនោះទេ ប៉ុន្តែត្រូវកំណត់ «ច្រកទ្វារយុទ្ធសាស្ត្រតែមួយគត់» ហើយបាញ់កម្លាំងធនធានលើសពីគូប្រជែង ៥ ទៅ ១០ ដង ដើម្បីវាយទម្លាយឱ្យខានតែបាន។', '«នៅពេលក្រុមហ៊ុនចែកចាយទំនិញប្រើប្រាស់មួយចង់ពង្រីកទីផ្សារទៅកាន់បណ្តាខេត្ត ប្រធានផ្នែកទីផ្សារចាស់ចង់ពង្រាយថវិកា $50,000 ទៅគ្រប់ ២៤ ខេត្តស្មើៗគ្នា (ប្រហែល $2,000/ខេត្ត) ដែលជាលទ្ធផលគ្មានខេត្តណាមួយស្គាល់ម៉ាកយីហោក្រុមហ៊ុនឡើយ។ \nលោក វិទ្យា ដែលទើបឡើងជា HOD បានលុបចោលផែនការនោះភ្លាមៗ។ ដោយអនុវត្តក្បួន Saturated Attack របស់ Huawei គាត់បានប្រមូលថវិកា $50,000 ទាំងអស់ និងបុគ្គលិកឆ្នើម ៨០% មកវាយលុកផ្តាច់មុខតែលើខេត្តសៀមរាបតែមួយគត់។ ពួកគេបានគ្របដណ្តប់ស្លាកប៉ាណូ ផ្សារទំនើប ភោជនីយដ្ឋាន និងបណ្តាញសង្គមទូទាំងខេត្ត។ ត្រឹមតែ ៣ ខែ ក្រុមហ៊ុនបានដណ្តើមចំណែកទីផ្សារ ៦៥% នៅសៀមរាប និងបង្កើតប្រាក់ចំណេញយ៉ាងច្រើន ដែលអនុញ្ញាតឱ្យពួកគេយកចំណេញនោះទៅវាយលុកខេត្តបន្ទាប់។»', '✅ របៀបអនុវត្ត Saturated Attack ក្នុងនាយកដ្ឋាន៖\n១. [Identify the Linchpin]៖ កំណត់គម្រោង ឬផលិតផលតែមួយគត់ដែលមានសក្តានុពលបង្កើតផលប៉ះពាល់ ៨០% ដល់ក្រុមហ៊ុន (80/20 Rule)។\n②. [Over-Concentrate Talent]៖ ដាក់បុគ្គលិកកំពូលៗ និងថវិកាច្រើនលើសលប់ទៅលើគម្រោងនោះ (Saturate resources)។\n៣. [Relentless Execution]៖ បន្តវាយលុកឥតឈប់ឈររហូតដល់សម្រេចបានជោគជ័យដាច់ខាត មុននឹងប្តូរទៅគម្រោងបន្ទាប់។', 'ពិនិត្យមើលបញ្ជីគម្រោងទាំងអស់របស់នាយកដ្ឋានអ្នកនៅឆ្នាំនេះ។ ជ្រើសរើសគម្រោងកំពូលតែមួយគត់ ហើយរៀបចំផែនការផ្ទេរធនធាន ៦០% ទៅផ្តោតលើវា។', 'តើនាយកដ្ឋានរបស់អ្នកកំពុងធ្វើគម្រោងច្រើនពេករហូតដល់គ្មានគម្រោងណាមួយលេចធ្លោពិតប្រាកដដែរឬទេ?', '🎯 សកម្មភាពថ្ងៃនេះ៖ កោះប្រជុំគណៈគ្រប់គ្រងនាយកដ្ឋាន ដើម្បីកាត់បន្ថយគម្រោងអាទិភាពទាបចោល ៣០% ហើយផ្ទេរធនធានទៅគម្រោងស្នូល។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-hod-3', 'lesson-hod-3', 'តើអ្វីជាគ្រោះថ្នាក់ធំបំផុតនៃការបែងចែកធនធាននាយកដ្ឋានតាមបែប «ព្រួចទឹកលើខ្សាច់» (Scattering resources equally)?', 'What is the greatest risk of scattering departmental resources equally across all initiatives?', '["A. ធ្វើឱ្យបុគ្គលិកសប្បាយចិត្តពេក។","B. ធនធានត្រូវពង្រាយស្តើងពេក ធ្វើឱ្យគ្មានគម្រោងណាមួយសម្រេចបានជោគជ័យដាច់ស្រេច ហើយងាយនឹងត្រូវគូប្រជែងកម្ទេច។","C. ធ្វើឱ្យនាយកដ្ឋានសន្សំប្រាក់បានច្រើនពេក។"]', '["A. Making employees overly happy.","B. Resources are spread too thin, causing every project to achieve mediocre results and leaving the firm vulnerable to competitors.","C. Accumulating too much surplus cash."]', 1, 'ការពន្យល់៖ ការបែងចែកធនធានស្តើងពេកធ្វើឱ្យបាត់បង់អំណាចវាយលុក។ ក្បួន Huawei Saturated Attack ទាមទារការប្រមូលផ្តុំកម្លាំងដើម្បីបង្កើតជ័យជម្នះដាច់ខាត។', 'Explanation: Spreading resources thin guarantees mediocrity; saturated attacks concentrate force to secure decisive breakthrough.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-hod-4', 'course-hod-strategy', 'mod-1', 4, '៤. ការប្រែក្លាយនាយកដ្ឋានពីកន្លែងចាយលុយទៅជាកន្លែងបង្កើតចំណូល (Cost Center to Profit Center)', 'Strategic Value Creation: Transforming Cost Centers into Profit Drivers', 'text', '• យល់ដឹងពីផ្នត់គំនិតខុសគ្នារវាង Cost Center (ផ្នែកដែលក្រុមហ៊ុនគិតថាគ្រាន់តែស៊ីលុយ) និង Profit Center (ផ្នែកដែលបង្កើតតម្លៃ)។\n• បង្ហាញពីផលចំណេញលើការវិនិយោគ (ROI) នៃនាយកដ្ឋានគាំទ្រដូចជា HR, IT, Legal, និង Operations។\n• កសាងប្រព័ន្ធសេវាកម្មផ្ទៃក្នុង (Internal Commercialization) ដែលនាយកដ្ឋានផ្សេងទៀតស្ម័គ្រចិត្តបង់ថ្លៃសេវា។', 'នៅក្នុងក្រសែភ្នែករបស់ Board of Directors នាយកដ្ឋានដូចជា HR, IT, Admin, និង Compliance តែងតែត្រូវបានចាត់ទុកថាជា «Cost Center» (បន្ទុកចំណាយដែលត្រូវកាត់បន្ថយរាល់ពេលសេដ្ឋកិច្ចធ្លាក់ចុះ)។ HOD កម្រិតយុទ្ធសាស្ត្រត្រូវតែផ្លាស់ប្តូររូបភាពនេះ ដោយបង្ហាញឱ្យឃើញច្បាស់ថាតើនាយកដ្ឋានរបស់ខ្លួនជួយបង្កើនប្រាក់ចំណេញ កាត់បន្ថយការខាតបង់ ឬបង្កើតឱកាសធុរកិច្ចថ្មីៗដោយរបៀបណា។', '«នាយកដ្ឋាន IT របស់ក្រុមហ៊ុនលក់រាយមួយ តែងតែត្រូវ CEO ស្តីបន្ទោសរាល់ពេលស្នើសុំថវិកា Server ព្រោះ CEO គិតថា IT គ្រាន់តែជាកន្លែងជួសជុលកុំព្យូទ័រដែលស៊ីលុយច្រើន។ \nលោក សម្បត្តិ ដែលទើបឡើងជា Head of IT បានប្តូរយុទ្ធសាស្ត្រទាំងស្រុង៖ គាត់បានបង្កើតប្រព័ន្ធវិភាគទិន្នន័យទម្លាប់ទិញទំនិញរបស់អតិថិជន (Automated Recommendation Engine) សម្រាប់ផ្នែកលក់។ មុខងារនេះបានជួយឱ្យផ្នែកលក់អាចលក់ទំនិញបន្ថែម (Cross-selling) បានទឹកប្រាក់ $350,000 ក្នុងរយៈពេល ៦ ខែ។ នៅក្នុងកិច្ចប្រជុំ Board សម្បត្តិបានបង្ហាញរបាយការណ៍ថា៖ រាល់ $1 ដែលវិនិយោគលើ IT បានបង្កើតចំណូលត្រឡប់មកវិញ $7 ដល់ក្រុមហ៊ុន។ ចាប់ពីពេលនោះមក CEO លែងចាត់ទុក IT ជាបន្ទុកចំណាយទៀតហើយ ប៉ុន្តែជាក្បាលម៉ាស៊ីនបង្កើតប្រាក់ចំណេញ។»', '✅ របៀបបង្ហាញតម្លៃនាយកដ្ឋានបែប Profit-Driven Metrics៖\n• HR Department៖ មិនរាយការណ៍ត្រឹម "បានជ្រើសរើសបុគ្គលិក ២០ នាក់" -> ត្រូវរាយការណ៍ "បានកាត់បន្ថយអត្រាលាលែង ១០% ដែលជួយសន្សំថ្លៃបណ្តុះបណ្តាល និងជ្រើសរើសថ្មីបាន $45,000"។\n• Legal & Compliance៖ "បានចរចាកិច្ចសន្យាផ្គត់ផ្គង់ដែលជួយការពារហានិភ័យផ្លូវច្បាប់ និងសន្សំថ្លៃពិន័យ $80,000"។\n• Admin & Procurement៖ "បានដេញថ្លៃអ្នកផ្គត់ផ្គង់ថ្មីដែលកាត់បន្ថយថ្លៃដើមប្រតិបត្តិការ ៨% ដោយរក្សាគុណភាពដដែល"។', 'សរសេរសេចក្តីសង្ខេប ១ ទំព័រដែលបង្ហាញពីតម្លៃហិរញ្ញវត្ថុ ឬការសន្សំថ្លៃដើមដែលនាយកដ្ឋានរបស់អ្នកបានបង្កើតជូនក្រុមហ៊ុនក្នុងរយៈពេល ៦ ខែកន្លងមក។', 'តើ Board of Directors មើលឃើញនាយកដ្ឋានរបស់អ្នកជា «បន្ទុកចំណាយដែលត្រូវកាត់បន្ថយ» ឬជា «ដៃគូយុទ្ធសាស្ត្រដែលបង្កើតតម្លៃ»?', '🎯 សកម្មភាពថ្ងៃនេះ៖ គណនាផលចំណេញជាប្រាក់ដុល្លារដែលនាយកដ្ឋានរបស់អ្នកបានជួយក្រុមហ៊ុនសន្សំ ឬរកបានក្នុងខែនេះ។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-hod-4', 'lesson-hod-4', 'តើធ្វើដូចម្តេចដើម្បីកុំឱ្យនាយកដ្ឋានគាំទ្រ (ដូចជា HR ឬ IT) ត្រូវបាន CEO កាត់បន្ថយថវិការាល់ពេលសេដ្ឋកិច្ចជួបវិបត្តិ?', 'How can support departments (like HR or IT) protect themselves from budget cuts during downturns?', '["A. អង្វរករ និងរៀបរាប់ពីការលំបាកផ្ទាល់ខ្លួនរបស់បុគ្គលិក។","B. បង្ហាញទិន្នន័យជាក់ស្តែងថាតើសកម្មភាពរបស់នាយកដ្ឋានបានជួយរកចំណូលផ្ទាល់ ការពារហានិភ័យ ឬសន្សំថ្លៃដើមដល់ក្រុមហ៊ុនកម្រិតណា (Demonstrating ROI)។","C. លាក់បាំងតួលេខចំណាយទាំងអស់កុំឱ្យ CEO ដឹង។"]', '["A. Plead emotionally about staff hardships.","B. Quantify how departmental initiatives directly generate revenue, mitigate enterprise risks, or cut operating costs (Demonstrating ROI).","C. Conceal operational expenses."]', 1, 'ការពន្យល់៖ ថ្នាក់ដឹកនាំកំពូលសម្រេចចិត្តលើតួលេខ ROI។ នៅពេលនាយកដ្ឋានអាចបង្ហាញថារាល់ការចំណាយបង្កើតផលចំណេញត្រឡប់មកវិញ ពួកគេនឹងត្រូវបានគាំទ្រជានិច្ច។', 'Explanation: Quantifying business impact and cost-savings converts perceived overhead into strategic value.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-hod-5', 'course-hod-strategy', 'mod-1', 5, '៥. ការតម្រឹមគោលដៅ OKR ពីថ្នាក់លើមកថ្នាក់ក្រោម (Cascading OKRs for Department Alignment)', 'Strategic OKR Cascading: Aligning Departmental Key Results with Corporate Vision', 'text', '• យល់ដឹងពីភាពខុសគ្នារវាង KPI (រង្វាស់ប្រតិបត្តិការទម្លាប់) និង OKR (គោលដៅលោតផ្លោះយុទ្ធសាស្ត្រ)។\n• ចេះបំបែក Company OKR មកជា Department OKR និង Team OKR ដោយរក្សាភាពស៊ីសង្វាក់គ្នា ១០០%។\n• រៀបចំវដ្តត្រួតពិនិត្យ OKR ប្រចាំត្រីមាស (Quarterly OKR Review & Grading)។', 'បញ្ហាធំបំផុតរបស់ក្រុមហ៊ុនជាច្រើនគឺ «ភាពមិនស៊ីសង្វាក់គ្នា» (Misalignment)៖ ក្រុមហ៊ុនចង់ដើរទៅទិសខាងកើត ប៉ុន្តែនាយកដ្ឋាននីមួយៗរត់ទៅទិសខាងជើង ត្បូង លិច តាមការយល់ឃើញរៀងៗខ្លួន។ វិធីសាស្ត្រ OKR (Objectives and Key Results) ដែលប្រើប្រាស់ដោយ Intel, Google និង ByteDance ជួយធានាថា រាល់សកម្មភាពទាំងអស់របស់សមាជិកក្នុងនាយកដ្ឋានសុទ្ធតែរុញច្រានឆ្ពោះទៅរកគោលដៅធំបំផុតរបស់ក្រុមហ៊ុន។', '«ក្នុងត្រីមាសទី ២ ក្រុមហ៊ុន FinTech មួយបានដាក់ចេញនូវ Company Objective ថា៖ "ក្លាយជាកម្មវិធីទូទាត់ប្រាក់ដែលពេញនិយមបំផុតសម្រាប់អាជីវកម្មខ្នាតតូច"។ \nលោកស្រី ចាន់ថា ដែលជា Head of Customer Support មិនបានរង់ចាំឱ្យគេប្រាប់ទេ។ នាងបានកោះប្រជុំក្រុមការងារដើម្បីបំប្លែង Objective នោះមកជា Department OKR យ៉ាងច្បាស់៖ \n• Objective នាយកដ្ឋាន៖ បង្កើតបទពិសោធន៍ដោះស្រាយបញ្ហាដ៏ល្អឥតខ្ចោះសម្រាប់អាជីវករខ្នាតតូច។\n• Key Result 1: កាត់បន្ថយពេលវេលារង់ចាំដោះស្រាយ (Resolution Time) ពី ២៤ ម៉ោងមកត្រឹម ៤ ម៉ោង។\n• Key Result 2: បង្កើនអត្រាពេញចិត្តរបស់អាជីវករ (Merchant CSAT) ពី ៧៥% ឡើងដល់ ៩៥%។\n• Key Result 3: បង្កើតវីដេអូបង្រៀនខ្លីៗចំនួន ១០ សម្រាប់ជួយអាជីវករប្រើប្រាស់ App ដោយខ្លួនឯង។ \nលទ្ធផល៖ ត្រឹមចុងត្រីមាស អាជីវករជាង ៥,០០០ ហាងបានចុះឈ្មោះប្រើប្រាស់ ហើយនាយកដ្ឋាន Support ត្រូវបាន CEO កោតសរសើរថាជាគំរូនៃការតម្រឹមគោលដៅល្អបំផុតក្នុងស្ថាប័ន។»', '✅ រូបមន្តបង្កើត OKR កម្រិតស្តង់ដារ៖\n• Objective (O)៖ "តើយើងចង់ទៅដល់ណា?" (មានមហិច្ឆតា ជំរុញទឹកចិត្ត មិនបាច់ដាក់លេខ)\n• Key Results (KRs)៖ "តើយើងដឹងថាយើងទៅដល់ដោយរបៀបណា?" (ត្រូវតែមានតួលេខវាស់វែងច្បាស់លាស់ ៣-៥ ចំណុច)\n• ក្បួនមាស៖ "ប្រសិនបើយើងសម្រេច KRs ទាំងអស់បាន ១០០% នោះ Objective នឹងសម្រេចបានដោយស្វ័យប្រវត្តិ"។', 'យក Objective ធំមួយរបស់ក្រុមហ៊ុនអ្នកសម្រាប់ត្រីមាសបន្ទាប់ ហើយសរសេរ Department OKR (O មួយ និង KRs ចំនួន ៣) សម្រាប់នាយកដ្ឋានរបស់អ្នក។', 'តើសមាជិកគ្រប់រូបក្នុងនាយកដ្ឋានរបស់អ្នកដឹងច្បាស់ទេថា OKR របស់ពួកគេភ្ជាប់ទៅនឹងជោគជ័យរបស់ក្រុមហ៊ុនដោយរបៀបណា?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ពិនិត្យមើល KRs របស់នាយកដ្ឋានអ្នក ហើយធានាថាគ្រប់ចំណុចសុទ្ធតែមានលេខវាស់វែងច្បាស់លាស់។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-hod-5', 'lesson-hod-5', 'តើលក្ខណៈវិនិច្ឆ័យដ៏សំខាន់បំផុតនៃ Key Results (KRs) នៅក្នុងប្រព័ន្ធ OKR គឺជាអ្វី?', 'What is the most critical criteria for Key Results (KRs) in the OKR framework?', '["A. ត្រូវតែមានភាពស្រពេចស្រពិលដើម្បីកុំឱ្យមានសម្ពាធ។","B. ត្រូវតែអាចវាស់វែងជាតួលេខជាក់ស្តែង (Measurable & Quantifiable) និងមានកាលបរិច្ឆេទកំណត់ច្បាស់លាស់។","C. ត្រូវតែដូចគ្នាទៅនឹង Job Description ប្រចាំថ្ងៃ។"]', '["A. Kept vague to avoid pressure.","B. Strictly measurable, numeric, and bound by time milestones.","C. Identical to routine daily job descriptions."]', 1, 'ការពន្យល់៖ Key Results ត្រូវតែមានតួលេខជាក់លាក់ (លេខភាគរយ ឬចំនួនប្រាក់) ដើម្បីឱ្យដឹងច្បាស់ថាសម្រេចបានឬអត់ ដោយគ្មានការលម្អៀង។', 'Explanation: Key Results must be unequivocally quantifiable to measure progress without subjectivity.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-hod-6', 'course-hod-strategy', 'mod-1', 6, '៦. កិច្ចព្រមព្រៀងកម្រិតសេវាកម្មផ្ទៃក្នុងតាមគំរូ Haier (Haier Rendanheyi & Internal SLAs)', 'Haier Rendanheyi Model: Internal Service Level Agreements (SLAs) & Zero Bureaucracy', 'text', '• យល់ដឹងពីគំរូគ្រប់គ្រងដ៏ល្បីល្បាញរបស់ Haier «人单合一» (Rendanheyi: Zero distance between employee and customer)។\n• បង្កើតកិច្ចសន្យាសេវាកម្មផ្ទៃក្នុង (Internal SLA) រវាងនាយកដ្ឋាននីមួយៗដើម្បីលុបបំបាត់ការរង់ចាំយឺតយ៉ាវ។\n• បំប្លែងនាយកដ្ឋានឱ្យដំណើរការដូចជា «សហគ្រាសខ្នាតតូច» (Micro-Enterprise) ដែលមានភាពស្វាហាប់ខ្ពស់។', 'នៅក្រុមហ៊ុនយក្ស Haier ស្ថាបនិក Zhang Ruimin បានរំលាយថ្នាក់ដឹកនាំកណ្តាលរាប់ពាន់នាក់ចោល ហើយបំប្លែងស្ថាប័នទាំងមូលឱ្យក្លាយជាបណ្តាញនៃ «សហគ្រាសខ្នាតតូចរាប់ពាន់» (Micro-Enterprises) ក្រោមទស្សនវិជ្ជា «人单合一» (មនុស្ស និងគោលដៅរួមបញ្ចូលគ្នាតែមួយ)។ នាយកដ្ឋានគាំទ្រមិនមែនជាស្ថាប័នរដ្ឋបាលដែលអង្គុយចាំបញ្ជានោះទេ ប៉ុន្តែត្រូវចុះកិច្ចសន្យា SLA ជាមួយផ្នែកជួរមុខ៖ ប្រសិនបើនាយកដ្ឋានគាំទ្រជួយឱ្យផ្នែកជួរមុខលក់ដាច់ ពួកគេទទួលបានរង្វាន់ ប៉ុន្តែបើពួកគេយឺតយ៉ាវ ពួកគេត្រូវទទួលខុសត្រូវ។', '«នៅក្រុមហ៊ុនអភិវឌ្ឍន៍អចលនទ្រព្យមួយ នាយកដ្ឋានច្បាប់ (Legal) តែងតែចំណាយពេល ២ សប្តាហ៍ដើម្បីពិនិត្យកិច្ចសន្យាទិញលក់ ដែលធ្វើឱ្យអតិថិជនជាច្រើនប្តូរចិត្តមិនទិញ។ ផ្នែកលក់តែងតែខឹង ប៉ុន្តែផ្នែកច្បាប់ឆ្លើយតបថា "ការងារខ្ញុំត្រូវតែម៉ត់ចត់!"។ \nលោក វិចិត្រ ដែលទើបឡើងជា Head of Operations បានយកគំរូ Haier Rendanheyi មកអនុវត្ត៖ គាត់បានសម្របសម្រួលឱ្យផ្នែកច្បាប់ និងផ្នែកលក់ចុះហត្ថលេខាលើ Internal SLA ផ្លូវការ៖ កិច្ចសន្យាស្តង់ដារត្រូវតែពិនិត្យចប់ក្នុងរយៈពេល ៤៨ ម៉ោង។ ប្រសិនបើផ្នែកច្បាប់សម្រេចបានទាន់ពេល ហើយការលក់កើនឡើង ផ្នែកច្បាប់នឹងទទួលបានប្រាក់លើកទឹកចិត្ត (Performance Bonus) ស្មើនឹង ២% នៃកម្រៃជើងសារលក់។ \nភ្លាមៗនោះ ផ្នែកច្បាប់បានរៀបចំ Template កិច្ចសន្យាស្វ័យប្រវត្តិ ហើយពេលវេលាពិនិត្យបានធ្លាក់ចុះមកត្រឹមតែ ៤ ម៉ោង! ការលក់បានកើនឡើងយ៉ាងសម្បើម ហើយទំនាក់ទំនងរវាងផ្នែកទាំងពីរប្រែជាស្និទ្ធស្នាលដូចបងប្អូន។»', '✅ ធាតុផ្សំ ៤ នៃ Internal SLA (កិច្ចព្រមព្រៀងកម្រិតសេវាកម្មផ្ទៃក្នុង)៖\n១. [Service Scope]៖ តើការងារណាខ្លះដែលនាយកដ្ឋាន A ត្រូវផ្តល់ឱ្យនាយកដ្ឋាន B?\n②. [Turnaround Time (TAT)]៖ ពេលវេលាឆ្លើយតបអតិបរមា (ឧ. ពិនិត្យសំណើ IT ក្នុងរយៈពេល ២ ម៉ោង, អនុម័ត PO ក្នុងរយៈពេល ២៤ ម៉ោង)។\n៣. [Quality Metric]៖ ស្តង់ដារគុណភាពអប្បបរមា (ឧ. ភាពត្រឹមត្រូវនៃទិន្នន័យ ៩៩%)។\n៤. [Escalation Protocol]៖ ប្រសិនបើមានការពន្យារពេល តើត្រូវរាយការណ៍ទៅអ្នកណាភ្លាមៗ?', 'បង្កើតសេចក្តីព្រាង Internal SLA មួយទំព័ររវាងនាយកដ្ឋានរបស់អ្នក និងនាយកដ្ឋានមួយទៀតដែលអ្នកឧស្សាហ៍ធ្វើការជាមួយបំផុត។', 'តើនាយកដ្ឋានរបស់អ្នកមាននីតិវិធីស្មុគស្មាញណាខ្លះដែលកំពុងធ្វើឱ្យផ្នែកដទៃរង់ចាំយូរ និងធ្វើឱ្យអតិថិជនខកចិត្ត?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ជួបពិភាក្សាជាមួយ HOD នៃផ្នែកដៃគូ ដើម្បីព្រមព្រៀងលើ Turnaround Time (TAT) ច្បាស់លាស់សម្រាប់ឯកសារបន្ទាន់។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-hod-6', 'lesson-hod-6', 'តើអ្វីជាអត្ថន័យស្នូលនៃទស្សនវិជ្ជា Haier Rendanheyi (人单合一) ក្នុងការកាត់បន្ថយការិយាធិបតេយ្យស្មុគស្មាញ?', 'What is the core principle of the Haier Rendanheyi model in eliminating bureaucratic inertia?', '["A. បង្កើនចំនួនកិច្ចប្រជុំ និងឯកសាររដ្ឋបាលឱ្យកាន់តែច្រើន។","B. តភ្ជាប់បុគ្គលិកគ្រប់រូបដោយផ្ទាល់ទៅនឹងតម្រូវការទីផ្សារ និងអតិថិជន (Zero distance to user) ដោយលុបបំបាត់ការិយាធិបតេយ្យកណ្តាល។","C. បិទក្រុមហ៊ុនចោលហើយចាប់ផ្តើមថ្មី។"]', '["A. Proliferate administrative meetings and paperwork.","B. Connect every employee directly to market outcomes and user needs (Zero distance to user), eliminating bureaucratic layers.","C. Dissolve the enterprise entirely."]', 1, 'ការពន្យល់៖ Rendanheyi លុបបំបាត់បន្ទាយការិយាធិបតេយ្យ ដោយភ្ជាប់បុគ្គលិកគ្រប់ផ្នែកទៅនឹងលទ្ធផលទីផ្សារផ្ទាល់តាមរយៈ Internal SLA និងស្វ័យភាពប្រតិបត្តិការ។', 'Explanation: Rendanheyi smashes bureaucracy by aligning every worker directly with market value delivery.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-hod-7', 'course-hod-strategy', 'mod-1', 7, '៧. ការដឹកនាំការផ្លាស់ប្តូរស្ថាប័ន និងការយកឈ្នះលើការប្រឆាំង (Leading Organizational Change)', 'Change Leadership: Overcoming Resistance & Institutional Inertia (Kotter 8-Step)', 'text', '• យល់ដឹងពីគំរូដឹកនាំការផ្លាស់ប្តូរ ៨ ជំហានរបស់ John Kotter សម្របតាមបរិបទក្រុមហ៊ុនអាស៊ី។\n• បង្កើតអារម្មណ៍បន្ទាន់ពិតប្រាកដ (Sense of Urgency) ដោយមិនបង្កឱ្យមានការភ័យស្លន់ស្លោ។\n• គ្រប់គ្រង និងបំប្លែងបុគ្គលិកដែលប្រឆាំងនឹងការផ្លាស់ប្តូរ (Resistors) ឱ្យក្លាយជាអ្នកគាំទ្រ។', 'មនុស្សភាគច្រើនមិនប្រឆាំងនឹង «ការផ្លាស់ប្តូរ» នោះទេ ប៉ុន្តែពួកគេប្រឆាំងនឹង «ការដែលត្រូវបានគេបង្ខំឱ្យផ្លាស់ប្តូរដោយមិនដឹងមូលហេតុ»។ នៅពេល HOD ដាក់ចេញនូវប្រព័ន្ធថ្មី (ដូចជា ប្រព័ន្ធ ERP ថ្មី ឬរចនាសម្ព័ន្ធការងារថ្មី) បុគ្គលិកចាស់ៗច្រើនតែបង្កើតការតវ៉ាស្ងប់ស្ងាត់ (Passive Resistance)។ មេដឹកនាំយុទ្ធសាស្ត្រមិនប្រើអំណាចបង្ខិតបង្ខំឡើយ ប៉ុន្តែពួកគេកសាង «អារម្មណ៍បន្ទាន់» បង្កើត «ក្រុមសម្ព័ន្ធភាពស្នូល» និងបង្កើត «ជ័យជម្នះរយៈពេលខ្លី (Short-Term Wins)» ដើម្បីទាក់ទាញចិត្តមនុស្ស។', '«លោក សុផាត ជា Head of Operations នៅរោងចក្រកាត់ដេរមួយ។ គាត់ចង់ដាក់ឱ្យប្រើប្រាស់ប្រព័ន្ធឌីជីថលស្កេនបាកូដជំនួសការកត់ត្រាលើក្រដាស។ មេជាងចាស់ៗបានប្រឆាំងយ៉ាងខ្លាំង ដោយធ្វើពុតជាស្កេនមិនកើត និងរអ៊ូរទាំថាពិបាកប្រើជាងក្រដាស។ \nជំនួសឱ្យការដាក់ទណ្ឌកម្ម សុផាតបានអនុវត្តក្បួន Kotter៖ \n១. បង្កើត Sense of Urgency: គាត់បានបង្ហាញតួលេខជាក់ស្តែងថា ដោយសារកត់ត្រាក្រដាសយឺត រោងចក្រត្រូវគេផាកពិន័យ $20,000 កាលពីខែមុន ហើយបើបន្តបែបនេះ រោងចក្រអាចត្រូវបិទទ្វារ។\n②. រក Guiding Coalition: គាត់បានជ្រើសរើសមេជាងវ័យក្មេង ២ នាក់ដែលរហ័សរហួនមកបណ្តុះបណ្តាលឱ្យស្ទាត់ជំនាញមុនគេ។\n៣. បង្កើត Short-Term Win: ក្រុមរបស់មេជាងទាំងពីរបានបញ្ចប់ការងារលឿនជាងមុន ២ ម៉ោង និងទទួលបានប្រាក់រង្វាន់លើកទឹកចិត្ត។ ឃើញលទ្ធផលល្អបែបនេះ មេជាងចាស់ៗដែលធ្លាប់ប្រឆាំង បានស្ម័គ្រចិត្តមករៀនប្រើប្រព័ន្ធថ្មីដោយខ្លួនឯង។»', '✅ ផែនទី ៤ ដំណាក់កាលនៃការដឹកនាំការផ្លាស់ប្តូរ៖\n• ដំណាក់កាល ១ [ភ្ញាក់រលឹក]៖ បង្ហាញពីគ្រោះថ្នាក់នៃការនៅស្ងៀម (The Burning Platform)។\n• ដំណាក់កាល ២ [ទស្សនវិស័យ]៖ គូររូបភាពអនាគតឱ្យច្បាស់ថា តើជីវិតការងារនឹងស្រួលជាងមុនកម្រិតណាពេលផ្លាស់ប្តូររួច។\n• ដំណាក់កាល ៣ [ជ័យជម្នះដំបូង]៖ អនុវត្តសាកល្បងលើក្រុមតូច (Pilot Project) និងអបអរសាទរជោគជ័យដំបូងជាសាធារណៈ។\n• ដំណាក់កាល ៤ [ចាក់ឫស]៖ បញ្ចូលដំណើរការថ្មីនេះទៅក្នុងគោលការណ៍ផ្លូវការរបស់ក្រុមហ៊ុន។', 'ជ្រើសរើសការផ្លាស់ប្តូរថ្មីមួយដែលអ្នកចង់អនុវត្តក្នុងនាយកដ្ឋាន ហើយកំណត់ឈ្មោះបុគ្គលិកគន្លឹះ ៣ នាក់ដែលអ្នកត្រូវទាក់ទាញឱ្យក្លាយជា «ក្រុមសម្ព័ន្ធភាពស្នូល» (Guiding Coalition)។', 'តើគម្រោងផ្លាស់ប្តូរកន្លងមករបស់អ្នកធ្លាប់បរាជ័យដោយសារកង្វះការរៀបចំចិត្តសាស្ត្ររបស់បុគ្គលិកដែរឬទេ?', '🎯 សកម្មភាពថ្ងៃនេះ៖ កំណត់គម្រោងសាកល្បងខ្នាតតូច (Pilot Project) មួយសម្រាប់ការផ្លាស់ប្តូរបន្ទាប់ ដើម្បីបង្កើតជ័យជម្នះដំបូងក្នុងរយៈពេល ៣០ ថ្ងៃ។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-hod-7', 'lesson-hod-7', 'ហេតុអ្វីបានជាការបង្កើត «ជ័យជម្នះរយៈពេលខ្លី» (Short-Term Wins) មានសារៈសំខាន់បំផុតក្នុងដំណើរការផ្លាស់ប្តូរស្ថាប័ន?', 'Why is generating Short-Term Wins critical during organizational change initiatives?', '["A. ដើម្បីឱ្យបុគ្គលិកឈប់ធ្វើការងារបន្ត។","B. ដើម្បីផ្តល់ភស្តុតាងជាក់ស្តែងថាការផ្លាស់ប្តូរពិតជាផ្តល់ផលល្អ កសាងទំនុកចិត្ត និងបំបាក់សំឡេងអ្នករិះគន់ប្រឆាំង។","C. ដើម្បីចំណាយថវិកាឱ្យអស់ពីគម្រោង។"]', '["A. To encourage staff to stop working early.","B. To provide tangible proof that the new way works, building momentum and disarming cynical critics.","C. To exhaust project budget allocations."]', 1, 'ការពន្យល់៖ ជ័យជម្នះរយៈពេលខ្លី (Short-term wins) បង្ហាញភស្តុតាងជាក់ស្តែងដល់មនុស្សដែលកំពុងសង្ស័យ និងផ្តល់ថាមពលដល់ក្រុមការងារដើម្បីបន្តដំណើរទៅមុខទៀត។', 'Explanation: Early quick wins validate the strategic direction and disarm cynical resistance.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-hod-8', 'course-hod-strategy', 'mod-1', 8, '៨. ការកសាងកៅអីបម្រុងថ្នាក់ដឹកនាំ និងជួរអ្នកបន្តវេន (Talent Pipeline & Bench Strength)', 'Building Leadership Bench Strength: Talent Pipelines & Succession Planning for HODs', 'text', '• យល់ដឹងពីម៉ាទ្រីស 9-Box Talent Grid សម្រាប់ការវាយតម្លៃសក្តានុពល និងលទ្ធផលការងាររបស់បុគ្គលិក។\n• បង្កើតកៅអីបម្រុងថ្នាក់ដឹកនាំ (Bench Strength) ធានាថារាល់តំណែង Supervisor/Manager សុទ្ធតែមានអ្នកត្រៀមខ្លួនជំនួស។\n• កាត់បន្ថយហានិភ័យអាជីវកម្មនៅពេលមានបុគ្គលិកសំខាន់លាលែងពីការងារភ្លាមៗ (Single Point of Failure Risk)។', 'ភាពខ្លាំងរបស់នាយកដ្ឋានមិនត្រូវបានវាស់វែងត្រឹមតែលើទិន្នផលបច្ចុប្បន្ននោះទេ ប៉ុន្តែត្រូវបានវាស់វែងលើ «ជម្រៅនៃកៅអីបម្រុងថ្នាក់ដឹកនាំ» (Leadership Bench Strength)។ ប្រសិនបើនាយកដ្ឋានរបស់អ្នកមាន Manager ឬ Supervisor ម្នាក់លាលែងពីការងារ ហើយនាយកដ្ឋានទាំងមូលត្រូវគាំងស្ទះអស់រយៈពេល ៣ ខែ នោះមានន័យថា HOD បានបរាជ័យក្នុងការគ្រប់គ្រងធនធានមនុស្ស។ HOD ឆ្នើមតែងតែដឹងច្បាស់ថានរណាជាអ្នកត្រៀមខ្លួនឡើងជំនួសតំណែងសំខាន់ៗជានិច្ច។', '«នៅក្នុងក្រុមហ៊ុនធានារ៉ាប់រងមួយ ស្រាប់តែ Finance Manager និង Senior Tax Accountant បានសម្រេចចិត្តលាលែងពីការងារដំណាលគ្នាក្នុងខែធ្នូ ដែលជាខែត្រូវបិទបញ្ជីប្រចាំឆ្នាំ។ \nសំណាងល្អ លោក គង់ សម្បត្តិ ដែលជា Head of Finance & Strategy បានអនុវត្តប្រព័ន្ធ 9-Box Grid តាំងពីមួយឆ្នាំមុន។ គាត់បានកំណត់ទុកជាមុននូវ Junior Manager ម្នាក់ និង Senior Analyst ម្នាក់ជា "High Potential Talent (HiPo)" ហើយបានបង្វឹកពួកគេឱ្យកាន់ការងារស្នូល ៣០% រួចជាស្រេច។ នៅពេលអ្នកចាស់ចាកចេញ គាត់បានតែងតាំងអ្នកទាំងពីរឡើងកាន់តំណែងភ្លាមៗដោយគ្មានការរអាក់រអួលសូម្បីតែមួយថ្ងៃ។ របាយការណ៍បិទបញ្ជីឆ្នាំត្រូវបានបញ្ចប់ទាន់ពេល ១០០% ហើយ Board of Directors បានកោតសរសើរសម្បត្តិជាខ្លាំងចំពោះការរៀបចំទុកជាមុនដ៏អស្ចារ្យនេះ។»', '✅ របៀបប្រើប្រាស់ 9-Box Talent Matrix៖\n• អ័ក្ស X៖ លទ្ធផលការងារ (Performance: ទាប, មធ្យម, ខ្ពស់)\n• អ័ក្ស Y៖ សក្តានុពលរីកចម្រើន (Potential: ទាប, មធ្យម, ខ្ពស់)\n• ប្រអប់កំពូលស្តាំ (High Performance + High Potential)៖ នេះជា Star Talent ដែលត្រូវរៀបចំផែនការឡើងជា Leader ក្នុងរយៈពេល ៦-១២ ខែខាងមុខ។\n• ច្បាប់ការពារហានិភ័យ៖ រាល់តួនាទីគន្លឹះ (Key Roles) ត្រូវតែមានបេក្ខជនបម្រុងយ៉ាងហោចណាស់ ១ នាក់ (Ready Now) និង ១ នាក់ទៀត (Ready in 1-2 years)។', 'គូរតារាង 9-Box Talent Matrix សម្រាប់ក្រុមការងារគ្រប់គ្រងរបស់អ្នក ហើយកំណត់ថាតើនរណាខ្លះជាបេក្ខជន Ready-Now សម្រាប់តំណែងសំខាន់ៗ។', 'ប្រសិនបើ Manager ឬអ្នកជំនាញសំខាន់បំផុតក្នុងនាយកដ្ឋានរបស់អ្នកលាលែងពីការងារនៅថ្ងៃស្អែក តើអ្នកមានអ្នកណាដែលអាចឡើងជំនួសបានភ្លាមៗដែរឬទេ?', '🎯 សកម្មភាពថ្ងៃនេះ៖ កំណត់តួនាទីគន្លឹះចំនួន ២ ក្នុងនាយកដ្ឋានរបស់អ្នកដែលងាយរងគ្រោះបំផុត ហើយចាប់ផ្តើមផែនការបង្វឹកអ្នកបន្តវេន។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-hod-8', 'lesson-hod-8', 'តើអ្វីជាគោលបំណងចម្បងនៃការកសាង Bench Strength ក្នុងនាយកដ្ឋាន?', 'What is the primary strategic purpose of building leadership bench strength?', '["A. ដើម្បីជួលមនុស្សឱ្យច្រើនលើសតម្រូវការ។","B. ដើម្បីការពារកុំឱ្យនាយកដ្ឋានគាំងស្ទះនៅពេលមានការលាលែង និងធានាថាមានថ្នាក់ដឹកនាំជំនាន់ក្រោយត្រៀមខ្លួនបន្តវេនជានិច្ច។","C. ដើម្បីកាត់បន្ថយប្រាក់ខែរបស់អ្នកចាស់។"]', '["A. To overhire redundant staff.","B. To insulate the organization from disruption when key talent departs and ensure a continuous pipeline of vetted future leaders.","C. To depress senior salaries."]', 1, 'ការពន្យល់៖ Bench Strength ការពារស្ថាប័នពីហានិភ័យនៃការបាត់បង់បុគ្គលិកគន្លឹះភ្លាមៗ (Continuity of Leadership)។', 'Explanation: Bench strength eliminates single-point-of-failure talent dependencies across critical business workflows.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-hod-9', 'course-hod-strategy', 'mod-1', 9, '៩. ការទំនាក់ទំនងក្នុងគ្រាអាសន្ន និងការតម្រឹមម្ចាស់ភាគហ៊ុន (Crisis Management & Alignment)', 'Crisis Leadership & Executive Stakeholder Management under Pressure', 'text', '• យល់ដឹងពីក្បួនគ្រប់គ្រងវិបត្តិ (Crisis Management Protocol) ក្នុងនាមជាប្រធាននាយកដ្ឋាន។\n• រក្សាភាពស្ងប់ស្ងាត់ និងទំនាក់ទំនងប្រកបដោយតម្លាភាពជាមួយ C-Suite និងអតិថិជនក្នុងគ្រាអាសន្ន។\n• បង្កើត War Room សម្រាប់ការសម្រេចចិត្តរហ័ស និងកាត់បន្ថយការខូចខាតកេរ្តិ៍ឈ្មោះស្ថាប័ន។', 'ក្នុងគ្រាធម្មតា មនុស្សគ្រប់គ្នាសុទ្ធតែអាចធ្វើជាមេដឹកនាំបាន ប៉ុន្តែនៅក្នុង «គ្រាអាសន្ន» (ដូចជា ប្រព័ន្ធទិន្នន័យត្រូវ Hack, ផលិតផលមានបញ្ហាសុខភាព, ឬវិបត្តិហិរញ្ញវត្ថុ) ទើបតម្លៃពិតរបស់ HOD ត្រូវបានលាតត្រដាង។ មេដឹកនាំទន់ខ្សោយនឹងភ័យស្លន់ស្លោ លាក់បាំងការពិត ឬបន្ទោសបុគ្គលិកជួរមុខ។ រីឯ HOD កម្រិតខ្ពស់នឹងបង្កើត War Room ភ្លាមៗ គ្រប់គ្រងលំហូរព័ត៌មាន និងរាយការណ៍ជូន C-Suite ដោយភាពស្មោះត្រង់ រឹងមាំ និងមានដំណោះស្រាយច្បាស់លាស់។', '«នៅធនាគារមួយ ប្រព័ន្ធ Core Banking បានជួបបញ្ហាគាំងនៅថ្ងៃបើកប្រាក់ខែចុងខែ ធ្វើឱ្យអតិថិជនរាប់ម៉ឺននាក់មិនអាចដកលុយបាន ហើយបណ្តាញសង្គមចាប់ផ្តើមផ្ទុះកំហឹងយ៉ាងខ្លាំង។ \nលោក សុវណ្ណារិទ្ធ ជា Head of Technology មិនបានភ័យស្លន់ស្លោឡើយ។ គាត់បានបង្កើត War Room ក្នុងរយៈពេល ១៥ នាទី៖ \n១. គាត់ចាត់តាំងក្រុមវិស្វករជំនាញឱ្យផ្តោតតែលើការជួសជុលកូដដោយគ្មានការរំខាន។\n②. គាត់បានទូរស័ព្ទរាយការណ៍ផ្ទាល់ជូន CEO រៀងរាល់ ៣០ នាទីម្តងជាមួយនឹងទិន្នន័យពិតប្រាកដ និងពេលវេលារំពឹងទុក។\n៣. គាត់បានសហការជាមួយផ្នែក PR ចេញសេចក្តីថ្លែងការណ៍សុំទោសជាសាធារណៈភ្លាមៗ និងធានាសុវត្ថិភាពសមតុល្យលុយ ១០០%។ \nប្រព័ន្ធត្រូវបានជួសជុលរួចរាល់ក្នុងរយៈពេល ៣ ម៉ោង។ ដោយសារភាពជាអ្នកដឹកនាំដ៏ស្ងប់ស្ងាត់ និងតម្លាភាពរបស់សុវណ្ណារិទ្ធ ធនាគារមិនត្រឹមតែមិនបាត់បង់ទំនុកចិត្តពីអតិថិជនទេ ថែមទាំងទទួលបានការកោតសរសើរពីធនាគារជាតិនៃកម្ពុជាចំពោះការគ្រប់គ្រងវិបត្តិដ៏មានវិជ្ជាជីវៈ។»', '✅ ច្បាប់មាស ៤ យ៉ាងក្នុងការគ្រប់គ្រងវិបត្តិ (Crisis Communication Rules)៖\n១. [Tell it Fast]៖ រាយការណ៍ដំណឹងពិតឱ្យបានលឿនបំផុត កុំលាក់បាំង។\n២. [Tell it All]៖ និយាយការពិតទាំងអស់ កុំឱ្យគេដឹងតាមរយៈអ្នកខាងក្រៅ។\n៣. [Tell it with Empathy]៖ បង្ហាញការសោកស្តាយ និងការយល់ចិត្តចំពោះអ្នករងផលប៉ះពាល់ជាមុនសិន។\n៤. [Show the Fix]៖ បង្ហាញសកម្មភាពជាក់ស្តែងដែលកំពុងដោះស្រាយ និងវិធានការការពារកុំឱ្យកើតឡើងម្តងទៀត។', 'បង្កើតផែនការឆ្លើយតបគ្រាអាសន្ន (Emergency Action Plan) មួយទំព័រសម្រាប់ហានិភ័យធំបំផុតដែលអាចកើតឡើងក្នុងនាយកដ្ឋានរបស់អ្នក។', 'តើអ្នកមានប្រតិកម្មបែបណាពេលមានរឿងបន្ទាន់កើតឡើង? តើអ្នកមានភាពស្ងប់ស្ងាត់គ្រប់គ្រាន់ដើម្បីដឹកនាំអ្នកដទៃដែរឬទេ?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ពិនិត្យមើលបញ្ជីទំនាក់ទំនងបន្ទាន់ (Crisis Contact Tree) របស់នាយកដ្ឋានអ្នក ដើម្បីធានាថាអាចទាក់ទងគ្នាបាន ២៤/៧។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-hod-9', 'lesson-hod-9', 'នៅពេលមានវិបត្តិធ្ងន់ធ្ងរកើតឡើងក្នុងនាយកដ្ឋាន តើកំហុសដ៏ធំបំផុតដែល HOD មិនត្រូវប្រព្រឹត្តជាដាច់ខាតគឺជាអ្វី?', 'During a major departmental crisis, what is the gravest mistake an HOD must strictly avoid?', '["A. រៀបចំកិច្ចប្រជុំបន្ទាន់ដើម្បីដោះស្រាយ។","B. លាក់បាំងដំណឹងអាក្រក់ពី CEO/Board ដោយសង្ឃឹមថាអាចដោះស្រាយស្ងាត់ៗបានមុនពេលគេដឹង។","C. ចេញមុខសុំទោសអតិថិជន។"]', '["A. Convening an urgent response team.","B. Concealing bad news from executive leadership hoping to resolve it quietly before detection.","C. Issuing a public apology."]', 1, 'ការពន្យល់៖ គ្មានអ្វីបំផ្លាញទំនុកចិត្តរបស់ C-Suite និង Board លឿនជាងការលាក់បាំងដំណឹងអាក្រក់ក្នុងគ្រាវិបត្តិនោះឡើយ។ តម្លាភាព និងល្បឿនគឺជាគន្លឹះ។', 'Explanation: Concealing severity forfeits leadership credibility; early transparency maintains executive trust.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-hod-10', 'course-hod-strategy', 'mod-1', 10, '១០. ការបង្កើតទស្សនវិស័យរយៈពេលវែង និងការបណ្តុះការច្នៃប្រឌិត (Long-Term Vision & Innovation)', 'Long-Term Strategic Vision & Innovation Incubation: Preparing for Industry Disruption', 'text', '• យល់ដឹងពីរបៀបបង្កើតទស្សនវិស័យរយៈពេល ៣ ទៅ ៥ ឆ្នាំសម្រាប់នាយកដ្ឋាន (Vision 2030)។\n• បង្កើតប្រព័ន្ធបណ្តុះគំនិតច្នៃប្រឌិតថ្មីៗ (Innovation Sandbox & 20% Time)។\n• ត្រៀមខ្លួនទប់ទល់នឹងរលកនៃការផ្លាស់ប្តូរបច្ចេកវិទ្យា (AI, Automation, Market Disruption)។', 'នាយកដ្ឋានដែលរវល់តែ «ពន្លត់ភ្លើង» នឹងការងារប្រតិបត្តិការប្រចាំថ្ងៃ ដោយមិនបានមើលទៅអនាគត នឹងត្រូវសាបរលាប ឬត្រូវជំនួសដោយបច្ចេកវិទ្យាស្វ័យប្រវត្តិនាពេលខាងមុខ។ HOD ឆ្នើមត្រូវតែបែងចែកខួរក្បាលជាពីរ៖ ៨០% សម្រាប់គ្រប់គ្រងប្រតិបត្តិការបច្ចុប្បន្នឱ្យរឹងមាំ និង ២០% សម្រាប់ «សម្លឹងមើលទៅអនាគត» — សាកល្បងឧបករណ៍ថ្មីៗ ស្រាវជ្រាវគំរូអាជីវកម្មថ្មី និងបណ្តុះបណ្តាលបុគ្គលិកឱ្យមានជំនាញនៃអនាគត។', '«លោកស្រី មុនីរ័ត្ន ជា Head of Finance នៅក្រុមហ៊ុនផ្គត់ផ្គង់ចំណីអាហារ។ កាលពី ៣ ឆ្នាំមុន ខណៈដែលក្រុមហ៊ុនដទៃទៀតនៅតែប្រើប្រាស់ការកត់ត្រាវិក្កយបត្រក្រដាស នាងបានមើលឃើញពីទិសដៅនៃបច្ចេកវិទ្យា AI OCR និង E-Invoicing។ \nនាងបានបង្កើតគម្រោងសាកល្បងតូចមួយ (Innovation Sandbox) ដោយចាត់តាំងគណនេយ្យករវ័យក្មេង ២ នាក់ឱ្យស្រាវជ្រាវ និងសាកល្បងប្រើប្រាស់ AI ក្នុងការស្កេនវិក្កយបត្រស្វ័យប្រវត្តិ។ នៅពេលរដ្ឋាភិបាលប្រកាសដាក់ឱ្យអនុវត្តច្បាប់វិក្កយបត្រអេឡិចត្រូនិកជាផ្លូវការ ក្រុមហ៊ុនរបស់នាងបានត្រៀមខ្លួនរួចរាល់ ១០០% ស្រេចទៅហើយ ខណៈដែលគូប្រជែងត្រូវចំណាយពេល ៦ ខែរញ៉េរញ៉ៃ។ ភាពមើលឃើញវែងឆ្ងាយនេះបានជួយឱ្យនាងត្រូវបានតែងតាំងជា Chief Financial Officer (CFO) របស់ក្រុមហ៊ុន។»', '✅ របៀបរៀបចំ Innovation Sandbox ក្នុងនាយកដ្ឋាន៖\n១. [Allocate 10% Time]៖ អនុញ្ញាតឱ្យបុគ្គលិកចំណាយពេលកន្លះថ្ងៃក្នុងមួយសប្តាហ៍ដើម្បីស្រាវជ្រាវបច្ចេកវិទ្យា ឬវិធីសាស្ត្រថ្មីៗ។\n②. [Safe to Fail]៖ បង្កើតគម្រោងតូចៗដែលអនុញ្ញាតឱ្យមានការបរាជ័យបានដោយមិនមានការពិន័យ។\n៣. [Scale Successes]៖ គម្រោងណាដែលជោគជ័យ ត្រូវពង្រីកឱ្យក្លាយជាស្តង់ដារអនុវត្តទូទាំងនាយកដ្ឋាន។', 'សរសេរសេចក្តីព្រាងទស្សនវិស័យ ៣ ឆ្នាំសម្រាប់នាយកដ្ឋានរបស់អ្នក៖ តើនាយកដ្ឋានរបស់អ្នកនឹងមានការផ្លាស់ប្តូរមុខមាត់បែបណាក្នុងរយៈពេល ៣ ឆ្នាំខាងមុខ?', 'តើបច្ចេកវិទ្យាថ្មីៗ (ដូចជា AI) អាចជំនួសការងារ ៥០% នៃនាយកដ្ឋានរបស់អ្នកក្នុងរយៈពេល ៣ ឆ្នាំខាងមុខដែរឬទេ? តើអ្នកបានរៀបចំបណ្តុះបណ្តាលបុគ្គលិកហើយឬនៅ?', '🎯 សកម្មភាពថ្ងៃនេះ៖ កំណត់ឧបករណ៍បច្ចេកវិទ្យាថ្មីមួយ (ឧ. AI tool) ហើយសាកល្បងឱ្យក្រុមការងារយកមកប្រើសាកល្បងក្នុងកិច្ចការតូចមួយនៅសប្តាហ៍នេះ។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-hod-10', 'lesson-hod-10', 'ហេតុអ្វីបានជា HOD ត្រូវតែបែងចែកពេលវេលាខ្លះសម្រាប់ស្រាវជ្រាវការច្នៃប្រឌិតថ្មីៗ (Innovation) ទោះបីជានាយកដ្ឋានកំពុងមមាញឹកខ្លាំងក៏ដោយ?', 'Why must an HOD allocate bandwidth for innovation even while current operations are fully stretched?', '["A. ដើម្បីកុំឱ្យបុគ្គលិកមានអារម្មណ៍ថាទំនេរពេក។","B. ដើម្បីការពារកុំឱ្យនាយកដ្ឋាន និងក្រុមហ៊ុនត្រូវហួសសម័យ ឬត្រូវកម្ទេចដោយការផ្លាស់ប្តូរបច្ចេកវិទ្យា និងគូប្រជែងថ្មីៗនាពេលអនាគត។","C. ដើម្បីទាក់ទាញការចាប់អារម្មណ៍ពីអ្នកកាសែត។"]', '["A. To keep staff looking occupied.","B. To future-proof the department against sudden technological disruption, obsolescence, and aggressive emerging market competitors.","C. To attract press attention."]', 1, 'ការពន្យល់៖ បើមិនបង្កើតថ្មី នឹងត្រូវស្លាប់ (Innovate or Die)។ HOD ត្រូវតែរៀបចំស្ថាប័នឱ្យរួចរាល់សម្រាប់អនាគត មិនមែនគ្រាន់តែរស់នៅជាមួយអតីតកាលនោះទេ។', 'Explanation: Proactive innovation shields the enterprise against external obsolescence and disruption.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-dir-1', 'course-director-governance', 'mod-1', 1, '១. អភិបាលកិច្ចស្ថាប័ន និងការគ្រប់គ្រងហានិភ័យ (Enterprise Governance & Risk Management)', 'Corporate Governance, Compliance & Enterprise Risk Management', 'text', '• យល់ដឹងពីសសរស្តម្ភនៃអភិបាលកិច្ចល្អ (Transparency, Accountability, Fairness)។\n• កសាងម៉ាទ្រីសគ្រប់គ្រងហានិភ័យស្ថាប័ន (Enterprise Risk Matrix)៖ ហានិភ័យច្បាប់ ហិរញ្ញវត្ថុ និងប្រតិបត្តិការ។\n• ធានាការអនុលោមតាមច្បាប់ការងារ និងពន្ធដារនៃព្រះរាជាណាចក្រកម្ពុជា។', 'តួនាទី Director មិនមែនគ្រាន់តែជំរុញការលូតលាស់នោះទេ ប៉ុន្តែជាការការពារកុំឱ្យក្រុមហ៊ុនដួលរលំដោយសារហានិភ័យផ្លូវច្បាប់ ពន្ធដារ ឬការគ្រប់គ្រងមិនត្រឹមត្រូវ។', '«លោកជំទាវ ជា សុភាព ជានាយកប្រតិបត្តិការងារ។ មុនពេលក្រុមហ៊ុនចុះហត្ថលេខាលើកិច្ចសន្យាវិនិយោគ $2,000,000 នាងបានដឹកនាំក្រុមការងារធ្វើសវនកម្មផ្ទៃក្នុង (Due Diligence) យ៉ាងម៉ត់ចត់។ នាងបានរកឃើញកំហុសបច្ចេកទេសផ្លូវច្បាប់មួយដែលដៃគូអាជីវកម្មបានលាក់បាំង ដែលអាចធ្វើឱ្យក្រុមហ៊ុនខាតបង់ទឹកប្រាក់យ៉ាងច្រើន។ ការទប់ស្កាត់ទាន់ពេលនេះបានជួយសង្គ្រោះក្រុមហ៊ុនពីហានិភ័យដ៏ធំធេង។»', '✅ គោលការណ៍វាយតម្លៃហានិភ័យមុនពេលសម្រេចចិត្ត៖\n«តើអ្វីជាហានិភ័យអាក្រក់បំផុត (Worst-case scenario) ប្រសិនបើគម្រោងនេះបរាជ័យ? ហើយតើយើងមានផែនការការពារ និងទប់ទល់កម្រិតណា?»', 'សរសេរបញ្ជីហានិភ័យកំពូលទាំង ៣ ដែលស្ថាប័នរបស់អ្នកអាចប្រឈមមុខក្នុងឆ្នាំនេះ និងវិធានការការពារ។', 'តើក្រុមហ៊ុនរបស់អ្នកមានប្រព័ន្ធការពារហានិភ័យ និងការអនុលោមតាមច្បាប់រឹងមាំកម្រិតណា?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ពិនិត្យឡើងវិញនូវគោលការណ៍អនុលោមភាពផ្លូវច្បាប់ ឬសុវត្ថិភាពទិន្នន័យក្នុងស្ថាប័ន។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-dir-1', 'lesson-dir-1', 'តើអ្វីជាទំនួលខុសត្រូវចម្បងរបស់ Director ក្នុងការគ្រប់គ្រងអភិបាលកិច្ចស្ថាប័ន?', 'What is the primary responsibility of a Director in corporate governance?', '["A. ផ្តោតតែលើការរកចំណូលដោយមិនខ្វល់ពីច្បាប់ទម្លាប់។","B. កសាងប្រព័ន្ធតម្លាភាព គណនេយ្យភាព គ្រប់គ្រងហានិភ័យ និងធានានិរន្តរភាពអាជីវកម្មស្របច្បាប់។","C. ទុកកិច្ចការគ្រប់គ្រងហានិភ័យឱ្យបុគ្គលិកថ្នាក់ក្រោមដោះស្រាយតាមការគួរ។"]', '["A. Focus purely on revenue ignoring laws.","B. Build transparent systems, risk management frameworks, and ensure legal and financial sustainability.","C. Leave risk management to junior staff."]', 1, 'ការពន្យល់៖ ជម្រើស B បង្ហាញពីកាតព្វកិច្ច Fiduciary Duty របស់ Director។', 'Explanation: Directors bear fiduciary responsibility for long-term governance and risk mitigation.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-dir-2', 'course-director-governance', 'mod-1', 2, '២. យុទ្ធសាស្ត្រពង្រីកសាខា និងទីផ្សារធុរកិច្ច (Strategic Expansion & Market Penetration)', 'Scaling Operations, Franchising & Regional Market Expansion', 'text', '• យល់ដឹងពីសញ្ញាបង្ហាញថាអាជីវកម្មបានត្រៀមខ្លួនរួចរាល់ក្នុងការពង្រីកសាខា (Readiness for Scale)។\n• ជ្រើសរើសគំរូពង្រីក៖ បើកសាខាផ្ទាល់ (Direct Branch) ឬលក់សិទ្ធិផ្តាច់មុខ (Franchise)។\n• គ្រប់គ្រងខ្សែច្រវាក់ផ្គត់ផ្គង់ និងស្តង់ដារគុណភាពនៅគ្រប់សាខាទាំងអស់។', 'ការពង្រីកអាជីវកម្មលឿនពេកដោយគ្មានប្រព័ន្ធគ្រប់គ្រងរឹងមាំ គឺជាមូលហេតុចម្បងដែលនាំឱ្យក្រុមហ៊ុនធំៗដួលរលំ (Premature Scaling)។ Director ធានាថាក្រុមហ៊ុនពង្រីកដោយឈរលើមូលដ្ឋានគ្រឹះរឹងមាំ។', '«ក្រុមហ៊ុនលក់រាយមួយបានរីកចម្រើនខ្លាំងនៅភ្នំពេញ។ ក្រុមប្រឹក្សាភិបាលចង់បើក ៥ សាខាបន្ថែមភ្លាមៗនៅតាមបណ្តាខេត្ត។ Director បានស្នើឱ្យបើកសាកល្បងតែ ១ សាខាសិននៅខេត្តសៀមរាប ដើម្បីធ្វើតេស្តប្រព័ន្ធដឹកជញ្ជូន និងការបណ្តុះបណ្តាលបុគ្គលិកមូលដ្ឋាន។ ការធ្វើតេស្តនេះបានជួយរកឃើញបញ្ហាកកស្ទះខ្សែច្រវាក់ផ្គត់ផ្គង់ និងបានកែសម្រួលមុនពេលបើក ៤ សាខាផ្សេងទៀត។ យុទ្ធសាស្ត្រពង្រីកដោយប្រុងប្រយ័ត្ននេះបានធ្វើឱ្យគ្រប់សាខាទាំងអស់រកប្រាក់ចំណេញបានចាប់ពីខែដំបូង។»', '✅ របៀបវាយតម្លៃទីតាំងពង្រីកសាខាថ្មី៖\n«យើងត្រូវពិនិត្យ ៣ កត្តា៖ ១. ចរាចរណ៍អតិថិជនគោលដៅ ២. ការចំណាយលើថ្លៃជួលធៀបនឹងចំណូលរំពឹងទុក ៣. សមត្ថភាពដឹកជញ្ជូនផ្គត់ផ្គង់ទំនិញទាន់ពេល។»', 'រៀបចំ Checklist វាយតម្លៃលទ្ធភាពពង្រីកសាខាថ្មីសម្រាប់អាជីវកម្មរបស់អ្នក។', 'តើអាជីវកម្មរបស់អ្នកមានប្រព័ន្ធ SOP រឹងមាំល្មមសម្រាប់ពង្រីកទៅសាខាទី ២ ឬទី ៣ ហើយឬនៅ?', '🎯 សកម្មភាពថ្ងៃនេះ៖ វាយតម្លៃសមត្ថភាពក្រុមការងារបច្ចុប្បន្ន ថាតើមានមនុស្សដែលអាចផ្ទេរទៅដឹកនាំសាខាថ្មីបានដែរឬទេ។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-dir-2', 'lesson-dir-2', 'តើអ្វីជាហានិភ័យធំបំផុតក្នុងការពង្រីកសាខាធុរកិច្ចលឿនពេក (Premature Scaling)?', 'What is the greatest danger of premature business scaling?', '["A. ធ្វើឱ្យម៉ាកសញ្ញាល្បីល្បាញពេក។","B. ខ្វះខាតលំហូរសាច់ប្រាក់ បាត់បង់ស្តង់ដារគុណភាព និងខ្វះអ្នកគ្រប់គ្រងមានសមត្ថភាពគ្រប់គ្រងសាខា។","C. មិនមានហានិភ័យអ្វីឡើយ ពង្រីកកាន់តែលឿនកាន់តែល្អ។"]', '["A. Brand becoming too famous.","B. Cash flow collapse, quality dilution, and shortage of capable managers.","C. There is no risk; faster is always better."]', 1, 'ការពន្យល់៖ ជម្រើស B ពន្យល់ពីមូលហេតុចម្បងនៃការពង្រីកខុសបច្ចេកទេស។', 'Explanation: Premature scaling without systems drains cash and ruins brand reputation.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-director-3', 'course-director-governance', 'mod-1', 3, '៣. សិល្បៈយុទ្ធសាស្ត្រជ្រើសរើសសមរភូមិទីផ្សារ (Sun Tzu: Strategic Terrain & Market Selection)', 'Sun Tzu Art of War: Selecting Strategic Market Terrains (The Nine Terrains)', 'text', '• យល់ដឹងពីទស្សនវិជ្ជាស៊ុនអ៊ូ (Sun Tzu) ជំពូក «ក្បួនដីទាំង ៩ (九地篇)» សម្រាប់ការវាយលុកទីផ្សារថ្មី។\n• ចៀសវាងការប្រយុទ្ធលើ «សមរភូមិសមុទ្រក្រហម» (Red Ocean) ដែលពោរពេញដោយសង្គ្រាមកាត់ថ្លៃ។\n• កំណត់ទីតាំងទីផ្សារដែលជា «ដីយុទ្ធសាស្ត្រគន្លឹះ» (Strategic High Ground) មុនពេលគូប្រជែងដឹងខ្លួន។', 'ទស្សនវិទូយុទ្ធសាស្ត្រ ស៊ុនអ៊ូ បានបង្រៀនថា ជោគជ័យនៃសង្គ្រាមមិនមែនអាស្រ័យលើភាពក្លាហាននោះទេ ប៉ុន្តែអាស្រ័យលើ «ការជ្រើសរើសសមរភូមិ»។ នាយកប្រតិបត្តិការ (Director) ដែលមានចក្ខុវិស័យខ្ពស់មិនដែលរុញក្រុមហ៊ុនឱ្យចូលទៅប្រយុទ្ធក្នុងទីផ្សារដែលគូប្រជែងកំពុងកាន់កាប់រឹងមាំនោះទេ (Do not attack uphill)។ ពួកគេចេះវាយលុកលើចំណុចដែលគូប្រជែងធ្វេសប្រហែស (Attack where they are unprepared) និងដណ្តើមយកទីតាំងយុទ្ធសាស្ត្រដែលចំណេញថ្លៃដើម និងងាយស្រួលការពារ។', '«ក្នុងអំឡុងពេលដែលទីផ្សារភេសជ្ជៈប៉ូវកម្លាំងនៅរាជធានីភ្នំពេញពោរពេញដោយការប្រកួតប្រជែងតម្លៃយ៉ាងសាហាវ លោកស្រី ជា សុភាព ជា Commercial Director នៃក្រុមហ៊ុនផលិតភេសជ្ជៈថ្មីមួយ បានបដិសេធមិនព្រមចំណាយលុយរាប់សែនដុល្លារប្រកួតប្រជែងនៅភ្នំពេញឡើយ។ \nនាងបានអនុវត្តក្បួនស៊ុនអ៊ូ «ចៀសកន្លែងរឹងមាំ វាយកន្លែងទន់ខ្សោយ» (避实击虚)៖ នាងបានដឹកនាំក្រុមការងារទៅវាយលុកផ្តាច់មុខនៅតំបន់ចម្ការកៅស៊ូ និងតំបន់កសិកម្មនៅខេត្តកំពង់ចាម និងត្បូងឃ្មុំ ដែលជាកន្លែងកសិករត្រូវការកម្លាំងពលកម្មធ្ងន់ធ្ងរ ប៉ុន្តែគ្មានក្រុមហ៊ុនណាទៅផ្សព្វផ្សាយផ្ទាល់។ ក្រុមហ៊ុនបានបង្កើតបណ្តាញចែកចាយរឹងមាំនៅជនបទ និងរកប្រាក់ចំណេញរាប់លានដុល្លារ មុនពេលគូប្រជែងនៅភ្នំពេញដឹងខ្លួន។ ក្រោយមក នាងបានយកទុនចំណេញនោះត្រឡប់មកវាយលុកភ្នំពេញដោយជោគជ័យ។»', '✅ ម៉ាទ្រីស ៣ ជំហានក្នុងការជ្រើសរើសសមរភូមិទីផ្សារ៖\n១. [Avoid Stronghold]៖ កុំចូលទៅប្រកួតប្រជែងតម្លៃជាមួយក្រុមហ៊ុនធំដែលកំពុងក្តោបទីផ្សារ ៨០%។\n②. [Find the Blindspot]៖ ស្វែងរកក្រុមអតិថិជនដែលគេមើលរំលង (Underserved Segments)។\n៣. [Fortify the Position]៖ នៅពេលដណ្តើមបានទីតាំងហើយ ត្រូវបង្កើតរនាំងការពារ (Moat) ដូចជា បណ្តាញចែកចាយផ្តាច់មុខ ឬកិច្ចសន្យារយៈពេលវែង។', 'វិភាគផែនទីទីផ្សារបច្ចុប្បន្នរបស់ក្រុមហ៊ុនអ្នក ហើយកំណត់តំបន់ ឬចន្លោះប្រហោងទីផ្សារ (Market White Space) មួយដែលគូប្រជែងកំពុងមើលរំលង។', 'តើក្រុមហ៊ុនរបស់អ្នកកំពុងប្រកួតប្រជែងនៅលើសមរភូមិដែលអ្នកមានប្រៀប ឬកំពុងជាប់ផុងក្នុងសង្គ្រាមកាត់ថ្លៃដែលគ្មានអ្នកឈ្នះ?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ពិនិត្យមើលទិន្នន័យអតិថិជនដើម្បីស្វែងរកចន្លោះប្រហោងទីផ្សារថ្មីមួយដែលគ្មានគូប្រជែងយកចិត្តទុកដាក់។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-director-3', 'lesson-director-3', 'តាមទស្សនវិជ្ជាស៊ុនអ៊ូ «ក្បួនដីទាំង ៩» តើយុទ្ធសាស្ត្រដ៏ឆ្លាតវៃបំផុតរបស់ Director ក្នុងការជ្រើសរើសទីផ្សារគឺជាអ្វី?', 'According to Sun Tzu Nine Terrains, what is the most brilliant market entry strategy?', '["A. បោះទុនទាំងអស់ប្រកួតប្រជែងតម្លៃជាមួយគូប្រជែងធំបំផុតនៅលើសមរភូមិកណ្តាល។","B. ចៀសវាងកន្លែងដែលគូប្រជែងរឹងមាំ ហើយវាយលុកលើកន្លែងដែលទន់ខ្សោយ ឬខ្វះការការពារ (避实击虚 - Avoid strength, strike weakness)។","C. រង់ចាំរហូតដល់គូប្រជែងទាំងអស់ដួលរលំដោយខ្លួនឯង។"]', '["A. Pour all capital into direct price wars against entrenched market leaders on their home turf.","B. Avoid entrenched competitor strongholds and strike unoccupied, underserved market niches (Avoid strength, strike weakness).","C. Passively wait for competitors to collapse on their own."]', 1, 'ការពន្យល់៖ ស៊ុនអ៊ូបង្រៀនឱ្យ «ចៀសកន្លែងរឹងមាំ វាយកន្លែងទន់ខ្សោយ» ដើម្បីដណ្តើមជ័យជម្នះដោយចំណាយកម្លាំងតិចបំផុត និងការពារការខាតបង់ធនធាន។', 'Explanation: Masterful strategy avoids frontal assaults on entrenched incumbents, capturing uncontested market terrain.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-director-4', 'course-director-governance', 'mod-1', 4, '៤. ការគ្រប់គ្រងហានិភ័យស្ថាប័ន និងការត្រៀមទប់ទល់នឹងហេតុការណ៍មិននឹកស្មានដល់ (Enterprise Risk & Black Swan)', 'Enterprise Risk Management (ERM) & Building Antifragile Corporate Defenses', 'text', '• យល់ដឹងពីក្របខ័ណ្ឌគ្រប់គ្រងហានិភ័យស្ថាប័ន COSO ERM Framework។\n• បង្កើតផែនការបន្តនិរន្តរភាពអាជីវកម្ម (Business Continuity Plan - BCP) សម្រាប់ទប់ទល់នឹងព្រឹត្តិការណ៍ Black Swan។\n• ធ្វើតេស្តសាកល្បងភាពធន់នៃស្ថាប័ន (Stress Testing) ចំពោះវិបត្តិសាច់ប្រាក់ និងការរអាក់រអួលនៃខ្សែច្រវាក់ផ្គត់ផ្គង់។', 'នៅក្នុងពិភពលោកដែលពោរពេញដោយភាពមិនប្រាកដប្រជា (VUCA World) ក្រុមហ៊ុនភាគច្រើនមិនដួលរលំដោយសារកង្វះប្រាក់ចំណេញនោះទេ ប៉ុន្តែដួលរលំដោយសារ «ព្រឹត្តិការណ៍ Black Swan» (ហេតុការណ៍កម្រកើតឡើង តែពេលកើតឡើងបង្កមហន្តរាយធ្ងន់ធ្ងរ ដូចជា ជំងឺរាតត្បាត សង្គ្រាម ឬវិបត្តិហិរញ្ញវត្ថុ)។ Director ត្រូវតែជាស្ថាបត្យករនៃភាពធន់ (Antifragility) — រៀបចំទុនបម្រុង ប្រព័ន្ធការពារសុវត្ថិភាព និងផែនការ BCP មុនពេលព្យុះមកដល់។', '«ក្នុងអំឡុងពេលវិបត្តិសេដ្ឋកិច្ចសកល ក្រុមហ៊ុនសំណង់ជាច្រើននៅកម្ពុជាត្រូវក្ស័យធនដោយសារជាប់បំណុលធនាគារ និងគ្មានសាច់ប្រាក់បង្វិល។ \nផ្ទុយទៅវិញ ក្រុមហ៊ុនអភិវឌ្ឍន៍មួយដែលដឹកនាំដោយលោក វីរៈ ជា Risk Director បានរួចផុតពីវិបត្តិនេះយ៉ាងអស្ចារ្យ។ កាលពី ២ ឆ្នាំមុន វីរៈបានជំរុញឱ្យ Board អនុវត្តគោលការណ៍ Stress Testing៖ គាត់បានទាមទារឱ្យក្រុមហ៊ុនរក្សាសាច់ប្រាក់បម្រុងសុទ្ធ (Cash Buffer) ស្មើនឹង ៩ ខែនៃថ្លៃប្រតិបត្តិការ និងបានចរចាកាត់បន្ថយបំណុលរយៈពេលខ្លីទាំងអស់។ \nនៅពេលវិបត្តិបានផ្ទុះឡើង ខណៈដែលគូប្រជែងត្រូវបញ្ឈប់គម្រោង ក្រុមហ៊ុនរបស់វីរៈមិនត្រឹមតែមិនកាត់បន្ថយបុគ្គលិកប៉ុណ្ណោះទេ ថែមទាំងឆ្លៀតឱកាសទិញដីធ្លី និងសម្ភារសំណង់ពីគូប្រជែងក្នុងតម្លៃបញ្ចុះ ៥០%។ ភាពធន់នេះបានធ្វើឱ្យក្រុមហ៊ុនកើនទ្រព្យសម្បត្តិ ៣ ដងក្រោយវិបត្តិបញ្ចប់។»', '✅ ម៉ាទ្រីសគ្រប់គ្រងហានិភ័យស្ថាប័ន (The ERM Risk Register)៖\n• អ័ក្ស ១ [លទ្ធភាពកើតឡើង]៖ ទាប, មធ្យម, ខ្ពស់\n• អ័ក្ស ២ [ទំហំនៃផលប៉ះពាល់]៖ ស្រាល, មធ្យម, មហន្តរាយ\n• ហានិភ័យកម្រិតក្រហម (Impact ធ្ងន់ធ្ងរ ទោះលទ្ធភាពទាប)៖ ត្រូវតែមាន Business Continuity Plan (BCP) និងទុនបម្រុងដាច់ខាត។', 'បង្កើត Risk Register សម្រាប់ស្ថាប័នរបស់អ្នក ដោយកំណត់ហានិភ័យធំបំផុត ៣ (ហិរញ្ញវត្ថុ ប្រតិបត្តិការ ច្បាប់) និងវិធានការការពារជាមុន។', 'ប្រសិនបើស្ថាប័នរបស់អ្នកគ្មានចំណូលសូម្បីតែ ១ ដុល្លារក្នុងរយៈពេល ៦ ខែខាងមុខ តើសាច់ប្រាក់បម្រុងបច្ចុប្បន្នអាចទប់ទល់បានដែរឬទេ?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ពិនិត្យឡើងវិញនូវទំហំសាច់ប្រាក់បម្រុងបន្ទាន់ (Emergency Cash Reserves) របស់ក្រុមហ៊ុនជាមួយ CFO។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-director-4', 'lesson-director-4', 'តើអ្វីជាគោលបំណងចម្បងនៃផែនការនិរន្តរភាពអាជីវកម្ម (Business Continuity Plan - BCP)?', 'What is the primary objective of a Business Continuity Plan (BCP)?', '["A. ដើម្បីបំពេញឯកសារចោលឱ្យសវនករមើល។","B. ដើម្បីធានាថាប្រតិបត្តិការស្នូលរបស់ក្រុមហ៊ុននៅតែអាចដំណើរការបានជាបន្តបន្ទាប់នៅពេលមានមហន្តរាយ ឬវិបត្តិធ្ងន់ធ្ងរកើតឡើង។","C. ដើម្បីកាត់បន្ថយការបង់ពន្ធរដ្ឋ។"]', '["A. To satisfy formal audit paperwork checklists.","B. To guarantee that critical operational workflows persist without interruption during systemic catastrophes or economic shocks.","C. To evade corporate taxes."]', 1, 'ការពន្យល់៖ BCP ធានាការរស់រានមានជីវិតរបស់ស្ថាប័នក្នុងគ្រាអាសន្ន ការពារទ្រព្យសម្បត្តិ និងកេរ្តិ៍ឈ្មោះរបស់ក្រុមហ៊ុន។', 'Explanation: BCP guarantees organizational survival and continuous core value delivery during catastrophic shocks.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-director-5', 'course-director-governance', 'mod-1', 5, '៥. អភិបាលកិច្ចស្ថាប័ន និងការគ្រប់គ្រងគណៈកម្មាធិការក្រុមប្រឹក្សាភិបាល (Board Committee Governance)', 'Corporate Governance & Board Oversight: Audit, Remuneration, and Nomination', 'text', '• យល់ដឹងពីរចនាសម្ព័ន្ធអភិបាលកិច្ចស្តង់ដារអន្តរជាតិ (OECD Principles of Corporate Governance)។\n• ស្គាល់ពីតួនាទីគន្លឹះនៃគណៈកម្មាធិការទាំង ៣៖ សវនកម្ម (Audit), ជ្រើសរើសតាំង (Nomination), និងបំណាច់ (Remuneration)។\n• ការពារទំនាស់ផលប្រយោជន៍ (Conflict of Interest) រវាងម្ចាស់ភាគហ៊ុន និងគណៈគ្រប់គ្រង។', 'ក្រុមហ៊ុនគ្រួសារជាច្រើនមិនអាចពង្រីកខ្លួនឱ្យធំបាន ឬមិនអាចចូលផ្សារហ៊ុន (IPO) បានឡើយ ដោយសារកង្វះប្រព័ន្ធអភិបាលកិច្ច (Corporate Governance)៖ ម្ចាស់ក្រុមហ៊ុនដកលុយតាមតែចិត្ត គ្មានសវនកម្មឯករាជ្យ និងតែងតាំងសាច់ញាតិដោយគ្មានសមត្ថភាព។ Director ត្រូវតែកសាងប្រព័ន្ធអភិបាលកិច្ចរឹងមាំ ដែលញែកឱ្យដាច់រវាង «កម្មសិទ្ធិរបស់ម្ចាស់ (Ownership)» និង «ការគ្រប់គ្រងអាជីវកម្ម (Management)» ដើម្បីកសាងទំនុកចិត្តដល់អ្នកវិនិយោគអន្តរជាតិ។', '«ក្រុមហ៊ុនពាណិជ្ជកម្មខ្នាតធំមួយនៅភ្នំពេញចង់ទាក់ទាញទុនវិនិយោគ $20,000,000 ពីមូលនិធិវិនិយោគជប៉ុន។ ទោះបីជាក្រុមហ៊ុនលក់ដាច់ខ្លាំងក៏ដោយ ប៉ុន្តែអ្នកវិនិយោគជប៉ុនបានបដិសេធមិនព្រមដាក់ទុនទេ ព្រោះរកឃើញថា ប្រធានក្រុមហ៊ុនតែងតែចុះហត្ថលេខាផ្ទេរប្រាក់ក្រុមហ៊ុនចូលគណនីផ្ទាល់ខ្លួន ហើយគណៈកម្មាធិការសវនកម្មផ្ទៃក្នុងគ្មានអំណាចឯករាជ្យ។ \nលោក សុខុន ដែលត្រូវបានតែងតាំងជា Governance Director បានធ្វើការកែទម្រង់ប្រព័ន្ធអភិបាលកិច្ចទាំងស្រុង៖ គាត់បានបង្កើតគណៈកម្មាធិការសវនកម្មឯករាជ្យ (Independent Audit Committee) ជួលក្រុមហ៊ុនសវនកម្ម Big 4 មកធ្វើសវនកម្មប្រចាំឆ្នាំ និងបង្កើតគោលការណ៍តឹងរ៉ឹងស្តីពីទំនាស់ផលប្រយោជន៍។ មួយឆ្នាំក្រោយមក ក្រុមហ៊ុនជប៉ុនបានយល់ព្រមបណ្តាក់ទុន $25,000,000 ដោយផ្តល់តម្លៃក្រុមហ៊ុន (Valuation) ខ្ពស់ជាងមុន ៤០%។»', '✅ សសរស្តម្ភ ៣ នៃអភិបាលកិច្ចស្ថាប័នកម្រិតស្តង់ដារ៖\n១. [Audit Committee]៖ ត្រួតពិនិត្យភាពត្រឹមត្រូវនៃរបាយការណ៍ហិរញ្ញវត្ថុ និងប្រព័ន្ធគ្រប់គ្រងផ្ទៃក្នុង។\n②. [Nomination Committee]៖ ជ្រើសរើសតែងតាំងថ្នាក់ដឹកនាំជាន់ខ្ពស់ដោយឈរលើសមត្ថភាព និងគុណសម្បត្តិ មិនមែនបក្សពួកនិយម។\n៣. [Remuneration Committee]៖ កំណត់ប្រាក់បំណាច់ និងភាគហ៊ុនលើកទឹកចិត្តដល់ C-Suite ដោយផ្អែកលើលទ្ធផលការងារជាក់ស្តែង។', 'ពិនិត្យមើលរចនាសម្ព័ន្ធអភិបាលកិច្ចបច្ចុប្បន្នរបស់ក្រុមហ៊ុនអ្នក ហើយកំណត់ចំណុចខ្វះខាតធំៗ ២ ដែលត្រូវការកែសម្រួលដើម្បីត្រៀមទាក់ទាញទុនវិនិយោគ។', 'តើការសម្រេចចិត្តក្នុងស្ថាប័នរបស់អ្នកកំពុងពឹងផ្អែកលើ «អារម្មណ៍របស់បុគ្គលម្នាក់» ឬលើ «ប្រព័ន្ធអភិបាលកិច្ច និងច្បាប់ច្បាស់លាស់»?', '🎯 សកម្មភាពថ្ងៃនេះ៖ រៀបចំសេចក្តីព្រាងគោលការណ៍ទំនាស់ផលប្រយោជន៍ (Conflict of Interest Policy) សម្រាប់ថ្នាក់ដឹកនាំស្ថាប័ន។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-director-5', 'lesson-director-5', 'ហេតុអ្វីបានជាអ្នកវិនិយោគស្ថាប័នអន្តរជាតិ (Institutional Investors) តែងតែទាមទារឱ្យមានប្រព័ន្ធអភិបាលកិច្ចឯករាជ្យ (Good Governance)?', 'Why do international institutional investors mandate robust independent corporate governance?', '["A. ដើម្បីធ្វើឱ្យដំណើរការការងារមានភាពស្មុគស្មាញ និងយឺតយ៉ាវ។","B. ដើម្បីការពារទ្រព្យសម្បត្តិវិនិយោគ កាត់បន្ថយហានិភ័យក្លែងបន្លំ និងធានាតម្លាភាពហិរញ្ញវត្ថុយូរអង្វែង។","C. ដើម្បីដណ្តើមយកអាជីវកម្មពីម្ចាស់ដើម។"]', '["A. To deliberately slow down operations.","B. To protect investor capital, prevent fraud, and ensure long-term fiduciary transparency and fair returns.","C. To forcefully seize the business."]', 1, 'ការពន្យល់៖ អភិបាលកិច្ចល្អការពារទ្រព្យសម្បត្តិម្ចាស់ភាគហ៊ុន ការពារការក្លែងបន្លំ និងបង្កើនតម្លៃក្រុមហ៊ុននៅក្នុងទីផ្សារទុន។', 'Explanation: Robust governance reduces fraud risk, protects minority shareholders, and unlocks valuation premiums.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-director-6', 'course-director-governance', 'mod-1', 6, '៦. ការទិញ-ច្របាច់បញ្ចូលអាជីវកម្ម និងការត្រួតពិនិត្យវប្បធម៌ (M&A & Cultural Due Diligence)', 'Mergers & Acquisitions (M&A): Financial, Legal & Cultural Integration Mastery', 'text', '• យល់ដឹងពីដំណើរការទិញ-ច្របាច់បញ្ចូលអាជីវកម្ម (M&A Process: Screening, Due Diligence, Valuation, Integration)។\n• ចៀសវាងមូលហេតុលេខ ១ នៃការបរាជ័យ M&A៖ ភាពមិនស៊ីគ្នានៃវប្បធម៌ (Cultural Rejection)។\n• រៀបចំផែនការច្របាច់បញ្ចូលក្រោយការទិញ (Post-Merger Integration - PMI) ក្នុងរយៈពេល ១០០ ថ្ងៃដំបូង។', 'ការសិក្សាផ្នែកហិរញ្ញវត្ថុបង្ហាញថា ជាង ៧០% នៃកិច្ចព្រមព្រៀងទិញ-ច្របាច់បញ្ចូលអាជីវកម្ម (M&A) ជុំវិញពិភពលោកត្រូវបរាជ័យក្នុងការបង្កើតតម្លៃ។ មូលហេតុមិនមែនដោយសារតួលេខហិរញ្ញវត្ថុខុសនោះទេ ប៉ុន្តែដោយសារ «ការច្រានចោលខាងវប្បធម៌» (Culture Clash) រវាងស្ថាប័នទាំងពីរ។ Director ឆ្នើមត្រូវតែធ្វើការត្រួតពិនិត្យវប្បធម៌ (Cultural Due Diligence) ឱ្យបានម៉ត់ចត់ស្មើនឹងការពិនិត្យបញ្ជីគណនេយ្យ និងច្បាប់។', '«ក្រុមហ៊ុនផ្គត់ផ្គង់ភស្តុភារកម្ម (Logistics) ធំមួយបានចំណាយប្រាក់ $8,000,000 ទិញយកក្រុមហ៊ុនដឹកជញ្ជូនរហ័សបែបបច្ចេកវិទ្យាវ័យក្មេងមួយ។ ក្រុមហិរញ្ញវត្ថុបានគណនាថាក្រុមហ៊ុននឹងចំណេញយ៉ាងសម្បើម។ \nប៉ុន្តែក្រោយទិញរួច ក្រុមហ៊ុនមេបានបង្ខំឱ្យបុគ្គលិកបច្ចេកវិទ្យាវ័យក្មេងស្លៀកពាក់ឯកសណ្ឋានតឹងរ៉ឹង ស្កេនមេដៃម៉ោង ៧:៣០ ព្រឹក និងបំពេញឯកសាររដ្ឋបាលរាប់សិបទំព័ររាល់ពេលចង់កែកូដ។ ត្រឹមតែ ៤ ខែ ក្រុមវិស្វករសំខាន់ៗ ៨០% បាននាំគ្នាលាលែងពីការងារ ធ្វើឱ្យប្រព័ន្ធ App គាំងដំណើរការ ហើយក្រុមហ៊ុនមេត្រូវខាតបង់ប្រាក់វិនិយោគទាំងស្រុង។ ក្រោយមក ក្រុមហ៊ុនទើបយល់ថា "ការទិញក្រុមហ៊ុន គឺការទិញមនុស្ស និងវប្បធម៌ បើកម្ទេចវប្បធម៌របស់គេ នោះអ្វីៗដែលទិញបាននឹងក្លាយជាធូលីដី"។»', '✅ បញ្ជីត្រួតពិនិត្យ Post-Merger Integration (PMI 100-Day Plan)៖\n• ថ្ងៃ ១-៣០ [Retain Key Talent]៖ ចុះកិច្ចសន្យារក្សាបុគ្គលិកគន្លឹះ (Golden Handcuffs / Retention Bonus)។\n• ថ្ងៃ ៣១-៦០ [Align Communications]៖ រៀបចំកិច្ចប្រជុំ Town Hall ពន្យល់ពីទស្សនវិស័យរួម និងបំបាត់ការភ័យខ្លាច។\n• ថ្ងៃ ៦១-១០០ [Harmonize Systems]៖ ភ្ជាប់ប្រព័ន្ធហិរញ្ញវត្ថុ និងប្រព័ន្ធប្រតិបត្តិការបន្តិចម្តងៗដោយមិនបង្ខិតបង្ខំ។', 'គិតអំពីអាជីវកម្ម ឬដៃគូមួយដែលក្រុមហ៊ុនអ្នកអាចទិញយក ឬបង្កើត Joint Venture ហើយសរសេរចំណុចខុសគ្នានៃវប្បធម៌ធំៗ ៣ ដែលត្រូវត្រៀមសម្របសម្រួល។', 'ប្រសិនបើស្ថាប័នរបស់អ្នកត្រូវច្របាច់បញ្ចូលជាមួយក្រុមហ៊ុនមួយទៀត តើវប្បធម៌បច្ចុប្បន្នរបស់អ្នកមានភាពបត់បែនគ្រប់គ្រាន់ដើម្បីសម្របខ្លួនដែរឬទេ?', '🎯 សកម្មភាពថ្ងៃនេះ៖ រៀបចំក្របខ័ណ្ឌ Cultural Due Diligence Checklist ខ្លីមួយសម្រាប់ប្រើប្រាស់ក្នុងការវាយតម្លៃដៃគូសហការ។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-director-6', 'lesson-director-6', 'តើមូលហេតុចម្បងបំផុតដែលធ្វើឱ្យកិច្ចព្រមព្រៀង M&A ភាគច្រើនលើពិភពលោកបរាជ័យក្រោយការទិញរួចគឺជាអ្វី?', 'What is the primary root cause behind the failure of most global M&A transactions?', '["A. អតិថិជនឈប់ប្រើប្រាស់លុយ។","B. ភាពមិនចុះសម្រុងគ្នានៃវប្បធម៌ស្ថាប័ន (Culture Clash) និងការចាកចេញរបស់បុគ្គលិកជំនាញគន្លឹះ។","C. មេធាវីគិតថ្លៃសេវាថ្លៃពេក។"]', '["A. Customers ceasing to use currency.","B. Institutional culture clash, toxic integration friction, and the mass exodus of essential talent.","C. Excessive legal advisory fees."]', 1, 'ការពន្យល់៖ វប្បធម៌ស្ថាប័នដែលមិនត្រូវគ្នានឹងកម្ទេចតម្លៃនៃកិច្ចព្រមព្រៀង M&A។ ការគ្រប់គ្រងការផ្លាស់ប្តូរវប្បធម៌ និងការរក្សាមនុស្សសំខាន់គឺជាគន្លឹះ។', 'Explanation: Culture clash and talent flight erode projected synergies, ruining M&A returns.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-director-7', 'course-director-governance', 'mod-1', 7, '៧. ការពង្រីកសាខាភូមិសាស្ត្រ និងការចម្លង DNA ស្ថាប័ន (Geographic Expansion & DNA Replication)', 'Scaling Multi-Branch Operations: Replicating Core Corporate DNA Without Dilution', 'text', '• យល់ដឹងពីយុទ្ធសាស្ត្រពង្រីកសាខា (Hub-and-Spoke vs. Cluster Expansion Model)។\n• បង្កើត «កញ្ចប់ដំណើរការសាខាថ្មី» (Branch-in-a-Box Playbook) សម្រាប់ការបើកសាខាយ៉ាងរហ័ស។\n• ការពារកុំឱ្យគុណភាពសេវាកម្ម និងវប្បធម៌ស្ថាប័នរលាយសាបសូន្យនៅពេលពង្រីកសាខាច្រើន។', 'ការបើកសាខាទី ១ គឺជាការបង្កើតសិល្បៈ ប៉ុន្តែការពង្រីកពីសាខាទី ៥ ទៅសាខាទី ៥០ គឺជាវិទ្យាសាស្ត្រ និងប្រព័ន្ធ (Standardization)។ បញ្ហាធំបំផុតរបស់ក្រុមហ៊ុនដែលពង្រីកសាខាលឿនពេកគឺ «ការរលាយបាត់ DNA» (Cultural Dilution)៖ សាខាកាន់តែឆ្ងាយ ការបម្រើសេវាកាន់តែខ្សោយ ហើយអតិថិជនចាប់ផ្តើមខកចិត្ត។ Director ត្រូវបង្កើតប្រព័ន្ធ Playbook ដែលអនុញ្ញាតឱ្យសាខាថ្មីអាចដំណើរការបានស្តង់ដារដូចគ្នាបេះបិទក្នុងរយៈពេលតែ ២ សប្តាហ៍។', '«បណ្តាញហាងកាហ្វេ និងនំប៉័ងក្នុងស្រុកមួយបានពង្រីកសាខាពី ៣ ទៅ ២០ សាខាក្នុងរយៈពេលតែមួយឆ្នាំ។ ប៉ុន្តែនៅពេលម្ចាស់ដើរពិនិត្យសាខានៅបាត់ដំបង និងកំពត គាត់បានភ្ញាក់ផ្អើលយ៉ាងខ្លាំង៖ រសជាតិកាហ្វេជូរខុសធម្មតា បុគ្គលិកមិនញញឹមដាក់ភ្ញៀវ ហើយអនាម័យក្នុងបន្ទប់ទឹកមានសភាពកខ្វក់។ \nលោក វិទូ ជា Operations Director បានចូលមកដោះស្រាយបញ្ហានេះជាបន្ទាន់៖ គាត់បានបង្កើតប្រព័ន្ធ "Branch-in-a-Box": \n១. រាល់គ្រឿងផ្សំទាំងអស់ត្រូវតែផលិតចេញពីផ្ទះបាយកណ្តាល (Central Kitchen) តែមួយគត់ដើម្បីធានារសជាតិ ១០០%។\n②. រាល់អ្នកគ្រប់គ្រងសាខាថ្មីទាំងអស់ត្រូវតែចូលហ្វឹកហាត់នៅសាខាមេយ៉ាងតិច ៤៥ ថ្ងៃមុនចេញទៅកាន់កាប់សាខា។\n៣. បង្កើតប្រព័ន្ធសវនករសម្ងាត់ (Mystery Shopper) ចុះពិនិត្យពិន្ទុគុណភាពរៀងរាល់សប្តាហ៍។ \nតាមរយៈប្រព័ន្ធនេះ គ្រប់សាខាទាំងអស់ទទួលបានពិន្ទុគុណភាពស្មើគ្នាឡើងវិញ ហើយម៉ាកយីហោបានក្លាយជាបណ្តាញកាហ្វេដ៏គួរឱ្យទុកចិត្តបំផុត។»', '✅ ធាតុផ្សំ ៤ នៃ Branch-in-a-Box Playbook៖\n• [Facility & Design Manual]៖ ប្លង់ស្ថាបត្យកម្មស្តង់ដារ ការរៀបចំតុ និងឧបករណ៍បច្ចេកវិទ្យា។\n• [Operations SOP]៖ សៀវភៅណែនាំការងារប្រចាំថ្ងៃតាំងពីបើកហាង រហូតដល់បិទទ្វារហាង។\n• [HR & Training Kit]៖ កម្មវិធីបណ្តុះបណ្តាលបុគ្គលិកថ្មីរយៈពេល ១៤ ថ្ងៃ និងស្គ្រីបបម្រើភ្ញៀវ។\n• [Audit & Compliance KPI]៖ បញ្ជីត្រួតពិនិត្យពិន្ទុគុណភាព និងសុវត្ថិភាពប្រចាំខែ។', 'ជ្រើសរើសផ្នែកសំខាន់បំផុតមួយនៃអាជីវកម្មរបស់អ្នក ហើយសរសេរសេចក្តីព្រាង Playbook ស្តង់ដារដើម្បីឱ្យសាខាថ្មីអាចយកទៅអនុវត្តបានភ្លាមៗ។', 'តើសាខា ឬក្រុមការងារនៅឆ្ងាយពីការិយាល័យកណ្តាលរបស់អ្នក កំពុងដំណើរការតាមស្តង់ដារដូចគ្នា ឬកំពុងធ្វើតាមទម្លាប់រៀងៗខ្លួន?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ចុះទៅពិនិត្យ ឬវីដេអូខលជាមួយសាខាដែលនៅឆ្ងាយបំផុត ដើម្បីត្រួតពិនិត្យការអនុវត្តស្តង់ដារ SOP ជាក់ស្តែង។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-director-7', 'lesson-director-7', 'តើអ្វីជាគន្លឹះសំខាន់បំផុតក្នុងការធានាថាគុណភាព និងវប្បធម៌ក្រុមហ៊ុនមិនរលាយសាបសូន្យនៅពេលពង្រីកសាខាច្រើន?', 'What is the critical mechanism to prevent cultural and quality dilution during multi-branch scaling?', '["A. អនុញ្ញាតឱ្យសាខានីមួយៗធ្វើអ្វីតាមចិត្តដោយគ្មានច្បាប់ទម្លាប់។","B. ការបង្កើតប្រព័ន្ធស្តង់ដាររួម (Centralized Playbook & SOP) រួមជាមួយការបណ្តុះបណ្តាល DNA មេដឹកនាំសាខា និងប្រព័ន្ធត្រួតពិនិត្យគុណភាពជាប្រចាំ (Audits)។","C. កាត់បន្ថយចំនួនបុគ្គលិកនៅគ្រប់សាខាឱ្យនៅតិចបំផុត។"]', '["A. Allowing autonomous branch practices without standardized guidelines.","B. Robust standardized playbooks (Branch-in-a-Box), intensive leadership DNA immersion, centralized quality control, and rigorous audits.","C. Starving branch headcount."]', 1, 'ការពន្យល់៖ ការពង្រីកអាជីវកម្មជោគជ័យទាមទារប្រព័ន្ធស្តង់ដារូបនីយកម្ម (Standardization) និងការបណ្តុះបណ្តាល DNA វប្បធម៌ឱ្យច្បាស់លាស់។', 'Explanation: Institutional standardization via playbooks paired with leadership culture-immersion protects brand equity at scale.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-director-8', 'course-director-governance', 'mod-1', 8, '៨. អនុលោមភាពផ្លូវច្បាប់ ការប្រឆាំងអំពើពុករលួយ និងស្តង់ដារសីលធម៌ (Compliance & Ethics)', 'Corporate Compliance, Anti-Corruption & Institutional Ethical Standards', 'text', '• យល់ដឹងពីសារៈសំខាន់នៃច្បាប់ស្តីពីការប្រឆាំងការលាងលុយកខ្វក់ (AML) និងច្បាប់ពន្ធដារកម្ពុជា។\n• បង្កើតប្រព័ន្ធរាយការណ៍អនាមិកការពារអ្នកផ្តល់ដំណឹង (Whistleblower Protection Policy)។\n• ការពារស្ថាប័នពីហានិភ័យផ្លូវច្បាប់ និងការខូចខាតកេរ្តិ៍ឈ្មោះធ្ងន់ធ្ងរ។', 'នៅក្នុងសម័យមុន ក្រុមហ៊ុនខ្លះអាចឆ្លៀតឱកាសកិបកេងពន្ធ ឬផ្តល់ប្រាក់ក្រោមតុដើម្បីសម្រួលការងារ ប៉ុន្តែនៅក្នុងសេដ្ឋកិច្ចទំនើប និងច្បាប់តឹងរ៉ឹង ការអនុវត្តបែបនេះគឺជា «គ្រាប់បែកពេលវេលា» (Ticking Time Bomb)។ ក្រុមហ៊ុនលំដាប់អន្តរជាតិ និងស្ថាប័នហិរញ្ញវត្ថុធំៗនឹងមិនសហការជាមួយក្រុមហ៊ុនដែលខ្វះតម្លាភាពឡើយ។ Director ត្រូវតែកសាងវប្បធម៌អនុលោមភាព (Culture of Compliance) ដែលប្រកាន់ខ្ជាប់នូវភាពស្មោះត្រង់ និងច្បាប់ជាចម្បង។', '«ក្រុមហ៊ុននាំចេញកសិផលមួយត្រូវបានមន្ត្រីលទ្ធកម្មម្នាក់ឃុបឃិតជាមួយអ្នកផ្គត់ផ្គង់ដើម្បីស៊ីថ្លៃកម្រៃជើងសារក្រោមតុ (Kickbacks) អស់រយៈពេល ៣ ឆ្នាំ ដែលធ្វើឱ្យក្រុមហ៊ុនខាតបង់ប្រាក់រាប់សែនដុល្លារ។ \nលោកស្រី មុនីកា ជា Compliance Director បានដាក់ចេញនូវប្រព័ន្ធ Whistleblower System តាមរយៈប្រអប់សារសម្ងាត់អនាមិក និងលេខទូរស័ព្ទពិសេស។ ត្រឹមតែមួយខែ នាងបានទទួលព័ត៌មានលម្អិត និងភស្តុតាងពីបុគ្គលិកស្មោះត្រង់ម្នាក់។ ករណីកិបកេងត្រូវបានលាតត្រដាង ហើយជនល្មើសត្រូវបានបញ្ជូនទៅកាន់ផ្លូវច្បាប់។ លើសពីនេះ នាងបានរៀបចំគោលការណ៍ "Zero Tolerance for Bribery" និងប្រព័ន្ធពិនិត្យអ្នកផ្គត់ផ្គង់ប្រកបដោយតម្លាភាព ដែលជួយឱ្យក្រុមហ៊ុនទទួលបានវិញ្ញាបនបត្រស្តង់ដារអន្តរជាតិ ISO 37001 (Anti-Bribery Management) ដំបូងគេក្នុងវិស័យ។»', '✅ ធាតុផ្សំ ៣ នៃប្រព័ន្ធការពារសីលធម៌ស្ថាប័ន៖\n១. [Whistleblower Channel]៖ បង្កើតបណ្តាញរាយការណ៍សម្ងាត់អនាមិកដែលគ្មានអ្នកណាអាចតាមដានអត្តសញ្ញាណអ្នករាយការណ៍បាន។\n②. [Gift & Entertainment Policy]៖ កំណត់ច្បាប់ច្បាស់លាស់៖ បុគ្គលិកមិនត្រូវទទួលកាដូ ឬប្រាក់ពីអ្នកផ្គត់ផ្គង់លើសពី $20 ឡើយ (លើសពីនេះត្រូវប្រកាសជាសាធារណៈ)។\n៣. [Independent Audit]៖ ធ្វើសវនកម្មដំណើរការទិញ-លក់ និងហិរញ្ញវត្ថុដោយមិនប្រាប់ឱ្យដឹងមុន (Surprise Audits)។', 'ពិនិត្យមើលគោលការណ៍ Whistleblower Policy និងច្បាប់ស្តីពីការទទួលអំណោយរបស់ក្រុមហ៊ុនអ្នក ហើយកែសម្រួលវាឱ្យស្របតាមស្តង់ដារអន្តរជាតិ។', 'តើបុគ្គលិកក្នុងស្ថាប័នរបស់អ្នកហ៊ានរាយការណ៍ពីភាពមិនប្រក្រតី ឬអំពើពុករលួយដែលពួកគេបានឃើញដែរឬទេ?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ផ្ញើអ៊ីមែលរំលឹកដល់បុគ្គលិកទាំងអស់អំពីក្រមសីលធម៌អាជីវកម្ម និងបណ្តាញរាយការណ៍សម្ងាត់របស់ស្ថាប័ន។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-director-8', 'lesson-director-8', 'តើអ្វីជាការធានាដ៏សំខាន់បំផុតដើម្បីឱ្យប្រព័ន្ធរាយការណ៍អំពើពុករលួយ (Whistleblower System) ដំណើរការបានជោគជ័យ?', 'What is the absolute prerequisite for a successful corporate Whistleblower System?', '["A. តម្រូវឱ្យអ្នករាយការណ៍សរសេរឈ្មោះ និងលេខទូរស័ព្ទជាសាធារណៈ។","B. ការរក្សាការសម្ងាត់ និងការការពារអនាមិក ១០០% ដល់អ្នកផ្តល់ដំណឹង ដើម្បីការពារកុំឱ្យមានការសងសឹក ឬធ្វើបាប (Protection from retaliation)។","C. មិនបាច់បើកមើលសាររាយការណ៍នោះទេ។"]', '["A. Requiring whistleblowers to publicly state their personal phone numbers.","B. Ironclad anonymity, strict confidentiality, and formal anti-retaliation legal protections for informants.","C. Ignoring incoming reports."]', 1, 'ការពន្យល់៖ ប្រសិនបើគ្មានការការពារអនាមិក និងសុវត្ថិភាពដល់អ្នករាយការណ៍ទេ គ្មានបុគ្គលិកណាម្នាក់ហ៊ានលាតត្រដាងការពិតនោះឡើយ។', 'Explanation: Uncompromising anonymity and anti-retaliation protections are essential for surfacing internal corruption.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-director-9', 'course-director-governance', 'mod-1', 9, '៩. ការកសាងតម្លៃយីហោជាយុទ្ធសាស្ត្រ និងការការពារកេរ្តិ៍ឈ្មោះ (Brand Equity & PR Defense)', 'Strategic Brand Equity: Building Institutional Trust and Reputational Moats', 'text', '• យល់ដឹងពីរបៀបវាស់វែង និងកសាងតម្លៃយីហោស្ថាប័ន (Brand Equity & Goodwill) លើតារាងតុល្យការ។\n• បង្កើតរនាំងការពារកេរ្តិ៍ឈ្មោះ (Reputational Moat) ក្នុងចំណោមសាធារណជន និងអ្នកសារព័ត៌មាន។\n• គ្រប់គ្រងវិបត្តិព័ត៌មានមិនពិត (Fake News & Smear Campaigns) លើបណ្តាញសង្គមក្នុងរយៈពេល ២ ម៉ោងដំបូង។', 'មហាសេដ្ឋី Warren Buffett ធ្លាប់បានមានប្រសាសន៍ថា៖ «វាត្រូវការពេល ២០ ឆ្នាំដើម្បីកសាងកេរ្តិ៍ឈ្មោះ ប៉ុន្តែត្រូវការពេលត្រឹមតែ ៥ នាទីដើម្បីបំផ្លាញវាចោល»។ នៅក្នុងយុគសម័យបណ្តាញសង្គម ព័ត៌មានអវិជ្ជមាន ឬការយល់ច្រឡំមួយអាចរីករាលដាលពេញប្រទេសក្នុងរយៈពេលតែប៉ុន្មានម៉ោង។ Director ត្រូវតែកសាងទ្រព្យសម្បត្តិយីហោ (Brand Goodwill) ឱ្យរឹងមាំ និងមានក្រុមឆ្លើយតបព័ត៌មានវិទ្យា (Rapid PR Defense Team) ២៤/៧។', '«ម៉ាកយីហោទឹកដោះគោក្នុងស្រុកដ៏ល្បីមួយ ត្រូវបានគេបង្ហោះវីដេអូក្លែងក្លាយលើ TikTok ដោយចោទប្រកាន់ថាទឹកដោះគោមានជាតិគីមីពុល ធ្វើឱ្យអតិថិជនរាប់ពាន់នាក់ទាមទារសងប្រាក់វិញ។ \nលោក សម្បត្តិ ជា Marketing & Public Affairs Director មិនបាននៅស្ងៀម ឬគំរាមប្តឹងតវ៉ាឡើយ។ ក្នុងរយៈពេលតែ ២ ម៉ោង៖ \n១. គាត់បានផ្សាយផ្ទាល់ (Facebook Live) បង្ហាញពីរោងចក្រស្អាតស្អំស្តង់ដារអន្តរជាតិ និងមន្ទីរពិសោធន៍តេស្តគុណភាព។\n②. គាត់បានអញ្ជើញអ្នកសារព័ត៌មានកំពូលៗ និងតំណាងក្រសួងសុខាភិបាលមកត្រួតពិនិត្យ និងយកសំណាកតេស្តដោយផ្ទាល់នៅព្រឹកស្អែក។\n៣. ក្រសួងបានចេញលិខិតបញ្ជាក់សុវត្ថិភាពជាផ្លូវការក្នុងរយៈពេល ២៤ ម៉ោង។ \nភាពរហ័សរហួន តម្លាភាព និងភាពក្លាហានរបស់សម្បត្តិ មិនត្រឹមតែបំបាត់ពាក្យចចាមអារ៉ាមនោះទេ ប៉ុន្តែបានធ្វើឱ្យសាធារណជនកាន់តែមានទំនុកចិត្តលើគុណភាពផលិតផល ហើយការលក់បានកើនឡើង ៣០% លើសកាលពីមុន។»', '✅ ច្បាប់មាស ៣ ក្នុងការការពារកេរ្តិ៍ឈ្មោះយីហោលើបណ្តាញសង្គម (Social Media Crisis Protocol)៖\n• ម៉ោងទី ១ [Verify & Contain]៖ ផ្ទៀងផ្ទាត់ប្រភព និងស្វែងយល់ពីឫសគល់នៃបញ្ហា (កុំប្រញាប់ប្រកែកដោយគ្មានទិន្នន័យ)។\n• ម៉ោងទី ២ [Transparent First Response]៖ ចេញសេចក្តីថ្លែងការណ៍ខ្លីបញ្ជាក់ថា ស្ថាប័នបានដឹងរឿង និងកំពុងស៊ើបអង្កេតយ៉ាងយកចិត្តទុកដាក់។\n• ម៉ោងទី ២៤ [Factual Resolution]៖ បង្ហាញភស្តុតាងវិទ្យាសាស្ត្រ ឬរបាយការណ៍សវនកម្មផ្លូវការ និងដំណោះស្រាយជាក់ស្តែង។', 'បង្កើតសេចក្តីព្រាងពិធីសារការពារកេរ្តិ៍ឈ្មោះយីហោ (Brand Crisis Response Protocol) សម្រាប់ករណីអតិថិជនរិះគន់ធ្ងន់ធ្ងរលើបណ្តាញសង្គម។', 'តើយីហោរបស់ស្ថាប័នអ្នកមាន «ដើមទុនទំនុកចិត្ត (Goodwill)» គ្រប់គ្រាន់ដើម្បីទប់ទល់នឹងព្យុះព័ត៌មានអវិជ្ជមានដែរឬទេ?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ត្រួតពិនិត្យប្រព័ន្ធ Social Listening Tools ដើម្បីតាមដានមតិរបស់អតិថិជនលើបណ្តាញសង្គមជាប្រចាំ។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-director-9', 'lesson-director-9', 'នៅពេលស្ថាប័នរងការចោទប្រកាន់អវិជ្ជមានលើបណ្តាញសង្គម តើកំហុសដ៏ធំបំផុតដែលមិនត្រូវធ្វើជាដាច់ខាតគឺជាអ្វី?', 'When an organization faces viral social media backlash, what is the gravest mistake to avoid?', '["A. ការចេញមុខបកស្រាយដោយតម្លាភាព និងភស្តុតាង។","B. ការលុប Comment ចោល រារាំង (Block) អតិថិជន និងការរក្សាភាពស្ងៀមស្ងាត់យូរថ្ងៃដោយគ្មានការឆ្លើយតប។","C. ការសហការជាមួយអាជ្ញាធរមានសមត្ថកិច្ច។"]', '["A. Responding transparently with verified factual evidence.","B. Deleting comments, blocking critical users, and remaining completely silent for days.","C. Cooperating with regulatory authorities."]', 1, 'ការពន្យល់៖ ការលុប Comment និងការស្ងៀមស្ងាត់នឹងធ្វើឱ្យមហាជនកាន់តែខឹងសម្បារ និងជឿជាក់ថាស្ថាប័នពិតជាបានប្រព្រឹត្តខុសមែន។', 'Explanation: Censoring comments and stonewalling validates public outrage, converting small issues into PR catastrophes.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-director-10', 'course-director-governance', 'mod-1', 10, '១០. និរន្តរភាពអាជីវកម្ម ESG និងការទទួលខុសត្រូវសង្គម (ESG & Sustainable Stewardship)', 'Environmental, Social & Governance (ESG): Building Century-Long Sustainability', 'text', '• យល់ដឹងពីក្របខ័ណ្ឌ ESG (បរិស្ថាន សង្គម និងអភិបាលកិច្ច) ក្នុងការទាក់ទាញទុនវិនិយោគបៃតង (Green Capital)។\n• បង្កើតគម្រោងទំនួលខុសត្រូវសង្គម (CSR) ដែលផ្សារភ្ជាប់ទៅនឹងយុទ្ធសាស្ត្រអាជីវកម្មស្នូល មិនមែនគ្រាន់តែជាការធ្វើបុណ្យចែកលុយ។\n• ត្រៀមស្ថាប័នឱ្យស្របតាមស្តង់ដារបញ្ចេញឧស្ម័នសូន្យ (Net Zero) និងការអភិវឌ្ឍប្រកបដោយចីរភាព។', 'កាលពីមុន គោលដៅតែមួយគត់របស់ក្រុមហ៊ុនគឺ «បង្កើនប្រាក់ចំណេញដល់ម្ចាស់ភាគហ៊ុន» (Shareholder Primacy)។ ប៉ុន្តែនៅក្នុងសតវត្សរ៍ទី ២១ ស្ថាប័នហិរញ្ញវត្ថុអន្តរជាតិធំៗ (ដូចជា World Bank, ADB, BlackRock) សម្រេចចិត្តវិនិយោគតែលើក្រុមហ៊ុនណាដែលមានស្តង់ដារ ESG (Environmental, Social, Governance) ខ្ពស់ប៉ុណ្ណោះ។ Director ត្រូវតែកសាងអាជីវកម្មដែលមិនត្រឹមតែចំណេញលុយទេ ប៉ុន្តែថែមទាំងការពារបរិស្ថាន និងលើកកម្ពស់ជីវភាពសហគមន៍។', '«រោងចក្រកែច្នៃផ្លែឈើក្នុងស្រុកមួយចង់ស្នើសុំកម្ចី $10,000,000 ពីធនាគារអន្តរជាតិដើម្បីពង្រីករោងចក្រ។ ធនាគារបានដាក់លក្ខខណ្ឌថា រោងចក្រត្រូវតែមានរបាយការណ៍ ESG ស្តង់ដារ។ \nលោកស្រី សុភាវី ជា Sustainability Director បានដឹកនាំការផ្លាស់ប្តូរ៖ \n• Environmental: ដំឡើងផ្ទាំងសូឡាលើដំបូលរោងចក្រដែលកាត់បន្ថយការប្រើប្រាស់អគ្គិសនីជាតិ ៤០% និងប្រព្រឹត្តិកម្មទឹកកខ្វក់មុនបង្ហូរចេញ។\n• Social: ចុះកិច្ចសន្យាទិញផ្លែស្វាយពីកសិករក្នុងតម្លៃសមរម្យ (Fair Trade) និងបង្កើតមណ្ឌលថែទាំកុមារសម្រាប់កម្មករ។\n• Governance: តម្លាភាពនៃរបាយការណ៍ហិរញ្ញវត្ថុ និងប្រព័ន្ធគ្រប់គ្រងសុវត្ថិភាពការងារ។ \nលទ្ធផល៖ ធនាគារបានអនុម័តកម្ចីបៃតង (Green Loan) ជាមួយអត្រាការប្រាក់ទាបជាងទីផ្សារ ៣% ដែលជួយសន្សំប្រាក់រាប់លានដុល្លារដល់ក្រុមហ៊ុន ហើយផលិតផលរបស់រោងចក្រត្រូវបានផ្សារទំនើបនៅអឺរ៉ុបបញ្ជាទិញផ្តាច់មុខ។»', '✅ របៀបបង្កើតយុទ្ធសាស្ត្រ ESG ផ្សារភ្ជាប់នឹងអាជីវកម្ម៖\n• Environmental៖ កាត់បន្ថយការប្រើប្រាស់ប្លាស្ទិក និងប្តូរមកប្រើប្រាស់ថាមពលពន្លឺព្រះអាទិត្យ (សន្សំថ្លៃភ្លើងផ្ទាល់)។\n• Social៖ វិនិយោគលើការបណ្តុះបណ្តាលសុខភាពបុគ្គលិក (កាត់បន្ថយអវត្តមាន និងបង្កើនទិន្នផល)។\n• Governance៖ តម្លាភាពក្នុងការបង់ពន្ធជូនរដ្ឋ និងការប្រឆាំងអំពើពុករលួយ (បង្កើនតម្លៃក្រុមហ៊ុន)។', 'វាយតម្លៃស្ថាប័នរបស់អ្នកលើទិដ្ឋភាពទាំង ៣ នៃ ESG (E, S, G) ហើយកំណត់គំនិតផ្តួចផ្តើមបៃតងចំនួន ១ ដែលអាចជួយសន្សំថ្លៃដើម និងជួយសង្គមក្នុងពេលតែមួយ។', 'តើក្រុមហ៊ុនរបស់អ្នកកំពុងធ្វើអាជីវកម្មដោយគិតគូរពីផលប៉ះពាល់បរិស្ថាន និងសហគមន៍ជំនាន់ក្រោយកម្រិតណា?', '🎯 សកម្មភាពថ្ងៃនេះ៖ កំណត់គម្រោងកាត់បន្ថយការខ្ជះខ្ជាយថាមពល ឬក្រដាសនៅក្នុងការិយាល័យចាប់ពីសប្តាហ៍នេះតទៅ។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-director-10', 'lesson-director-10', 'ហេតុអ្វីបានជាយុទ្ធសាស្ត្រ ESG ក្លាយជាកត្តាកំណត់ជោគវាសនារបស់ក្រុមហ៊ុនធំៗនាពេលបច្ចុប្បន្ន?', 'Why has ESG strategy become a decisive factor for enterprise survival today?', '["A. ដោយសារតែវាជាម៉ូដទាន់សម័យដែលមិនបាច់អនុវត្តពិតប្រាកដ។","B. ដោយសារស្ថាប័នហិរញ្ញវត្ថុអន្តរជាតិ និងអតិថិជនជំនាន់ថ្មីជ្រើសរើសវិនិយោគ និងទិញទំនិញតែពីក្រុមហ៊ុនណាដែលមានការទទួលខុសត្រូវខ្ពស់ចំពោះបរិស្ថាន សង្គម និងអភិបាលកិច្ច។","C. ដើម្បីចំណាយលុយក្រុមហ៊ុនឱ្យអស់។"]', '["A. It is merely a fashionable PR label with no substance.","B. Global investment funds and modern consumers increasingly direct capital and spending strictly to firms with verified environmental, social, and governance excellence.","C. To exhaust surplus corporate cash."]', 1, 'ការពន្យល់៖ ESG មិនមែនជាការងារស្ម័គ្រចិត្តទេ ប៉ុន្តែជាលក្ខខណ្ឌតម្រូវក្នុងការទាក់ទាញទុនវិនិយោគសកល និងការកសាងអាជីវកម្មដែលមានចីរភាពយូរអង្វែង។', 'Explanation: Institutional capital increasingly mandates ESG compliance, making it critical for enterprise valuation and financing.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-csuite-1', 'course-executive-csuite', 'mod-1', 1, '១. ទំនាក់ទំនងជាមួយក្រុមប្រឹក្សាភិបាល និងអ្នកវិនិយោគ (Board Alignment & Investor Relations)', 'Executive Board Alignment & Investor Relations', 'text', '• យល់ដឹងពីរបៀបរៀបចំរបាយការណ៍សង្ខេបកម្រិត Executive Board Deck។\n• កសាងទំនុកចិត្តជាមួយម្ចាស់ភាគហ៊ុន និងអ្នកវិនិយោគធំៗ (Shareholder Trust)។\n• គ្រប់គ្រងការរំពឹងទុករបស់ក្រុមប្រឹក្សាភិបាលលើកំណើន និងហានិភ័យ។', 'ថ្នាក់ដឹកនាំ C-Suite (CEO, COO, CFO) ត្រូវតែនិយាយជាភាសាយុទ្ធសាស្ត្រខ្ពស់ (Strategic Altitude) ដោយបង្ហាញពីទស្សនវិស័យ ទិន្នន័យហិរញ្ញវត្ថុ និងផលចំណេញលើដើមទុន (ROIC)។', '«ឯកឧត្តមបណ្ឌិត ហេង វណ្ណា (CEO) បានរៀបចំកិច្ចប្រជុំក្រុមប្រឹក្សាភិបាលប្រចាំឆ្នាំ។ គាត់មិនបានចំណាយពេល ៣ ម៉ោងអានតួលេខលម្អិតនោះទេ ប៉ុន្តែបានរៀបចំ Slide សង្ខេបតែ ៥ សន្លឹក៖ ១. លទ្ធផលហិរញ្ញវត្ថុស្នូល ២. ឧបសគ្គទីផ្សារ ៣. ឱកាសកំណើនថ្មី ៤. ផែនការបែងចែកទុន ៥. សេចក្តីសម្រេចដែលត្រូវការការអនុម័តពីក្រុមប្រឹក្សាភិបាល។ កិច្ចប្រជុំបានបញ្ចប់យ៉ាងរលូនក្នុងរយៈពេល ១ ម៉ោងកន្លះ ហើយក្រុមប្រឹក្សាភិបាលបានអនុម័តកញ្ចប់វិនិយោគថ្មី $5,000,000 ដោយគ្មានការសង្ស័យ។»', '✅ របៀបបង្ហាញ Board Deck ប្រកបដោយភាពចាស់ទុំ៖\n«យើងសូមរាយការណ៍ដោយស្មោះត្រង់នូវចំណុចដែលយើងសម្រេចបាន និងចំណុចដែលយើងជួបការប្រឈម។ ផ្អែកលើទិន្នន័យទីផ្សារ នេះជាអនុសាសន៍យុទ្ធសាស្ត្រចំនួន ៣ ដែលយើងស្នើឱ្យក្រុមប្រឹក្សាភិបាលពិចារណា។»', 'បង្កើតសេចក្តីព្រាង Board Executive Summary ១ ទំព័រសម្រាប់បង្ហាញដល់ក្រុមប្រឹក្សាភិបាល ឬម្ចាស់ភាគហ៊ុន។', 'តើអ្នកប្រាស្រ័យទាក់ទងជាមួយថ្នាក់ដឹកនាំជាន់ខ្ពស់ដោយភាពស្មោះត្រង់ និងតម្លាភាពកម្រិតណា?', '🎯 សកម្មភាពថ្ងៃនេះ៖ រៀបចំរបាយការណ៍សង្ខេបបែប Executive Summary ខ្លីមួយច្បាប់សម្រាប់កិច្ចប្រជុំបន្ទាប់។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-csuite-1', 'lesson-csuite-1', 'តើអ្វីជាក្បួនសំខាន់បំផុតក្នុងការពង្រឹងទំនាក់ទំនងរវាង C-Suite និងក្រុមប្រឹក្សាភិបាល (Board)?', 'What is the most critical rule in maintaining strong C-Suite and Board relations?', '["A. លាក់បាំងព័ត៌មានអវិជ្ជមានទាំងអស់ ហើយរាយការណ៍តែរឿងល្អៗ។","B. តម្លាភាពខ្ពស់ រាយការណ៍ទាន់ពេលវេលាទាំងដំណឹងល្អ និងដំណឹងអាក្រក់ និងផ្តល់ដំណោះស្រាយច្បាស់លាស់។","C. មិនបាច់ជួបប្រជុំជាមួយក្រុមប្រឹក្សាភិបាលឡើយ។"]', '["A. Conceal all bad news and only show positives.","B. Complete transparency, early communication of both good and bad news with vetted solutions.","C. Avoid meeting the board."]', 1, 'ការពន្យល់៖ ជម្រើស B កសាងទំនុកចិត្តយូរអង្វែង (Board Trust)។ គ្មានអ្វីបំផ្លាញទំនុកចិត្តលឿនជាងការលាក់បាំងដំណឹងអាក្រក់នោះឡើយ។', 'Explanation: Transparency and early warning are the bedrock of board and executive trust.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-csuite-2', 'course-executive-csuite', 'mod-1', 2, '២. យុទ្ធសាស្ត្របែងចែកទុន និងការបង្កើនតម្លៃក្រុមហ៊ុន (Capital Allocation & Company Valuation)', 'Capital Allocation Strategy & Driving Enterprise Valuation', 'text', '• យល់ដឹងពីកាតព្វកិច្ចសំខាន់បំផុតរបស់ CEO គឺការបែងចែកទុន (Capital Allocation)។\n• ជ្រើសរើសរវាងការបណ្តាក់ទុនឡើងវិញ (Reinvestment), ការទិញភាគហ៊ុនត្រឡប់ (Share Buybacks) ឬការទិញអាជីវកម្មដទៃ (M&A)។\n• បង្កើនតម្លៃក្រុមហ៊ុន (Enterprise Valuation) សម្រាប់ត្រៀមទាក់ទាញទុន ឬចូលផ្សារហ៊ុន (IPO)។', 'CEO ឆ្នើមមិនត្រូវបានវាស់វែងត្រឹមតែលើទំហំនៃការលក់នោះទេ ប៉ុន្តែវាស់វែងលើសមត្ថភាពបង្វិលដើមទុន ១ ដុល្លារឱ្យបង្កើតផលចំណេញលើសពីអត្រាការប្រាក់ទីផ្សារក្នុងរយៈពេលវែង។', '«ក្នុងអំឡុងពេលដែលក្រុមហ៊ុនទទួលបានប្រាក់ចំណេញច្រើន CFO បានស្នើឱ្យទុកលុយក្នុងធនាគារធម្មតា។ CEO បានវិភាគឃើញថា ក្រុមហ៊ុនមានឱកាសទិញយកក្រុមហ៊ុនបច្ចេកវិទ្យាតូចមួយដែលមានកម្មសិទ្ធិបញ្ញាពិសេស។ គាត់បានសម្រេចចិត្តបែងចែកទុន ២០% មកទិញក្រុមហ៊ុននោះ។ ពីរឆ្នាំក្រោយមក បច្ចេកវិទ្យានោះបានជួយឱ្យក្រុមហ៊ុនកាត់បន្ថយថ្លៃដើមផលិត ៣០% និងបានបង្កើនតម្លៃក្រុមហ៊ុន (Valuation) ពី $10,000,000 ឡើងដល់ $35,000,000។ ម្ចាស់ភាគហ៊ុនទាំងអស់ទទួលបានផលចំណេញយ៉ាងច្រើនសន្ធឹកសន្ធាប់។»', '✅ ក្បួនមាសនៃការបែងចែកទុន (Warren Buffett Rule)៖\n«មុននឹងវិនិយោគទុនលើគម្រោងណាមួយ យើងត្រូវប្រាកដថា អត្រាផលចំណេញលើដើមទុនវិនិយោគ (ROIC) ត្រូវតែខ្ពស់ជាងថ្លៃដើមនៃទុន (Cost of Capital) យ៉ាងហោចណាស់ ៥%។»', 'គណនា និងពិនិត្យមើលថាតើទុនបម្រុងរបស់ស្ថាប័នអ្នកកំពុងត្រូវបានវិនិយោគលើអ្វីដែលផ្តល់ផលចំណេញខ្ពស់បំផុតហើយឬនៅ។', 'តើការសម្រេចចិត្តវិនិយោគរបស់អ្នកកន្លងមក ត្រូវបានជំរុញដោយអារម្មណ៍ ឬដោយការគណនាផលចំណេញលើដើមទុនច្បាស់លាស់?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ពិនិត្យមើលផែនការចំណាយវិនិយោគធំៗនៃស្ថាប័នរបស់អ្នក ដើម្បីធានាថាវាបង្កើតតម្លៃរយៈពេលវែង។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-csuite-2', 'lesson-csuite-2', 'តើភារកិច្ចសំខាន់បំផុតរបស់ CEO ក្នុងការបង្កើនតម្លៃក្រុមហ៊ុនយូរអង្វែងគឺជាអ្វី?', 'What is the most critical duty of a CEO in maximizing long-term company valuation?', '["A. ចុះទៅត្រួតពិនិត្យការងារតូចតាចរបស់បុគ្គលិកគ្រប់ផ្នែកជារៀងរាល់ថ្ងៃ។","B. ការបែងចែកទុនប្រកបដោយភាពវៃឆ្លាត (Effective Capital Allocation) និងការជ្រើសរើសថ្នាក់ដឹកនាំកំពូលដែលស័ក្តិសម។","C. ចំណាយលុយទាំងអស់លើការជប់លៀង និងរថយន្តទំនើប។"]', '["A. Micromanage daily tasks of all employees.","B. Intelligent capital allocation and recruiting outstanding senior leadership.","C. Spend all money on luxury cars and parties."]', 1, 'ការពន្យល់៖ ជម្រើស B ជាទំនួលខុសត្រូវស្នូលរបស់ CEO កម្រិតសកលលោក។', 'Explanation: Capital allocation and executive talent placement are the twin drivers of enterprise valuation.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-csuite-3', 'course-executive-csuite', 'mod-1', 3, '៣. យុទ្ធសាស្ត្របែងចែកភាគលាភ និងភាគហ៊ុននិម្មិតរបស់ Huawei (Huawei Profit-Sharing & TUP Model)', 'Huawei Incentive Architecture: Phantom Shares (TUP) & Profit-Sharing Mechanisms', 'text', '• យល់ដឹងពីទស្សនវិជ្ជាបែងចែកផលប្រយោជន៍ដ៏ល្បីល្បាញរបស់ Huawei «មិនឱ្យមនុស្សល្អខាតបង់» (不让雷锋吃亏)។\n• រចនាប្រព័ន្ធភាគហ៊ុននិម្មិត (Time-based Unit Plan - TUP) ដើម្បីចងចិត្តថ្នាក់ដឹកនាំកំពូលដោយមិនបាច់បាត់បង់សិទ្ធិបោះឆ្នោត (Equity Dilution)។\n• បង្កើតយន្តការ «បែងចែកប្រាក់ចំណេញតាមស្នាដៃ» ដែលជំរុញឱ្យបុគ្គលិកខិតខំដូចជាសហគ្រិនផ្ទាល់។', 'ស្ថាបនិកក្រុមហ៊ុន Huawei លោក Ren Zhengfei កាន់កាប់ភាគហ៊ុនក្រុមហ៊ុនត្រឹមតែប្រហែល ១% ប៉ុណ្ណោះ រីឯ ៩៩% ទៀតត្រូវបានបែងចែកទៅឱ្យបុគ្គលិកតាមរយៈប្រព័ន្ធភាគហ៊ុននិម្មិត (Employee Shareholding Scheme & TUP)។ លោកតែងតែបង្រៀនថា៖ «អាថ៌កំបាំងនៃការដឹកនាំមិនមែនជាការចេះនិយាយទ្រឹស្តីល្អៗនោះទេ ប៉ុន្តែជាសមត្ថភាព "ចេះបែងចែកលុយឱ្យយុត្តិធម៌" (分钱的艺术)»។ នៅពេលផលប្រយោជន៍ត្រូវបានបែងចែកយ៉ាងស័ក្តិសម បុគ្គលិកគ្រប់រូបនឹងប្រែក្លាយជាកងទ័ពចចក (Wolf Pack) ដ៏អង់អាចក្លាហាន។', '«ក្នុងអំឡុងពេលក្រុមហ៊ុនបច្ចេកវិទ្យាហិរញ្ញវត្ថុមួយរីកចម្រើនខ្លាំង ថ្នាក់ដឹកនាំកំពូលៗ (VP & Directors) ចាប់ផ្តើមត្រូវក្រុមហ៊ុនគូប្រជែងទាក់ទាញដោយផ្តល់ប្រាក់ខែខ្ពស់ជាង ២ ដង។ CEO មានការព្រួយបារម្ភយ៉ាងខ្លាំងព្រោះខ្លាចបាត់បង់ក្បាលម៉ាស៊ីនស្នូល។ \nដោយរៀនសូត្រពីក្បួន TUP របស់ Huawei គាត់បានរៀបចំប្រព័ន្ធ "Time-based Unit Plan (TUP)": គាត់បានបែងចែកកញ្ចប់ TUP រយៈពេល ៥ ឆ្នាំដល់ថ្នាក់ដឹកនាំកំពូលទាំង ១០ នាក់។ ពួកគេមិនបាច់ចំណាយលុយទិញហ៊ុនទេ ប៉ុន្តែពួកគេទទួលបានភាគលាភ (Cash Dividend) ជារៀងរាល់ឆ្នាំផ្អែកលើកំណើនប្រាក់ចំណេញសុទ្ធរបស់ក្រុមហ៊ុន ហើយនៅឆ្នាំទី ៥ ពួកគេទទួលបានប្រាក់កើនតម្លៃភាគហ៊ុន (Capital Gain) មួយដុំធំ។ \nលទ្ធផល៖ គ្មានថ្នាក់ដឹកនាំណាម្នាក់ចាកចេញឡើយ។ ពួកគេបានរួបរួមគ្នាធ្វើការទាំងយប់ទាំងថ្ងៃដូចជាម្ចាស់ក្រុមហ៊ុនផ្ទាល់ ហើយបានរុញច្រានចំណូលក្រុមហ៊ុនឱ្យកើនឡើង ៥ ដងក្នុងរយៈពេល ៤ ឆ្នាំ។ ថ្នាក់ដឹកនាំម្នាក់ៗទទួលបានប្រាក់រង្វាន់រាប់សែនដុល្លារដោយយុត្តិធម៌។»', '✅ របៀបរៀបចំប្រព័ន្ធភាគហ៊ុននិម្មិត TUP (Huawei 5-Year Cycle)៖\n• ឆ្នាំទី ១៖ ទទួលបានសិទ្ធិ TUP (មិនទាន់មានភាគលាភ)\n• ឆ្នាំទី ២៖ ទទួលបានភាគលាភ ១/៣ នៃប្រាក់ចំណេញ\n• ឆ្នាំទី ៣៖ ទទួលបានភាគលាភ ២/៣ នៃប្រាក់ចំណេញ\n• ឆ្នាំទី ៤៖ ទទួលបានភាគលាភពេញលេញ ១០០%\n• ឆ្នាំទី ៥៖ ទទួលបានភាគលាភ ១០០% + ប្រាក់កើនតម្លៃហ៊ុន (Capital Gain) រួចបញ្ចប់វដ្ត ហើយចាប់ផ្តើមវដ្តថ្មី។\n• អត្ថប្រយោជន៍៖ ម្ចាស់ក្រុមហ៊ុនមិនបាត់បង់សិទ្ធិអំណាចគ្រប់គ្រង (No Voting Rights) ប៉ុន្តែបុគ្គលិកមានអារម្មណ៍ដូចជាម្ចាស់ហ៊ុនពិតប្រាកដ។', 'គណនាទំហំប្រាក់ចំណេញសុទ្ធបម្រុង (Surplus Pool) របស់ក្រុមហ៊ុនអ្នក ដែលអាចយកមកបង្កើតជាកញ្ចប់លើកទឹកចិត្ត TUP សម្រាប់ថ្នាក់ដឹកនាំគន្លឹះនៅឆ្នាំក្រោយ។', 'តើប្រព័ន្ធលើកទឹកចិត្តបច្ចុប្បន្នរបស់ក្រុមហ៊ុនអ្នក បានធ្វើឱ្យថ្នាក់ដឹកនាំកំពូលមានអារម្មណ៍ថាខ្លួនឯងជា «ម្ចាស់ក្រុមហ៊ុន» ឬគ្រាន់តែជា «អ្នកស៊ីឈ្នួល»?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ពិភាក្សាជាមួយ CFO និងក្រុមប្រឹក្សាភិបាលអំពីលទ្ធភាពនៃការរចនាគម្រោងលើកទឹកចិត្តបែប Phantom Shares (TUP)។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-csuite-3', 'lesson-csuite-3', 'តើអ្វីជាអត្ថប្រយោជន៍ដ៏អស្ចារ្យបំផុតនៃប្រព័ន្ធភាគហ៊ុននិម្មិត (TUP / Phantom Shares) ធៀបនឹងការកាត់ភាគហ៊ុនពិតប្រាកដ (Direct Equity)?', 'What is the greatest strategic advantage of Phantom Shares (TUP) over direct equity dilution?', '["A. មិនបាច់ផ្តល់លុយដល់បុគ្គលិក។","B. ចងចិត្តបុគ្គលិកឆ្នើមរយៈពេលវែង និងចែករំលែកប្រាក់ចំណេញយ៉ាងច្រើន ដោយមិនធ្វើឱ្យស្ថាបនិកបាត់បង់សិទ្ធិសម្រេចចិត្ត ឬសិទ្ធិបោះឆ្នោតក្នុងក្រុមហ៊ុន (No Voting Dilution)។","C. ដើម្បីគេចវេះពីការបង់ពន្ធរដ្ឋ។"]', '["A. Refusing to compensate staff.","B. Anchoring elite executive talent and sharing windfall profits without diluting voting control or complicating the corporate capitalization table.","C. Evading tax compliance."]', 1, 'ការពន្យល់៖ TUP ផ្តល់សិទ្ធិទទួលភាគលាភ និងប្រាក់ចំណេញ ប៉ុន្តែមិនផ្តល់សិទ្ធិបោះឆ្នោត (No Voting Rights) ជួយការពារការបែកបាក់អំណាចរបស់ស្ថាបនិក។', 'Explanation: Phantom shares align long-term economic incentives without fragmenting board control or equity cap tables.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-csuite-4', 'course-executive-csuite', 'mod-1', 4, '៤. សិល្បៈនៃការបង្វិលទុន និងលំហូរសាច់ប្រាក់សេរី (Warren Buffett: Capital Allocation)', 'Capital Allocation Mastery: Compounding Free Cash Flow and ROIC', 'text', '• យល់ដឹងពីកាតព្វកិច្ចលេខ ១ របស់ C-Suite (CEO/CFO)៖ ការបែងចែកទុន (Capital Allocation)។\n• ផ្តោតលើលំហូរសាច់ប្រាក់សេរីពិតប្រាកដ (Free Cash Flow) ជំនួសឱ្យប្រាក់ចំណេញគណនេយ្យលើក្រដាស (Accounting Profit)។\n• ជ្រើសរើសរវាងការបណ្តាក់ទុនពង្រីក (Capex), ការទិញអាជីវកម្ម (M&A), ឬការសងបំណុល ដោយផ្អែកលើ ROIC។', 'មហាសេដ្ឋី Warren Buffett តែងតែលើកឡើងថា៖ CEO ភាគច្រើនឡើងកាន់តំណែងដោយសារពូកែខាងលក់ ឬវិស្វកម្ម ប៉ុន្តែនៅពេលក្លាយជា CEO ភារកិច្ចសំខាន់បំផុតគឺ «ការបែងចែកទុន» ដែលពួកគេមិនដែលបានរៀនសូត្រពីមុនមក។ ប្រសិនបើក្រុមហ៊ុនរកប្រាក់ចំណេញបាន $1,000,000 តើអ្នកគួរយកលុយនោះទៅទិញម៉ាស៊ីនថ្មី បើកសាខាថ្មី ទិញក្រុមហ៊ុនគូប្រជែង ឬទុកក្នុងធនាគារ? ការសម្រេចចិត្តបង្វិលទុនត្រូវ ក្រុមហ៊ុននឹងក្លាយជាអាណាចក្រយក្ស រីឯការសម្រេចចិត្តខុស ទុនរាប់លាននឹងត្រូវរលាយ។', '«ក្នុងអំឡុងពេលអាជីវកម្មលក់រាយកំពុងកាក់កប CFO ចាស់ចង់យកប្រាក់ចំណេញសល់ $2,000,000 ទៅសាងសង់អគារការិយាល័យធំមួយកម្ពស់ ៧ ជាន់ដើម្បីបង្ហាញភាពហ៊ឺហារ។ \nប៉ុន្តែ CEO ថ្មីដែលយល់ដឹងពីក្បួន Capital Allocation បានជំទាស់។ គាត់បានគណនាថា ការសាងសង់អគារផ្តល់ផលចំណេញត្រឹមតែ ៤% ក្នុងមួយឆ្នាំ (ទាបជាងការប្រាក់ធនាគារ)។ ផ្ទុយទៅវិញ គាត់បានយកលុយ $2,000,000 នោះទៅវិនិយោគលើប្រព័ន្ធឃ្លាំងទំនិញស្វ័យប្រវត្តិ និងប្រព័ន្ធ E-Commerce ដែលផ្តល់ផលចំណេញលើដើមទុន (ROIC) រហូតដល់ ៣៥% ក្នុងមួយឆ្នាំ។ \nបីឆ្នាំក្រោយមក ប្រព័ន្ធ E-Commerce បានបង្កើតលំហូរសាច់ប្រាក់បន្ថែម $1,500,000 ជារៀងរាល់ឆ្នាំ ដែលអនុញ្ញាតឱ្យក្រុមហ៊ុនទិញអគារធំជាងមុន ៣ ដងដោយមិនបាច់ខ្ចីបំណុលធនាគារសូម្បីតែមួយដុល្លារ។»', '✅ ជម្រើស ៥ នៃការបែងចែកទុនរបស់ C-Suite (Buffett Framework)៖\n១. [Reinvest in Organic Growth]៖ វិនិយោគពង្រីកអាជីវកម្មដើម ប្រសិនបើ ROIC > 15%។\n②. [Acquire Other Businesses (M&A)]៖ ទិញក្រុមហ៊ុនដទៃដែលមានតម្លៃថោកជាងតម្លៃពិត។\n៣. [Pay Down Debt]៖ សងបំណុលធនាគារដែលមានការប្រាក់ខ្ពស់ដើម្បីកាត់បន្ថយហានិភ័យ។\n៤. [Share Repurchases / Buybacks]៖ ទិញភាគហ៊ុនក្រុមហ៊ុនខ្លួនឯងត្រឡប់មកវិញ ប្រសិនបើតម្លៃហ៊ុនធ្លាក់ថោក។\n៥. [Pay Dividends]៖ ចែកភាគលាភជាសាច់ប្រាក់ដល់ម្ចាស់ភាគហ៊ុន ប្រសិនបើគ្មានឱកាសវិនិយោគណាដែលចំណេញ។', 'គណនាអត្រាផលចំណេញលើដើមទុនវិនិយោគ (ROIC = Net Operating Profit / Invested Capital) នៃគម្រោងវិនិយោគធំៗចំនួន ២ របស់ក្រុមហ៊ុនអ្នក។', 'តើការសម្រេចចិត្តវិនិយោគទុនរបស់ក្រុមហ៊ុនអ្នកកន្លងមក ត្រូវបានជំរុញដោយ «ផលចំណេញលើដើមទុន (ROIC)» ឬដោយសារ «ចំណង់ចង់បានភាពហ៊ឺហារ»?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ពិនិត្យរបាយការណ៍លំហូរសាច់ប្រាក់សេរី (Free Cash Flow Statement) ជាមួយ CFO សម្រាប់ត្រីមាសនេះ។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-csuite-4', 'lesson-csuite-4', 'តើរវាងប្រាក់ចំណេញគណនេយ្យ (Accounting Net Profit) និងលំហូរសាច់ប្រាក់សេរី (Free Cash Flow) តើមួយណាជារង្វាស់នៃតម្លៃពិតប្រាកដរបស់ក្រុមហ៊ុន?', 'Between Accounting Net Profit and Free Cash Flow, which metric reveals the true economic reality of a business?', '["A. ប្រាក់ចំណេញគណនេយ្យ ព្រោះវាជាលេខដែលបង្ហាញលើបណ្តាញព័ត៌មាន។","B. លំហូរសាច់ប្រាក់សេរី (Free Cash Flow) ព្រោះវាជាសាច់ប្រាក់សុទ្ធដែលនៅសល់ជាក់ស្តែងដែលអាចយកទៅវិនិយោគ ឬចែកភាគលាភ ដោយមិនអាចក្លែងបន្លំតាមក្បួនគណនេយ្យបាន។","C. តួលេខទាំងពីរមិនសំខាន់ទាំងអស់។"]', '["A. Accounting Net Profit because it headlines press releases.","B. Free Cash Flow because it represents real spendable cash after all capex, immune to accounting gimmickry.","C. Neither metric matters."]', 1, 'ការពន្យល់៖ "Cash is King"។ ប្រាក់ចំណេញគណនេយ្យអាចកែច្នៃបានតាមវិធីសាស្ត្ររំលស់ ប៉ុន្តែលំហូរសាច់ប្រាក់សេរី (FCF) គឺជាការពិតជាក់ស្តែងដែលចិញ្ចឹមស្ថាប័ន។', 'Explanation: Free cash flow represents unencumbered capital available for compounding; accounting net income can be manipulated.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-csuite-5', 'course-executive-csuite', 'mod-1', 5, '៥. យន្តការផ្លាស់ប្តូរតំណែងថ្នាក់ដឹកនាំ «ឡើងបាន ចុះបាន» (Cadre Mobility: 干部能上能下)', 'Executive Cadre Mobility: The Philosophy of Graceful Demotion & Institutional Renewal', 'text', '• យល់ដឹងពីទស្សនវិជ្ជាគ្រប់គ្រងមន្ត្រីជាន់ខ្ពស់របស់ Huawei «干部能上能下» (ថ្នាក់ដឹកនាំត្រូវតែអាចឡើងបាន និងអាចចុះបានដោយកិត្តិយស)។\n• លុបបំបាត់ «សិទ្ធិកាន់កាប់តំណែងអស់មួយជីវិត» (Tenure Entitlement) ដែលធ្វើឱ្យថ្នាក់លើខ្ជិលច្រអូស។\n• បង្កើតវប្បធម៌ដែលការចុះពីតំណែងមិនមែនជាការអាម៉ាស់ ប៉ុន្តែជាការផ្លាស់ប្តូរតួនាទីដើម្បីភាពរស់រវើកនៃស្ថាប័ន។', 'បញ្ហាធំបំផុតរបស់ស្ថាប័នធំៗគឺ «ជំងឺចាស់វស្សា» (Bureaucratic Sclerosis)៖ ថ្នាក់ដឹកនាំជាន់ខ្ពស់ដែលធ្លាប់មានស្នាដៃកាលពី ១០ ឆ្នាំមុន បានក្លាយជាអ្នកអង្គុយកាន់កាប់តំណែងធំ រារាំងផ្លូវយុវជនជំនាន់ក្រោយ និងបាត់បង់ស្មារតីតស៊ូ។ នៅក្រុមហ៊ុន Huawei និង Alibaba គោលការណ៍ដែកគឺ «干部能上能下» (មន្ត្រីត្រូវតែអាចឡើងបាន និងចុះបាន)៖ ប្រសិនបើអ្នកមិនអាចដឹកនាំការច្នៃប្រឌិតថ្មីបានទេ អ្នកត្រូវតែចុះមកធ្វើជាទីប្រឹក្សា ឬធ្វើជាជំនួយការ ដើម្បីបើកផ្លូវឱ្យយុវជនមានសមត្ថភាពឡើងដឹកនាំ។', '«នៅក្រុមហ៊ុនទូរគមនាគមន៍មួយ Vice President ផ្នែកបច្ចេកវិទ្យា គឺជាបុគ្គលិកជើងចាស់ដែលធ្លាប់កសាងប្រព័ន្ធ 2G/3G។ ប៉ុន្តែនៅពេលក្រុមហ៊ុនត្រូវប្តូរទៅប្រព័ន្ធ Cloud និង 5G គាត់មិនព្រមរៀនសូត្រទេ ហើយតែងតែជំទាស់នឹងបច្ចេកវិទ្យាថ្មី ធ្វើឱ្យគម្រោងរបស់ក្រុមហ៊ុនយឺតជាងគូប្រជែង ២ ឆ្នាំ។ \nCEO មិនបានបណ្តេញគាត់ចេញដោយអយុត្តិធម៌នោះទេ ប៉ុន្តែបានអនុវត្តក្បួន Cadre Mobility៖ គាត់បានតែងតាំងគាត់ជា "Honorary Senior Technical Advisor" ជាមួយប្រាក់បៀវត្សរ៍សមរម្យ និងបានតម្លើងវិស្វករវ័យក្មេងអាយុ ៣៥ ឆ្នាំម្នាក់ដែលពូកែខាង Cloud ឡើងជា Chief Technology Officer (CTO)។ \nការផ្លាស់ប្តូរនេះបានធ្វើឡើងដោយកិត្តិយស ដោយគ្មានជម្លោះផ្ទៃក្នុង។ ត្រឹមតែ ៦ ខែ ក្រុមការងារថ្មីបានដាក់ឱ្យដំណើរការប្រព័ន្ធ 5G ទូទាំងប្រទេស និងបានទាក់ទាញអតិថិជនរាប់លាននាក់។ ក្រុមហ៊ុនបានរក្សាទាំងកិត្តិយសចាស់ទុំ និងថាមពលយុវជនក្នុងពេលតែមួយ។»', '✅ យន្តការអនុវត្តគោលការណ៍ «ឡើងបាន ចុះបាន» (Executive Mobility System)៖\n១. [Term Limits & Re-evaluation]៖ កំណត់អាណត្តិដឹកនាំ ៣-៥ ឆ្នាំ និងវាយតម្លៃសមត្ថភាពឡើងវិញជាប្រចាំ។\n②. [Honorable Exit / Advisory Roles]៖ បង្កើតតួនាទីជាទីប្រឹក្សាជាន់ខ្ពស់ (Senior Advisor / Fellow) សម្រាប់ថ្នាក់ដឹកនាំចាស់វស្សាដើម្បីកុំឱ្យបាត់បង់បទពិសោធន៍។\n៣. [Promote Hungry Young Talent]៖ បង្កើតកូតាបង្ខំឱ្យមានយុវជនក្រោមអាយុ ៣៥-៤០ ឆ្នាំក្នុងជួរ C-Suite យ៉ាងហោចណាស់ ៣០%។', 'ពិនិត្យមើលជួរថ្នាក់ដឹកនាំ C-Suite និង Director ក្នុងក្រុមហ៊ុនអ្នក តើមានតំណែងណាខ្លះដែលកំពុងជាប់គាំងដោយសារមនុស្សចាស់វស្សាអស់ថាមពល?', 'ប្រសិនបើថ្ងៃណាមួយមានយុវជនជំនាន់ក្រោយដែលមានសមត្ថភាព និងថាមពលខ្លាំងជាងអ្នក តើអ្នកមានចិត្តទូលាយគ្រប់គ្រាន់ក្នុងការចុះពីតំណែងដើម្បីបើកផ្លូវឱ្យគេដែរឬទេ?', '🎯 សកម្មភាពថ្ងៃនេះ៖ រៀបចំគោលការណ៍វាយតម្លៃអាណត្តិដឹកនាំ (Executive Tenure Review Policy) សម្រាប់ដាក់ជូន Board ពិចារណា។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-csuite-5', 'lesson-csuite-5', 'តើគោលបំណងចម្បងនៃទស្សនវិជ្ជា Huawei «干部能上能下» (Executive Mobility) គឺជាអ្វី?', 'What is the primary rationale behind the Huawei executive mobility doctrine (干部能上能下)?', '["A. ដើម្បីបណ្តេញមនុស្សចាស់ចោលដោយគ្មានកិត្តិយស។","B. ដើម្បីលុបបំបាត់ការក្រអឺតក្រទមនៃតំណែងអចិន្ត្រៃយ៍ បញ្ចូលថាមពលយុវជនថ្មី និងរក្សាភាពស្វាហាប់រស់រវើកនៃស្ថាប័នជាបន្តបន្ទាប់។","C. ដើម្បីកាត់បន្ថយប្រាក់ខែរបស់ថ្នាក់ដឹកនាំ។"]', '["A. To dishonorably purge older employees.","B. To eradicate tenure entitlement, inject dynamic young talent, and sustain institutional vitality and aggressive innovation.","C. To cut executive compensation."]', 1, 'ការពន្យល់៖ ស្ថាប័នដែលមិនហ៊ានផ្លាស់ប្តូរថ្នាក់ដឹកនាំចាស់ៗដែលអស់ថាមពល នឹងត្រូវស្លាប់ដោយសារភាពនៅទ្រឹង (Inertia)។ ការចរាចរតំណែងរក្សាភាពរស់រវើក។', 'Explanation: Cadre mobility dismantles bureaucratic ossification, ensuring meritocratic leadership renewal.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-csuite-6', 'course-executive-csuite', 'mod-1', 6, '៦. ទំនាក់ទំនងអ្នកវិនិយោគ និងការបង្កើនមេគុណតម្លៃក្រុមហ៊ុន (Investor Relations & Valuation Multiples)', 'Investor Relations & Enterprise Valuation: Mastering Multiples (P/E, EV/EBITDA)', 'text', '• យល់ដឹងពីរបៀបដែលទីផ្សារទុនវាយតម្លៃក្រុមហ៊ុន (EV/EBITDA, P/E Ratio, DCF Valuation)។\n• បង្កើតរឿងរ៉ាវយុទ្ធសាស្ត្រ (Equity Story) ដ៏ទាក់ទាញសម្រាប់ទាក់ទាញមូលនិធិវិនិយោគ Private Equity (PE) និង Venture Capital (VC)។\n• គ្រប់គ្រងទំនាក់ទំនងជាមួយអ្នកវិនិយោគ (Investor Relations - IR) ប្រកបដោយភាពស្មោះត្រង់ និងវិជ្ជាជីវៈខ្ពស់។', 'ក្រុមហ៊ុនពីរដែលមានប្រាក់ចំណេញ $1,000,000 ដូចគ្នា ប៉ុន្តែក្រុមហ៊ុនមួយអាចមានតម្លៃទីផ្សារ $5,000,000 (មេគុណ 5x) រីឯក្រុមហ៊ុនមួយទៀតមានតម្លៃ $30,000,000 (មេគុណ 30x)។ ភាពខុសគ្នានេះអាស្រ័យលើ «គុណភាពនៃប្រាក់ចំណូល» (Revenue Quality) ដូចជា ការមានអតិថិជនបង់ប្រាក់ប្រចាំខែ (Recurring Revenue), សមត្ថភាពការពារទីផ្សារ (Moat), និង «ជំនឿទុកចិត្តរបស់អ្នកវិនិយោគ»។ C-Suite ឆ្នើមត្រូវតែយល់ដឹងពីរបៀបជំរុញមេគុណតម្លៃក្រុមហ៊ុន (Multiple Expansion)។', '«ក្រុមហ៊ុនចែកចាយសម្ភារសំណង់មួយរកប្រាក់ចំណេញ EBITDA បាន $3,000,000 ក្នុងមួយឆ្នាំ ប៉ុន្តែអ្នកវិនិយោគផ្តល់តម្លៃឱ្យត្រឹមតែ 4x EBITDA (ស្មើនឹង $12,000,000) ព្រោះជាអាជីវកម្មទិញមកលក់ទៅបែបប្រពៃណី។ \nCEO និង CFO ថ្មីបានរួមគ្នាផ្លាស់ប្តូរគំរូអាជីវកម្ម៖ ពួកគេបានបង្កើតប្រព័ន្ធ B2B Digital Platform ដែលផ្គត់ផ្គង់សម្ភារសំណង់តាមកិច្ចសន្យាប្រចាំឆ្នាំ (Contracted Recurring Supply) និងមានទិន្នន័យបញ្ជាទិញស្វ័យប្រវត្តិ។ ពួកគេបានបង្ហាញរបាយការណ៍ Investor Deck ថ្មីទៅកាន់មូលនិធិវិនិយោគសិង្ហបុរី ដោយបង្ហាញថា ៨០% នៃចំណូលគឺជា Recurring Revenue ដែលអាចទស្សន៍ទាយទុកជាមុនបាន។ \nអ្នកវិនិយោគបានកែប្រែមេគុណតម្លៃក្រុមហ៊ុនឡើងដល់ 12x EBITDA! តម្លៃក្រុមហ៊ុនបានកើនឡើងពី $12,000,000 ឡើងដល់ $36,000,000 ក្នុងរយៈពេលតែ ២ ឆ្នាំ ដោយម្ចាស់ភាគហ៊ុនដើមទទួលបានផលចំណេញមហាសាល។»', '✅ កត្តា ៤ យ៉ាងដែលជួយបង្កើនមេគុណតម្លៃក្រុមហ៊ុន (Multiple Drivers)៖\n១. [Recurring Revenue]៖ ចំណូលកិច្ចសន្យាជាប់លាប់ (Subscription/Retainer) មានតម្លៃខ្ពស់ជាងចំណូលលក់ដាច់មួយដងៗ ៣ ដង។\n②. [High Gross Margins]៖ អាជីវកម្មដែលមាន Margin លើស ៤០% ទាក់ទាញមេគុណខ្ពស់ជាង។\n៣. [Low Customer Churn]៖ អត្រាអតិថិជនឈប់ប្រើប្រាស់ទាបជាង ៥% ក្នុងមួយឆ្នាំ។\n៤. [Predictable Growth Runway]៖ ផែនការលូតលាស់ច្បាស់លាស់ក្នុងទីផ្សារដែលមានទំហំធំ (Large TAM)។', 'វិភាគគំរូចំណូលបច្ចុប្បន្នរបស់ក្រុមហ៊ុនអ្នក តើមានប៉ុន្មានភាគរយជា Recurring Revenue ហើយតើអ្នកអាចបង្កើនវាដោយរបៀបណា?', 'តើក្រុមហ៊ុនរបស់អ្នកកំពុងរស់នៅដោយពឹងផ្អែកលើ «ការលក់រត់រកភ្ញៀវថ្មីរាល់ខែ» ឬមាន «ប្រព័ន្ធចំណូលស្វ័យប្រវត្តិតាមកិច្ចសន្យា»?', '🎯 សកម្មភាពថ្ងៃនេះ៖ រៀបចំកិច្ចប្រជុំជាមួយ Chief Commercial Officer (CCO) ដើម្បីពិភាក្សាអំពីការបំប្លែងផលិតផលមួយឱ្យទៅជាទម្រង់ Subscription/Retainer។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-csuite-6', 'lesson-csuite-6', 'ហេតុអ្វីបានជាក្រុមហ៊ុនដែលមានចំណូលបែប Recurring Revenue (ចំណូលទៀងទាត់ប្រចាំខែ/ឆ្នាំ) ទទួលបានតម្លៃក្រុមហ៊ុន (Valuation Multiple) ខ្ពស់ជាងក្រុមហ៊ុនលក់ដាច់មួយដងៗ?', 'Why do companies with recurring revenue command significantly higher valuation multiples than transactional firms?', '["A. ព្រោះអតិថិជនមិនសូវត្អូញត្អែរ។","B. ព្រោះលំហូរសាច់ប្រាក់នាពេលអនាគតមានស្ថេរភាពខ្ពស់ អាចទស្សន៍ទាយបានច្បាស់លាស់ និងមានហានិភ័យទាបចំពោះអ្នកវិនិយោគ។","C. ព្រោះមិនបាច់ចំណាយថ្លៃផ្សាយពាណិជ្ជកម្ម។"]', '["A. Because recurring customers complain less.","B. Because predictable forward cash flows drastically reduce investment risk, warranting a premium valuation multiple.","C. Because advertising expenses drop to zero."]', 1, 'ការពន្យល់៖ ភាពអាចទស្សន៍ទាយបាននៃសាច់ប្រាក់ (Cash Flow Predictability) កាត់បន្ថយហានិភ័យរបស់អ្នកវិនិយោគ ដែលធ្វើឱ្យពួកគេស្ម័គ្រចិត្តបង់ថ្លៃខ្ពស់ជាង។', 'Explanation: High visibility and predictability of future cash flows compress discount rates, boosting valuation multiples.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-csuite-7', 'course-executive-csuite', 'mod-1', 7, '៧. យុទ្ធសាស្ត្រកសាងប្រព័ន្ធអេកូឡូស៊ី និងបណ្តាញសម្ព័ន្ធភាព (Ecosystem & Platform Strategy)', 'Platform & Ecosystem Strategy: Transforming Standalone Firms into Symbiotic Networks', 'text', '• យល់ដឹងពីភាពខុសគ្នារវាងគំរូអាជីវកម្មខ្សែបន្ទាត់ (Linear Pipeline Business) និងគំរូបណ្តាញអេកូឡូស៊ី (Platform Ecosystem)។\n• អនុវត្តទស្សនវិជ្ជារបស់ Tencent «បើកចំហខ្នងបង្អែក ភ្ជាប់អ្វីៗទាំងអស់» (Connect Everything)។\n• បង្កើតឥទ្ធិពលបណ្តាញ (Network Effects) ដែលធ្វើឱ្យក្រុមហ៊ុនកាន់តែរីកធំ កាន់តែពិបាកសម្រាប់គូប្រជែងផ្តួលរំលំ។', 'នៅក្នុងយុគសម័យទំនើប ក្រុមហ៊ុនទោល (Standalone Products) នឹងត្រូវចាញ់ក្រុមហ៊ុនដែលមាន «ប្រព័ន្ធអេកូឡូស៊ី» (Ecosystems)។ នៅប្រទេសចិន Tencent និង Alibaba មិនមែនគ្រាន់តែជាក្រុមហ៊ុនលក់ទំនិញ ឬផ្ញើសារនោះទេ ប៉ុន្តែជាប្រព័ន្ធអេកូឡូស៊ីដ៏ធំដែលភ្ជាប់ទាំងការទូទាត់ប្រាក់ (WeChat Pay / Alipay) ភស្តុភារកម្ម (Cainiao) កម្សាន្ត និងពពកទិន្នន័យ (Cloud)។ C-Suite ត្រូវចេះគិតលើសពីព្រំដែនផលិតផលរបស់ខ្លួន — បង្កើតសម្ព័ន្ធភាពជាមួយដៃគូខាងក្រៅ ដើម្បីឱ្យគ្រប់គ្នារស់នៅក្នុងប្រព័ន្ធរបស់អ្នក។', '«ធនាគារពាណិជ្ជក្នុងស្រុកមួយតែងតែប្រកួតប្រជែងដណ្តើមអតិថិជនដាក់ប្រាក់សន្សំដោយផ្តល់អត្រាការប្រាក់ខ្ពស់ ដែលធ្វើឱ្យប្រាក់ចំណេញរួមធ្លាក់ចុះ។ \nCEO ថ្មីបានប្តូរយុទ្ធសាស្ត្រមកជា Platform Ecosystem៖ ជំនួសឱ្យការធ្វើការងារតែម្នាក់ឯង គាត់បានបើកប្រព័ន្ធ Open Banking API ភ្ជាប់ជាមួយសាលារៀន មន្ទីរពេទ្យ ក្រុមហ៊ុនអគ្គិសនី និង App កក់សំបុត្រកុន។ អតិថិជនអាចទូទាត់ប្រាក់គ្រប់យ៉ាងនៅក្នុង App តែមួយគត់។ \nក្នុងរយៈពេល ២ ឆ្នាំ ធនាគារបានក្លាយជាបេះដូងនៃជីវិតប្រចាំថ្ងៃរបស់ប្រជាជនជាង ២,០០០,០០០ នាក់។ ចំនួនប្រាក់បញ្ញើគ្មានការប្រាក់ (CASA) បានកើនឡើង ៤០០% ដែលជួយឱ្យធនាគារមានថ្លៃដើមទុនទាបបំផុតក្នុងវិស័យ និងមានប្រៀបឈ្នះដាច់លើគូប្រជែង។»', '✅ ជំហាន ៣ នៃការកសាងប្រព័ន្ធអេកូឡូស៊ី (Ecosystem Blueprint)៖\n១. [Core Anchor]៖ កសាងផលិតផលស្នូលមួយឱ្យខ្លាំងបំផុតដែលមនុស្សប្រើរាល់ថ្ងៃ (Daily High-Frequency Use Case)។\n②. [Open API & Partnerships]៖ អញ្ជើញដៃគូអាជីវកម្មដទៃទៀតឱ្យចូលមកភ្ជាប់សេវាកម្មរបស់ពួកគេក្នុងប្រព័ន្ធរបស់អ្នក។\n៣. [Data & Value Sharing]៖ បង្កើតតម្លៃរួមគ្នា (Shared Value) ដោយមិនលេបត្របាក់ដៃគូ ប៉ុន្តែឱ្យដៃគូរីកចម្រើនជាមួយអ្នក។', 'គូរដ្យាក្រាមប្រព័ន្ធអេកូឡូស៊ីជុំវិញអាជីវកម្មរបស់អ្នក៖ តើមានដៃគូខាងក្រៅណាខ្លះ (សាលារៀន មន្ទីរពេទ្យ ភស្តុភារ) ដែលអ្នកអាចភ្ជាប់សម្ព័ន្ធភាពជាមួយបាន?', 'តើអាជីវកម្មរបស់អ្នកកំពុងប្រយុទ្ធតែម្នាក់ឯងជាផលិតផលទោល ឬកំពុងកសាងបណ្តាញសម្ព័ន្ធភាពដែលមិនអាចបំបែកបាន?', '🎯 សកម្មភាពថ្ងៃនេះ៖ កំណត់ដៃគូយុទ្ធសាស្ត្រធំមួយ (Strategic Partner) ហើយផ្តួចផ្តើមការពិភាក្សាអំពីការភ្ជាប់សេវាកម្ម API រួមគ្នា។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-csuite-7', 'lesson-csuite-7', 'តើអ្វីជាអត្ថប្រយោជន៍ដ៏ខ្លាំងក្លាបំផុតនៃឥទ្ធិពលបណ្តាញ (Network Effects) នៅក្នុងប្រព័ន្ធអេកូឡូស៊ី?', 'What constitutes the most formidable competitive advantage of Network Effects in an ecosystem?', '["A. ចំណាយថ្លៃអគ្គិសនីតិចជាង។","B. រាល់ពេលដែលមានអ្នកប្រើប្រាស់ ឬដៃគូថ្មីម្នាក់ចូលរួមក្នុងប្រព័ន្ធ តម្លៃនៃប្រព័ន្ធទាំងមូលនឹងកើនឡើងសម្រាប់មនុស្សគ្រប់គ្នា ដែលធ្វើឱ្យគូប្រជែងមិនអាចចម្លងតាមបាន (Self-reinforcing moat)។","C. មិនបាច់ជួលបុគ្គលិកផ្នែកលក់។"]', '["A. Lower utility consumption.","B. Every additional user or partner geometrically increases the systemic utility for all participants, engineering an impenetrable, self-reinforcing moat.","C. Eliminating the sales department entirely."]', 1, 'ការពន្យល់៖ Network Effects បង្កើតរនាំងការពារដ៏រឹងមាំបំផុត។ នៅពេលមនុស្សគ្រប់គ្នានៅក្នុងប្រព័ន្ធរបស់អ្នក គ្មានអ្នកណាចង់ចាកចេញទៅប្រើប្រព័ន្ធថ្មីឡើយ។', 'Explanation: Two-sided network effects create compounding enterprise utility, generating near-monopolistic defensibility.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-csuite-8', 'course-executive-csuite', 'mod-1', 8, '៨. ការទស្សន៍ទាយសេដ្ឋកិច្ចម៉ាក្រូ និងការការពារហានិភ័យអតិផរណា (Macroeconomics & FX Hedging)', 'Macro-Economic Strategy: Currency Hedging, Inflation Defense & ASEAN Geo-Economics', 'text', '• យល់ដឹងពីផលប៉ះពាល់នៃអត្រាការប្រាក់សកល (US Fed Rates) និងគោលនយោបាយរូបិយវត្ថុកម្ពុជា (KHR/USD) លើអាជីវកម្ម។\n• អនុវត្តយុទ្ធសាស្ត្រការពារហានិភ័យប្តូរប្រាក់ (FX Hedging & Forward Contracts) សម្រាប់អាជីវកម្មនាំចេញ-នាំចូល។\n• រៀបចំរចនាសម្ព័ន្ធទ្រព្យសម្បត្តិដើម្បីទប់ទល់នឹងរលកអតិផរណា និងការប្រែប្រួលភូមិសាស្ត្រនយោបាយ។', 'ថ្នាក់ដឹកនាំ C-Suite មិនអាចមើលត្រឹមតែប្រតិបត្តិការផ្ទៃក្នុងក្រុមហ៊ុននោះទេ ប៉ុន្តែត្រូវយល់ដឹងពី «ចរន្តទឹកសេដ្ឋកិច្ចម៉ាក្រូសកល» (Macroeconomic Currents)។ ការផ្លាស់ប្តូរអត្រាការប្រាក់របស់ធនាគារកណ្តាលសហរដ្ឋអាមេរិក ឬការប្រែប្រួលតម្លៃប្រេងសកល អាចកម្ទេចប្រាក់ចំណេញរបស់ក្រុមហ៊ុនក្នុងរយៈពេលតែមួយយប់ ប្រសិនបើគ្មានយុទ្ធសាស្ត្រការពារហានិភ័យ (Hedging) ច្បាស់លាស់។ C-Suite ត្រូវចេះអានសញ្ញាសេដ្ឋកិច្ច និងរៀបចំកប៉ាល់ក្រុមហ៊ុនឱ្យរួចរាល់មុនពេលព្យុះសេដ្ឋកិច្ចបោកបក់មកដល់។', '«ក្រុមហ៊ុននាំចូលគ្រឿងចក្រកសិកម្មមួយបានបញ្ជាទិញគ្រឿងចក្រពីប្រទេសជប៉ុនជាប្រាក់យេន (JPY) ប៉ុន្តែលក់ឱ្យកសិករនៅកម្ពុជាជាប្រាក់ដុល្លារ (USD) និងរៀល (KHR) តាមការបង់រំលស់រយៈពេល ៣ ឆ្នាំ។ \nCFO ដែលមានចក្ខុវិស័យម៉ាក្រូសេដ្ឋកិច្ចបានកត់សម្គាល់ឃើញថារូបិយប័ណ្ណអន្តរជាតិកំពុងជួបការប្រែប្រួលខ្លាំង។ គាត់បានសម្រេចចិត្តប្រើប្រាស់កិច្ចសន្យាការពារហានិភ័យរូបិយប័ណ្ណ (FX Forward Contract) ជាមួយធនាគារ ដើម្បីចាក់សោអត្រាប្តូរប្រាក់ JPY/USD ថេរសម្រាប់រយៈពេល ២ ឆ្នាំ។ \nមួយឆ្នាំក្រោយមក នៅពេលតម្លៃប្រាក់យេនឡើងថ្លៃ ២៥% ភ្លាមៗ គូប្រជែងដែលមិនបាន Hedging ត្រូវខាតបង់រាប់លានដុល្លារ និងត្រូវបង្ខំចិត្តដំឡើងថ្លៃរហូតដល់លក់មិនដាច់។ រីឯក្រុមហ៊ុនរបស់គាត់នៅតែរក្សាថ្លៃដើមថេរដដែល និងបានឆ្លៀតឱកាសនេះដណ្តើមចំណែកទីផ្សារ ៤០% ទូទាំងប្រទេស។»', '✅ វិធាន ៣ យ៉ាងក្នុងការការពារហានិភ័យសេដ្ឋកិច្ចម៉ាក្រូ៖\n១. [Match Currency Revenue & Debt]៖ ប្រសិនបើចំណូលរបស់អ្នកជារៀល ចូរខ្ចីបំណុលជារៀល កុំខ្ចីបំណុលជាដុល្លារ ឬយេនដែលប្រឈមនឹងហានិភ័យប្តូរប្រាក់។\n②. [Natural Hedging]៖ ទិញវត្ថុធាតុដើម និងលក់ចេញក្នុងរូបិយប័ណ្ណតែមួយតាមដែលអាចធ្វើទៅបាន។\n៣. [Dynamic Pricing Contracts]៖ បញ្ចូលខចែងកែសម្រួលតម្លៃតាមអតិផរណា (Inflation Adjustment Clause) ក្នុងកិច្ចសន្យាផ្គត់ផ្គង់រយៈពេលវែង។', 'វិភាគរចនាសម្ព័ន្ធរូបិយប័ណ្ណនៃចំណូល និងចំណាយរបស់ក្រុមហ៊ុនអ្នក តើក្រុមហ៊ុនមានហានិភ័យប្តូរប្រាក់ (FX Exposure) ត្រង់ចំណុចណាខ្លះ?', 'តើកិច្ចសន្យាអាជីវកម្មរយៈពេលវែងរបស់អ្នក បានត្រៀមការពារខ្លួនពីការកើនឡើងនៃអតិផរណា និងការប្រែប្រួលអត្រាការប្រាក់ហើយឬនៅ?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ពិនិត្យបញ្ជីបំណុល និងរូបិយប័ណ្ណទូទាត់ទាំងអស់របស់ក្រុមហ៊ុនជាមួយ CFO ដើម្បីកំណត់ FX Exposure។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-csuite-8', 'lesson-csuite-8', 'តើអ្វីជាហានិភ័យដ៏ធំបំផុតសម្រាប់ក្រុមហ៊ុនដែលរកចំណូលជារូបិយប័ណ្ណក្នុងស្រុក ប៉ុន្តែខ្ចីបំណុលធនាគារជារូបិយប័ណ្ណបរទេសដោយមិនបាន Hedging?', 'What is the greatest risk for a firm earning local currency while holding unhedged foreign-denominated debt?', '["A. អតិថិជននឹងឈប់ទិញទំនិញ។","B. នៅពេលរូបិយប័ណ្ណក្នុងស្រុកធ្លាក់ថ្លៃ ទំហំបំណុលដែលត្រូវសងនឹងកើនឡើងយ៉ាងសម្បើមភ្លាមៗ ដែលអាចរុញច្រានក្រុមហ៊ុនឱ្យក្ស័យធន (Currency Mismatch Crisis)។","C. ធនាគារនឹងទារបំណុលមុនកាលកំណត់។"]', '["A. Customers will immediately stop buying goods.","B. Local currency depreciation drastically inflates foreign debt servicing burdens in local terms, frequently causing insolvencies.","C. Banks will accelerate early repayment."]', 1, 'ការពន្យល់៖ វិបត្តិរូបិយប័ណ្ណមិនស៊ីគ្នា (Currency Mismatch) គឺជាមូលហេតុចម្បងដែលក្រុមហ៊ុនជាច្រើននៅអាស៊ីក្ស័យធនក្នុងអំឡុងពេលវិបត្តិសេដ្ឋកិច្ច។', 'Explanation: Unhedged currency mismatches rapidly trigger debt distress during currency devaluation shocks.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-csuite-9', 'course-executive-csuite', 'mod-1', 9, '៩. ឥទ្ធិពលបុគ្គលិកលក្ខណៈថ្នាក់ដឹកនាំកំពូល និងការទូតធុរកិច្ច (Executive Presence & High-Stakes Diplomacy)', 'Executive Presence: Gravitas, Strategic Communication & High-Stakes Diplomacy', 'text', '• យល់ដឹងពីសសរស្តម្ភទាំង ៣ នៃ Executive Presence៖ ភាពថ្លៃថ្នូរ (Gravitas), ទំនាក់ទំនង (Communication), និងរូបរាងវិជ្ជាជីវៈ (Appearance)។\n• ដឹកនាំការចរចាដែលមានសម្ពាធ និងទំហំទឹកប្រាក់រាប់លានដុល្លារ (High-Stakes Negotiation) ដោយភាពស្ងប់ស្ងាត់ដាច់ខាត។\n• កសាងទំនាក់ទំនងការទូតជាមួយថ្នាក់ដឹកនាំរដ្ឋាភិបាល ស្ថានទូត និងដៃគូអន្តរជាតិ។', 'នៅកម្រិត C-Suite មនុស្សមិនគ្រាន់តែវាយតម្លៃអ្នកលើចំណេះដឹងបច្ចេកទេសនោះទេ ប៉ុន្តែពួកគេសម្រេចចិត្តវិនិយោគ ឬសហការដោយផ្អែកលើ «Executive Presence» — ភាពថ្លៃថ្នូរ ភាពស្ងប់ស្ងាត់ក្នុងគ្រាអាសន្ន និងសមត្ថភាពបញ្ចុះបញ្ចូលដោយគ្មានការស្រែកគំហក។ មេដឹកនាំដែលមាន Gravitas ខ្ពស់ គ្រាន់តែដើរចូលបន្ទប់ប្រជុំ ក៏អាចធ្វើឱ្យបរិយាកាសស្ងប់ស្ងាត់ និងបង្កើតការគោរពដោយស្វ័យប្រវត្តិ។', '«ក្នុងអំឡុងពេលចរចាកិច្ចសន្យារួមទុន $50,000,000 ជាមួយក្រុមហ៊ុនវិនិយោគបរទេស ភាគីម្ខាងទៀតបានព្យាយាមប្រើវិធីសាស្ត្រគាបសង្កត់ផ្លូវចិត្តយ៉ាងខ្លាំង៖ ពួកគេបានស្រែកតវ៉ា ទម្លាក់ឯកសារលើតុ និងគំរាមដើរចេញពីបន្ទប់ប្រជុំ។ \nលោកបណ្ឌិត ហេង វណ្ណា (CEO) មិនបានខឹង មិនបានតបតដោយកំហឹង ហើយក៏មិនបានភ័យស្លន់ស្លោឡើយ។ គាត់បានអង្គុយត្រង់ខ្លួន សម្លឹងមើលភ្នែកដៃគូចរចាដោយស្នាមញញឹមដ៏ស្ងប់ស្ងាត់ ហើយបានរង់ចាំឱ្យពួកគេស្រែកចប់។ បន្ទាប់មក គាត់បាននិយាយដោយសំឡេងទាប មួយៗ និងច្បាស់ៗថា៖ "យើងយល់ពីក្តីបារម្ភរបស់លោក។ ប៉ុន្តែភាពជាដៃគូរយៈពេលវែងមិនអាចកសាងឡើងលើការគំរាមកំហែងបានឡើយ។ ប្រសិនបើលោកត្រៀមខ្លួនជជែកលើតួលេខជាក់ស្តែង យើងនឹងបន្ត។ ប្រសិនបើមិនទាន់ទេ យើងអាចសម្រាកពិសាកាហ្វេសិន"។ \nភាពស្ងប់ស្ងាត់ និងម៉ឺងម៉ាត់កម្រិតកំពូលនេះបានធ្វើឱ្យភាគីម្ខាងទៀតមានការកោតញញើតជាខ្លាំង។ ពួកគេបានសុំទោស និងត្រឡប់មកចរចាដោយសន្តិវិធីវិញ ហើយកិច្ចសន្យាត្រូវបានចុះហត្ថលេខាដោយផ្តល់លក្ខខណ្ឌអំណោយផលបំផុតដល់ក្រុមហ៊ុនរបស់គាត់។»', '✅ សសរស្តម្ភ ៣ នៃ Executive Gravitas៖\n១. [Grace Under Fire]៖ កាន់តែមានសម្ពាធខ្លាំង កាន់តែត្រូវនិយាយយឺត និងរក្សាដង្ហើមវែងៗ។ កុំបង្ហាញការខឹង ឬភ័យស្លន់ស្លោជាដាច់ខាត។\n②. [The Power of the Pause]៖ មុននឹងឆ្លើយសំណួរពិបាក ចូរផ្អាកស្ងៀម ៣ វិនាទីសិន។ ភាពស្ងៀមស្ងាត់បង្ហាញពីអំណាច និងការគ្រប់គ្រងស្ថានការណ៍។\n៣. [Crisp Brevity]៖ និយាយខ្លី ចំចំណុច កុំប្រើពាក្យស្ទាក់ស្ទើរ (Um, Ah, Like)។', 'អនុវត្តការហ្វឹកហាត់កាយវិការ និងការផ្អាក ៣ វិនាទី (The 3-Second Pause) មុននឹងឆ្លើយសំណួរក្នុងកិច្ចប្រជុំបន្ទាប់របស់អ្នក។', 'តើអ្នកធ្លាប់បាត់បង់ការគ្រប់គ្រងអារម្មណ៍ក្នុងកិច្ចប្រជុំសំខាន់ដែរឬទេ? តើអ្នកអាចហ្វឹកហាត់ចិត្តឱ្យស្ងប់ស្ងាត់ជាងមុនដោយរបៀបណា?', '🎯 សកម្មភាពថ្ងៃនេះ៖ អនុវត្តទម្លាប់ដកដង្ហើមវែងៗ និងផ្អាក ៣ វិនាទីមុននឹងឆ្លើយតបចំពោះសារ ឬសំណួរដែលធ្វើឱ្យអ្នកខឹង។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-csuite-9', 'lesson-csuite-9', 'នៅក្នុងកិច្ចចរចាដែលមានសម្ពាធខ្ពស់ (High-Stakes Negotiation) តើប្រតិកម្មណាដែលបង្ហាញពី Executive Gravitas ពិតប្រាកដ?', 'In high-stakes negotiation environments, what reaction demonstrates authentic executive gravitas?', '["A. ស្រែកតវ៉ា និងជេរតបតវិញដើម្បីកុំឱ្យគេមើលងាយ។","B. រក្សាភាពស្ងប់ស្ងាត់ដាច់ខាត និយាយដោយសំឡេងទាបម៉ឺងម៉ាត់ និងមិនបណ្តោយឱ្យអារម្មណ៍គ្រប់គ្រងការសម្រេចចិត្ត (Grace under pressure)។","C. យល់ព្រមតាមការទាមទាររបស់គេគ្រប់យ៉ាងដើម្បីកុំឱ្យមានជម្លោះ។"]', '["A. Shouting angrily to demonstrate dominance.","B. Maintaining absolute composure, speaking with calm precision, and refusing to allow emotional outbursts to dictate strategic outcomes.","C. Conceding to all demands to avoid confrontation."]', 1, 'ការពន្យល់៖ ភាពស្ងប់ស្ងាត់ក្នុងគ្រាអាសន្ន (Grace under fire) គឺជាសញ្ញាសម្គាល់នៃអំណាចពិតប្រាកដ។ អ្នកណាគ្រប់គ្រងអារម្មណ៍បាន អ្នកនោះគ្រប់គ្រងតុចរចា។', 'Explanation: Gravitas is marked by unshakeable composure under fire, neutralizing hostility with calm precision.');
INSERT INTO `lessons` (`id`, `course_id`, `module_id`, `order_index`, `title_kh`, `title_en`, `type`, `learning_objectives`, `short_explanation`, `workplace_story`, `practical_example`, `practical_exercise`, `reflection`, `workplace_action`) VALUES ('lesson-csuite-10', 'course-executive-csuite', 'mod-1', 10, '១០. ការកសាងអាជីវកម្មរយឆ្នាំ និងកេរដំណែលស្ថាប័ន (Building a 102-Year Enterprise)', 'Century-Old Enterprise Stewardship: The Alibaba 102-Year Vision & Institutional Legacy', 'text', '• យល់ដឹងពីទស្សនវិជ្ជាអាជីវកម្មរយឆ្នាំរបស់ Alibaba «កសាងក្រុមហ៊ុនដែលរស់នៅឆ្លងកាត់ ៣ សតវត្សរ៍ (១០២ ឆ្នាំ)»។\n• បង្កើតស្ថាប័នដែលមិនពឹងផ្អែកលើបុគ្គលម្នាក់ (Institutionalization over Personalization)។\n• ត្រៀមលក្ខណៈផ្ទេរតំណែងកំពូល (CEO Succession) ដើម្បីធានានិរន្តរភាពអាជីវកម្មរាប់ទសវត្សរ៍ខាងមុខ។', 'នៅក្រុមហ៊ុន Alibaba ស្ថាបនិក Jack Ma បានដាក់ទស្សនវិស័យថា ក្រុមហ៊ុនត្រូវតែរស់នៅឱ្យបាន ១០២ ឆ្នាំ (ចាប់ពីឆ្នាំ ១៩៩៩ ឆ្លងកាត់សតវត្សរ៍ទី ២០, ២១ និងចូលដល់សតវត្សរ៍ទី ២២)។ ភាគច្រើននៃក្រុមហ៊ុនបរាជ័យព្រោះវាពឹងផ្អែកតែលើទេពកោសល្យរបស់ស្ថាបនិកម្នាក់ឯង នៅពេលស្ថាបនិកចាស់ជរា ឬចាកចេញ ក្រុមហ៊ុនក៏រលាយសាបសូន្យ។ C-Suite ឆ្នើមមិនគ្រាន់តែជាអ្នករកលុយក្នុងអាណត្តិរបស់ខ្លួននោះទេ ប៉ុន្តែជា «អ្នកថែរក្សា និងបន្តវេន» (The Steward) — កសាងវប្បធម៌ ប្រព័ន្ធ និងគុណតម្លៃដែលនឹងបន្តរស់នៅរាប់ជំនាន់ក្រោយពេលខ្លួនចាកចេញ។', '«នៅពេល Jack Ma សម្រេចចិត្តចុះចេញពីតំណែងជាប្រធានក្រុមហ៊ុន Alibaba ក្នុងឆ្នាំ ២០១៩ មនុស្សជាច្រើនគិតថាក្រុមហ៊ុននឹងជួបវិបត្តិធ្ងន់ធ្ងរ។ ប៉ុន្តែការពិតជាក់ស្តែង Jack Ma បានរៀបចំផែនការបន្តវេននេះតាំងពី ១០ ឆ្នាំមុន (Partnership System)។ គាត់បានបណ្តុះបណ្តាលថ្នាក់ដឹកនាំជំនាន់ថ្មីដូចជា Daniel Zhang និង Eddie Wu ឱ្យយល់ដឹងពី DNA និងវប្បធម៌ក្រុមហ៊ុនយ៉ាងស៊ីជម្រៅ។ \nនៅថ្ងៃដែល Jack Ma ដើរចេញពីឆាក ក្រុមហ៊ុននៅតែដំណើរការយ៉ាងរលូន និងបន្តរកចំណូលបានរាប់សិបពាន់លានដុល្លារ។ នេះគឺជាភាពខុសគ្នារវាង "ក្រុមហ៊ុនដែលពឹងលើបុគ្គលម្នាក់" និង "ស្ថាប័នដែលពឹងលើប្រព័ន្ធ និងជំនឿរួម"។ ភាពជោគជ័យពិតប្រាកដរបស់មេដឹកនាំ គឺការកសាងស្ថាប័នដែលអាចដំណើរការបានកាន់តែល្អប្រសើរទោះបីជាគ្មានវត្តមានរបស់ខ្លួនក៏ដោយ។»', '✅ សសរស្តម្ភ ៣ នៃការកសាងអាជីវកម្មរយឆ្នាំ (The Century-Old Blueprint)៖\n១. [Core Purpose Beyond Profit]៖ ស្វែងរកបេសកកម្មដែលបម្រើមនុស្សជាតិ (ដូចជា "Make it easy to do business anywhere") មិនមែនគ្រាន់តែរកលុយ។\n②. [Institutionalized Culture]៖ ចងក្រងគុណតម្លៃស្នូលឱ្យក្លាយជាច្បាប់ និងជាខ្យល់ដង្ហើមរបស់បុគ្គលិកគ្រប់រូប។\n៣. [Partnership Governance]៖ បង្កើតរចនាសម្ព័ន្ធដៃគូ (Partnership Committee) ដែលជ្រើសរើសអ្នកបន្តវេនដោយផ្អែកលើការការពារបេសកកម្មស្ថាប័ន។', 'សរសេរសេចក្តីប្រកាសកេរដំណែលស្ថាប័ន (Legacy Statement)៖ ប្រសិនបើ ៥០ ឆ្នាំក្រោយ ក្រុមហ៊ុនរបស់អ្នកនៅតែបន្តរីកចម្រើន តើអ្វីជាគុណតម្លៃ និងបេសកកម្មស្នូលដែលអ្នកចង់ឱ្យគេចងចាំបំផុត?', 'ប្រសិនបើអ្នកដើរចេញពីស្ថាប័ននៅថ្ងៃស្អែក តើអ្វីដែលអ្នកបានកសាងនឹងបន្តរីកចម្រើន ឬនឹងរលាយបាត់ទៅជាមួយអ្នក?', '🎯 សកម្មភាពថ្ងៃនេះ៖ ចំណាយពេល ១ ម៉ោងសរសេរទស្សនវិស័យកេរដំណែល ២០ ឆ្នាំ (20-Year Legacy Document) សម្រាប់ស្ថាប័នរបស់អ្នក។');
INSERT INTO `quiz_questions` (`id`, `lesson_id`, `prompt_kh`, `prompt_en`, `options_kh`, `options_en`, `correct_option_index`, `explanation_kh`, `explanation_en`) VALUES ('q-csuite-10', 'lesson-csuite-10', 'តាមទស្សនវិជ្ជាស្ថាប័ន Alibaba «102-Year Company» តើអ្វីជារង្វាស់នៃភាពជោគជ័យដ៏អស្ចារ្យបំផុតរបស់ CEO ជំនាន់ស្ថាបនិក?', 'According to Alibaba 102-Year Company doctrine, what is the ultimate measure of an executive founder success?', '["A. ក្តោបក្តាប់អំណាចរហូតដល់ថ្ងៃស្លាប់។","B. ការកសាងប្រព័ន្ធអភិបាលកិច្ច វប្បធម៌ និងជួរអ្នកបន្តវេនរឹងមាំ ដែលអនុញ្ញាតឱ្យស្ថាប័នបន្តលូតលាស់កាន់តែខ្លាំងក្លា ទោះបីជាគ្មានវត្តមានរបស់ស្ថាបនិកក៏ដោយ។","C. ការដកលុយទាំងអស់ចេញពីក្រុមហ៊ុនមុនពេលចូលនិវត្តន៍។"]', '["A. Hoarding supreme executive power until death.","B. Architecting an institutionalized governance, cultural DNA, and talent pipeline capable of thriving vibrantly long after the founder steps aside.","C. Liquidating enterprise capital before retiring."]', 1, 'ការពន្យល់៖ ភាពជោគជ័យពិតប្រាកដរបស់ស្ថាបត្យករអាជីវកម្ម គឺការកសាងស្ថាប័នដែលរស់នៅយូរអង្វែងជាងអាយុកាលរបស់ខ្លួនឯង (Built to Last)។', 'Explanation: True greatness is measured by institutional immortality: building an enterprise that prospers without individual dependency.');
INSERT INTO `cv_templates` (`id`, `industry_kh`, `industry_en`, `title_kh`, `title_en`, `icon_name`, `summary`, `skills`, `achievements_xyz`, `education`, `recommended_for_level`) VALUES ('cv-marketing', 'ទីផ្សារឌីជីថល & ប្រព័ន្ធផ្សព្វផ្សាយ', 'Digital Marketing & Content Media', 'ប្រធានយុទ្ធសាស្ត្រទីផ្សារឌីជីថល', 'Digital Marketing & Growth Specialist', 'campaign', 'អ្នកជំនាញទីផ្សារឌីជីថលដែលមានបទពិសោធន៍ ៤ ឆ្នាំក្នុងការរៀបចំយុទ្ធនាការ Performance Marketing បង្កើនអតិថិជនសក្តានុពល (Lead Generation) និងការគ្រប់គ្រងថវិកាផ្សាយពាណិជ្ជកម្មតាមបែប ROI-driven។', '["Meta Ads Manager","TikTok Ads","Google Analytics 4","SEO/SEM Optimization","Content Strategy","Canva & CapCut Production","Customer Acquisition Cost (CAC) Reduction"]', '• បង្កើនការលក់អនឡាញ ៣៥% ក្នុងរយៈពេល ៦ ខែ (X) តាមរយៈការរៀបចំយុទ្ធនាការ TikTok Short Videos ចំនួន ៣០ ភាគ (Z) ដែលបង្កើតចំណូលបន្ថែម $45,000 (Y)។\n\n• កាត់បន្ថយថ្លៃដើមទាក់ទាញអតិថិជន (CAC) ២៥% (X) តាមរយៈការធ្វើ A/B Testing លើ Meta Ad Creatives ចំនួន ៥០ ទម្រង់ (Z) សន្សំថវិកាក្រុមហ៊ុនបាន $3,500 ក្នុងមួយខែ (Y)។\n\n• ដឹកនាំ និងបណ្តុះបណ្តាលក្រុមការងារ Content Creators ៤ នាក់ (Z) ឱ្យផលិតវីដេអូ Viral ដែលមានអ្នកទស្សនាសរុបជាង ២ លានដង (X)។', 'បរិញ្ញាបត្រ ផ្នែកទីផ្សារ (Marketing) — សាកលវិទ្យាល័យភូមិន្ទនីតិសាស្ត្រ និងវិទ្យាសាស្ត្រសេដ្ឋកិច្ច (RULE)\nវិញ្ញាបនបត្រ Meta Certified Digital Marketing Associate (2025)', 'Junior / Senior Specialist');
INSERT INTO `cv_templates` (`id`, `industry_kh`, `industry_en`, `title_kh`, `title_en`, `icon_name`, `summary`, `skills`, `achievements_xyz`, `education`, `recommended_for_level`) VALUES ('cv-tech', 'បច្ចេកវិទ្យា & អភិវឌ្ឍន៍សូហ្វវែរ', 'Software Engineering & IT Infrastructure', 'វិស្វករអភិវឌ្ឍន៍ប្រព័ន្ធជាន់ខ្ពស់', 'Senior Full-Stack Software Engineer', 'code', 'វិស្វករកម្មវិធីដែលមានបទពិសោធន៍ ៥ ឆ្នាំក្នុងការកសាងប្រព័ន្ធ Cloud Scalable, RESTful APIs, និង Mobile/Web Applications។ មានជំនាញក្នុងការបង្កើនល្បឿនប្រព័ន្ធ និងការការពារសុវត្ថិភាពទិន្នន័យ។', '["Flutter & Dart","Node.js & TypeScript","PostgreSQL & MongoDB","Docker & CI/CD Pipelines","AWS Cloud Infrastructure","System Architecture & Microservices","Clean Architecture & Unit Testing"]', '• បង្កើនល្បឿនដំណើរការប្រព័ន្ធ ៦០% (X) តាមរយៈការ Refactor Database Queries និងការអនុវត្ត Redis Caching Layer (Z) កាត់បន្ថយ Latency ពី 800ms មកត្រឹម 120ms (Y)។\n\n• កសាង និងដាក់ឱ្យដំណើរការ Mobile App ថ្មីសម្រាប់អតិថិជន ១០០,០០០ នាក់ (X) ក្នុងរយៈពេល ៤ ខែ ដោយប្រើ Flutter & Clean Architecture (Z) សម្រេចបាន Crash-free Rate ៩៩.៨% (Y)។\n\n• កាត់បន្ថយការចំណាយលើ Cloud Server ៣០% (X) តាមរយៈការផ្លាស់ប្តូរទៅកាន់ Containerized Microservices លើ AWS ECS (Z) សន្សំ $1,200 ក្នុងមួយខែ (Y)។', 'បរិញ្ញាបត្រ វិទ្យាសាស្ត្រកុំព្យូទ័រ — វិទ្យាស្ថានបច្ចេកវិទ្យាកម្ពុជា (ITC)\nAWS Certified Solutions Architect – Associate', 'Senior Specialist / Tech Lead');
INSERT INTO `cv_templates` (`id`, `industry_kh`, `industry_en`, `title_kh`, `title_en`, `icon_name`, `summary`, `skills`, `achievements_xyz`, `education`, `recommended_for_level`) VALUES ('cv-finance', 'គណនេយ្យ ហិរញ្ញវត្ថុ & ធនាគារ', 'Accounting, Banking & Corporate Finance', 'ប្រធានគណនេយ្យ និងវិភាគហិរញ្ញវត្ថុ', 'Accounting & Financial Analysis Manager', 'account_balance_wallet', 'អ្នកជំនាញគណនេយ្យ និងហិរញ្ញវត្ថុដែលមានការយល់ដឹងស៊ីជម្រៅអំពីស្តង់ដារ CIFRS for SMEs ច្បាប់សារពើពន្ធកម្ពុជា (GDT) និងការគ្រប់គ្រងលំហូរសាច់ប្រាក់អាជីវកម្មប្រកបដោយតម្លាភាព។', '["QuickBooks & SAP ERP","Cambodian Tax Declarations (Monthly & Annual Tax on Income)","Cash Flow Forecasting","P&L & Balance Sheet Analysis","Cost Reduction & Internal Audit","Advanced Microsoft Excel (Financial Modeling)"]', '• កាត់បន្ថយកំហុសទិន្នន័យប្រកាសពន្ធមកត្រឹម ០% (X) តាមរយៈការរៀបចំប្រព័ន្ធផ្ទៀងផ្ទាត់វិក្កយបត្រ E-Tax Invoice ស្វ័យប្រវត្ត (Z) ជៀសវាងការផាកពិន័យពីអគ្គនាយកដ្ឋានពន្ធដារបាន $12,000 (Y)។\n\n• បង្កើនលំហូរសាច់ប្រាក់បម្រុងរបស់ក្រុមហ៊ុន ៤០% (X) តាមរយៈការកែសម្រួលគោលការណ៍ទារបំណុលអតិថិជន (DSO) ពី ៦០ ថ្ងៃមកត្រឹម ៣០ ថ្ងៃ (Z)។\n\n• ដឹកនាំការរៀបចំរបាយការណ៍សវនកម្មផ្ទៃក្នុងប្រចាំឆ្នាំ (Z) ដែលទទួលបានការអនុម័តដោយគ្មានលក្ខខណ្ឌពីក្រុមហ៊ុនសវនកម្មអន្តរជាតិ Big 4 (X)។', 'បរិញ្ញាបត្រ គណនេយ្យ និងហិរញ្ញវត្ថុ — សាកលវិទ្យាល័យជាតិគ្រប់គ្រង (NUM)\nវិញ្ញាបនបត្រ ACCA Candidate (Affiliate Level)', 'Senior / Supervisor / Manager');
INSERT INTO `cv_templates` (`id`, `industry_kh`, `industry_en`, `title_kh`, `title_en`, `icon_name`, `summary`, `skills`, `achievements_xyz`, `education`, `recommended_for_level`) VALUES ('cv-hr', 'គ្រប់គ្រងធនធានមនុស្ស & រដ្ឋបាល', 'Human Resources & Talent Management', 'ប្រធានផ្នែកធនធានមនុស្ស', 'Human Resources Business Partner (HRBP)', 'people', 'អ្នកគ្រប់គ្រងធនធានមនុស្សដែលមានបទពិសោធន៍ក្នុងការជ្រើសរើសបុគ្គលិកឆ្នើម ការអនុវត្តច្បាប់ការងារកម្ពុជា (ប.ស.ស, អតីតភាពការងារ) និងការកសាងវប្បធម៌ស្ថាប័នប្រកបដោយផលិតភាពខ្ពស់។', '["Talent Acquisition & Interviewing","Cambodian Labor Law & NSSF Compliance","KPI & OKR Performance Appraisals","Employee Retention & 1-on-1 Coaching","Training & Capacity Building","Conflict Mediation & Workplace Harmony"]', '• កាត់បន្ថយអត្រាបុគ្គលិកលាលែងពីការងារ (Turnover Rate) ពី ២៨% មកត្រឹម ១១% ក្នុងមួយឆ្នាំ (X) តាមរយៈការរៀបចំប្រព័ន្ធវាយតម្លៃលទ្ធផលការងារប្រកបដោយយុត្តិធម៌ និងកម្មវិធីសុខុមាលភាពបុគ្គលិក (Z)។\n\n• ជ្រើសរើស និងបណ្តុះបណ្តាលបុគ្គលិកថ្មីចំនួន ៤៥ នាក់ទាន់កាលកំណត់ (X) សម្រាប់ការពង្រីកសាខាថ្មីចំនួន ៣ (Z) ដោយកាត់បន្ថយពេលវេលាជ្រើសរើស (Time-to-hire) ពី ៤៥ ថ្ងៃមកត្រឹម ២១ ថ្ងៃ (Y)។\n\n• រៀបចំ និងសម្របសម្រួលវគ្គបណ្តុះបណ្តាលផ្ទៃក្នុងចំនួន ១២ វគ្គ (Z) ដែលបង្កើនពិន្ទុពេញចិត្តរបស់បុគ្គលិក (eNPS) ដល់ ៨៥% (X)។', 'បរិញ្ញាបត្រ គ្រប់គ្រងធនធានមនុស្ស — សាកលវិទ្យាល័យបៀលប្រាយ (BBU)\nវិញ្ញាបនបត្រ Professional Human Resource Management (CAMHR)', 'Supervisor / Manager / Head of Dept');
INSERT INTO `cv_templates` (`id`, `industry_kh`, `industry_en`, `title_kh`, `title_en`, `icon_name`, `summary`, `skills`, `achievements_xyz`, `education`, `recommended_for_level`) VALUES ('cv-sales', 'ផ្នែកលក់ និងទំនាក់ទំនងអតិថិជន', 'B2B/B2C Sales & Business Development', 'ប្រធានអភិវឌ្ឍន៍អាជីវកម្ម និងការលក់', 'Business Development & Corporate Sales Lead', 'trending_up', 'អ្នកជំនាញផ្នែកលក់ B2B ដែលមានកំណត់ត្រាជោគជ័យក្នុងការចរចាកិច្ចសន្យាធុរកិច្ចធំៗ ការបើកទីផ្សារថ្មី និងការកសាងទំនាក់ទំនងយូរអង្វែងជាមួយដៃគូសាជីវកម្ម។', '["B2B Pipeline Management","Contract Negotiation & Closing","Key Account Management","Sales Pitch & Presentation","CRM (HubSpot & Salesforce)","Market Penetration Strategy"]', '• បង្កើតចំណូលលក់កិច្ចសន្យាថ្មីបាន $320,000 ក្នុងរយៈពេល ១ ឆ្នាំ (X) តាមរយៈការចរចា និងចុះហត្ថលេខាលើកិច្ចព្រមព្រៀងជាមួយអតិថិជនសាជីវកម្មធំៗចំនួន ១៨ ក្រុមហ៊ុន (Z) សម្រេចបាន ១៣៥% នៃ KPI ប្រចាំឆ្នាំ (Y)។\n\n• បង្កើនអត្រាបំប្លែងពី Lead ទៅជាការទិញពិតប្រាកដ (Conversion Rate) ពី ១២% ឡើងដល់ ២៨% (X) តាមរយៈការកែសម្រួល Sales Script និងការផ្តល់ដំណោះស្រាយចំតម្រូវការអតិថិជន (Z)។\n\n• ដឹកនាំក្រុមលក់ ៦ នាក់សម្រេចចំណូលជាប់ចំណាត់ថ្នាក់លេខ ១ ទូទាំងក្រុមហ៊ុនរយៈពេល ៣ ត្រីមាសជាប់គ្នា (X)។', 'បរិញ្ញាបត្រ គ្រប់គ្រងពាណិជ្ជកម្ម (BBA) — សាកលវិទ្យាល័យភូមិន្ទភ្នំពេញ (RUPP)\nវិញ្ញាបនបត្រ Advanced Consultative Selling Skills', 'Senior / Team Leader / Manager');
INSERT INTO `cv_templates` (`id`, `industry_kh`, `industry_en`, `title_kh`, `title_en`, `icon_name`, `summary`, `skills`, `achievements_xyz`, `education`, `recommended_for_level`) VALUES ('cv-logistics', 'ប្រតិបត្តិការ ដឹកជញ្ជូន & ឃ្លាំង', 'Supply Chain, Logistics & Warehouse Operations', 'អ្នកគ្រប់គ្រងខ្សែច្រវាក់ផ្គត់ផ្គង់ និងឃ្លាំង', 'Supply Chain & Logistics Operations Manager', 'local_shipping', 'អ្នកជំនាញប្រតិបត្តិការឃ្លាំង និងដឹកជញ្ជូនដែលមានបទពិសោធន៍ក្នុងការកាត់បន្ថយការខាតបង់ស្តុក ការរៀបចំប្រព័ន្ធដឹកជញ្ជូនលឿនរហ័ស និងការគ្រប់គ្រងអ្នកផ្គត់ផ្គង់ (Vendor Management)។', '["Warehouse Inventory Management (FIFO/LIFO)","Route & Fleet Optimization","Vendor Contract Negotiation","Safety & Quality Standards (5S / Kaizen)","ERP Inventory Tracking","Logistics Cost Optimization"]', '• កាត់បន្ថយការខូចខាត និងការបាត់បង់ទំនិញក្នុងស្តុក ៤៥% (X) តាមរយៈការអនុវត្តប្រព័ន្ធ Barcode Scanning និងក្បួន 5S ក្នុងឃ្លាំងទំហំ ៣,០០០ ម៉ែត្រការ៉េ (Z) សន្សំ $18,000 ក្នុងមួយឆ្នាំ (Y)។\n\n• បង្កើនអត្រាដឹកជញ្ជូនទំនិញដល់ដៃអតិថិជនទាន់ពេលវេលា (On-Time Delivery) ពី ៨២% ឡើងដល់ ៩៧% (X) តាមរយៈការកែសម្រួលផ្លូវធ្វើដំណើរ និងការតាមដាន GPS យានយន្ត (Z)។\n\n• ចរចាកាត់បន្ថយថ្លៃដើមដឹកជញ្ជូនពីដៃគូផ្គត់ផ្គង់បាន ១២% (X) ដែលសន្សំថ្លៃដើមប្រតិបត្តិការប្រចាំឆ្នាំបាន $24,000 (Y)។', 'បរិញ្ញាបត្រ គ្រប់គ្រងខ្សែច្រវាក់ផ្គត់ផ្គង់ និងភស្តុភារ — សាកលវិទ្យាល័យវេស្ទើន (Western University)\nវិញ្ញាបនបត្រ Certified Supply Chain Specialist', 'Supervisor / Manager');
INSERT INTO `cv_templates` (`id`, `industry_kh`, `industry_en`, `title_kh`, `title_en`, `icon_name`, `summary`, `skills`, `achievements_xyz`, `education`, `recommended_for_level`) VALUES ('cv-design', 'ផ្នែករចនាក្រាហ្វិក & UI/UX', 'Graphic Design, Branding & UI/UX Product Design', 'ប្រធានផ្នែករចនាម៉ាកសញ្ញា និងផលិតផល', 'Senior Brand & UI/UX Product Designer', 'palette', 'អ្នករចនាច្នៃប្រឌិតដែលមានបទពិសោធន៍ក្នុងការកសាងអត្តសញ្ញាណម៉ាកសញ្ញា (Brand Identity) និងការរចនាបទពិសោធន៍អ្នកប្រើប្រាស់ (User Experience) សម្រាប់ Mobile App និង Web Platform។', '["Figma & Adobe XD","Adobe Illustrator & Photoshop","Design System & Component Architecture","User Research & Wireframing","Responsive Web & Mobile UI","Brand Guidelines & Packaging Design"]', '• បង្កើនការចុះឈ្មោះប្រើប្រាស់លើកម្មវិធីទូរស័ព្ទ (Sign-up Rate) ៥០% (X) តាមរយៈការធ្វើ Redesign លើទម្រង់ Onboarding Flow ឱ្យសាមញ្ញ និងងាយស្រួល (Z) ផ្អែកលើការស្រាវជ្រាវអ្នកប្រើប្រាស់ ៣០ នាក់ (Y)។\n\n• បង្កើត Design System ស្តង់ដាររួមមួយដែលមាន Components ជាង ២០០ (Z) ដែលជួយឱ្យក្រុម Developers បង្កើតមុខងារថ្មីៗបានលឿនជាងមុន ៣៥% (X)។\n\n• ដឹកនាំការរចនា Brand Identity ថ្មីទាំងស្រុងសម្រាប់ផលិតផល ៥ មុខ (Z) ដែលទទួលបានការសរសើរពីអតិថិជន និងបង្កើនការចងចាំម៉ាកសញ្ញា (Brand Recall) ៦០% (X)។', 'បរិញ្ញាបត្រ រចនាប្រព័ន្ធផ្សព្វផ្សាយ និងសិល្បៈ — សាកលវិទ្យាល័យភូមិន្ទវិចិត្រសិល្បៈ (RUFA)\nGoogle UX Design Professional Certificate', 'Senior / Lead Designer');
INSERT INTO `cv_templates` (`id`, `industry_kh`, `industry_en`, `title_kh`, `title_en`, `icon_name`, `summary`, `skills`, `achievements_xyz`, `education`, `recommended_for_level`) VALUES ('cv-project', 'គ្រប់គ្រងគម្រោង & យុទ្ធសាស្ត្រ', 'Agile Project Management & Scrum Master', 'ប្រធានគ្រប់គ្រងគម្រោងស្ថាប័ន', 'Enterprise Agile Project Manager / Scrum Master', 'assignment_turned_in', 'អ្នកគ្រប់គ្រងគម្រោងដែលមានវិញ្ញាបនបត្រ PMP និងមានបទពិសោធន៍ដឹកនាំគម្រោងបច្ចេកវិទ្យា និងអាជីវកម្មឆ្លងកាត់នាយកដ្ឋានជាច្រើន ដោយធានាការប្រគល់លទ្ធផលទាន់ពេលវេលា និងក្នុងកញ្ចប់ថវិកាកំណត់។', '["Agile, Scrum & Kanban Frameworks","Jira, Trello & Asana Management","Budget & Resource Forecasting","Risk Mitigation & Stakeholder Management","Sprint Planning & Retrospectives","KPI & Milestone Tracking"]', '• ដឹកនាំគម្រោង Digital Transformation ទំហំ $150,000 បញ្ចប់បានមុនកាលកំណត់ ៣ សប្តាហ៍ (X) និងសន្សំថវិកាបាន ៨% (Y) តាមរយៈការអនុវត្តក្បួន Scrum Sprints រយៈពេល ២ សប្តាហ៍ម្តង (Z)។\n\n• កាត់បន្ថយឧបសគ្គកកស្ទះគម្រោង (Project Bottlenecks) ៧០% (X) តាមរយៈការរៀបចំ Daily Standup និង Risk Register យ៉ាងម៉ត់ចត់ (Z)។\n\n• សម្របសម្រួលកិច្ចសហការរវាងក្រុមការងារចំនួន ៤ នាយកដ្ឋានសរុប ២៥ នាក់ (Z) សម្រេចបានពិន្ទុពេញចិត្តពីភាគីពាក់ព័ន្ធ (Stakeholder Satisfaction) ៩៥% (X)។', 'បរិញ្ញាបត្រ គ្រប់គ្រងពាណិជ្ជកម្ម និងប្រព័ន្ធព័ត៌មាន — សាកលវិទ្យាល័យបញ្ញាសាស្ត្រកម្ពុជា (PUC)\nវិញ្ញាបនបត្រ Project Management Professional (PMP) / Certified ScrumMaster (CSM)', 'Project Manager / Scrum Master');
INSERT INTO `cv_templates` (`id`, `industry_kh`, `industry_en`, `title_kh`, `title_en`, `icon_name`, `summary`, `skills`, `achievements_xyz`, `education`, `recommended_for_level`) VALUES ('cv-hospitality', 'បដិសណ្ឋារកិច្ច និងសេវាកម្ម', 'Hospitality, Tourism & Guest Relations', 'ប្រធានផ្នែកសេវាកម្ម និងបដិសណ្ឋារកិច្ច', 'Guest Relations & Hospitality Operations Manager', 'hotel', 'អ្នកជំនាញផ្នែកបដិសណ្ឋារកិច្ចលំដាប់ផ្កាយ ៥ ដែលមានជំនាញពិសេសក្នុងការផ្តល់សេវាកម្មល្អឥតខ្ចោះ ការដោះស្រាយបណ្តឹងភ្ញៀវដោយសន្តិវិធី និងការបណ្តុះបណ្តាលបុគ្គលិកជួរមុខ។', '["5-Star Hospitality Service Standards","VIP Guest Relations & Protocol","Guest Complaint Resolution","Front Office Management Systems (Opera PMS)","Service Quality Audit & Staff Training","Cross-Cultural Communication (Khmer, English, Chinese)"]', '• បង្កើនពិន្ទុពេញចិត្តរបស់ភ្ញៀវលើ TripAdvisor ពី ៤.២ ឡើងដល់ ៤.៨ ផ្កាយ (X) ក្នុងរយៈពេល ៨ ខែ តាមរយៈការបណ្តុះបណ្តាលបុគ្គលិកជួរមុខលើក្បួន "Service from the Heart" (Z)។\n\n• ដោះស្រាយ និងបម្លែងបណ្តឹងភ្ញៀវមិនពេញចិត្ត ១០០% ឱ្យក្លាយជាភ្ញៀវស្មោះត្រង់ (X) តាមរយៈការអនុវត្តក្បួនសុំទោស និងផ្តល់ដំណោះស្រាយភ្លាមៗក្នុងរយៈពេលមិនឱ្យលើសពី ១៥ នាទី (Z)។\n\n• បង្កើនចំណូលពីការលក់សេវាកម្មបន្ថែម (Upselling Rooms & Dining) បាន $30,000 ក្នុងមួយត្រីមាស (X) តាមរយៈការបង្កើតកញ្ចប់លើកទឹកចិត្តដល់បុគ្គលិកទទួលភ្ញៀវ (Z)។', 'បរិញ្ញាបត្រ គ្រប់គ្រងទេសចរណ៍ និងបដិសណ្ឋារកិច្ច — សាកលវិទ្យាល័យជាតិគ្រប់គ្រង (NUM)\nវិញ្ញាបនបត្រ Certified Hospitality Supervisor (CHS)', 'Supervisor / Manager');
INSERT INTO `cv_templates` (`id`, `industry_kh`, `industry_en`, `title_kh`, `title_en`, `icon_name`, `summary`, `skills`, `achievements_xyz`, `education`, `recommended_for_level`) VALUES ('cv-executive', 'ថ្នាក់ដឹកនាំកំពូល & នាយកប្រតិបត្តិ', 'C-Suite Executive & General Management', 'អគ្គនាយកប្រតិបត្តិ / នាយកគ្រប់គ្រងទូទៅ', 'Chief Executive Officer (CEO) / General Manager', 'business_center', 'ថ្នាក់ដឹកនាំជាន់ខ្ពស់ដែលមានកំណត់ត្រាដឹកនាំក្រុមហ៊ុនឱ្យមានកំណើនប្រាក់ចំណេញជាបន្តបន្ទាប់ ការរៀបចំយុទ្ធសាស្ត្រពង្រីកទីផ្សារ ការកសាងក្រុមដឹកនាំរឹងមាំ និងការគ្រប់គ្រងអភិបាលកិច្ចស្ថាប័នកម្រិតខ្ពស់។', '["Strategic Vision & Company Valuation","P&L Management & Capital Allocation","Board of Directors & Investor Relations","Mergers & Acquisitions (M&A) & Joint Ventures","Executive Talent Recruitment & ESOP Architecture","Organizational Transformation & Crisis Management"]', '• ដឹកនាំក្រុមហ៊ុនពង្រីកចំណូលសរុបពី $2.5M ឡើងដល់ $7.2M ក្នុងរយៈពេល ៣ ឆ្នាំ (X) តាមរយៈការពង្រីកសាខាថ្មីចំនួន ៨ និងការដាក់លក់ខ្សែស្រឡាយផលិតផលថ្មីចំនួន ៣ (Z) បង្កើន EBITDA ២៨% (Y)។\n\n• រៀបចំរចនាសម្ព័ន្ធស្ថាប័នឡើងវិញ និងអនុវត្តប្រព័ន្ធ OKRs ទូទាំងក្រុមហ៊ុន (Z) ដែលកាត់បន្ថយចំណាយប្រតិបត្តិការ ១៨% និងបង្កើនផលិតភាពបុគ្គលិក ៣៥% (X)។\n\n• ដឹកនាំការចរចាស្វែងរកទុនវិនិយោគស៊េរី A បានសម្រេចចំនួន $3,000,000 ពីស្ថាប័នវិនិយោគអន្តរជាតិ (Z) បង្កើនតម្លៃក្រុមហ៊ុន (Valuation) ឡើងដល់ $15M (X)។', 'អនុបណ្ឌិត គ្រប់គ្រងពាណិជ្ជកម្មសម្រាប់ថ្នាក់ដឹកនាំ (Executive MBA) — AIT / National University of Singapore\nសមាជិកវិទ្យាស្ថាននាយកកម្ពុជា (Cambodian Institute of Directors)', 'Director / Executive / Founder');
INSERT INTO `user_progress` (`id`, `user_id`, `course_id`, `lesson_id`, `completed`, `quiz_passed`) VALUES
('prog-01', 'usr-learner-01', 'course-intern-comm', 'lesson-comm-1', 1, 1),
('prog-02', 'usr-learner-01', 'course-intern-comm', 'lesson-comm-2', 1, 1),
('prog-03', 'usr-learner-01', 'course-eq-critical', 'lesson-eq-1', 1, 1);
